ns:Register("test", "skillplan: the profession data's recipes and trainers", function(t)
    local SP = ns.skillPlan


    -- Plans that are a quest's reward: accept the quest at its giver, not "buy".
    local plans = { recipe = "Test Plans__test", recipeItem = 2, learn = 1, quest = { id = 99901, npc = 7804 } }
    local Q = ns.quests
    local old = { IsCompleted = Q.IsCompleted, InLog = Q.InLog, QuestieGet = Q.QuestieGet }
    local state = { done = false, inLog = false }
    Q.IsCompleted = function() return state.done end
    Q.InLog = function() return state.inLog end
    Q.QuestieGet = function(_, fname)
        if fname == "GetQuest" then return { name = "Test Plans Quest", requiredLevel = 1, Starts = { NPC = { 7804 } } } end
        if fname == "GetNPC" then return { name = "Test Giver", spawns = {} } end
    end
    local ok, err = pcall(function()
        if ns.api.Count(plans.recipeItem) > 0 then return end   -- (you have the plans: it says "use")
        local r = SP._recipeStop("Test__test", plans, {})
        t:eq(r and r.kind, "accept", "quest plans: an accept step")
        t:eq(r and r.key, "recipequest:99901", "quest plans: keyed by the quest")
        t:ok(r and r.text:find("Test Giver", 1, true), "quest plans: names the giver")
        state.inLog = true
        t:eq(SP._recipeStop("Test__test", plans, {}), nil, "quest in your log: its own steps take over")
        state.inLog, state.done = false, true
        t:eq(SP._recipeStop("Test__test", plans, {}), nil, "quest done: nothing")
        t:eq(SP._recipeStop("Test__test", plans, { ["Test Plans__test"] = true }), nil, "recipe known: nothing")
    end)
    Q.IsCompleted, Q.InLog, Q.QuestieGet = old.IsCompleted, old.InLog, old.QuestieGet
    t:ok(ok, "quest plans test ran (" .. tostring(err) .. ")")

    -- Heavy Runecloth Bandage: the Triage doctor for your side.
    local fa
    for _, s in ipairs(ns:Get("profGuide", "First Aid").steps) do
        if s.recipe == "Heavy Runecloth Bandage" then fa = s end
    end
    local names = SP.StepTrainers("First Aid", fa)
    t:eq(names[1], UnitFactionGroup("player") == "Horde" and "Doctor Gregory Victor" or "Doctor Gustaf VanHowzen",
        "Heavy Runecloth Bandage: your side's Triage doctor")
    t:eq(select(2, SP.StepTrainers("Cooking", {})), "Cooking trainer", "other steps: the profession's trainers")
end)

ns:Register("test", "skillplan: works out each step from the window's colours, not a fixed path", function(t)
    local SP = ns.skillPlan
    local bs = ns:Get("profGuide", "Blacksmithing").steps
    -- Every bought recipe has a source, so its step knows what it is and roughly costs.
    for prof, g in ns:Each("profGuide") do
        for _, s in ipairs(g.steps or {}) do
            if s.recipeItem and not s.quest then
                local src = ns:Get("itemSource", s.recipeItem)
                t:ok(src and src.vendor, prof .. ": " .. s.recipe .. "'s recipe has a vendor source")
            end
            t:eq(s.use, nil, prof .. ": " .. s.recipe .. " has no fixed range of its own (SP.Score decides)")
        end
    end
    -- Nothing seen in the window: no colour, so nothing is planned.
    local _, none, reaches, _, reached = SP._simulate("Blacksmithing__test", bs, 1, 270, {})
    t:eq(#none, 0, "no colour seen: nothing planned"); t:ok(not reaches, "doesn't reach"); t:eq(reached, 1, "stays at 1")
    -- At the skill Flow saw, the step SP.Score rates best of all of them.
    local seen = {
        ["Rough Sharpening Stone"] = { diff = "easy", reagents = { [2835] = 1 } },
        ["Rough Grinding Stone"] = { diff = "medium", reagents = { [2835] = 2 } },
        ["Runed Copper Belt"] = { diff = "trivial", reagents = { [2840] = 10 } } }
    with(ns.recipes, "Known", function(_, prof) if prof == "Blacksmithing__test" then return seen, 30 end end, function()
        local _, order = SP._simulate("Blacksmithing__test", bs, 30, 31, {})
        local at, step, best = order[1] and order[1].recipe, nil, 0
        for _, s in ipairs(bs) do
            local v = SP.Score(s, 30, { prof = "Blacksmithing__test" })
            if v > best then best = v end
            if s.recipe == at then step = s end
        end
        t:eq(at, "Rough Grinding Stone", "30: yellow for 2 stones beats green for 1")
        t:near(step and SP.Score(step, 30, { prof = "Blacksmithing__test" }) or -1, best, 1e-9, "30: the best-rated step")
        t:eq((SP.Score(bs[5], 30, { prof = "Blacksmithing__test" })), 0, "grey in the window: not a choice")
    end)
    -- Fish recipes stand in only while you carry the fish.
    local cooking = {}
    for _, s in ipairs(ns:Get("profGuide", "Cooking").steps) do if not s.faction then cooking[#cooking + 1] = s end end
    local fishSeen = { ["Charred Wolf Meat"] = { diff = "optimal", reagents = { [2672] = 1 } },
                       ["Longjaw Mud Snapper"] = { diff = "optimal", reagents = { [6289] = 1 } } }
    with(ns.recipes, "Known", function(_, prof) if prof == "Cooking__test" then return fishSeen, 60 end end, function()
        local _, order = SP._simulate("Cooking__test", cooking, 60, 70, {})
        t:ok(#order > 0, "60: the meat recipe is planned")
        for _, s in ipairs(order) do t:ok(not s.recipe:find("Mud Snapper"), "60, no fish in bags: no fish recipe (" .. s.recipe .. ")") end
    end)
end)

ns:Register("test", "perf: Flow's update loops are timed", function(t)
    local P = ns.perf
    local f = P.Wrap("test: wrapped", function(a, b) return a + b, "x" end)
    local s, x = f(2, 3)
    t:eq(s, 5, "wrapped function still returns its results"); t:eq(x, "x", "second result too")
    t:eq(P.stats["test: wrapped"].calls, 1, "call counted")
    P.stats["test: wrapped"] = nil
    t:ok(P.stats["arrow + minimap (10/s)"] ~= nil, "route arrow timed")
    t:ok(P.stats["route: order steps"] ~= nil, "planner timed")
    for _, name in ipairs({ "rotation: choosing the spell", "flow actions", "status icons (1/s)", "rotation: showing it (10/s)" }) do
        t:ok(P.stats[name] ~= nil, name .. ": timed apart from drawing the key")
    end
    -- quick: a full clean-up inside the login self-test run is a hitch.
    local rep = P:Report(true)
    t:ok(#rep >= 1, "report has a summary line")
    t:ok(rep[1]:find("/flow perf", 1, true) ~= nil, "quick report skips the clean-up and says so")
    t:ok(ns.nav.Busy() == true or ns.nav.Busy() == false, "tracker can tell when the route is being redone")
end)

ns:Register("test", "perf: route refresh gathers one step source at a time", function(t)
    local N, P = ns.nav, ns.perf
    local list = { "already here" }
    N._gatherFrom("test: src", { collect = function() return { { key = "k1", text = "a" } } end }, list)
    t:eq(#list, 2, "one source's steps added to the list being built")
    t:eq(list[2].provider, "test: src", "step tagged with its source")
    N._gatherFrom("test: bad", { collect = function() error("boom") end }, list)
