ns:Register("test", "skillplan: materials from bags, then bank, then smelting", function(t)
    local SP = ns.skillPlan
    local BAR, ORE, LEATHER = 900001, 900002, 900003
    local bags = { [BAR] = 2, [ORE] = 3 }
    local bank = { [BAR] = 1, [ORE] = 6, [LEATHER] = 4 }
    local function smeltOf(id) if id == BAR then return { from = ORE, n = 1 } end end
    local st = SP.Stock(function(id) return bags[id] or 0 end, function(id) return bank[id] or 0 end, smeltOf)
    t:eq(st:Avail(BAR), 12, "2 bags + 1 bank + 9 ore to smelt")
    local r = st:Take(BAR, 8)
    t:eq(r.bags, 2, "bags first"); t:eq(r.bank, 1, "then the bank")
    t:eq(r.smelt, 5, "then smelt the rest")
    t:eq(r.oreBags, 3, "ore from your bags first"); t:eq(r.oreBank, 2, "then the bank's ore")
    t:eq(r.short, 0, "nothing short")
    t:eq(st:Avail(BAR), 4, "what's left counts once")
    local try = st:Fork()
    local r2 = try:Take(BAR, 6)
    t:eq(r2.short, 2, "a copy sees only what's left")
    t:eq(st:Avail(BAR), 4, "trying on the copy takes nothing")
    local line = SP.SourceLine("Copper Bar", r, "Copper Ore")
    t:ok(line:find("2 in your bags", 1, true) and line:find("1 from your bank", 1, true)
        and line:find("smelt 5 from 5 Copper Ore (bags and bank)", 1, true), "says where each comes from: " .. line)
    t:ok(SP.SourceLine("Tigerseye", { need = 2, bags = 0, bank = 0, smelt = 0, oreBags = 0, oreBank = 0, short = 2 })
        :find("2 still to get", 1, true), "and what's still to get")
end)

ns:Register("test", "skillplan: the bank Flow saw counts, an upgrade with an unread material isn't makeable", function(t)
    local SP = ns.skillPlan
    local saved = ns.db.bank
    local ok, err = pcall(function()
        ns.db.bank = { items = { [900004] = 7 }, seenAt = 1 }
        t:eq(SP.BankCount(900004), 7, "what Flow saw in your bank")
        t:eq(SP.BankCount(900005), 0, "not in it: none")
    end)
    ns.db.bank = saved
    t:ok(ok, "ran" .. (ok and "" or (": " .. tostring(err))))
    local ups = SP.PickUpgrades({ { recipe = "Boots", item = 1, reagents = { [2840] = 2 }, partial = true } },
        function() return 3, "dps", "boots", "INVTYPE_FEET" end)
    t:ok(ups[1] and ups[1].partial, "an incomplete material list comes along")
    local lines = ns.craftHint.UpgradeLines({ { recipe = "Boots", tag = "+3 DPS", missing = { "2 Tigerseye", "4 Light Leather" } },
                                             { recipe = "Belt", tag = "+1 DPS", missing = {}, unread = true } })
    t:ok(lines[1]:find("needs 2 Tigerseye, 4 Light Leather", 1, true), "the fold-out says what's missing")
    t:ok(lines[2]:find("open this window again", 1, true), "and when Flow couldn't read the materials")
    for _, g in ipairs(SP.lastStops or {}) do
        t:ok(not (g.key or ""):find("^upgrade:") or not g.blockedBy or not g.blockedBy:find("^needs %d"),
            (g.recipe or g.key) .. ": an upgrade missing materials is never a step")
    end
end)

ns:Register("test", "crafting: the window shows the arrow's step, materials and the upgrades fold-out", function(t)
    local H = ns.craftHint
    local a = { key = "craft:X:A", recipe = "A" }
    local b = { key = "upgrade:X:B", recipe = "B" }
    t:eq(H.Pick({ b, a }, { goal = { key = "craft:X:A" } }), a, "the faint arrow's step wins")
    t:eq(H.Pick({ b, a }, nil, { { goal = { key = "craft:X:A" } } }), a, "else the profession route's first")
    t:eq(H.Pick({ b, a }), b, "else the first")
    local lines, now = H.MaterialLines({ reagents = { [2840] = 2 } }, 4,
        function() return 3 end, function() return 10 end)
    t:eq(#lines, 1, "one line per material")
    t:ok(lines[1]:find("3 in your bags", 1, true) and lines[1]:find("5 from your bank", 1, true), "bags then bank: " .. lines[1])
    t:eq(now, 1, "make now only what your bags hold")
    local ok, err = pcall(function()
        local p = H.Panel()
        t:ok(p.goalBox and p.goalBox ~= p, "the goal has its own box, apart from the lists")
        t:eq(p.btn:GetParent(), p.goalBox, "the Make button sits in the goal box")
        t:eq(_G.FlowCraftGoal and _G.FlowCraftGoal.btn, p.btn, "the action key finds the Make button")
        if p.goalBox.GetBackdropBorderColor then
            local r, g, b = p.goalBox:GetBackdropBorderColor()
            t:ok(r > 0.95 and math.abs(g - 0.5) < 0.05 and b < 0.05, "the goal box has a legendary orange border")
        end
        local was = H.upgradesOpen
        p.upBtn:Click()
        t:eq(H.upgradesOpen, not was, "clicking opens / closes the fold-out")
        p.upBtn:Click()
        t:eq(H.upgradesOpen, was, "and back")
    end)
    t:ok(ok, "fold-out click" .. (ok and "" or (": " .. tostring(err))))
end)

ns:Register("test", "crafting: skill recipes are ranked by material cost per skill point", function(t)
    local known = {
        Dear   = { diff = "optimal", reagents = { [1] = 10 } },   -- 100 a point
        Cheap  = { diff = "medium",  reagents = { [1] = 3 } },    -- 30 / 0.6 = 50 a point
        Grey   = { diff = "trivial", reagents = { [1] = 1 } },    -- gives no skill
        NoIdea = { diff = "optimal", reagents = { [2] = 1 } },    -- no price known
    }
    local list = ns.skillPlan.CheapSkillUps(known, function(id) return id == 1 and 10 or nil end)
    t:eq(#list, 3, "the grey one is left out")
    t:eq(list[1].recipe, "Cheap", "cheapest per skill point first")
    t:eq(list[2].recipe, "Dear", "then the dearer one")
    t:eq(list[3].recipe, "NoIdea", "unknown prices go last")
    local rows = ns.craftHint.CheapRows(list, 2)
    t:eq(#rows, 2, "only the top ones are shown")
    t:ok(rows[1].line:find("Cheap", 1, true), "the row names the recipe: " .. rows[1].line)
end)

ns:Register("test", "crafting: what your bags make for skill is ranked by skill points", function(t)
    local known = {
        Two    = { diff = "optimal", reagents = { [1] = 2 } },          -- 5 made, 5 points
        Many   = { diff = "easy",    reagents = { [1] = 1 } },          -- 10 made, 2 points
        Both   = { diff = "medium",  reagents = { [1] = 1, [2] = 1 } }, -- 3 made, 1.8 points
        Lack   = { diff = "optimal", reagents = { [3] = 1 } },          -- none in bags
        Grey   = { diff = "trivial", reagents = { [1] = 1 } },
    }
    local bags = { [1] = 10, [2] = 3 }
    local list = ns.skillPlan.MakeNowSkillUps(known, function(id) return bags[id] or 0 end)
    t:eq(#list, 3, "what you can't make, and grey, are left out")
    t:eq(list[1].recipe, "Two", "most skill points first")
    t:eq(list[1].count, 5, "how many your bags make")
    t:eq(list[2].recipe, "Many", "then the next most")
    t:eq(list[3].count, 3, "the scarcest material sets the count")
    local rows = ns.craftHint.MakeNowRows(list, 3)
    t:ok(rows[1].line:find("make 5, 5 sure skill points", 1, true), "orange: sure points: " .. rows[1].line)
    t:ok(rows[2].line:find("maybe 2 skill points (not every time)", 1, true), "others: maybe: " .. rows[2].line)
    -- 4 yellow (2.4 expected) vs 2 orange (2 sure): the sure one first.
    local tie = ns.skillPlan.MakeNowSkillUps({
        Pants = { diff = "medium",  reagents = { [1] = 1 } },
        Belt  = { diff = "optimal", reagents = { [2] = 1 } },
    }, function(id) return id == 1 and 4 or 2 end)
    t:eq(tie[1].recipe, "Belt", "on the same whole points, the sure recipe first")
end)

ns:Register("test", "crafting: an upgrade's hover lists its materials, read from the newest recipe data", function(t)
    local mats = ns.craftHint.UpgradeMats({ reagents = { [2840] = 6, [2842] = 2 } },
        function(id) return id == 2840 and 4 or 0 end, function(id) return id == 2840 and 5 or 0 end)
    t:eq(#mats, 2, "one line per material")
    t:ok(mats[1].text:find("^6 x ") and mats[1].text:find("you have 4", 1, true)
        and mats[1].text:find("+5 in the bank", 1, true), "need, bags and bank: " .. mats[1].text)
    t:eq(mats[1].enough, true, "bags and bank together cover it")
    t:eq(mats[2].enough, false, "none of the other: still to get")
    local r = { reagents = {} }
    ns.recipes._schematicReagents(function()
        return { reagentSlotSchematics = {
            { reagentType = 1, required = true, quantityRequired = 8, reagents = { { itemID = 2840 } } },
            { reagentType = 0, required = false, quantityRequired = 1, reagents = { { itemID = 999 } } },
        } }
    end, 1, r)
    t:eq(r.reagents[2840], 8, "the plain material and how many")
    t:eq(r.reagents[999], nil, "an optional extra isn't needed")
    t:eq(r.partial, nil, "all read")
    local bad = { reagents = {} }
    ns.recipes._schematicReagents(function() error("no data") end, 1, bad)
    t:eq(bad.partial, true, "unreadable: marked incomplete")
end)

