    t:ok(ns:Get("gatherNode", "Iron Deposit") and ns:Get("gatherNode", "Peacebloom"), "ore and herb nodes listed")
    with(ns.db.nav, "nearbyNodes", false, function()
        t:ok(not NB.Enabled() and #NB.MinimapGroups({ map = 1, cont = 0, wx = 0, wy = 0 }, 200) == 0, "the setting turns it off")
    end)
end)

ns:Register("test", "party: your own messages echoed back are never someone else's", function(t)
    local IsMe = ns.party.IsMe
    t:ok(IsMe("Bob", "Bob", "Realm"), "plain name")
    t:ok(IsMe("Bob-Realm", "Bob", "Realm"), "Name-Realm, as this client sends it")
    t:ok(IsMe("Bob-Argent Dawn", "Bob", "ArgentDawn"), "realm with a space")
    t:ok(not IsMe("Bob-Other", "Bob", "Realm"), "someone with your name from another realm isn't you")
    t:ok(not IsMe("Alice-Realm", "Bob", "Realm"), "another player isn't you")
    t:ok(not IsMe(nil, "Bob", "Realm"), "no sender: no")
    t:ok(IsMe((UnitName("player"))), "you, by your own name")
end)

ns:Register("test", "quest sharing: share what party members are missing, once each", function(t)
    local QS = ns.questShare
    local members = { Zed = { [83] = true }, Amy = { [83] = true, [86] = true } }
    t:ok(QS.ShouldShare(86, members, 0, {}, false), "Zed doesn't have 86: share it")
    t:ok(not QS.ShouldShare(83, members, 0, {}, false), "everyone has 83: don't")
    t:ok(not QS.ShouldShare(86, members, 0, { Zed = { [86] = true } }, false), "already offered to Zed: not again")
    t:ok(QS.ShouldShare(83, members, 1, {}, true), "just picked up, and someone without Flow is here: share")
    t:ok(not QS.ShouldShare(83, members, 1, {}, false), "your older quests aren't pushed on players without Flow")
    t:ok(not QS.ShouldShare(86, members, 0, {}, false, function() return false end), "too low a level for it: not offered")
    t:eq(QS.Count(members), 2, "two Flow players")
    with(ns.db.quests, "share", false, function() t:ok(not QS.Enabled(), "the settings box turns it off") end)
    with(ns.db.quests, "share", nil, function() t:ok(QS.Enabled(), "on by default") end)
end)

ns:Register("test", "loot: leave junk behind, take everything else", function(t)
    local L = ns.lootFilter
    local ITEM, MONEY = (Enum and Enum.LootSlotType and Enum.LootSlotType.Item) or 1, (Enum and Enum.LootSlotType and Enum.LootSlotType.Money) or 2
    t:ok(not L.Take(ITEM, 0, false, false), "a grey item stays")
    t:ok(L.Take(ITEM, 1, false, false), "a white item is taken")
    t:ok(L.Take(ITEM, 0, true, false), "a quest item is always taken, even grey")
    t:ok(L.Take(MONEY, 0, false, false), "money is always taken")
    t:ok(not L.Take(ITEM, 2, false, true), "a locked slot (someone's roll) is left alone")
    t:ok(L.Take(ITEM, nil, nil, nil), "an item whose quality can't be read is taken, never left as junk")
    with(ns.db.loot, "skipJunk", nil, function() t:ok(not L.Enabled(), "off by default") end)
    -- 0.35.320: "it just opens the loot window and immediately closes". The
    -- window closes only the first time Flow looks at a corpse.
    t:ok(L.ShouldClose(2, 2, "Creature-1", {}), "only junk left, the first look: closed")
    t:ok(not L.ShouldClose(2, 2, "Creature-1", { ["Creature-1"] = true }), "the same corpse opened again: left open for you")
    t:ok(not L.ShouldClose(2, 1, "Creature-2", {}), "something besides junk left: left open")
    t:ok(not L.ShouldClose(0, 0, "Creature-3", {}), "nothing left: nothing to close (the game closes it)")
    t:ok(L.ShouldClose(1, 1, nil, {}), "the corpse can't be told apart: as before")
    -- Why it closed, by your cursor ("can we make it more intuitive to users why it's closing").
    local title, sub = L.JunkWords({ "Thin Black Claw" })
    t:eq(title, "Flow left the junk: Thin Black Claw", "the note names what it left")
    t:eq(sub, "(open it again to take it)", "and how to take it")
    t:eq(L.JunkWords({ "A", "B", "C", "D" }), "Flow left the junk: A, B and 2 more", "many: two by name, the rest counted")
    t:eq(L.JunkWords({}), "Flow left the junk: grey items", "names hidden: grey items")
    -- "the fact that it left junk on them means I can't skin them": a skinner is told.
    local warn = L.SkinWarning(true, true)
    t:ok(warn ~= nil and warn:find("can't be skinned", 1, true) ~= nil and warn:find("/flow loot junk", 1, true) ~= nil,
        "on, with Skinning: the warning, and how to turn it off")
    t:eq(L.SkinWarning(true, false), nil, "no Skinning: nothing to say")
    t:eq(L.SkinWarning(false, true), nil, "off: nothing to say")
end)

ns:Register("test", "paladin: a seal goes on whenever you have none", function(t)
    local def = ns:Get("rotation", "PALADIN")
    local A = ns.api
    with(A, "Buff", function() return false, 0 end, function()
        t:ok(def.wantSeal({ hostile = false, inCombat = false }), "out of combat, no seal: put one on")
        t:ok(def.wantSeal({ hostile = true, inCombat = false }), "an enemy targeted, no seal: put one on")
    end)
    with(A, "Buff", function() return true, 20 end, function()
        t:ok(not def.wantSeal({ hostile = false, inCombat = false }), "seal up: nothing")
        t:ok(not def.wantSeal({ hostile = false, inCombat = true }), "in a fight with 20 s left: nothing")
    end)
    with(A, "Buff", function() return true, 2 end, function()
        t:ok(def.wantSeal({ hostile = true, inCombat = true }), "in a fight, about to drop: refresh")
        t:ok(not def.wantSeal({ hostile = false, inCombat = false }), "out of combat, still up: no nagging")
    end)
end)

ns:Register("test", "spec: your talents set the role Flow plays you as, ties and all", function(t)
    -- "Why isn't it suggesting Righteous Fury if I'm prot? Why don't we have an option to set your spec?"
    local specs = { dps = { name = "Retribution" }, heal = { name = "Holy" }, tank = { name = "Protection" } }
    local function tr(h, p, r)
        return { { name = "Holy", points = h }, { name = "Protection", points = p }, { name = "Retribution", points = r } }
    end
    t:eq(ns.RoleFromTrees(specs, tr(0, 11, 2)), "tank", "most points in Protection: tank")
    t:eq(ns.RoleFromTrees(specs, tr(5, 0, 9)), "dps", "most in Retribution: dps")
    t:eq(ns.RoleFromTrees(specs, tr(8, 1, 0)), "heal", "most in Holy: heal")
    t:eq(ns.RoleFromTrees(specs, tr(0, 0, 0)), nil, "no points yet: nothing (the recommended role)")
    t:eq(ns.RoleFromTrees(specs, tr(5, 5, 0)), nil, "a tie: nothing")
    t:eq(ns.RoleFromTrees(specs, tr(1, 7, 7)), nil, "a tie for the most, not the leftmost: nothing")
    t:eq(ns.RoleFromTrees({ dps = { name = "Feral (Cat)" } }, { { name = "Feral Combat", points = 9 } }), nil,
        "a tree no role is named after: nothing")
    t:eq(ns.RoleFromTrees(specs, {}), nil, "no talent trees: nothing")
    t:eq((ns.DominantTree(tr(7, 3, 0))), 1, "the leftmost tree when it has the most")
    t:eq((ns.DominantTree(tr(3, 3, 9))), 3, "a tie below the most doesn't matter")
    t:eq((ns.DominantTree(tr(4, 4, 0))), nil, "a tie for the most: no tree")
    t:eq((ns.DominantTree(nil)), nil, "no trees: no tree")
    -- "Still not suggesting Righteous Fury": Forever's one talent sheet (x far apart per tree;
    -- a tree's four columns 600 apart, every column holding a talent).
    local sheet = {
        { x = 1020, y = 2730, rank = 0 }, { x = 1620, y = 2130, rank = 0 },             -- Holy
        { x = 2220, y = 2130, rank = 0 }, { x = 2820, y = 2730, rank = 0 },
        { x = 5020, y = 2730, rank = 1 }, { x = 6220, y = 2130, rank = 5 },             -- Protection
        { x = 5620, y = 2130, rank = 0 },
        { x = 9080, y = 2730, rank = 0 }, { x = 9680, y = 2130, rank = 0 },             -- Retribution
        { x = 10280, y = 2130, rank = 0 }, { x = 10880, y = 3330, rank = 0 },
    }
    local fromSheet = ns.TreesFromNodes(sheet, ns.TALENT_TREES.PALADIN)
    t:eq(fromSheet and fromSheet[2].points, 6, "Forever's sheet: 6 points in the middle tree")
    t:eq(ns.RoleFromTrees(specs, fromSheet), "tank", "6 points in Protection on Forever: tank")
    t:eq(ns.TreesFromNodes({ { x = 1, y = 1, rank = 1 } }, ns.TALENT_TREES.PALADIN), nil,
        "a sheet that isn't three trees: nothing (never a guess)")
    t:ok(ns.DruidWantsBear("tank", true, false), "druid tank, a fight: Bear Form")
    t:ok(not ns.DruidWantsBear("tank", true, true), "already a bear: nothing")
    t:ok(not ns.DruidWantsBear("tank", false, false), "travelling, nothing targeted: nothing")
    t:ok(not ns.DruidWantsBear("dps", true, false), "not tanking: the form you're in")
end)

ns:Register("test", "spec: your chosen role beats your talents, which beat your class's", function(t)
    local function both(...) local r, s = ns.ResolveRole(...) return r .. "/" .. s end
    t:eq(both("dps", "tank", "heal"), "dps/chosen", "chose DPS, Protection talents: DPS")
    t:eq(both("tank", nil, "dps"), "tank/chosen", "chose Tank before any talents: Tank")
    t:eq(both(nil, "tank", "dps"), "tank/talents", "Auto, Protection talents: Tank")
    t:eq(both(nil, nil, "heal"), "heal/class", "Auto, no talents: your class's role")
    t:eq(both("auto", nil, nil), "dps/class", "not a role: Auto")
    t:eq(type(ns:LevelingRole()), "string", "ns:LevelingRole: one role")
    t:ok(({ chosen = true, talents = true, class = true })[ns:RoleSource()] == true, "ns:RoleSource: where it came from")
end)

ns:Register("test", "spec: a talent read that found nothing is tried again, not kept", function(t)
    local now, reads, answer = 100, 0, nil
    local cache = ns.TalentCache(function() reads = reads + 1 return answer end, function() return now end, 5)
    t:eq(#cache:Get(), 0, "talents not loaded yet: none for now")
    t:eq(reads, 1, "read once")
    now = 102
    cache:Get()
    t:eq(reads, 1, "two seconds later: not read again yet")
    answer = { { name = "Holy", points = 0 }, { name = "Protection", points = 3 } }
    now = 106
    t:eq(#cache:Get(), 2, "five seconds later: read again, and found")
    cache:Get()
    t:eq(reads, 2, "a good read is kept")
    answer = { { name = "Holy", points = 9 } }
    cache:Forget()
    t:eq(cache:Get()[1].points, 9, "your talents changed: read afresh")
    local failing = ns.TalentCache(function() error("no talent API") end, function() return now end, 5)
    t:eq(#failing:Get(), 0, "a reader that errors: none, no error")
end)

ns:Register("test", "talents: the classic talent API when the talent sheet has nothing", function(t)
    local T = ns.talents
    local node = { { x = 1, y = 1, rank = 1 } }
    local nodes, unspent = T.ReadWith({ function() return {}, 0 end, function() return node, 2 end })
    t:eq(#nodes, 1, "the sheet empty (no loadout yet): the classic API's talents")
    t:eq(unspent, 2, "and its unspent points")
    nodes = T.ReadWith({ function() return nil end, function() return node, 0 end })
    t:eq(#nodes, 1, "no talent sheet on this client: the classic API")
    nodes = T.ReadWith({ function() error("present but unusable") end, function() return node, 0 end })
    t:eq(#nodes, 1, "a talent function that errors: the next one")
    nodes, unspent = T.ReadWith({ function() return {}, 4 end, function() return nil end })
    t:eq(#nodes, 0, "nothing anywhere: no talents")
    t:eq(unspent, 4, "the first answer that worked is kept")
    nodes, unspent = T.ReadWith({})
    t:eq(#nodes + unspent, 0, "no talent API at all: nothing")
end)

ns:Register("test", "paladin: seal, blessing and Righteous Fury follow your role, not your talent tree", function(t)
    local def = ns:Get("rotation", "PALADIN")
    local knowsAll = { Knows = function() return true end }
    local noKings = { Knows = function(_, s) return s ~= "Blessing of Kings" end }
    local savedB, savedCast, savedSeal = ns.db.paladinBlessing, ns.db.paladinBlessingCast, ns.db.paladinSeal
    ns.db.paladinBlessing, ns.db.paladinBlessingCast, ns.db.paladinSeal = nil, nil, nil
    local ok, err = pcall(function()
        t:ok(def.wantFury("tank"), "tanking: Righteous Fury")
        t:ok(not def.wantFury("dps"), "DPS (even with Protection talents): no Righteous Fury")
        t:ok(not def.wantFury("heal"), "healing: no Righteous Fury")
        t:eq(def.pickSeal(knowsAll, "dps", { grouped = false, own = false, learned = false }), "Seal of Command",
            "DPS, knowing Seal of Fury too: Command, not Fury")
        t:eq(def.pickSeal(knowsAll, "tank", { grouped = false, own = false, learned = false }), "Seal of Fury", "tanking: Fury")
        t:eq(def.pickBlessing(knowsAll, "dps", {}), "Blessing of Might", "DPS: Might")
        t:eq(def.pickBlessing(knowsAll, "tank", {}), "Blessing of Kings", "tanking: Kings")
        t:eq(def.pickBlessing(noKings, "tank", {}), "Blessing of Might", "tanking without Kings yet: Might")
        t:eq(def.pickBlessing(knowsAll, "heal", {}), "Blessing of Wisdom", "healing: Wisdom")
        local learned = { tank = "Blessing of Wisdom" }
        t:eq(def.pickBlessing(knowsAll, "tank", learned), "Blessing of Wisdom", "Auto: the one you cast as a tank")
        t:eq(def.pickBlessing(knowsAll, "dps", learned), "Blessing of Might", "...only while you tank")
        ns.db.paladinBlessing = "Blessing of Salvation"
        t:eq(def.pickBlessing(knowsAll, "tank", learned), "Blessing of Salvation", "your choice beats what you cast")
        ns.db.paladinBlessingCast = { dps = "Blessing of Light" }
        def.SetBlessing("Blessing of Kings")
        t:eq(ns.db.paladinBlessing, "Blessing of Kings", "the settings row sets your choice")
        t:eq(ns.db.paladinBlessingCast, nil, "and forgets the ones you cast")
        ns.db.paladinBlessingCast = { dps = "Blessing of Light" }
        def.SetBlessing(nil)
        t:eq(ns.db.paladinBlessing, nil, "Auto clears your choice")
        t:eq(ns.db.paladinBlessingCast, nil, "and the ones you cast")
    end)
    ns.db.paladinBlessing, ns.db.paladinBlessingCast, ns.db.paladinSeal = savedB, savedCast, savedSeal
    if not ok then error(err, 0) end
end)

ns:Register("test", "paladin: what you cast becomes a preference only when it's yours, on you, and new", function(t)
    local def = ns:Get("rotation", "PALADIN")
    local IS_B, IS_S = def.IS_BLESSING, def.IS_SEAL
    local K = def.KeptFromCast
    t:eq(K("Blessing of Wisdom", IS_B, "Blessing of Might", false, true), "Blessing of Wisdom",
        "a different blessing you cast on yourself: kept")
    t:eq(K("Blessing of Wisdom", IS_B, "Blessing of Might", true, true), nil,
        "cast with Flow's key: Flow's suggestion, Auto stays")
    t:eq(K("Blessing of Might", IS_B, "Blessing of Might", false, true), nil, "the one Flow would put up: Auto stays")
    t:eq(K("Blessing of Wisdom", IS_B, "Blessing of Might", false, false), nil, "on someone else: nothing")
    t:eq(K("Blessing of Wisdom", IS_B, "Blessing of Might", false, nil), nil, "can't tell who it went on: nothing")
    t:eq(K("Blessing of Protection", IS_B, "Blessing of Might", false, true), nil, "Protection is a moment, not a choice")
    t:eq(K("Seal of Justice", IS_S, "Seal of Righteousness", false, true), "Seal of Justice", "a seal of yours: kept")
    t:eq(K("Seal of Justice", IS_B, "Blessing of Might", false, true), nil, "a seal isn't a blessing")
    local P = def.Preferred
    local all = function() return true end
    t:eq(P(all, "tank", "Blessing of Kings", { tank = "Blessing of Wisdom" }), "Blessing of Kings",
        "your setting beats what you cast")
    t:eq(P(all, "tank", nil, { tank = "Blessing of Wisdom" }), "Blessing of Wisdom", "Auto: what you cast for this role")
    t:eq(P(all, "dps", nil, { tank = "Blessing of Wisdom" }), nil, "another role's: not this one")
    t:eq(P(function(s) return s ~= "Blessing of Kings" end, "tank", "Blessing of Kings", { tank = "Blessing of Wisdom" }),
        "Blessing of Wisdom", "a setting you don't know yet: the next one")
    t:eq(P(all, "dps", nil, nil), nil, "nothing set or cast: by your role")
    local R = def.RecipientIsYou
    t:eq(R("Yang", "Yang", { exists = true, friendly = true }), true, "named you: you")
    t:eq(R("Yang-Forever", "Yang", nil), true, "named you with a realm: you")
    t:eq(R("Bob", "Yang", { exists = false }), false, "named someone else: not you")
    t:eq(R("", "Yang", { exists = false }), true, "no name, nothing targeted: you")
    t:eq(R(nil, "Yang", { exists = true, isYou = true }), true, "no name, targeting yourself: you")
    t:eq(R(nil, "Yang", { exists = true, friendly = false }), true, "no name, an enemy targeted: you")
    t:eq(R(nil, "Yang", { exists = true, friendly = true }), nil, "no name, a friend or pet targeted: can't tell")
    t:eq(R(nil, "Yang", { exists = true }), nil, "no name, can't read the target: can't tell")
    local C = ns.cast
    local log = { ["Blessing of Might"] = 10 }
    t:ok(C.PressedFor(log, "Blessing of Might", 11, 2), "Flow's key cast it a second ago: Flow's")
    t:ok(not C.PressedFor(log, "Blessing of Might", 13, 2), "three seconds later: yours")
    t:ok(not C.PressedFor(log, "Blessing of Wisdom", 11, 2), "another spell: yours")
    t:ok(not C.PressedFor(log, "Blessing of Might", 9, 2), "before the press: yours")
end)

ns:Register("test", "paladin: a new seal or blessing goes on while another is up", function(t)
    local def = ns:Get("rotation", "PALADIN")
    local A = ns.api
    local function up(name, left)
        return function(_, match)
            if match(name) then return true, left end
            return false, 0
        end
    end
    with(A, "Buff", up("Blessing of Might", 200), function()
        t:ok(def.needBlessing("Blessing of Wisdom"), "Might up, Wisdom wanted: Wisdom")
        t:ok(not def.needBlessing("Blessing of Might"), "Might up and wanted: nothing")
    end)
    with(A, "Buff", up("Greater Blessing of Might", 200), function()
        t:ok(not def.needBlessing("Blessing of Might"), "a Greater Blessing of Might counts as Might")
    end)
    with(A, "Buff", up("Blessing of Might", 10), function()
        t:ok(def.needBlessing("Blessing of Might"), "Might running out: again")
    end)
    with(A, "Buff", up("Seal of Righteousness", 20), function()
        t:ok(def.wantSeal({ hostile = true, inCombat = true }, "Seal of Command"),
            "in a fight with Righteousness up, Command wanted: Command")
        t:ok(not def.wantSeal({ hostile = true, inCombat = true }, "Seal of Righteousness"), "the one wanted, 20 s left: nothing")
        t:ok(not def.wantSeal({ hostile = false, inCombat = false }, "Seal of Command"),
            "out of combat with a seal up: no recasting between pulls")
    end)
end)

ns:Register("test", "paladin: the seal Flow suggests (your role, your choice, the seal you cast)", function(t)
    local def = ns:Get("rotation", "PALADIN")
    local knowsAll = { Knows = function() return true end }
    local noFury = { Knows = function(_, s) return s ~= "Seal of Fury" end }
    local noCommand = { Knows = function(_, s) return s ~= "Seal of Command" end }
    local function at(grouped, own, learned)
        return { grouped = grouped or false, own = own or false, learned = learned or false }
    end
    local saved, savedCast = ns.db.paladinSeal, ns.db.paladinSealCast
    ns.db.paladinSeal, ns.db.paladinSealCast = nil, nil
    local ok, err = pcall(function()
        t:eq(def.pickSeal(noCommand, "dps", at()), "Seal of Righteousness", "DPS without Command: Righteousness")
        t:eq(def.pickSeal(knowsAll, "tank", at()), "Seal of Fury", "tanking: Fury")
        t:eq(def.pickSeal(noFury, "tank", at()), "Seal of Righteousness", "tanking without Fury yet: Righteousness")
        t:eq(def.pickSeal(knowsAll, "dps", at()), "Seal of Command", "DPS: Command")
        t:eq(def.pickSeal(knowsAll, "heal", at(true)), "Seal of Wisdom", "healing in a group: Wisdom")
        t:eq(def.pickSeal(knowsAll, "heal", at(false)), "Seal of Righteousness", "healing on your own: Righteousness")
        t:eq(def.pickSeal(knowsAll, "dps", at(false, "Seal of Justice")), "Seal of Justice",
            "a seal you cast yourself is kept for the fight")
        -- "You think somebody's gonna go through all of that to change their stuff?"
        local cast = { dps = "Seal of Justice" }
        t:eq(def.pickSeal(knowsAll, "dps", at(false, nil, cast)), "Seal of Justice",
            "Auto: the seal you cast while playing DPS, every fight")
        t:eq(def.pickSeal(knowsAll, "tank", at(false, nil, cast)), "Seal of Fury",
            "...only for that role: tanking still gets Fury")
        t:eq(def.pickSeal(noCommand, "dps", at(false, nil, { dps = "Seal of Command" })), "Seal of Righteousness",
            "a cast seal you no longer know: your role's")
        ns.db.paladinSeal = "Seal of Wisdom"
        t:eq(def.pickSeal(knowsAll, "dps", at(false, nil, cast)), "Seal of Wisdom",
            "your choice wins over a seal you cast (a cast never becomes or beats the setting)")
        t:eq(def.pickSeal(knowsAll, "dps", at()), "Seal of Wisdom", "your choice wins over your role")
        t:eq(def.pickSeal(noFury, "tank", at()), "Seal of Wisdom", "your choice wins over tanking")
        t:eq(def.pickSeal(knowsAll, "dps", at(false, "Seal of Light")), "Seal of Light",
            "a different seal cast mid-fight wins over your choice")
        ns.db.paladinSeal = "Seal of Fury"
        t:eq(def.pickSeal(noFury, "dps", at()), "Seal of Command", "a seal you don't know yet: your role's")
        def.SetSeal("Seal of Light")
        t:eq(ns.db.paladinSeal, "Seal of Light", "the settings row sets your choice")
        def.SetSeal(nil)
        t:eq(ns.db.paladinSeal, nil, "Auto clears it")
        ns.db.paladinSealCast = { dps = "Seal of Justice" }
        def.SetSeal(nil)
        t:eq(ns.db.paladinSealCast, nil, "Auto (or a choice) forgets the seals you cast")
    end)
    ns.db.paladinSeal, ns.db.paladinSealCast = saved, savedCast
    if not ok then error(err, 0) end
    t:ok(type(ns.commands.seal) == "function", "/flow seal exists")
    for _, s in ipairs(def.SEALS) do t:ok(s:find("^Seal of ") ~= nil, s .. " is a seal") end
end)

ns:Register("test", "follow: the arrow follows a party member only while you follow one", function(t)
    local F = ns.follow
    t:eq(F:Target(), nil, "not following anyone at first")
    t:eq(F.Choice({ map = 1, cont = 0, wx = 0, wy = 0 }), nil, "no one to follow: the arrow stays on the route")
    t:eq(F.UnitOf("Nobody-Here"), nil, "someone not in your group has no unit")
    t:ok(type(F:MenuItems()) == "table", "menu items build")
end)

ns:Register("test", "target button: hover says what, why, and what's coming", function(t)
    local L = ns.cast.TooltipLines({ spell = "Judgement", reason = "Judge the seal" }, "Judgement",
        { { spell = "Holy Strike", reason = "Holy Strike" }, { spell = "Seal of Righteousness", reason = "No seal, or running out" } }, false)
    t:ok(L[1][1]:find("Judgement", 1, true), "what Flow suggests")
    t:ok(L[2][1]:find("Judge the seal", 1, true), "why")
    local all = {}
    for _, l in ipairs(L) do all[#all + 1] = l[1] end
    local text = table.concat(all, "\n")
    t:ok(text:find("Coming up", 1, true) and text:find("1. Holy Strike", 1, true) and text:find("No seal", 1, true), "the next ones, with reasons")
    local fight = ns.cast.TooltipLines({ spell = "Holy Strike" }, "Judgement", {}, true)
    local says = false
    for _, l in ipairs(fight) do if l[1]:find("key casts Judgement", 1, true) then says = true end end
    t:ok(says, "in a fight: what the key is locked to, when it differs")
end)

ns:Register("test", "buff items: used when you're about to kill a lot, if not on already", function(t)
    local BI = ns.buffItems
    local items = {
        { id = 1, sub = 2, name = "Elixir of Lion's Strength", spell = "Lesser Strength" },
        { id = 2, sub = 6, name = "Rough Sharpening Stone" },
        { id = 3, sub = 6, name = "Rough Weightstone" },
        { id = 4, sub = 5, name = "Roasted Boar Meat" },
    }
    local none = function() return false end
    local all = function() return true end
    local fedOnly = function(spell) return spell ~= BI.WELL_FED end
    t:eq(BI.Pick(items, none, 7, false, true).id, 4, "not Well Fed: the food first, before the elixir")
    local fed = function(spell) return spell == BI.WELL_FED end
    t:eq(BI.Pick(items, fed, 7, false, true).id, 1, "Well Fed: the elixir, when its buff is missing")
    t:eq(BI.Pick(items, all, 7, false, true).id, 2, "buff on: a sharpening stone for a sword")
    t:eq(BI.Pick(items, all, 4, false, true).id, 3, "a weightstone for a mace")
    t:eq(BI.Pick(items, all, 7, true, true), nil, "the weapon has one already, Well Fed: nothing")
    t:eq(BI.Pick(items, fedOnly, 7, true, true).id, 4, "not Well Fed: eat")
    t:ok(BI.FitsWeapon("Minor Wizard Oil", 10), "oil goes on anything")
    t:ok(not BI.FitsWeapon("Rough Sharpening Stone", 4), "no sharpening stone on a mace")
    t:ok(not BI.FitsWeapon("Minor Wizard Oil", 20), "no oil on a fishing pole")
    t:eq(BI.Pick(items, none, 7, false, false), nil, "not about to fight: the stone waits too")
    t:eq(BI.Pick(items, fedOnly, 7, true, false), nil, "not about to fight: no food")
    t:ok(BI.IsBuffFood({ "Roasted Boar Meat", "Use: Restores 294 health over 27 sec. If you spend at least 10 seconds eating you will become well fed." }),
        "food that says Well Fed")
    t:ok(not BI.IsBuffFood({ "Tough Jerky", "Use: Restores 61 health over 18 sec." }), "plain food: no")
    -- "Why is Flow suggesting I eat my fish buff food instead of combat food?"
    local ribsTip = { "Dry Pork Ribs", "Use: Restores 552 health over 21 sec. Must remain seated while eating. "
        .. "If you spend at least 10 seconds eating you will become well fed and gain 6 Stamina and Spirit for 15 min." }
    local fishTip = { "Smoked Sagefish", "Use: Restores 378 health over 21 sec. Must remain seated while eating. "
        .. "If you spend at least 10 seconds eating you will become well fed and gain 3 Mana every 5 seconds for 15 min." }
    local ribs, fish = BI.WellFedGain(ribsTip), BI.WellFedGain(fishTip)
    t:ok(ribs.Stamina == 6 and ribs.Spirit == 6 and ribs.mp5 == nil, "ribs: 6 Stamina and 6 Spirit (not the 10 seconds)")
    t:ok(fish.mp5 == 3 and fish.Stamina == nil, "sagefish: 3 mana every 5 seconds")
    t:eq(BI.WellFedGain({ "Use: ... you will become well fed and increases your Agility by 10 for 10 min." }).Agility, 10,
         "\"increases your Agility by 10\" read too")
    t:eq(next(BI.WellFedGain({ "Use: ... you will become well fed." })), nil, "says no more: nothing known")
    t:eq(BI.FoodScore(fish, "WARRIOR"), 0, "mana food on a warrior: worth nothing")
    t:ok(BI.FoodScore(ribs, "PALADIN") > BI.FoodScore(fish, "PALADIN"), "a paladin: Stamina and Spirit before mana")
    t:ok(BI.FoodScore(ribs, "MAGE") > BI.FoodScore(fish, "MAGE"), "a mage too: Stamina is what keeps you up")
    t:eq(BI.FoodScore({}, "MAGE"), nil, "nothing known: no score")
    -- "Why isn't it spec specific?"
    t:ok(BI.FoodScore(ribs, "PALADIN", "dps") > BI.FoodScore(fish, "PALADIN", "dps"), "Retribution: the ribs")
    t:ok(BI.FoodScore(ribs, "PALADIN", "tank") > BI.FoodScore(fish, "PALADIN", "tank"), "Protection: the ribs")
    t:ok(BI.FoodScore(fish, "PALADIN", "heal") > BI.FoodScore(ribs, "PALADIN", "heal"), "Holy: the sagefish's mana")
    t:ok(BI.FoodScore(fish, "SHAMAN", "heal") > BI.FoodScore(ribs, "SHAMAN", "heal"), "Restoration shaman: mana too")
    t:eq(BI.FoodScore(fish, "WARRIOR", "tank"), 0, "a warrior tank: still nothing from mana")
    local agi = { Agility = 10 }
    t:ok(BI.FoodScore(agi, "DRUID", "tank") > 0 and BI.FoodScore(agi, "DRUID", "heal") == 0,
         "Agility: for a bear, not a tree")
    local bag = {
        { id = 21072, sub = 5, name = "Smoked Sagefish", score = BI.FoodScore(fish, "PALADIN") },
        { id = 2687, sub = 5, name = "Dry Pork Ribs", score = BI.FoodScore(ribs, "PALADIN") },
    }
    t:eq(BI.Pick(bag, none, 7, false, true).id, 2687, "the combat food, though the fish comes first in your bags")
    bag[2].score, bag[1].score = nil, BI.FoodScore(fish, "WARRIOR")
    t:eq(BI.Pick(bag, none, 7, false, true).id, 2687, "a food that doesn't say what it gives, before one worth nothing")
    t:eq(BI.Pick({ bag[1] }, none, 7, true, true), nil, "only food worth nothing to you: not suggested")
    t:ok(not BI.IsBuffFood(nil), "no tooltip yet: no")
    t:eq(BI.CampStep(true, false, false), "sit", "by a campfire without its buffs: sit")
    t:eq(BI.CampStep(true, false, true), "wait", "the minute is running: wait, don't stand up")
    t:eq(BI.CampStep(true, true, false), nil, "camp buffs on: nothing")
    t:eq(BI.CampStep(false, false, false), nil, "no campfire near: nothing")
    t:eq(BI.CampStep(true, false, false, { name = "Camp Tent" }), "place", "a camp object to place: before sitting")
    t:eq(BI.CampStep(true, true, false, { name = "Camp Tent" }), "place", "buffs on: still place it (it adds to them)")
    t:eq(BI.CampStep(true, false, true, { name = "Camp Tent" }), "wait", "the minute is running: never stand up to place one")
    t:eq(BI.CampStep(true, true, false, nil, 100), "sit", "just placed one: sit again so the buffs include it")
    t:eq(BI.PartyKitText({ ["Mia-Realm"] = { kits = { "Camp Tent", "Enchanted Lute" }, at = 95 },
                           Bob = { kits = { "Mana Well" }, at = -100 } }, 100),   -- (Bob: 200 s old; a list counts for 2 minutes)
        "Mia: Camp Tent, Enchanted Lute", "party camp objects: fresh lists only, realm dropped")
    t:eq(BI.PartyKitText({}, 100), nil, "no party lists: nothing")
    -- With your party known: near, elsewhere, unknown, and people who left.
    local lists = { ["Mia-Realm"] = { kits = { "Camp Tent" }, at = 95 }, Bob = { kits = { "Mana Well" }, at = 95 },
                    Zed = { kits = { "Lodestone" }, at = 95 }, Ann = { kits = { "Fish Bowl" }, at = 95 } }
    local roster = { { name = "Mia", near = true }, { name = "Bob", near = false }, { name = "Cid", near = true },
                     { name = "Ann" } }
    local can, rest = BI.PartyKitText(lists, 100, roster)
    t:eq(can, "Ann (place unknown): Fish Bowl; Mia: Camp Tent", "only people near you (or unplaced) count; Zed left the party")
    t:eq(rest, "Bob: elsewhere; Cid: unknown", "out of range: elsewhere; no list: unknown, not 'has nothing'")
    local st = BI.PartyKitStatus(lists, 100, roster, { { name = "Enchanted Lute", state = "placed" }, { name = "Camp Tent", state = "notready" } })
    t:eq(st.text, "2", "the count is the objects near you")
    t:ok(st.tip:find("Bob: elsewhere", 1, true) ~= nil and st.tip:find("Enchanted Lute (placed), Camp Tent (not ready)", 1, true) ~= nil,
        "the tip says who isn't counted and your own objects' state")
    t:eq(BI.PartyKitStatus({ Bob = lists.Bob }, 100, { { name = "Bob", near = false } }), nil, "only someone elsewhere: no icon")
    local pruned = BI.PruneParty({ Mia = {}, ["Zed-Realm"] = {} }, { { name = "Mia" } })
    t:ok(pruned.Mia ~= nil and pruned["Zed-Realm"] == nil, "someone who left: their list is dropped")
    -- Placed is per visit to a fire, not a fixed hour.
    t:eq(BI.CampVisit(3, 100, 130), 3, "back within a minute: the same camp visit")
    t:eq(BI.CampVisit(3, 100, 161), 4, "away over a minute: a new visit")
    t:eq(BI.CampVisit(0, nil, 5), 1, "first fire: visit 1")
    t:eq(BI.KitState(true, true, true), "placed", "placed by you this visit")
    t:eq(BI.KitState(false, true, true), "ready", "have it, usable now")
    t:eq(BI.KitState(false, true, false), "notready", "have it, on cooldown: not ready (not 'placed')")
    t:eq(BI.KitState(false, false, false), nil, "don't have it: not listed")
    -- The minute: counting, done, interrupted.
    t:eq(BI.CampStep(true, false, true), "wait", "sitting, minute running: wait")
    t:eq(BI.CampStep(true, true, false), nil, "minute done, buffs on: nothing more")
    t:eq(BI.CampStep(true, false, false), "sit", "stood up before it ended (no minute, no buffs): sit again")
    t:eq(BI.CampStep(false, false, true), nil, "walked away from the fire: nothing")
    t:eq(BI.HealKind("Minor Healthstone", 0, 0), "healthstone", "a healthstone")
    t:eq(BI.HealKind("Lesser Healing Potion", 0, 1), "potion", "a healing potion")
    t:eq(BI.HealKind("Minor Mana Potion", 0, 1), nil, "a mana potion doesn't heal")
    t:eq(BI.HealKind("Heavy Linen Bandage", 0, 7), "bandage", "a bandage")
    t:eq(BI.HealKind("Tough Jerky", 0, 5, { "Tough Jerky", "Use: Restores 61 health over 18 sec." }), "food", "plain food heals")
    t:eq(BI.HealKind("Refreshing Spring Water", 0, 5, { "Use: Restores 151 mana over 18 sec." }), "drink", "water: a drink (since 0.35.136 the key drinks when you're low on mana)")
    local k, wf = BI.HealKind("Roasted Boar Meat", 0, 5, { "Use: Restores 294 health. ...you will become well fed..." })
    t:eq(k, "food", "Well Fed food that restores health heals too")
    t:eq(wf, true, "...and is marked as Well Fed food")
    t:eq(select(2, BI.HealKind("Tough Jerky", 0, 5, { "Use: Restores 61 health over 18 sec." })), false, "plain food: not marked")
    local foods = { { id = 1, kind = "food", rank = 5 }, { id = 2, kind = "food", rank = 25, buff = true } }
    t:eq(BI.PickFood(foods, true).id, 1, "plain food before Well Fed food, whatever the rank")
    t:eq(BI.PickFood({ foods[2] }, true).id, 2, "only Well Fed food: eat it to heal")
    t:eq(BI.PickFood({ foods[2] }, false), nil, "only Well Fed food, and you keep it for the buff: none")
    t:eq(BI.PickFood(foods, true, function(id) return id ~= 1 end).id, 2, "plain food unusable: the Well Fed food")
    local fishes = { { id = 11, kind = "food", name = "Smoked Sagefish", rank = 20, buff = true, score = 6 },
                     { id = 12, kind = "food", name = "Dry Pork Ribs", rank = 15, buff = true, score = 12 } }
    t:eq(BI.PickFood(fishes, true, nil, true).id, 12, "about to fight: the Well Fed food that's best for you, not the highest rank")
    -- The Well Fed tooltips as the game words them (text only: any language
    -- or character reads these the same).
    local function wellFedOf(text) return BI.WellFedGain({ "Use: Restores 100 health over 21 sec. If you spend at least 10 seconds eating you will become well fed and " .. text }) end
    t:eq(wellFedOf("gain 10 Agility for 15 min.").Agility, 10, "\"gain 10 Agility\"")
    t:eq(wellFedOf("gain 10 Strength for 15 min.").Strength, 10, "\"gain 10 Strength\"")
    t:eq(wellFedOf("gain 10 Intellect for 15 min.").Intellect, 10, "\"gain 10 Intellect\"")
    t:eq(wellFedOf("restore 8 mana per 5 sec. for 15 min.").mp5, 8, "\"8 mana per 5 sec\"")
    t:eq(wellFedOf("gain 6 health every 5 seconds for 15 min.").hp5, 6, "\"6 health every 5 seconds\"")
    local sd = wellFedOf("increase your spell damage by up to 23 and your Spirit by 20 for 15 min.")
    t:ok(sd.SpellDamage == 23 and sd.Spirit == 20, "spell damage up to 23 and Spirit 20 (not Spirit 23)")
    local ap = wellFedOf("increase your Attack Power by 40 and your Spirit by 20 for 15 min.")
    t:ok(ap.AttackPower == 40 and ap.Spirit == 20 and ap.Strength == nil, "Attack Power 40 and Spirit 20")
    local both = wellFedOf("increases your Stamina and Spirit by 12 for 15 min.")
    t:ok(both.Stamina == 12 and both.Spirit == 12, "\"your Stamina and Spirit by 12\": both 12")
    local mixed = wellFedOf("gain 6 Stamina and Spirit and increase your Agility by 10 for 15 min.")
    t:ok(mixed.Stamina == 6 and mixed.Spirit == 6 and mixed.Agility == 10, "one number for two stats, then a \"by 10\"")
    t:eq(wellFedOf("increase healing done by spells by up to 44 for 15 min.").Healing, 44, "healing done by spells")
    t:eq(next(wellFedOf("for 15 min.")), nil, "only the duration: nothing known (not 15 of anything)")
    -- Which stats count: your class's own data where Flow has it, the same
    -- weights gear advice reads (a Retribution paladin's gear weighs no spell
    -- damage, a Holy one's no attack power).
    t:eq(BI.FoodScore({ SpellDamage = 23 }, "PALADIN", "dps"), 0, "Retribution: spell damage food worth nothing (class data)")
    t:ok(BI.FoodScore({ SpellDamage = 23 }, "PALADIN", "heal") > 0, "Holy: spell damage counts")
    t:ok(BI.FoodScore({ AttackPower = 40 }, "PALADIN", "dps") > 0, "Retribution: attack power counts")
    t:eq(BI.FoodScore({ AttackPower = 40 }, "PALADIN", "heal"), 0, "Holy: attack power worth nothing")
    t:eq(BI.FoodScore({ AttackPower = 40 }, "MAGE", "dps"), 0, "no class data yet: a mage's attack power worth nothing")
    t:ok(BI.FoodScore({ SpellDamage = 23 }, "MAGE", "dps") > BI.FoodScore({ SpellDamage = 23 }, "PALADIN", "heal"),
        "a mage's spell damage is worth more than a healer's")
    -- Equal scores: the higher rank, then the lower item ID, whatever the bag order.
    local a = { id = 20, sub = 5, name = "A", score = 5, rank = 10 }
    local b = { id = 10, sub = 5, name = "B", score = 5, rank = 10 }
    local c = { id = 30, sub = 5, name = "C", score = 5, rank = 12 }
    t:eq(BI.BestBuffFood({ a, b, c }).id, 30, "a tie: the higher rank")
    t:eq(BI.BestBuffFood({ c, b, a }).id, 30, "...in any bag order")
    t:eq(BI.BestBuffFood({ a, b }).id, 10, "same score and rank: the lower item ID")
    t:eq(BI.BestBuffFood({ b, a }).id, 10, "...in any bag order")
    t:eq(BI.Pick({ a, b }, none, 7, false, true).id, 10, "the Flow key's pick breaks the tie the same way")
    t:eq(BI.PickFood({ { id = 20, kind = "food", buff = true, score = 5, rank = 10 },
                       { id = 10, kind = "food", buff = true, score = 5, rank = 10 } }, true, nil, true).id, 10,
        "...and the healing food's")
    t:eq(BI.BestBuffFood({ { id = 2, score = 5 }, { id = 1, score = 5, rank = 0 } }).id, 1, "no rank known: counts as 0, then the ID")
    -- /flow rot why: the same order and pick, and why the others aren't.
    local why = BI.FoodWhyText({ a, b, { id = 40, sub = 5, name = "Fish", gain = { mp5 = 3 }, score = 0 } }, "WARRIOR", "dps", false)
    t:ok(why:find("*B (", 1, true) ~= nil and why:find("*A", 1, true) == nil, "why: marks the same pick as the key")
    t:ok(why:find("B (", 1, true) < why:find("A (", 1, true), "why: best first, ties as the pick breaks them")
    t:ok(why:find("Fish (3 mp5; score 0.0; does nothing for you: never suggested)", 1, true) ~= nil, "why: says why a food is skipped")
    t:ok(BI.FoodWhyText({ a }, "WARRIOR", "dps", true):find("you're Well Fed, so none is suggested", 1, true) ~= nil,
        "why: Well Fed already: says none is suggested")
    t:eq(BI.FoodWhyText({}, "WARRIOR", "dps", false), "Well Fed food: none in your bags", "why: no Well Fed food")
    local heal = { { id = 1, kind = "potion", rank = 15 }, { id = 2, kind = "healthstone", rank = 10 },
                   { id = 3, kind = "bandage", rank = 5 }, { id = 4, kind = "bandage", rank = 20 } }
    t:eq(BI.PickEmergency(heal).id, 2, "in a fight: the healthstone before the potion")
    t:eq(BI.PickEmergency(heal, function(id) return id ~= 2 end).id, 1, "healthstone on cooldown: the potion")
    t:eq(BI.PickKind(heal, "bandage").id, 4, "best bandage first by default")
    t:eq(BI.PickKind(heal, "bandage", true).id, 3, "lowest bandage first when you choose it")
    -- The smallest bandage that fills you (0.35.134): a big one on a
    -- scratch wastes most of it.
    t:eq(BI.BandageHeal("Linen Bandage", { "Use: Heals 70 damage over 6 sec." }), 70, "from the tooltip")
    t:eq(BI.BandageHeal("Heavy Wool Bandage", {}), 301, "else by its name")
    t:eq(BI.BandageHeal("Mystery Rag", nil), nil, "unknown: can't tell")
    local rolls = { { id = 1, kind = "bandage", rank = 5, name = "Linen Bandage" },
                    { id = 2, kind = "bandage", rank = 15, name = "Wool Bandage" },
                    { id = 3, kind = "bandage", rank = 25, name = "Heavy Wool Bandage" } }
    local function healOf(it) return BI.BandageHeal(it.name) end
    t:eq(BI.PickBandage(rolls, 50, false, nil, healOf).id, 1, "50 missing: Linen fills it")
    t:eq(BI.PickBandage(rolls, 150, false, nil, healOf).id, 2, "150 missing: Wool, not Heavy Wool")
    t:eq(BI.PickBandage(rolls, 900, false, nil, healOf).id, 3, "more than any fills: the biggest")
    t:eq(BI.PickBandage(rolls, nil, false, nil, healOf).id, 3, "can't tell how hurt: the biggest, as before")
    t:eq(BI.PickBandage(rolls, 900, true, nil, healOf).id, 1, "lowest first, your choice: the lowest")
    t:eq(BI.PickBandage(rolls, 50, false, function(id) return id ~= 1 end, healOf).id, 2, "Linen not usable: the next that fills")
    t:near(BI.MissingHealth(nil, 1000, 15, 60), 250, 0.01, "health hidden: Flow's estimate of max health")
    t:eq(BI.MissingHealth(700, 1000, 15, 60), 300, "health shown: exact")
    t:eq(BI.MissingHealth(nil, nil, 15, 60), nil, "max hidden too: can't tell")
    t:eq(table.concat(BI.Order(nil), ","), "bandage,food,heal", "default order: bandage, food, heal spell")
    t:eq(table.concat(BI.Order("heal,bandage"), ","), "heal,bandage,food", "your order, missing steps added")
    t:eq(table.concat(BI.Order("food,food,junk"), ","), "food,bandage,heal", "repeats and unknown words dropped")
    t:eq(BI.PartyKitStatus({}, 100), nil, "no party objects: no camp icon")
    t:eq(BI.PartyKitStatus({ Mia = { kits = { "Camp Tent", "Enchanted Lute" }, at = 95 } }, 100).text, "2",
        "camp icon: how many objects your group can add")
    t:ok(BI.IsWeaponBuff("Rough Sharpening Stone"), "a stone by its name")
    t:ok(BI.IsWeaponBuff("Coarse Weightstone"), "a weightstone by its name")
    t:ok(BI.IsWeaponBuff("Minor Wizard Oil") and BI.IsWeaponBuff("Frost Oil"), "weapon oils by name")
    t:ok(not BI.IsWeaponBuff("Oily Blackmouth") and not BI.IsWeaponBuff("Fire Oil")
        and not BI.IsWeaponBuff("Oil of Immolation"), "fish and reagents aren't weapon oils")
    t:ok(not BI.IsWeaponBuff(nil), "no name yet: no")
    t:ok(BI.WeaponFirst(false, 100, 100), "out of combat, no enemy, healthy: the stone goes before the rotation's buff")
    t:ok(not BI.WeaponFirst(true, 100, 100), "enemy targeted: the opener first")
    t:ok(not BI.WeaponFirst(false, 40, 100), "under half health: the heal first")
    -- WoW: Forever hides your health (0.35.125: testing it errored, so the
    -- stone never showed): Flow's own estimate of how hurt you are decides.
    t:ok(BI.WeaponFirst(false, nil, nil, false), "health hidden, not hurt by Flow's estimate: the stone first")
    t:ok(not BI.WeaponFirst(false, nil, nil, true), "health hidden and hurt: the heal first")
    t:ok(not BI.WeaponFirst(true, nil, nil, false), "health hidden, enemy targeted: the opener first")
    t:ok(BI.WeaponFirst(false, 100, 0, false), "max health 0 (not known): Flow's estimate")
    t:ok(BI.WeaponFirst(false, nil, nil), "health the client hides: counts as fine (no error)")
    t:ok(ns:Get("action", "buff:item").order < ns:Get("action", "bag:learn").order, "before learning a recipe in your bags")
    t:ok(BI.Killing({ at = true, goal = { key = "500:1", kind = "kill" } }) or IsResting(), "at a kill step: yes")
    t:ok(not BI.Killing({ at = false, goal = { key = "500:done", kind = "turnin" } }, GetTime() + 1000), "walking to a turn-in, no fight lately: no")
end)

