    t:eq(C.UnitFor({ spell = "Mark of the Wild", kind = "buff", unit = "party1" }), "party1", "a group buff: on them")
    t:eq(C.UnitFor({ spell = "Wrath", kind = "damage" }), nil, "an attack: your target")
