ns:Register("test", "queue: four things on one key (Ctrl, Shift, Alt)", function(t)
    -- The player's design: the key's spell big, three smaller beside it with
    -- CTRL / SHIFT / ALT above them; a modifier swaps its spell in.
    local Q = ns.queue
    if not Q then t:ok(false, "Queue.lua not loaded") return end
    local wrath = { spell = "Wrath", kind = "damage" }
    -- A fight, or an enemy targeted.
    local q = Q.Slots(wrath, { heal = "Rejuvenation", ctrlSpell = "Moonfire", altSpell = "Entangling Roots" })
    t:eq(q.key, wrath, "the key: its own spell")
    t:eq(q.ctrl and q.ctrl.spell, "Moonfire", "Ctrl: your second attack")
    t:eq(q.shift and q.shift.spell, "Rejuvenation", "Shift: your heal")
    t:eq(q.shift and q.shift.unit, "player", "on you")
    t:eq(q.alt and q.alt.spell, "Entangling Roots", "Alt: the spell that holds your target")
    q = Q.Slots(wrath, { heal = "Rejuvenation", ctrlSpell = "Moonfire", altSpell = "Entangling Roots", emergency = "item:5512" })
    t:eq(q.alt and q.alt.item, "item:5512", "a healthstone you carry takes Alt")
    t:eq(Q.Slots(wrath, {}).ctrl, nil, "nothing known for it: the slot stays empty")
    -- A friendly target and a heal or buff on the key: Ctrl casts it on them.
    local buff = { spell = "Mark of the Wild", kind = "buff" }
    q = Q.Slots(buff, { friend = true, ctrlSpell = "Moonfire" })
    -- (With no heal on Shift, the nearest icon is Shift's: 0.35.227.)
    t:eq(q.shift.spell .. "@" .. tostring(q.shift.unit), "Mark of the Wild@target", "friend targeted: the same buff on them")
    t:eq(Q.Slots(buff, { ctrlSpell = "Moonfire" }).shift.spell, "Moonfire", "no friend targeted: the second attack")
    -- Hurt between fights: the other ways to heal up, in your order.
    local bandage = { type = "item", item = "item:3531", kind = "heal" }
    local food = { type = "item", item = "item:117", kind = "heal" }
    local big = { spell = "Healing Touch", kind = "heal" }
    q = Q.Slots(bandage, { heal = "Rejuvenation", ctrlSpell = "Moonfire", options = { bandage, food, big } })
    t:eq(q.ctrl, food, "bandage on the key: food on Ctrl")
    t:eq(q.alt, big, "and the big heal on Alt (Shift has the quick one)")
    q = Q.Slots(bandage, { heal = "Healing Touch", ctrlSpell = "Moonfire", options = { bandage, big } })
    t:eq(q.ctrl.spell, "Moonfire", "an option Shift already casts isn't given a second slot")
    q = Q.Slots(bandage, { heal = "Rejuvenation", emergency = "item:5512", options = { bandage, food, big } })
    t:eq(q.alt.item, "item:5512", "the healthstone keeps Alt")
    -- What a class's fights use.
    local def = { fightKeys = function() return { ctrl = { "Moonfire" }, alt = { "Entangling Roots", "War Stomp" } } end }
    local c, a = Q.FightSpells(def, function(sp) return sp ~= "Entangling Roots" end, "Wrath")
    t:eq(c, "Moonfire", "Ctrl: the first you know")
    t:eq(a, "War Stomp", "Alt: Roots not learned yet, so the next one")
    t:eq((Q.FightSpells(def, function() return true end, "Moonfire")), nil, "never the key's own spell")
    local plain = { priority = { { spell = "Seal", kind = "buff", target = true }, { spell = "Attack", target = true },
        { spell = "Smite", target = true }, { spell = "Strike", target = true } } }
    t:eq((Q.FightSpells(plain, function() return true end, "Smite")), "Strike", "a class without fightKeys: its next attack")
    for _, class in ipairs({ "DRUID", "PALADIN" }) do
        local rot = ns:Get("rotation", class)
        local keys = rot and rot.fightKeys and rot.fightKeys(ns.rotation)
        t:ok(keys and type(keys.ctrl) == "table" and #keys.ctrl > 0, class .. ": says what Ctrl + key casts in a fight")
    end
    -- Which press does what Flow advises.
    local slots = { key = wrath, ctrl = { spell = "Moonfire" }, shift = { spell = "Rejuvenation", kind = "heal" }, alt = { item = "item:5512" } }
    t:eq(Q.AdviceSlot({ spell = "Moonfire" }, slots), "ctrl", "Moonfire advised: Ctrl")
    t:eq(Q.AdviceSlot({ spell = "Healing Touch", kind = "heal" }, slots), "shift", "any heal advised: Shift heals")
    t:eq(Q.AdviceSlot({ item = "item:5512", kind = "emergency" }, slots), "alt", "the healthstone: Alt")
    t:eq(Q.AdviceSlot({ spell = "War Stomp" }, slots), nil, "on none of them: your bar (the corner icon)")
    -- One modifier at a time.
    t:eq(Q.HeldMod(true, false, false), "ctrl", "Ctrl")
    t:eq(Q.HeldMod(false, true, false), "shift", "Shift")
    t:eq(Q.HeldMod(false, false, true), "alt", "Alt")
    t:eq(Q.HeldMod(true, true, false), "more", "Ctrl and Shift together: the fifth press (0.35.194)")
    t:eq(Q.HeldMod(true, false, true), nil, "any other two: none")
    t:eq(Q.HeldMod(true, true, true), nil, "all three: none")
    t:eq(Q.HeldMod(false, false, false), nil, "none")
    -- Holding one: the big icon becomes its spell.
    local v, m = Q.ModView(wrath, slots, "ctrl", true)
    t:eq(v.spell, "Moonfire", "Ctrl held: Moonfire is the big icon")
    t:eq(m, "ctrl", "and it says which modifier")
    t:eq(v.label, "CTRL + key: Moonfire", "labelled")
    v, m = Q.ModView(nil, slots, "shift", false)
    t:ok(v == nil and m == nil, "nothing to press, not in a fight: nothing swaps in")
    v, m = Q.ModView(wrath, slots, nil, true)
    t:ok(v == wrath and m == nil, "no modifier: the key's spell")
    -- When the three icons show.
    t:ok(Q.Shows(nil, true, false, nil), "in a fight")
    t:ok(Q.Shows(wrath, false, true, nil), "an enemy targeted")
    t:ok(Q.Shows(bandage, false, false, nil), "healing up")
    t:ok(not Q.Shows(buff, false, false, nil), "idle: not shown (no clutter)")
    t:ok(Q.Shows(buff, false, false, "shift"), "a modifier held: shown, to see what it casts")
    -- A slot that would only repeat the big icon isn't drawn.
    t:ok(ns.QueueDup({ spell = "Rejuvenation", unit = "player", kind = "heal" }, { spell = "Rejuvenation", kind = "heal" }), "the same heal as the key: once")
    t:ok(not ns.QueueDup({ spell = "Mark of the Wild", unit = "target", kind = "buff" }, buff), "the same buff on your target: a different press")
    t:ok(not ns.QueueDup({ spell = "Moonfire" }, wrath), "another spell: drawn")
end)

ns:Register("test", "queue: modifier presses are set so the game finds them", function(t)
    -- With Shift held the game looks for "shift-type-heal", then "*type-heal",
    -- then the key's own "type": never plain "type-heal". Until 0.35.162 the
    -- plain one was set, so Shift + key cast the key's spell, not your heal.
    local C = ns.cast
    local kind, what, unit = C.SlotAttributes({ spell = "Moonfire", kind = "damage" })
    t:eq(kind .. "/" .. what .. "/" .. tostring(unit), "spell/Moonfire/target", "an attack: on your target, said outright")
    kind, what, unit = C.SlotAttributes({ spell = "Rejuvenation", kind = "heal", unit = "player" })
    t:eq(kind .. "/" .. what .. "/" .. tostring(unit), "spell/Rejuvenation/player", "your heal: on you")
    kind, what, unit = C.SlotAttributes({ spell = "Mark of the Wild", kind = "buff", unit = "target" })
    t:eq(kind .. "/" .. what .. "/" .. tostring(unit), "spell/Mark of the Wild/target", "a buff for your friendly target: on them")
    kind, what = C.SlotAttributes({ type = "item", item = "item:5512", kind = "emergency" })
    t:eq(kind .. "/" .. what, "item/item:5512", "a healthstone: as an item")
    t:eq((C.SlotAttributes(nil)), nil, "nothing: nothing set")
    t:eq(table.concat(C.QueueLines({ ctrl = { spell = "Moonfire", kind = "damage" },
            shift = { spell = "Rejuvenation", unit = "player", kind = "heal" }, alt = { item = "item:5512" } }), " | "),
        "Ctrl + key: Moonfire | Shift + key: Rejuvenation on you | Alt + key: your healthstone or healing potion", "the tooltip's lines")
    local b = _G.FlowCastButton
    if not b or InCombatLockdown() then t:ok(true, "(no Flow key yet, or in a fight)") return end
    local slots = C:Slots()
    for slot, name in pairs({ ctrl = "ctrl", shift = "heal", alt = "emerg" }) do
        if slots[slot] then
            local set = b:GetAttribute("*type-" .. name)
            t:ok(set == "spell" or set == "item", slot .. ": set with the * prefix, found whatever modifier is held")
            t:eq(b:GetAttribute("type-" .. name), nil, slot .. ": no plain attribute left behind")
            t:ok(set == "item" or b:GetAttribute("*unit-" .. name) ~= nil, slot .. ": with its own unit")
        end
    end
    t:eq(b:GetAttribute("ctrl-type1"), "macro", "Ctrl + click with the mouse still only moves the button")
    t:ok(type(ns.perf.stats["target button: queue"]) == "table", "the queue's upkeep is timed (/flow perf)")
end)

ns:Register("test", "taint: the distance question is asked in a fight only about an enemy", function(t)
    -- 0.35.159 was "blocked from an action only available to the Blizzard UI":
    -- the cast recorder asked how far the target was on every cast in a
    -- fight, also with a friend, yourself or nothing targeted, which the game
    -- forbids there.
    local E = ns.rotation
    t:ok(E.MayAskDistance(false, true, false, false), "out of a fight: a friend is fine")
    t:ok(E.MayAskDistance(true, true, true, false), "in a fight: an enemy you can attack")
    t:ok(not E.MayAskDistance(true, true, false, false), "in a fight, a friend (or yourself): not asked")
    t:ok(not E.MayAskDistance(true, true, true, true), "in a fight, a corpse: not asked")
    t:ok(not E.MayAskDistance(true, false, false, false), "nobody targeted: not asked")
    t:ok(not E.MayAskDistance(false, false, false, false), "nobody targeted, out of a fight: not asked")
    if not InCombatLockdown() then
        t:ok(pcall(E.Near, "target"), "asking about your target now: no error")
    end
end)

ns:Register("test", "heals: hit a lot, a heal that lands at once; Shift + key casts the same", function(t)
    -- From the player's casts (0.35.163): 6 heals in fights, each a Healing
    -- Touch where Flow advised Rejuvenation; 48 Rejuvenation prompts ignored.
    local E, C = ns.rotation, ns.cast
    local ms = { ["Healing Touch"] = 2500, Rejuvenation = 0, Regrowth = 2000 }
    local function castMs(sp) return ms[sp] end
    local heals, hots = { "Regrowth", "Healing Touch", "Rejuvenation" }, { "Rejuvenation" }
    local function all() return true end
    t:eq(E.DirectHeal(heals, hots, all, castMs), "Regrowth", "the fastest heal that lands at once")
    t:eq(E.DirectHeal(heals, hots, function(sp) return sp ~= "Regrowth" end, castMs), "Healing Touch", "Regrowth not learned: Healing Touch, not the heal over time")
    t:eq(E.DirectHeal(heals, hots, function(sp) return sp == "Rejuvenation" end, castMs), "Rejuvenation", "only a heal over time known: that one")
    t:eq(E.DirectHeal(heals, nil, all, castMs), "Rejuvenation", "a class with no heals over time listed: simply the fastest")
    t:eq(E.DirectHeal(heals, hots, function() return false end, castMs), nil, "none usable: none")
    t:eq(C.HealFor({ heals = heals, hots = hots }, function(sp) return sp ~= "Regrowth" end, castMs), "Healing Touch",
        "Shift + key: the same heal Flow advises when you're hit a lot")
end)

ns:Register("test", "press audit: does the key cast what the icon shows?", function(t)
    -- The player: "when I hit the keybind it casts Wrath, sometimes even
    -- when it was showing Moonfire". Each press is now noted with what the
    -- icon showed, what the key was set to, and what was cast.
    local Au = ns.audit
    if not Au then t:ok(false, "Audit.lua not loaded") return end
    t:ok(Au.Agree("Wrath", "Wrath"), "icon and key the same: agree")
    t:ok(not Au.Agree("Moonfire", "Wrath"), "icon Moonfire, key set to Wrath: they disagree")
    t:ok(Au.Agree(nil, "Wrath") and Au.Agree("Wrath", nil), "nothing to compare on one side: not a disagreement")
    t:eq(Au.Judge({ icon = "Moonfire", set = "Moonfire" }, "Moonfire"), "ok", "cast what the icon showed")
    t:eq(Au.Judge({ icon = "Moonfire", set = "Wrath" }, "Wrath"), "key", "cast the key's spell, not the icon's")
    t:eq(Au.Judge({ icon = "Moonfire", set = "Wrath" }, "Thorns"), "other", "something else altogether")
    t:eq(Au.Judge({ icon = "Moonfire", set = "Wrath" }, nil), "nothing", "no cast followed")
    local line = Au.Line({ at = "00:12:31", icon = "Moonfire", set = "Wrath", cast = "Wrath", combat = true, sinceFight = 0.3,
        advice = "Moonfire", lockedTo = "Wrath", shot = true })
    t:eq(line, "00:12:31 icon Moonfire, key set to Wrath, cast Wrath; in a fight for 0.3 s; advice Moonfire; locked to Wrath; screenshot",
        "a kept press reads plainly")
    local report = table.concat(Au.Report({ counts = { ok = 8, key = 1, nothing = 2 }, disagreed = 1,
        list = { { at = "00:12:31", icon = "Moonfire", set = "Wrath", cast = "Wrath", combat = false } } }), "\n")
    t:ok(report:find("11 key presses: 8 cast what the icon showed, 1 cast the key's spell while the icon showed another", 1, true) ~= nil, "the tally: " .. report)
    t:ok(report:find("icon Moonfire, key set to Wrath, cast Wrath; not in a fight", 1, true) ~= nil, "and each disagreement")
    t:ok(Au.Report({})[1]:find("no key presses", 1, true) ~= nil, "nothing yet: says so")
    -- A press goes into the tally (no screenshot in a test; your own tally put back after).
    local d = ns.db.audit
    local list, counts, disagreed, shots = d.list, d.counts, d.disagreed, d.shots
    d.list, d.counts, d.disagreed, d.shots = {}, {}, nil, false
    Au._Forget()   -- (a press left waiting, yours or an earlier run's, isn't this test's)
    local realLog = ns.Log
    ns.Log = function() end   -- (the test's presses stay out of your log)
    Au.Press("Moonfire", "Wrath", true, 0.2, "Wrath")
    t:eq(d.disagreed, 1, "a press with the icon on Moonfire and the key on Wrath is kept")
    t:eq(d.list[1] and d.list[1].icon, "Moonfire", "with what the icon showed")
    t:eq(d.list[1] and d.list[1].shot, nil, "screenshots off: none taken")
    Au.Press("Wrath", "Wrath", true, 1.5, "Wrath")
    t:eq(d.disagreed, 1, "a press where they agree isn't")
    t:eq(d.counts.nothing, 1, "the press before it got no cast: counted so")
    Au._Forget()
    local leftover = {}
    d.counts = leftover
    Au.Press("Wrath", "Wrath", false)
    t:eq(next(leftover), nil, "and the test's last press isn't counted into the next one")
    Au._Forget()
    ns.Log = realLog
    d.list, d.counts, d.disagreed, d.shots = list, counts, disagreed, shots
    t:ok(type(ns.commands.audit) == "function" and type(ns.commands.mark) == "function", "/flow audit and /flow mark")
end)

ns:Register("test", "click: Flow Talents takes the points only after you confirm, all or none", function(t)
    local T = ns.talents
    if not T then t:ok(false, "Talents.lua not loaded") return end
    local byName = { Claws = { id = 11 }, Hide = { id = 12 } }
    local list = { { name = "Claws" }, { name = "Claws" }, { name = "Hide" } }
    local calls = {}
    local function api(refuse, saves)
        calls = {}
        return {
            purchase = function(id) calls[#calls + 1] = "buy " .. id; return id ~= refuse end,
            commit = function() calls[#calls + 1] = "save"; return saves ~= false end,
            rollback = function() calls[#calls + 1] = "undo" end,
        }
    end
    local taken, problem = T.TakeWith(list, byName, api())
    t:eq(taken, 3, "all three taken")
    t:eq(problem, nil, "no problem")
    t:eq(table.concat(calls, ", "), "buy 11, buy 11, buy 12, save", "each point, then saved once")
    taken, problem = T.TakeWith(list, byName, api(12))
    t:eq(taken, 0, "one refused: none kept")
    t:ok(problem and problem:find("Hide", 1, true) ~= nil, "it says which: " .. tostring(problem))
    t:eq(calls[#calls], "undo", "what was staged is undone")
    taken = (T.TakeWith(list, byName, api(nil, false)))
    t:eq(taken, 0, "the game wouldn't save: none kept")
    t:eq(calls[#calls], "undo", "undone")
    taken, problem = T.TakeWith({ { name = "Nonsense" } }, byName, api())
    t:ok(taken == 0 and problem:find("no talent called Nonsense", 1, true) ~= nil, "a talent the game doesn't have: nothing bought")
    t:eq(#calls, 0, "and nothing asked of the game")
    t:eq((T.TakeWith({}, byName, api())), 0, "nothing to take: nothing")
    -- The view hands its gold picks to the button; the button only ASKS.
    local nodes = { { name = "Claws", x = 100, y = 10, rank = 0, max = 5 } }
    local v = T.View(nodes, 2, { name = "Test", order = { { "Claws", 5 } } }, 11)
    t:eq(#v.take, 2, "two points to spend: two picks for the button")
    t:eq(#T.View(nodes, 0, { name = "Test", order = { { "Claws", 5 } } }, 11).take, 0, "no points: nothing to take")
    T:Show()
    local f = T._Frame()
    if f and f.take then
        local asked
        with(T, "Ask", function(l) asked = l end, function()
            f.takeList = v.take
            t:ok(pcall(f.take:GetScript("OnClick"), f.take), "click: Take these points")
        end)
        t:eq(asked, v.take, "the click asks first, with the gold picks (nothing is spent by the click itself)")
        f:Hide()
    end
    t:ok(type(T.CanTake()) == "boolean", "knows whether this client lets an add-on set talents")
end)

ns:Register("test", "review fixes for pull requests 18 to 22", function(t)
    local E, N, SP = ns.rotation, ns.nav, ns.skillPlan
    -- 20: Cannibalize is the first way to heal up, and the others still
    -- follow it in the queue's list (returning early left the list empty).
    local keep = { busy = E.RecoverBusy, fine = E.HealthFine, hd = E.HealDecision, lh = E.LowHealthHeal,
                   eh = E.EarlyHeal, can = E.CannibalizeStep, mounted = E.Mounted, hurt = E.hurt }
    local r = ns.db.rotation
    local keepHeal = r.recoverHeal
    E.RecoverBusy = function() return false end
    E.HealthFine = function() return false end
    E.HealDecision = function() return nil end
    E.LowHealthHeal = function() return nil end
    E.EarlyHeal = function() return { spell = "Fast Heal", kind = "heal" } end
    E.CannibalizeStep = function() return { spell = "Cannibalize", kind = "heal" } end
    E.Mounted = function() return false end
    E.hurt, r.recoverHeal = E.HURT.outBig, nil
    local ok, options = pcall(E.RecoverOptions, E, { inCombat = false, maxHp = 0, hp = 0, hpPct = 1 }, { heals = { "Fast Heal" } })
    E.RecoverBusy, E.HealthFine, E.HealDecision, E.LowHealthHeal = keep.busy, keep.fine, keep.hd, keep.lh
    E.EarlyHeal, E.CannibalizeStep, E.Mounted, E.hurt, r.recoverHeal = keep.eh, keep.can, keep.mounted, keep.hurt, keepHeal
    t:ok(ok, "listing the ways to heal up: no error" .. (ok and "" or (": " .. tostring(options))))
    if ok then
        t:eq(options[1] and options[1].spell, "Cannibalize", "Cannibalize first")
        local heal
        for _, s in ipairs(options) do if s.spell == "Fast Heal" then heal = true end end
        t:ok(heal, "and the heal spell is still offered after it")
    end
    -- 19: the Artisan quests ask for the cap itself (225), not 25 below it.
    local quest = SP.Tier("Cooking", 210, 225, 60)
    t:eq(quest and quest.how, "quest", "Artisan Cooking: a quest teaches it")
    t:eq(quest and quest.skill, 225, "which asks for skill 225")
    t:ok(quest and not quest.ready, "at 210 it isn't on the route yet")
    t:ok(SP.Tier("Cooking", 225, 225, 60).ready, "at 225 it is")
    local trainer = SP.Tier("Mining", 130, 150, 60)
    t:eq(trainer and trainer.skill, 125, "a trainer's tier: from 25 below the cap, as before")
    -- 20: the planner's flight times, cheap per plan.
    with(ns.db, "flights", { One = { cont = 0, wx = 0, wy = 0 } }, function()
        t:eq(N.PlanAir(), nil, "one flight master known: nothing to fly, the planner isn't asked")
    end)
    with(ns.db, "flights", { One = { cont = 0, wx = 0, wy = 0 }, Two = { cont = 0, wx = 3000, wy = 0 } }, function()
    with(ns.db, "flightTimes", {}, function()
        local air = N.PlanAir()
        t:ok(type(air) == "function", "two known: an answer for this plan")
        local a, b = { cont = 0, wx = 100, wy = 0 }, { cont = 0, wx = 2900, wy = 0 }
        local first = air and air(a, b)
        t:ok(type(first) == "number" and first > 200, "walk to one, fly, walk from the other")
        t:eq(air and air(a, b), first, "asked again: the same (worked out once)")
        t:eq(air and air(a, { cont = 0, wx = 200, wy = 0 }), nil, "the same flight master at both ends: no flight")
    end) end)
    -- 22: a step's tool counts by its name too (other item IDs on Forever).
    local D = ns.disposition
    with(ns.api, "Count", function() return 0 end, function()
        with(D, "EachBagItem", function(_, fn) fn(0, 1, "|cffffffff|Hitem:999999::|h[Runed Copper Rod]|h|r") end, function()
            t:ok(SP._haveStepTool(6218), "a Runed Copper Rod with another item ID still counts")
            t:ok(not SP._haveStepTool(6339), "no Runed Silver Rod in your bags: missing")
        end)
    end)
    t:eq(D:ToolProfession(999999, "Runed Copper Rod"), "Enchanting", "and it's kept as an enchanter's tool")
    -- 20: "Only the dungeon run" is a tick of its own, not a fourth route.
    local it = ns.dungeons and ns.dungeons.RouteItem and select(2, pcall(ns.dungeons.RouteItem, ns.dungeons))
    if type(it) == "table" then
        t:ok(it.radio == nil, "the dungeon run: a tick under the route's ticks")
        t:ok(it.text:find("Only the dungeon run", 1, true) ~= nil, "named for what it does")
    end
    t:ok(ns:Get("charData", "nav.dungeonOnly") ~= nil, "and it's each character's own")
end)

