    t:eq(B(train, N.TRAIN_NEAR + 40, {}, false), nil, "a hundred yards off (killing mobs): fitted into the route")
    t:eq(B({ key = "train:class", cost = 500 }, 30, {}, false), nil, "can't pay for any of it: not now")
