ns:Register("test", "choices: your casts set beside Flow's advice", function(t)
    -- The player: compare what the target button advised with what was cast,
    -- and find the reason for the differences before changing the rotation.
    local C, E = ns.choices, ns.rotation
    if not C then t:ok(false, "Choices.lua not loaded") return end
    t:eq(C.Kind("Wrath", "Wrath", "Wrath"), "advice", "cast what Flow advised")
    t:eq(C.Kind("Wrath", "Moonfire", "Wrath"), "key", "pressed the key while the advice was a bar spell")
    t:eq(C.Kind("Entangling Roots", "Wrath", "Wrath"), "own", "something else: your own choice")
    t:eq(C.Kind("Healing Touch", nil, "Wrath"), "own", "Flow advised nothing: your own choice too")
    -- The situation, as tags.
    local tags = table.concat(C.Tags({ opening = true, moving = true, onYou = 1, near = false, hurt = 12, mana = 0.2,
        targetHp = 0.9, attackers = 2, adviceRange = false, adviceCooldown = 4 }), ", ")
    for _, want in ipairs({ "opening cast", "moving", "enemy on you", "target far", "hurt", "low mana",
                            "target healthy", "several enemies", "advice out of range", "advice on cooldown" }) do
        t:ok(tags:find(want, 1, true) ~= nil, "tag: " .. want)
    end
    t:eq(#C.Tags({ onYou = 0.5 }), 0, "nothing known: no tags")
    -- The tally.
    local data = { list = {} }
    t:eq(C.Note(data, "Wrath", "Wrath", "Wrath", {}, 1), nil, "followed: counted, not a choice")
    local key
    for i = 1, 4 do key = C.Note(data, "Entangling Roots", "Wrath", "Wrath", i <= 3 and { "enemy on you", "moving" } or { "moving" }, 10 + i) end
    C.Note(data, "Wrath", "Moonfire", "Wrath", { "opening cast" }, 20)
    t:eq(data.casts, 6, "every cast counted")
    t:eq(data.kinds.advice .. "/" .. data.kinds.key .. "/" .. data.kinds.own, "1/1/4", "by kind")
    t:eq(data.list[key].n, 4, "the same choice adds up")
    t:eq(C.TagLine(data.list[key]), "moving 100%, enemy on you 75%", "its commonest situations")
    -- Fights with the choice beside fights without it.
    local fights = {}
    for i = 1, 3 do fights[#fights + 1] = { type = "normal", duration = 20, v = 12, own = { [key] = 1 } } end
    for i = 1, 4 do fights[#fights + 1] = { type = "normal", duration = 25, v = 10 } end
    fights[#fights + 1] = { type = "elite", duration = 90, v = 3 }   -- another kind of fight: not compared
    local o = C.Outcome(key, fights, function(f) return f.v end)
    t:ok(o and o.with == 3 and o.without == 4, "3 fights with it, 4 of the same type without")
    t:near(o and o.speedWith / o.speedWithout or 0, 1.2, 0.001, "20% faster with it")
    t:eq(C.Outcome(key, { fights[1], fights[4] }, function(f) return f.v end), nil, "too few fights: no verdict")
    local report = table.concat(C.Report(data, fights, function(f) return f.v end), "\n")
    t:ok(report:find("6 casts in fights: 17% what Flow advised, 17% your key while it advised a bar spell, 67% your own choice", 1, true) ~= nil,
        "the shares: " .. report)
    t:ok(report:find("Entangling Roots when Flow advised Wrath: 4x. Mostly: moving 100%, enemy on you 75%. Kill speed +20% in the 3 fights with it (4 without)", 1, true) ~= nil,
        "a choice with its situations and what it did to kill speed")
    t:ok(report:find("Wrath when Flow advised Moonfire: 1x", 1, true) ~= nil, "the key instead of bar advice is listed apart")
    -- Only so many kinds are kept: the rarest go.
    for i = 1, 5 do C.Note(data, "Spell " .. i, "Wrath", "Wrath", {}, 30 + i) end
    t:eq(C.Trim(data, 3), 4, "over the limit: the rarest dropped")
    t:ok(data.list[key] ~= nil, "the common one stays")
    -- An instant is judged against the advice from a moment before it landed.
    t:eq(E.AdviceBack("Wrath", "Moonfire", 10.0, 10.1, 0.3), "Moonfire", "advice changed 0.1 s ago: what showed when you pressed")
    t:eq(E.AdviceBack("Wrath", "Moonfire", 10.0, 11.0, 0.3), "Wrath", "changed a second ago: the current advice")
    t:eq(E.AdviceBack("Wrath", nil, nil, 5, 0.3), "Wrath", "never changed: the current advice")
    t:ok(type(ns.commands.choices) == "function", "/flow choices")
end)

ns:Register("test", "route kinds: one tick per kind of step", function(t)
    -- 0.35.157: in place of Quests only / Optimal / Completionist + Professions.
    local N = ns.nav
    local keys = {}
    for _, k in ipairs(N.Kinds()) do keys[#keys + 1] = k.key end
    t:ok(table.concat(keys, ","):find("^quests,newQuests,lowQuests,training,professions,town") ~= nil, "the kinds, in menu order (later ones, the bank and flight paths, after them)")
    -- Which kind a step is (you're level 20 here).
    t:eq(N.KindOf({ key = "748:2", provider = "questie" }, 20), "quests", "a quest objective: current quests")
    t:eq(N.KindOf({ key = "748:done" }, 20), "quests", "its turn-in too")
    t:eq(N.KindOf({ key = "pickup:5", level = 18, provider = "pickups" }, 20), "newQuests", "a quest to pick up at your level")
    t:eq(N.KindOf({ key = "pickup:6", level = 12, provider = "pickups" }, 20), "lowQuests", "one 8 levels under you: low-level")
    t:eq(N.KindOf({ key = "train:class", provider = "errands" }, 20), "training", "class trainer")
    t:eq(N.KindOf({ key = "weapon:Staves", provider = "weaponskill" }, 20), "training", "weapon master")
    t:eq(N.KindOf({ key = "train:Mining", provider = "errands" }, 20), "professions", "profession trainer")
    t:eq(N.KindOf({ key = "skill:Fishing", provider = "skillplan" }, 20), "professions", "skill-up step")
    t:eq(N.KindOf({ key = "repair", provider = "repair" }, 20), "town", "repair")
    t:eq(N.KindOf({ key = "run:WC", provider = "dungeon" }, 20), nil, "a dungeon run you prepared: always on")
    t:eq(N.KindOf({ key = "party:1", provider = "party" }, 20), nil, "party steps: always on")
    -- Only ticked kinds stay; steps no kind claims always do.
    local list = {
        { key = "748:2", provider = "questie" }, { key = "pickup:5", level = 18 }, { key = "pickup:6", level = 12 },
        { key = "train:Mining", provider = "errands" }, { key = "run:WC", provider = "dungeon" },
    }
    local on = { quests = true, lowQuests = true }
    local out = N.FilterKinds(list, function(k) return on[k] == true end, 20)
    local got = {}
    for _, g in ipairs(out) do got[#got + 1] = g.key end
    t:eq(table.concat(got, ","), "748:2,pickup:6,run:WC", "current + low-level quests ticked; the dungeon run stays")
    t:eq(list[4].routeKind, "professions", "each step is tagged with its kind")
    -- The Router's "Route: ..." line.
    -- (Kinds added since, the bank and flight paths, count as ticked here.)
    local base = { quests = true, newQuests = true, lowQuests = true, training = true, professions = true, town = true }
    local function sum(set) return N.KindsSummary(function(k) if base[k] then return set[k] == true end return set.quests ~= nil and (set.newQuests == true) end) end
    t:eq(sum({ quests = true, lowQuests = true, newQuests = true, training = true, professions = true, town = true }), "everything", "all ticked")
    t:eq(sum({ quests = true }), "current quests", "one ticked: named")
    t:eq(sum({ quests = true, newQuests = true, training = true, professions = true, town = true }), "all but low-level quests", "one off: named")
    t:eq(sum({}), "nothing", "none")
    -- The older routes as ticks (your saved route moves over once).
    local q = N.ModeKinds("quests", true)
    t:ok(q.quests and not q.newQuests and not q.professions and not q.town, "Quests only: just your log")
    local o = N.ModeKinds("optimal", false)
    t:ok(o.newQuests and o.training and not o.lowQuests and not o.professions, "Optimal without professions")
    t:ok(N.ModeKinds("complete", true).lowQuests, "Completionist: low-level quests too")
    t:ok(type(ns.db.nav.kinds) == "table", "your saved route became ticks")
end)

ns:Register("test", "click: route menu ticks stay open; select all, clear all", function(t)
    local N, M = ns.nav, ns.menu
    local kinds, profs, arrow = ns.db.nav.kinds, ns.db.nav.professions, ns.db.nav.profArrow
    ns.focus.kindsPaused = true   -- (your usual ticks, whether or not you're on a custom route)
    with(N, "Collect", function() end, function()
        ns.db.nav.kinds = {}
        local items = M.KindItems()
        local by = {}
        for _, it in ipairs(items) do
            if it.kind or it.text then by[it.kind or it.text] = it end   -- (a line across has neither)
        end
        t:eq(items[1].text, "Route includes", "its title")
        t:ok(by.quests and by.newQuests and by.lowQuests and by.training and by.professions and by.town, "a tick for every kind")
        t:ok(by.quests.checked and not by.lowQuests.checked, "ticked as the route is (low-level quests off by default)")
        t:ok(by.quests.tip ~= nil, "each says what it is on hover")
        -- Click the way a click does: the menu stays up and the tick flips.
        M:Open(items)
        local okC = pcall(M.Click, by.lowQuests)
        t:ok(okC, "click: no error")
        t:ok(N:Includes("lowQuests"), "low-level quests now on the route")
        t:ok(by.lowQuests.checked, "its tick shows at once")
        t:ok(_G.FlowMenu and _G.FlowMenu:IsShown(), "the menu stays open for the next tick")
        pcall(M.Click, by["Clear all"])
        local any = false
        for _, k in ipairs(N.Kinds()) do any = any or N:Includes(k.key) end
        t:ok(not any, "Clear all: nothing ticked")
        local own = by["      on their own faint arrow"]
        t:ok(own and own.disabled, "professions off: their own arrow can't be ticked")
        pcall(M.Click, by["Select all"])
        local all = true
        for _, k in ipairs(N.Kinds()) do all = all and N:Includes(k.key) end
        t:ok(all, "Select all: everything ticked")
        t:ok(own and not own.disabled, "professions on: their own arrow can be")
        M:Close()
    end)
    ns.focus.kindsPaused = nil
    ns.db.nav.kinds, ns.db.nav.professions, ns.db.nav.profArrow = kinds, profs, arrow
end)

ns:Register("test", "route menu: professions are one tick of their own", function(t)
