    db.sorter, db.baseSorter = saved.s, saved.b
end)

ns:Register("test", "settings: options are grouped by when you use them; WoW's own stay apart", function(t)
    local S = ns.settings
    local keys = {}
    for i, g in ipairs(S.GROUPS) do keys[i] = g.key end
    t:eq(table.concat(keys, " "), "key group route quests loot learn screen fun more", "the groups, in the order they're shown")
    local n = 0
    for _, g in ipairs(S.GROUPS) do n = n + #S.ExtrasFor(g.key) end
    t:eq(n, #S.extraChecks, "every tick another file added is in exactly one group")
    local function inGroup(label, key)
        for _, x in ipairs(S.ExtrasFor(key)) do if x.label == label then return true end end
        return false
    end
    t:ok(inGroup("Show Questie's tracker", "screen"), "Questie's tracker: On your screen")
    t:ok(inGroup("Show WoW's quest tracker", "screen"), "WoW's quest tracker: On your screen")
    t:ok(inGroup("Flow buttons on WoW's windows", "screen"), "Flow's buttons on WoW's windows: On your screen")
    t:ok(inGroup("Finish the area you're in first", "route"), "the area-first tick: Finding your way")
    t:ok(inGroup("Self button beside Flow's icon", "key"), "the self button: Easy keys")
    with(S, "extraChecks", { { label = "x", group = "nowhere" }, { label = "y" } }, function()
        t:eq(#S.ExtrasFor("more"), 2, "a tick with no group, or one Flow doesn't know: under More")
        t:eq(#S.ExtrasFor("route"), 0, "and nowhere else")
    end)
    -- The page itself (built here if you haven't opened it yet).
    local ok, err = pcall(S._Build)
    t:ok(ok, "the page builds" .. (ok and "" or (": " .. tostring(err))))
    local heads = table.concat(S:Headings(), " | ")
    t:ok(heads:find("Easy keys | In a group | Finding your way | Quests | Loot and selling | New spells and professions | On your screen", 1, true) ~= nil,
        "headings by use: " .. heads)
    local wow, screen = heads:find("Suggested WoW settings", 1, true), heads:find("On your screen", 1, true)
    t:ok(wow and screen and wow > screen, "WoW's own settings come last, under their own heading")
    local function has(label)
        for _, c in ipairs(S:Checks()) do
            if (c.label:GetText() or ""):find(label, 1, true) == 1 then return true end
        end
        return false
    end
    for _, label in ipairs({ "Path moves along the route", "Show WoW's quest tracker", "Flow buttons on WoW's windows",
                             "Turn in finished quests for you", "Shift + easy key heals you", "Show the Flow Tracker" }) do
        t:ok(has(label), "the page has \"" .. label .. "\"")
    end
    -- click: the Path opacity slider.
    local slider
    for _, s in ipairs(S:Sliders()) do if s.name == "Path opacity" then slider = s end end
    t:ok(slider ~= nil, "a Path opacity slider")
    if slider then
        with(ns.db.nav, "pathAlpha", nil, function()
            local ran, why = pcall(slider:GetScript("OnValueChanged"), slider, 0.8)
            t:ok(ran, "click: dragging it runs" .. (ran and "" or (": " .. tostring(why))))
            t:near(ns.db.nav.pathAlpha or 0, 0.8, 1e-6, "and sets the path's opacity")
            t:eq(slider.value:GetText(), "80%", "shown as a percentage")
            slider.filling = true
            pcall(slider:GetScript("OnValueChanged"), slider, 0.3)
            slider.filling = false
            t:near(ns.db.nav.pathAlpha or 0, 0.8, 1e-6, "the page filling itself in isn't a change of yours")
        end)
    end
end)

ns:Register("test", "tracker: WoW's own quest tracker, shown or hidden as you set it", function(t)
    -- "on reload the default wow tracker comes up": with Questie's tracker
    -- off, nothing hid the game's own. Now there's a tick for it.
    local RT = ns.routeTracker
    t:eq(RT.GameTrackerStep(nil, true, false), nil, "never chosen: left to the game")
    t:eq(RT.GameTrackerStep(true, true, false), nil, "ticked (show): left to the game")
    t:eq(RT.GameTrackerStep(false, true, false), "hide", "unticked, and it's showing: hide it")
    t:eq(RT.GameTrackerStep(false, false, false), nil, "already hidden: nothing to do")
    t:eq(RT.GameTrackerStep(false, true, true), "wait", "in a fight: once the fight is over")
    local shown, hides = true, 0
    local fake = { IsShown = function() return shown end, Hide = function() shown = false; hides = hides + 1 end }
    with(ns.db.tracker, "gameTracker", false, function()
        RT.ApplyGameTracker(fake)
        t:eq(hides, 1, "unticked: the game's tracker is hidden")
        RT.ApplyGameTracker(fake)
        t:eq(hides, 1, "once: not again while it stays hidden")
        shown = true
        RT.ApplyGameTracker(fake)
        t:eq(hides, 2, "the game showed it again: hidden again")
        t:eq(RT.GameTrackerWanted(), false, "and the tick reads unticked")
    end)
    shown = true
    with(ns.db.tracker, "gameTracker", nil, function()
        RT.ApplyGameTracker(fake)
        t:eq(hides, 2, "never chosen: Flow doesn't touch it")
        t:eq(RT.GameTrackerWanted(), true, "and the tick reads Show")
    end)
    local byText = {}
    for _, it in ipairs(RT.MenuItems()) do if it.text then byText[it.text] = it end end
    if RT._gameTracker() then
        local it = byText["Show WoW's quest tracker"]
        t:ok(it ~= nil, "the Flow Tracker's menu offers it")
        t:eq(it and it.checked, RT.GameTrackerWanted(), "ticked while it's left showing")
    end
    t:ok(byText["Hide Questie's tracker"] == nil, "Questie's is a Show tick too (both read the same way)")
end)

ns:Register("test", "click: Flow's buttons on WoW's windows open their Flow view", function(t)
    local GB = ns.gameButtons
    if not GB then t:ok(false, "GameButtons.lua not loaded") return end
    -- Finding the game's window: dots walk into a window's parts, and the
    -- first of a button's windows that exists is the one.
    local tab = { IsShown = function() return true end }
    local win = { IsShown = function() return true end, TalentsFrame = tab, name = "not a frame" }
    local env = { PlayerSpellsFrame = win, Number = 5 }
    t:ok(GB.Resolve("PlayerSpellsFrame.TalentsFrame", env) == tab, "a tab of a window is found by its path")
    t:ok(GB.Resolve("PlayerSpellsFrame", env) == win, "a window by its name")
    t:eq(GB.Resolve("PlayerSpellsFrame.Missing", env), nil, "a missing part: nothing")
    t:eq(GB.Resolve("PlayerSpellsFrame.name", env), nil, "a part that isn't a frame: nothing")
    t:eq(GB.Resolve("Nope.TalentsFrame", env), nil, "a missing window: nothing")
    t:eq(GB.Resolve("Number.TalentsFrame", env), nil, "something that isn't a window: nothing")
    local f, path = GB.Find({ frames = { "OldTalentFrame", "PlayerSpellsFrame.TalentsFrame", "PlayerSpellsFrame" } }, env)
    t:ok(f == tab and path == "PlayerSpellsFrame.TalentsFrame", "the first of its windows that exists")
    t:eq(GB.Find({ frames = { "A", "B" } }, env), nil, "none of them loaded yet: no button yet")
    -- The window a part belongs to (the button sits in that window's title bar).
    local screen = {}
    local w = { GetParent = function() return screen end }
    local mid = { GetParent = function() return w end }
    local part = { GetParent = function() return mid end }
    t:ok(GB.Window(part, screen) == w, "a part's window: its outermost parent under the screen")
    t:ok(GB.Window(w, screen) == w, "a window: itself")
    t:eq(GB.Line({ label = "Flow Talents", frames = { "A", "B" } }, nil), "Flow Talents: its window isn't loaded yet (looked for A, B)",
        "/flow buttons says which windows it looked for")
    t:eq(GB.Line({ label = "Flow Talents" }, "PlayerSpellsFrame.TalentsFrame", true),
        "Flow Talents: on PlayerSpellsFrame.TalentsFrame, showing now", "and which one it found")
    -- The built-in ones: each has a window to sit on and a Flow view to open.
    local keys = {}
    for _, e in ipairs(GB.List()) do
        keys[e.key] = true
        t:ok(type(e.def.click) == "function" and #(e.def.frames or {}) > 0, e.key .. ": a window to sit on and a view to open")
        t:ok((e.def.label or ""):find("^Flow ") ~= nil, e.key .. ": named for its Flow view (" .. tostring(e.def.label) .. ")")
    end
    t:ok(keys.talents and keys.spellbook and keys.professions and keys.character, "talents, spellbook, professions and character windows")
    with(ns.db.settings, "gameButtons", false, function() t:eq(GB.On(), false, "the setting turns them all off") end)
    with(ns.db.settings, "gameButtons", nil, function() t:eq(GB.On(), true, "on unless you turn them off") end)
    -- click: the talent window's button opens Flow Talents, and closes it
    -- again ("closed by default": nothing opens until you click).
    local T = ns.talents
    local frame = T._Frame()
    local was = frame and frame:IsShown() and true or false
    t:ok(GB.Click("talents"), "click: runs")
    frame = T._Frame()
    t:eq(frame and frame:IsShown() and true or false, not was, "Flow Talents " .. (was and "closes" or "opens"))
    t:ok(GB.Click("talents"), "click again: runs")
    t:eq(frame and frame:IsShown() and true or false, was, "and it's back as it was")
    t:eq(GB.Click("no-such-button"), false, "an unknown button: nothing happens")
    -- A button that's on a window now: its own OnClick, the way a click runs it.
    local b = GB._Buttons().talents
    if b then
        local ran = pcall(b:GetScript("OnClick"), b)
        t:ok(ran, "click: the button on the talent window runs")
        pcall(b:GetScript("OnClick"), b)   -- (and back)
        t:eq(frame and frame:IsShown() and true or false, was, "Flow Talents is back as it was")
    end
end)

ns:Register("test", "clicks: a plain click on a unit frame that does nothing is spotted", function(t)
    -- "I click to select party members and nothing, right click and nothing.
    -- I had click cast without a modifier but I added the modifier now."
    local CC = ns.clickCheck
    if not CC then t:ok(false, "ClickCheck.lua not loaded") return end
    local defaults = { { type = 3, actionID = 1, button = "BUTTON1", modifiers = 0 },
                       { type = 3, actionID = 2, button = "BUTTON2", modifiers = 0 } }
    t:eq(#CC.Problems(defaults), 0, "the game's defaults (left targets, right opens the menu): nothing wrong")
    t:eq(#CC.Problems({}), 0, "no list at all: Flow says nothing (a client may not list its defaults)")
    t:eq(#CC.Problems(nil), 0, "no click casting on this client: nothing")
    -- The spells moved to Shift + click; Target and Open menu were never given their buttons back.
    local moved = { { type = 1, actionID = 5185, button = "BUTTON1", modifiers = 1 },
                    { type = 1, actionID = 774, button = "BUTTON2", modifiers = 1 } }
    local p = CC.Problems(moved)
    t:eq(#p, 2, "spells moved to a modifier: both plain clicks are dead")
    t:ok(p[1] and p[1]:find("plain left button on a unit frame does nothing", 1, true) ~= nil
        and p[1]:find("has no button at all", 1, true) ~= nil, "left: " .. tostring(p[1]))
    t:ok(p[2] and p[2]:find("plain right button", 1, true) ~= nil and p[2]:find("Open menu", 1, true) ~= nil, "right: " .. tostring(p[2]))
    -- A spell on the plain left button: Target has lost its button.
    p = CC.Problems({ { type = 1, actionID = 5185, button = "BUTTON1", modifiers = 0 },
                      { type = 3, actionID = 2, button = "BUTTON2", modifiers = 0 } })
    t:eq(#p, 1, "a spell on the plain left button: one thing wrong")
    t:ok(p[1] and p[1]:find("\"Target\" has no button", 1, true) ~= nil, tostring(p[1]))
    -- Target needs Shift now: the plain click still does nothing.
    p = CC.Problems({ { type = 3, actionID = 1, button = "BUTTON1", modifiers = 1 },
                      { type = 3, actionID = 2, button = "BUTTON2", modifiers = 0 } })
    t:ok(#p == 1 and p[1]:find("needs a modifier", 1, true) ~= nil, "Target on Shift + click: " .. tostring(p[1]))
    t:eq(CC.What({ type = 1, actionID = 5185 }, function() return "Healing Touch" end), "casts Healing Touch", "a spell binding in words")
    t:eq(CC.What({ type = 3, actionID = 2 }), "Open menu", "an interaction in words")
    local report = table.concat(CC.Report(moved, function() return "Healing Touch" end, function(m) return m == 0 and "" or "Shift + " end), "\n")
    t:ok(report:find("Shift + Left button: casts Healing Touch", 1, true) ~= nil, "the report lists each binding: " .. report)
    t:ok(report:find("Click Bindings", 1, true) ~= nil, "and says where to fix it")
    t:ok(CC.Report(nil)[1]:find("no click casting", 1, true) ~= nil, "no such feature here: says so")
    -- Reading the game's, the advice line and what's under the mouse: no errors.
    local okRead, list = pcall(CC.Read)
    t:ok(okRead and (list == nil or type(list) == "table"), "the game's click bindings read without error")
    local adv = ns:Get("advisor", "clickBindings")
    local okAdv, items = pcall(adv.check)
    t:ok(okAdv and type(items) == "table", "Flow Improvements asks without error")
    local okUnder, names = pcall(CC.Under)
    t:ok(okUnder and type(names) == "table", "/flow under reads what's under the mouse")
    t:ok(type(ns.commands.clicks) == "function" and type(ns.commands.under) == "function", "/flow clicks and /flow under")
end)

ns:Register("test", "rotation: the first press at a new enemy starts auto attack", function(t)
    -- "it still doesn't seem to enable auto-attack after I engage an enemy"
    local E, C = ns.rotation, ns.cast
    local base = { on = true, hostile = true, inCombat = false, attacking = false, canStart = true, barred = false }
    local function with1(k, v)
        local s = {}
        for key, val in pairs(base) do s[key] = val end
        s[k] = v
        return E.EngageFirst(s)
    end
    t:eq(E.EngageFirst(base), true, "a new enemy, no fight yet, not swinging: auto attack first")
    t:eq(with1("attacking", true), false, "already swinging: straight to your opener")
    t:eq(with1("inCombat", true), false, "a fight is on: the key keeps its fight spell")
    t:eq(with1("hostile", false), false, "no enemy targeted: nothing")
    t:eq(with1("canStart", false), false, "no Start Attack on this client: never the Attack spell (it toggles)")
    t:eq(with1("barred", true), false, "an enemy on the noAutoAttack list: left alone")
    t:eq(with1("on", false), false, "the setting off: nothing")
    with(ns.db.rotation, "autoAttack", nil, function() t:eq(E.AutoAttackOn(), true, "on unless you turn it off") end)
    with(ns.db.rotation, "autoAttack", false, function() t:eq(E.AutoAttackOn(), false, "off when you untick it") end)

    -- The step itself, with Flow's own checks stood in for.
    local known, eng = E:KnownSpells(), E._engage
    local saved = { unit = eng.unit, presses = eng.presses, gaveUp = eng.gaveUp, current = E.current }
    local realLog = ns.Log
    ns.Log = function() end   -- (the test's lines stay out of your log)
    local ok, err = pcall(function()
        with(ns.db.rotation, "autoAttack", nil, function()
        with(known, "Auto Attack", true, function()
        with(ns.api, "Swinging", function() return false end, function()
        with(C, "HasStartAttack", function() return true end, function()
            eng.unit, eng.presses, eng.gaveUp = "not this one", 0, false
            local ctx = { hostile = true, inCombat = false, fightType = "normal" }
            local s = E:EngageStep(ctx)
            t:ok(s and s.engage and s.spell == "Auto Attack", "the step: Start attacking")
            t:eq(s and C.KeyCommandFor(s, true), "STARTATTACK", "the key is the game's Start Attack (on, never off)")
            t:eq(E:EngageStep({ hostile = true, inCombat = true }), nil, "in a fight: not offered")
            t:eq(E:EngageStep({ hostile = false, inCombat = false }), nil, "no enemy: not offered")
            -- Pressed twice and the game didn't start it: Flow lets go.
            E.current = s
            E.NoteKeyPress(); E.NoteKeyPress()
            E.current = saved.current
            t:eq(eng.presses, 2, "presses of the key are counted while it's Start Attack")
            t:eq(E:EngageStep(ctx), nil, "two presses and no swing: your opener shows instead (the key is never stuck)")
            t:eq(E:EngageStep(ctx), nil, "and it stays out of the way for that enemy")
            -- A press while the key shows something else isn't counted.
            eng.presses = 0
            E.current = { spell = "Wrath" }
            E.NoteKeyPress()
            E.current = saved.current
            t:eq(eng.presses, 0, "a press of your opener isn't counted")
        end) end) end) end)
    end)
    ns.Log = realLog
    E.current = saved.current
    eng.unit, eng.presses, eng.gaveUp = saved.unit, saved.presses, saved.gaveUp
    t:ok(ok, "the step runs" .. (ok and "" or (": " .. tostring(err))))
end)

ns:Register("test", "heal: a full health bar clears the heal prompt", function(t)
    -- "after my health fills the 'cast a heal' in the target button doesn't clear"
    local E = ns.rotation
    t:eq(E.FULL_QUIET, 6, "six quiet seconds (regen ticks come every 2 s)")
    t:eq(E.HealthSettled(100, 90, 80, 0), false, "never saw your health change out of a fight: not trusted")
    t:eq(E.HealthSettled(100, 97, 80, 3), false, "it changed 3 s ago: still filling")
    t:eq(E.HealthSettled(100, 93, 80, 3), true, "no change for 7 s, out of a fight: full")
    t:eq(E.HealthSettled(100, 50, 96, 3), false, "the fight ended 4 s ago: regen hasn't had time to show")
    t:eq(E.HealthSettled(100, 50, 93, 3), true, "7 s after the fight with no change at all: you came out of it full")
    t:eq(E.HealthSettled(100, nil, nil, 2), true, "no change since you logged in: full")
    t:ok(type(E._health) == "table" and type(E._health.out) == "number", "the count of changes is kept for /flow rot why")
end)

local mapOpenLink   -- (made once: a test may not make a new frame every run)
ns:Register("test", "click: step card links open the map through the game's own button", function(t)
    -- "can the select on map and select quest links open the map if it is not open?"
    local O = ns.mapOpen
    if not O then t:ok(false, "MapOpen.lua not loaded") return end
    t:eq(O.CanArm(false, false, {}), true, "map closed, no fight, the game has a button: the link opens it")
    t:eq(O.CanArm(true, false, {}), false, "in a fight: the plain link (a secure button can't be placed)")
    t:eq(O.CanArm(false, true, {}), false, "already open: the plain link (the game's button would close it)")
    t:eq(O.CanArm(false, false, nil), false, "no such button on this client: the plain link")
    local x, y, w, h = O.Rect(100, 200, 80, 14, 0.5)
    t:ok(x == 49 and y == 99 and w == 42 and h == 9, "the secure button sits exactly over the link, a pixel to spare")
    t:eq(O.Rect(nil, 1, 2, 3), nil, "a link that isn't placed yet: nothing")
    local zone = { IsShown = function() return true end }
    local log = { IsShown = function() return true end }
    local env = { MinimapCluster = { IsShown = function() return true end, ZoneTextButton = zone } }
    local f, path = O.Target("map", env)
    t:ok(f == zone and path == "MinimapCluster.ZoneTextButton", "the map: the zone name over the minimap")
    f = O.Target("log", env)
    t:ok(f == zone, "no Quest Log button: the quest link opens the map instead")
    env.QuestLogMicroButton = log
    f, path = O.Target("log", env)
    t:ok(f == log and path == "QuestLogMicroButton", "the quest log: its own button on the menu bar")
    t:eq(O.Target("map", {}), nil, "none of them here: nothing")
    t:ok(#O.Lines() >= 5, "/flow buttons says which buttons the links use, and the map's controls for other zones")
    -- click: the link arms when the mouse comes over it, and its own click still works.
    if not mapOpenLink then
        mapOpenLink = ns.nav._uiLink(UIParent, "test link", function() mapOpenLink.clicks = (mapOpenLink.clicks or 0) + 1 end,
            function() mapOpenLink.arms = (mapOpenLink.arms or 0) + 1 end)
        mapOpenLink:SetPoint("CENTER", UIParent, "CENTER", 0, -2000)   -- (off the screen)
    end
    local armed, clicked = mapOpenLink.arms or 0, mapOpenLink.clicks or 0
    t:ok(pcall(mapOpenLink:GetScript("OnEnter"), mapOpenLink), "hover: runs")
    t:eq((mapOpenLink.arms or 0) - armed, 1, "and arms the link")
    t:ok(pcall(mapOpenLink:GetScript("OnClick"), mapOpenLink), "click: runs")
    t:eq((mapOpenLink.clicks or 0) - clicked, 1, "the plain click still does the link's own thing")
    pcall(mapOpenLink:GetScript("OnLeave"), mapOpenLink)
    -- Arming for real (a secure button over the link), then letting go.
    local okArm, did = pcall(O.Arm, mapOpenLink, "map")
    t:ok(okArm, "arming runs" .. (okArm and "" or (": " .. tostring(did))))
    local okOff = pcall(O.Disarm)
    t:ok(okOff, "and letting go runs")
    local ov = O._Overlay()
    t:ok(not ov or not ov:IsShown() or InCombatLockdown(), "nothing is left over the link afterwards")
end)

ns:Register("test", "inventory: every bag item with what Flow would do and why", function(t)
    -- "you take inventory while I'm in the game and you optimize the bags"
    local D = ns.disposition
    local rows = D.InventoryRows({
        { id = 2589, name = "Linen Cloth", count = 20, action = "keep", reason = "for First Aid", rule = "professionMaterial", sell = 13, quality = 1 },
        { id = 222, name = "Odd Relic", count = 1, action = "keep", reason = "quest item", rule = "quest", sell = 0, quality = 1, bound = true, kind = "Quest" },
        { id = 2589, name = "Linen Cloth", count = 5, action = "keep", reason = "for First Aid", rule = "professionMaterial", sell = 13, quality = 1 },
        { id = 111, name = "Broken Fang", count = 3, action = "sell", reason = "junk", rule = "junk", sell = 7, quality = 0 },
    })
    t:eq(#rows, 3, "the stacks of one item are one row")
    t:eq(rows[1].name, "Broken Fang", "what leaves your bags comes first")
    t:eq(rows[2].name, "Linen Cloth", "then what stays, by name")
    t:ok(rows[2].count == 25 and rows[2].stacks == 2, "counts and slots added up")
    local money = function(c) return c .. "c" end
    local line = D.InventoryLine(rows[1], money)
    t:ok(line:find("SELL", 1, true) == 1 and line:find("3 x Broken Fang [111] in 1 slot (grey, vendor 7c each): junk {junk}", 1, true) ~= nil,
        "a row reads plainly: " .. line)
    line = D.InventoryLine(rows[3], money)
    t:ok(line:find("1 x Odd Relic [222] in 1 slot (white, Quest, soulbound, no vendor price): quest item {quest}", 1, true) ~= nil,
        "a quest item no vendor takes: " .. line)
    local head, value = D.InventorySummary(rows, 40, 68)
    t:eq(head, "40 of 68 bag slots used; Flow would empty 1 (sell 1, auction house 0, disenchant 0)", "the heading")
    t:eq(value, 21, "and what a vendor pays for it")
    local ok, live, used, total = pcall(D.Inventory, D)
    t:ok(ok and type(live) == "table" and (used or 0) <= (total or 0), "your own bags read without error")
    t:ok(type(ns.commands.inventory) == "function" and ns.commands.inv == ns.commands.inventory, "/flow inventory (and /flow inv)")
    t:ok(type(ns.auction.Known) == "function" and type(ns.auction:Known()) == "number", "how many auction prices Flow has")
end)

ns:Register("test", "pathing: between regions the way goes by a gate (Thunder Bluff's lifts, a zone's pass)", function(t)
    -- "we need pathing working, walls, caves, Thunderbluff elevators"
    local G = ns.gates
    if not G then t:ok(false, "Gates.lua not loaded") return end
    -- What's learned: the way INTO a walled place, and any way between two zones.
    t:eq(G.Learnable(1412, 1456, false, true), true, "from Mulgore up into Thunder Bluff: a gate to learn")
    t:eq(G.Learnable(1456, 1412, true, false), false, "out of Thunder Bluff: not learned (you can leave a mesa by falling off it)")
    t:eq(G.Learnable(1412, 1413, false, false), true, "from one zone into the next: learned")
    t:eq(G.Learnable(1412, 1412, false, false), false, "the same region: nothing")
    t:eq(G.Learnable(nil, 1412, false, false), false, "no region (a continent map): nothing")
    local known = { { cont = 1, wx = 100, wy = 100, a = 1412, b = 1456 } }
    t:eq(G.IsNew(known, 1, 120, 110, 1456, 1412), false, "the same lift again: already known")
    t:eq(G.IsNew(known, 1, 400, 100, 1412, 1456), true, "the other lift: new")
    t:eq(G.IsNew(known, 1, 100, 100, 1412, 1413), true, "another pair of regions at the same spot: new")
    t:ok(G.Walled(1456) and not G.Walled(1412), "Thunder Bluff is walled (a mesa); Mulgore isn't")

    -- Two lifts up the bluff and a pass into the next zone.
    local lift1 = { cont = 1, wx = 100, wy = 0, a = 1412, b = 1456 }
    local lift2 = { cont = 1, wx = 500, wy = 0, a = 1412, b = 1456 }
    local pass = { cont = 1, wx = 0, wy = 1000, a = 1412, b = 1413 }
    local gates = { lift1, lift2, pass }
    local function between(r1, r2)
        local out = {}
        for _, g in ipairs(gates) do
            if (g.a == r1 and g.b == r2) or (g.a == r2 and g.b == r1) then out[#out + 1] = g end
        end
        return out
    end
    local function touching(r)
        local out = {}
        for _, g in ipairs(gates) do if g.a == r or g.b == r then out[#out + 1] = g end end
        return out
    end
    local below, top = { cont = 1, wx = 90, wy = 30, map = 1412 }, { cont = 1, wx = 110, wy = 20, map = 1456 }
    local r = G.Route(below, top, 1412, 1456, between, touching)
    t:ok(r and #r.points == 1 and r.points[1] == lift1, "from the foot of the bluff to the top: the nearer lift")
    t:near(r and r.yards or 0, 53.98, 0.05, "the walk: to the lift and on, not the 22 yd it looks from above")
    local barrens = { cont = 1, wx = 0, wy = 1500, map = 1413 }
    r = G.Route(barrens, top, 1413, 1456, between, touching)
    t:ok(r and #r.points == 2 and r.points[1] == pass and r.points[2] == lift1, "two regions away: the pass, then the lift")
    t:eq(G.Route(below, top, 1412, 1999, between, touching), nil, "no way known between them: nothing")
    t:eq(G.Route({ cont = 0, wx = 0, wy = 0 }, top, 1412, 1456, between, touching), nil, "gates on another continent don't count")
    local part = G.Partial(top, { cont = 1, wx = 5000, wy = 5000 }, 1456, touching)
    t:ok(part and part.partial and part.points[1] == lift1, "out of a walled place with no whole way known: its nearest gate first")
    t:eq(G.Partial(top, below, 1454, touching), nil, "a walled place with no gate yet: nothing")

    -- The whole thing, with those gates standing in for yours.
    with(G, "Region", function(m) return m end, function()
    with(G, "Between", between, function()
    with(G, "Touching", touching, function()
    with(G, "Count", function() return #gates end, function()
        local via = G.Via(below, top)
        t:ok(via and via.points[1] == lift1 and via.to == 1456, "the arrow's way up Thunder Bluff: by the lift")
        t:eq(G.Via(below, { cont = 1, wx = 300, wy = 300, map = 1412 }), nil, "the same region: a straight line")
        t:eq(G.Via(below, { cont = 1, wx = 300, wy = 300 }), nil, "a spot with no map: a straight line")
        t:eq(G.Via(below, { cont = 1, wx = 1, wy = 1, map = 1999 }), nil, "two open zones with no gate known: a straight line, as before")
        local city = G.Via(below, { cont = 1, wx = 3000, wy = 3000, map = 1454 })
        t:ok(city and city.unknown and #city.points == 0, "a walled city Flow has never walked into: it says it doesn't know the way")
        -- The planner: steps on the bluff cost the lift ride, so they're done together.
        local walk = G.PlanWalk()
        t:ok(type(walk) == "function", "the planner gets the walk by gate")
        if walk then
            t:near(walk(below, top) or 0, 53.98, 0.05, "foot to top: by the lift")
            t:eq(walk(below, { cont = 1, wx = 300, wy = 300, map = 1412 }), nil, "the same region: nothing to add")
            t:near(ns.planner._Far(below, top, { walk = walk }), 53.98, 0.05, "the planner measures by the gate")
            t:near(ns.planner._Far(below, top, {}), 22.36, 0.05, "without it: the straight line")
            t:near(ns.planner._Far(below, { cont = 1, wx = 300, wy = 300, map = 1412 }, { walk = walk }), 342.05, 0.05,
                "two spots on one map: the straight line, never asked")
        end
    end) end) end) end)
    with(G, "Count", function() return 0 end, function()
        t:eq(G.PlanWalk(), nil, "no gate known at all: the planner isn't asked")
    end)

    -- Learning one: you walk (or ride the lift) from one map into another.
    local realLog = ns.Log
    ns.Log = function() end
    local ok, err = pcall(function()
        with(ns.db.nav, "gates", {}, function()
            G.Forget()
            -- Walking the rim of Thunder Bluff, the game's map flips between
            -- Mulgore and Thunder Bluff: that's no way up (four were learned
            -- in twenty minutes, on a mesa with two lifts).
            G.Track(nil)
            G.Track({ cont = 1, wx = 100, wy = 0, map = 1412 }, false, 100)
            G.Track({ cont = 1, wx = 100.7, wy = 0, map = 1456 }, false, 100.1)
            t:eq(#ns.db.nav.gates, 0, "walking as the map flips to Thunder Bluff's: not a way in (lifts only)")
            -- A lift: you stand still on the map while it carries you up.
            G.Track(nil)
            G.Track({ cont = 1, wx = 100, wy = 0, map = 1412 }, false, 200)
            G.Track({ cont = 1, wx = 100, wy = 0, map = 1412 }, false, 201)
            G.Track({ cont = 1, wx = 100, wy = 0, map = 1456 }, false, 203)
            t:eq(#ns.db.nav.gates, 1, "standing still as the map becomes Thunder Bluff's (a lift): the spot is kept")
            G.Track({ cont = 1, wx = 110, wy = 2, map = 1412 }, false, 204)
            t:eq(#ns.db.nav.gates, 1, "back down by the same lift: the same way, not a second one")
            G.Track({ cont = 1, wx = 2000, wy = 2000, map = 1456 }, false, 205)
            t:eq(#ns.db.nav.gates, 1, "a jump of 2000 yd is a hearthstone, not a walk: not learned")
            G.Track(nil)
            G.Track({ cont = 1, wx = 100, wy = 0, map = 1412 }, true, 300)
            G.Track({ cont = 1, wx = 100, wy = 0, map = 1456 }, true, 303)
            t:eq(#ns.db.nav.gates, 1, "carried in on a flight path: not learned")
            -- Stepping off at the top: the long standstill ended a moment ago.
            G.Track(nil)
            G.Track({ cont = 1, wx = 600, wy = 0, map = 1412 }, false, 400)
            G.Track({ cont = 1, wx = 600, wy = 0, map = 1412 }, false, 401)
            G.Track({ cont = 1, wx = 600, wy = 0, map = 1412 }, false, 408)
            G.Track({ cont = 1, wx = 603, wy = 0, map = 1456 }, false, 408.5)
            t:eq(#ns.db.nav.gates, 2, "the map changes as you step off the lift: kept too")
            -- Between two ordinary zones a walk is how you cross.
            G.Track(nil)
            G.Track({ cont = 1, wx = 900, wy = 0, map = 1412 }, false, 500)
            G.Track({ cont = 1, wx = 900.7, wy = 0, map = 1413 }, false, 500.1)
            t:eq(#ns.db.nav.gates, 3, "walking from one zone into the next: learned (a pass)")
            t:eq(#G.Lines(), 3, "/flow gates lists them")
        end)
    end)
    ns.Log = realLog
    G.Track(nil)
    G.Forget()
    t:ok(ok, "learning runs" .. (ok and "" or (": " .. tostring(err))))
    t:ok(type(ns.commands.gates) == "function", "/flow gates")
end)

ns:Register("test", "map: the dotted path follows the way you'd walk", function(t)
    -- "the dots should follow the path"
    local M, N = ns.mapOverlay, ns.nav
    local mids = { { id = 1 }, { id = 2 }, { id = 3 } }
    local chain = M.LegChain(0.1, 0.1, 0.9, 0.9, mids, function(m)
        if m.id == 2 then return nil end   -- (not on the map shown)
        return m.id / 10, 0.5
    end)
    t:eq(#chain, 4, "a leg bends through the points on this map: start, two of them, end")
    t:ok(chain[1][1] == 0.1 and chain[2][1] == 0.1 and chain[3][1] == 0.3 and chain[4][1] == 0.9, "in order")
    t:eq(#M.LegChain(0, 0, 1, 1, nil, function() end), 2, "nothing between: a straight leg, as before")
    -- The arrow says how it's taking you.
    t:eq(N.HowText("path"), "Following a trail you've walked before.", "a trail")
    t:ok(N.HowText("gate"):find("the way in you've used before", 1, true) ~= nil, "a gate: " .. N.HowText("gate"))
    t:ok(N.HowText("entrance"):find("entrance first", 1, true) ~= nil, "a cave")
    t:eq(N.HowText("direct"), "Straight line: no known trail yet.", "straight")
    t:ok(N.HowText("direct", { points = {}, unknown = true, from = 1412, to = 1456 }):find("doesn't know the way", 1, true) ~= nil,
        "a walled place Flow has no way into yet: it says so")
    t:eq(N.GateText(nil), "", "no gate: nothing beside the distance")
    t:ok(N.GateText({ points = { {} }, yards = 340 }, 340):find("340 yd", 1, true) ~= nil, "a gate: the walk by it")
    t:ok(type(N.PathStamp()) == "string", "the map knows when the arrow's way changes")
    local okVia, via = pcall(N.LegVia, { cont = 1, wx = 0, wy = 0, map = 1412 }, { cont = 1, wx = 10, wy = 10, map = 1412 }, false)
    t:ok(okVia and via == nil, "a leg inside one region, not the arrow's own: a straight line")
end)

ns:Register("test", "professions: a recipe isn't bought long before you can learn it", function(t)
    -- "longjaw mud snapper requires 50, but it [was on the route at Cooking 32]"
    local SP = ns.skillPlan
    t:eq(SP.BUY_AHEAD, 10, "bought once you're within 10 points")
    t:eq(SP.RecipeDue(50, 32), false, "Cooking 32, the recipe needs 50: not yet")
    t:eq(SP.RecipeDue(50, 40), true, "at 40: buy it now")
    t:eq(SP.RecipeDue(50, 49, 0), false, "in your bags at 49: the game won't let you learn it yet")
    t:eq(SP.RecipeDue(50, 50, 0), true, "at 50: use it")
    t:eq(SP.RecipeDue(50, nil), true, "skill not looked at: as before")
    -- (The 50 is what a trainer's window showed, kept by Trainer.lua: the
    -- step itself lists no learn skill any more. SP.LearnSkill reads it.)
    local step = { recipe = "Flow Test Fish", recipeItem = 99999001, mats = {} }
    local hadProf = ns.db.prof ~= nil
    ns.db.prof = ns.db.prof or {}
    local was = ns.db.prof.recipeLearn
    ns.db.prof.recipeLearn = { Cooking = { ["Flow Test Fish"] = 50 } }
    local ok, early = pcall(SP._recipeStop, "Cooking", step, {}, 32)
    local ok2, due = pcall(SP._recipeStop, "Cooking", step, {}, 45)
    local ok3, asBefore = pcall(SP._recipeStop, "Cooking", step, {})
    ns.db.prof.recipeLearn = was
    if not hadProf then ns.db.prof = nil end
    t:ok(ok and early == nil, "the buy step at 32: none")
    t:ok(ok2 and due and due.key == "buy:99999001", "at 45: Buy Recipe is on the route")
    t:ok(ok3 and asBefore and asBefore.key == "buy:99999001", "no skill given: as before")
end)

ns:Register("test", "professions: a third profession the game's two slots leave out is still yours", function(t)
    -- "journeyman skinning needs 50 and I don't have it but it is taking me
    -- there": Forever lets a character have Herbalism, Blacksmithing and
    -- Skinning; the game's profession slots list two, so Flow took Skinning
    -- for unlearned and sent the route to its trainer.
    local A, SP = ns.api, ns.skillPlan
    local slots = { { name = "Herbalism", rank = 13, max = 75, primary = true }, { name = "Cooking", rank = 32, max = 75 } }
    local lines = { { name = "Skinning", rank = 22, max = 75, primary = true }, { name = "Herbalism", rank = 13, max = 75 } }
    local spells = { { name = "Skinning", rank = 0, max = 0, unsure = true }, { name = "Blacksmithing", rank = 0, max = 0, unsure = true } }
    local all = A.MergeProfessions(slots, lines, {}, spells)
    local by = {}
    for _, p in ipairs(all) do by[p.name] = p end
    t:eq(#all, 4, "each profession once, whichever sources name it")
    t:ok(by.Skinning and by.Skinning.rank == 22 and by.Skinning.max == 75 and not by.Skinning.unsure,
        "Skinning isn't in the slots: its skill comes from the next source that knows it")
    t:ok(by.Blacksmithing and by.Blacksmithing.unsure and by.Blacksmithing.max == 0,
        "only its spell is known: yours, with a skill Flow can't read")
    local filled = A.MergeProfessions(spells, lines)
    t:ok(filled[1].name == "Skinning" and filled[1].rank == 22 and not filled[1].unsure,
        "a source with the numbers fills in one that only knew you have it")
    t:eq(A.BaseProfession("Classic Skinning"), "Skinning", "a line named for an expansion is still Skinning")
    t:eq(A.BaseProfession("First Aid"), "First Aid", "a plain name stays")
    t:eq(A.BaseProfession("Jewelcrafting"), "Jewelcrafting", "one Flow doesn't know stays as it is")
    with(A, "Professions", function() return all end, function()
        local rank, max, unsure = A.Skill("Skinning")
        t:ok(rank == 22 and max == 75 and not unsure, "A.Skill finds it")
        rank, max, unsure = A.Skill("Blacksmithing")
        t:ok(rank == 0 and max == 0 and unsure == true, "one Flow can't read: 0, 0, unsure (not nil: you have it)")
        t:eq(A.Skill("Mining"), nil, "one you don't have: nil")
        -- No trip to the trainer for either: Skinning 22 is short of the 50
        -- Journeyman needs, and Blacksmithing has no number to go by.
        local steps = ns.professions.NextSteps({ { name = "Skinning" }, { name = "Blacksmithing" }, { name = "Mining" } }, A.Skill, 12)
        t:eq(#steps, 1, "only the one you really don't have is a thing to learn")
        t:eq(steps[1] and steps[1].name, "Mining", "that's Mining")
        t:eq(steps[1] and steps[1].kind, "learn", "to learn, not to train")
    end)
    local tier = SP.Tier("Skinning", 22, 75, 12)
    t:ok(tier and tier.name == "Journeyman" and tier.skill == 50 and not tier.ready, "Journeyman Skinning needs skill 50: at 22 it isn't on the route")
    t:ok(SP.Tier("Skinning", 50, 75, 12).ready, "at 50 it is")
    t:eq(SP.Tier("Blacksmithing", 0, 0, 12), nil, "a skill Flow can't read: no tier step at all")
    local text = table.concat(A.ProfessionLines({ { "slots", slots }, { "spells", spells } }), "\n")
    t:ok(text:find("slots: Herbalism 13/75, Cooking 32/75", 1, true) ~= nil, "/flow skills lists each source: " .. text)
    t:ok(text:find("Blacksmithing (you have it; skill not readable here)", 1, true) ~= nil, "and says when a skill can't be read")
    local ok, sources = pcall(A.ProfessionSources)
    t:ok(ok and type(sources) == "table" and #sources == 4, "the game's own lists read without error")
    t:ok(type(ns.commands.skills) == "function", "/flow skills")
end)

ns:Register("test", "professions: a profession's spell is proof only when the game doesn't say you lack it", function(t)
    local A = ns.api
    t:eq(A.SpellProves(true, true), true, "its name resolves and the game says you know it: yours")
    t:eq(A.SpellProves(true, nil), true, "its name resolves and the game can't be asked: yours")
    t:eq(A.SpellProves(true, false), false, "its name resolves but the game says you don't know it: not proof")
    t:eq(A.SpellProves(false, nil), false, "its name doesn't resolve: not yours")
end)

ns:Register("test", "route: a quest in your log is always on the route, even where Flow has no place for it", function(t)
    -- "I don't see the Thunderhorn Cleansing in my route but I have it, same
    -- with Stalk With The Earthmother"
    local db = {
        GetQuest = function(id)
            if id == 758 then return { name = "Thunderhorn Cleansing", level = 8, Finisher = { NPC = { 2 } },
                ObjectiveData = { { Type = "event", Text = "Cleanse the Thunderhorn Water Well", Coordinates = { [12] = { { 44, 45 } } } } } } end
            if id == 76160 then return { name = "Stalk With The Earthmother", level = 10, Finisher = { NPC = { 2 } },
                ObjectiveData = { { Type = "item", Id = 9 } } } end
            if id == 5722 then return { name = "Searching for the Lost Satchel", level = 13, Finisher = { NPC = { 3 } }, ObjectiveData = {} } end
        end,
        GetNPC = function(id)
            if id == 2 then return { name = "Mull Thunderhorn", spawns = { [12] = { { 42, 60 } } } } end
            if id == 3 then return { name = "Maur Grimtotem" } end   -- (no place known)
        end,
        GetItem = function(id) if id == 9 then return { name = "Pine Salve" } end end,
    }
    local function byKey(goals)
        local out = {}
        for _, g in ipairs(goals) do out[g.key] = g end
        return out
    end
    local none = function() return nil end
    local marker = function() return { map = 1412, x = 0.5, y = 0.5 } end

    -- An event objective: Questie has its place.
    local goals = {}
    ns.quests.QuestGoals(db, { id = 758, title = "Thunderhorn Cleansing", complete = false,
        objectives = { { text = "Cleanse the Thunderhorn Water Well", finished = false } } }, goals, { waypoint = none })
    local g = byKey(goals)["758:1"]
    if g and not g.blockedBy then
        t:ok(#g.points > 0 and g.text:find("Cleanse the Thunderhorn Water Well", 1, true) ~= nil,
            "an event objective is a step at the place Questie has for it")
        local turn = byKey(goals)["758:done"]
        t:ok(turn and turn.deps[1] == "758:1", "and its turn-in waits for it")
    else
        t:ok(g ~= nil, "(no map for the test zone here: the objective is listed without a place)")
    end

    -- An item nobody knows the source of: listed with the lock and the reason...
    goals = {}
    ns.quests.QuestGoals(db, { id = 76160, title = "Stalk With The Earthmother", complete = false,
        objectives = { { text = "Pine Salve: 0/1", finished = false } } }, goals, { waypoint = none })
    g = byKey(goals)["76160:1"]
    t:ok(g ~= nil, "an objective Flow can't place is still a step on the list")
    t:ok(g and g.blockedBy and g.blockedBy:find("Questie has no spot for Pine Salve", 1, true) ~= nil, "with the reason: " .. tostring(g and g.blockedBy))
    t:eq(g and g.blockedShort, ns.nav.NO_SPOT, "and a few words of it for its row (0.35.177)")
    t:ok(g and g.text:find("Stalk With The Earthmother", 1, true) ~= nil, "and the quest's name")
    -- ...or placed where the game itself marks the quest.
    goals = {}
    ns.quests.QuestGoals(db, { id = 76160, title = "Stalk With The Earthmother", complete = false,
        objectives = { { text = "Pine Salve: 0/1", finished = false } } }, goals, { waypoint = marker })
    g = byKey(goals)["76160:wp"]
    t:ok(g and g.points[1] and g.points[1].map == 1412 and not g.blockedBy, "the game marks the quest: the step goes there")
    t:eq(byKey(goals)["76160:1"], nil, "and it isn't listed twice")
    local turnIn = byKey(goals)["76160:done"]
    t:ok(turnIn and turnIn.deps[1] == "76160:wp", "its turn-in waits for it")
    -- A party member's quest: neither (the marker is for your own).
    goals = {}
    ns.quests.QuestGoals(db, { id = 76160, title = "Stalk With The Earthmother", complete = false,
        objectives = { { text = "Pine Salve: 0/1", finished = false } } }, goals, { waypoint = marker, prefix = "help:", who = "Bob" })
    t:eq(byKey(goals)["help:76160:wp"], nil, "a party member's unplaceable objective: no step of yours")

    -- A finished quest with no known place to hand it in.
    goals = {}
    ns.quests.QuestGoals(db, { id = 5722, title = "Searching for the Lost Satchel", complete = true, objectives = {} }, goals, { waypoint = none })
    g = byKey(goals)["5722:done"]
    t:ok(g and g.blockedBy and g.blockedBy:find("Maur Grimtotem", 1, true) ~= nil, "nowhere known to hand it in: listed, with who to")
    -- (This one is handed in inside a dungeon: where the quest data knows
    -- that, the row names the dungeon, 0.35.205.)
    local inside = ns.dungeons and ns.dungeons.Of and ns.dungeons.Of(5722)
    t:eq(g and g.blockedShort, inside and ("in " .. inside) or ns.nav.NO_SPOT, "its row says it in a few words")
    goals = {}
    ns.quests.QuestGoals(db, { id = 5722, title = "Searching for the Lost Satchel", complete = true, objectives = {} }, goals, { waypoint = marker })
    g = byKey(goals)["5722:done"]
    t:ok(g and #g.points == 1 and not g.blockedBy, "the game marks where: the turn-in goes there")

    -- A quest the quest data doesn't have at all (one of WoW: Forever's own).
    goals = {}
    ns.quests.QuestGoals(db, { id = 99999, title = "A Forever Quest", complete = false, objectives = {} }, goals, { waypoint = none })
    g = byKey(goals)["99999:wp"]
    t:ok(g and g.blockedBy ~= nil and g.text == "A Forever Quest", "unknown to the quest data: listed with the reason")
    goals = {}
    ns.quests.QuestGoals(db, { id = 99999, title = "A Forever Quest", complete = true, objectives = {} }, goals, { waypoint = marker })
    g = byKey(goals)["99999:wp"]
    t:ok(g and #g.points == 1 and g.text == "Turn in: A Forever Quest", "the game marks it: a step there")
    t:ok(type(ns.quests.GameWaypoint) == "function" and (pcall(ns.quests.GameWaypoint, 99999)), "the game's marker reads without error")
end)

ns:Register("test", "route: the class quest for a spell is always a step (Bear Form)", function(t)
    -- "Flow Improvements shows I need Bear Form, the level 10 druid quest,
    -- but the Flow Tracker isn't having me go there"
    local Q = ns.quests
    -- Heeding the Call -> Moonglade -> Great Bear Spirit -> Back to Thunder Bluff -> Body and Heart.
    local chain = {
        [6002] = { id = 6002, name = "Body and Heart", raw = { preQuestSingle = { 5932 } } },
        [5932] = { id = 5932, name = "Back to Thunder Bluff", raw = { preQuestSingle = { 5930 } } },
        [5930] = { id = 5930, name = "Great Bear Spirit", raw = { preQuestSingle = { 5922 } } },
        [5922] = { id = 5922, name = "Moonglade", raw = { preQuestSingle = { 5928 } } },
        [5928] = { id = 5928, name = "Heeding the Call", level = 10, raw = {},
                   starter = { name = "Turak Runetotem", spawns = { [12] = { { 42, 60 } } } } },
    }
    local function get(id) return chain[id] end
    local function state(doneSet, logSet)
        return Q.ChainStep(6002, get, function(id) return doneSet[id] == true end, function(id) return logSet[id] == true end)
    end
    local s, q = state({}, {})
    t:ok(s == "accept" and q and q.id == 5928, "nothing done yet: pick up the first part, Heeding the Call")
    s, q = state({ [5928] = true }, {})
    t:ok(s == "accept" and q and q.id == 5922, "the first part done: the next one")
    s, q = state({ [5928] = true }, { [5922] = true })
    t:ok(s == "inlog" and q and q.id == 5922, "a part in your log: its own steps take you on")
    s, q = state({ [5928] = true, [5922] = true, [5930] = true, [5932] = true }, {})
    t:ok(s == "accept" and q and q.id == 6002, "all but the last done: the quest that teaches the spell")
    s = state({ [6002] = true }, {})
    t:eq(s, "done", "the teaching quest done: nothing to pick up")
    t:eq((Q.ChainStep(7777, get, function() return false end, function() return false end)), "unknown", "a quest the data doesn't have: unknown")
    -- Two quests that can come first (one a faction): the one meant for you.
    local two = {
        [10] = { id = 10, name = "Teach", raw = { preQuestSingle = { 11, 12 } } },
        [11] = { id = 11, name = "Alliance start", raw = { side = "A" } },
        [12] = { id = 12, name = "Horde start", raw = { side = "H" } },
    }
    s, q = Q.ChainStep(10, function(id) return two[id] end, function() return false end, function() return false end,
        function(x) return x.raw.side == "H" end)
    t:ok(s == "accept" and q and q.id == 12, "of two ways in, the one for your side")

    -- On the route: a step of its own when the pickups didn't have it...
    local goals = {}
    local onMap = function() return { { map = 1412, x = 0.4, y = 0.6 } } end
    local nowhere = function() return {} end
    Q.AddClassQuests(goals, { { spell = "Bear Form", state = "accept", quest = chain[5928] } }, onMap)
    t:eq(#goals, 1, "the class quest's first part is a step")
    t:eq(goals[1] and goals[1].key, "pickup:5928", "under the pickup's own key")
    t:ok(goals[1] and goals[1].text == "Accept: Heeding the Call (Bear Form)" and goals[1].details[1]:find("leads to Bear Form", 1, true) ~= nil,
        "named, and saying what it leads to")
    -- ...and the same step, marked, when they did.
    goals = { { key = "pickup:5928", weight = 0.9, details = { "Level 10 quest." } } }
    Q.AddClassQuests(goals, { { spell = "Bear Form", state = "accept", quest = chain[5928] } }, nowhere)
    t:ok(#goals == 1 and goals[1].classQuest == "Bear Form" and goals[1].weight == 0.7, "already among the pickups: marked, not added twice")
    -- No place known for its giver: listed with the reason.
    goals = {}
    Q.AddClassQuests(goals, { { spell = "Bear Form", state = "accept", quest = chain[5928] } }, nowhere)
    t:ok(goals[1] and goals[1].blockedBy and goals[1].blockedBy:find("Turak Runetotem", 1, true) ~= nil, "no place for its giver: listed, saying who")
    goals = {}
    Q.AddClassQuests(goals, { { spell = "Bear Form", state = "inlog", quest = chain[5922] }, { spell = "Aquatic Form", state = "unknown" } }, nowhere)
    t:eq(#goals, 0, "in your log, or unknown to the data: no pickup")
    -- Flow Improvements links to it, and /flow nav why says where it stands.
    local key, text = Q.ClassQuestKey("Bear Form", { { spell = "Bear Form", state = "accept", quest = chain[5928] } })
    t:eq(key, "pickup:5928", "the improvement's link is the step")
    t:eq(text, "Heeding the Call from Turak Runetotem", "and it says which quest, from whom")
    t:eq((Q.ClassQuestKey("Bear Form", { { spell = "Bear Form", state = "inlog", quest = chain[5922] } })), "5922:done", "in your log: the link is its turn-in's step (0.35.279)")
    t:eq(Q.ClassQuestLine({ spell = "Bear Form", state = "accept", quest = chain[5928] }),
        "Bear Form: pick up \"Heeding the Call\" from Turak Runetotem", "the route check says it")
    t:ok(Q.ClassQuestLine({ spell = "Bear Form", state = "unknown" }):find("doesn't have its class quest", 1, true) ~= nil, "or that the data doesn't have it")
    local ok, steps = pcall(Q.ClassQuestSteps, Q)
    t:ok(ok and type(steps) == "table", "your own class quests read without error")
end)

ns:Register("test", "clicks: the game's own button names count (no false alarm)", function(t)
    -- 0.35.171 expected "BUTTON1"; the game says "LeftButton", so a good left
    -- click was reported dead (and Flow Improvements said to fix it).
    local CC = ns.clickCheck
    local asTheGameSays = { { type = 3, actionID = 1, button = "LeftButton", modifiers = 0 },
                            { type = 3, actionID = 2, button = "RightButton", modifiers = 0 } }
    t:eq(#CC.Problems(asTheGameSays), 0, "LeftButton targets and RightButton opens the menu: nothing wrong")
    t:eq(CC.Button("LeftButton"), "BUTTON1", "LeftButton is the left button")
    t:eq(CC.Button("BUTTON2"), "BUTTON2", "the other spelling stays")
    local report = table.concat(CC.Report(asTheGameSays), "\n")
    t:ok(report:find("Left button: Target", 1, true) ~= nil and report:find("!!", 1, true) == nil, "the report reads plainly, with no warning: " .. report)
    local moved = { { type = 1, actionID = 5185, button = "LeftButton", modifiers = 1 } }
    t:eq(#CC.Problems(moved), 2, "a spell on Shift + LeftButton and nothing on the plain clicks: still spotted")
end)

ns:Register("test", "vendor: gear for sale shows whether it's an upgrade, per spec", function(t)
    -- "when I go to an item vendor it should show me if the items are upgrades"
    local MM = ns.merchantMarks
    if not MM then t:ok(false, "MerchantMarks.lua not loaded") return end
    t:eq(MM.Index(1, 10, 3), 3, "page 1, button 3: the vendor's 3rd item")
    t:eq(MM.Index(2, 10, 3), 13, "page 2, button 3: the 13th")
    local better = { canUse = true, diffs = { dps = 3.2, heal = -1, tank = 0 } }
    t:ok(MM.Diffs(better) == better.diffs, "gear you can use: a badge with each spec's difference")
    t:eq(MM.Diffs({ canUse = false }), nil, "gear you can't use: no badge")
    t:eq(MM.Diffs(nil), nil, "not gear (or not loaded yet): no badge")
    t:near(MM.UpgradeFor(better, "dps") or 0, 3.2, 1e-6, "better for the spec you level as: an upgrade")
    t:eq(MM.UpgradeFor(better, "heal"), nil, "worse for another spec: not one")
    t:eq(MM.UpgradeFor(better, "tank"), nil, "the same: not one")
    local money = function(c) return c .. "c" end
    t:eq(MM.Line({}, "DPS", money), nil, "nothing better for sale: nothing said")
    t:eq(MM.Line({ { link = "[Staff]", gain = 3.2, price = 240, afford = true } }, "DPS", money),
        "for sale here, better than what you wear: [Staff] (+3 DPS, 240c)", "an upgrade you can pay for")
    t:eq(MM.Line({ { link = "[Staff]", gain = 3.2, price = 900, afford = false } }, "DPS", money),
        "for sale here, better than what you wear: [Staff] (+3 DPS, 900c, more than you have)", "one you can't pay for yet")
    -- With no vendor open, a look does nothing (and doesn't error).
    t:ok(pcall(MM._update), "no vendor open: nothing happens")
end)

ns:Register("test", "professions: the trainer's own word on the next tier beats the classic rule", function(t)
    -- "journeyman skinning needs level 50 and I don't have it but it is
    -- taking me there": Skinning was 58 of 75 at level 12, enough for
    -- classic's Journeyman (skill 50, level 10), so Flow kept the trainer on
    -- the route. What the trainer says now decides.
    local SP, TR, P = ns.skillPlan, ns.trainer, ns.professions
    local classic = SP.Tier("Skinning", 58, 75, 12)
    t:ok(classic and classic.ready, "never looked at the trainer: classic's rule (skill 50, level 10)")
    local seen = { cap = 75, category = "unavailable", level = 50, skill = 50, cost = 500, atLevel = 12, atRank = 58 }
    local tier = SP.Tier("Skinning", 58, 75, 12, seen)
    t:ok(tier and not tier.ready and tier.level == 50, "the trainer asks for level 50: not on the route at level 12")
    t:eq(tier and tier.cost, 500, "its price is remembered (the route waits until you can pay)")
    t:ok(SP.Tier("Skinning", 58, 75, 50, seen).ready, "at level 50: back on the route")
    -- Red at the trainer for a reason it didn't name: wait for a level or five skill points.
    local red = { cap = 75, category = "unavailable", level = 0, skill = 0, atLevel = 12, atRank = 58 }
    tier = SP.Tier("Skinning", 58, 75, 12, red)
    t:ok(tier and not tier.ready and tier.wait ~= nil, "red at the trainer, no reason Flow could read: off the route for now")
    t:ok(SP.Tier("Skinning", 58, 75, 13, red).ready, "a level later: worth another look")
    t:ok(SP.Tier("Skinning", 63, 75, 12, red).ready, "or five skill points later")
    local green = { cap = 75, category = "available", level = 10, skill = 50, cost = 500, atLevel = 12, atRank = 58 }
    t:ok(SP.Tier("Skinning", 58, 75, 12, green).ready, "available at the trainer: on the route")
    -- A book-taught tier isn't the trainer's to say.
    t:eq(SP.Tier("Cooking", 130, 150, 20, { cap = 150, category = "unavailable", level = 60 }).how, "book", "Expert Cooking is a book: unchanged")
    t:eq(SP.TierName(75), "Journeyman", "the tier after a cap of 75")
    -- Reading the trainer's list.
    local services = {
        { name = "Apprentice Skinner", category = "used" },
        { name = "Journeyman Skinner", category = "unavailable", level = 50, skill = 50, cost = 500 },
    }
    local s = TR.TierService(services, "Journeyman")
    t:ok(s and s.level == 50, "the tier's line is found by its name")
    t:eq(TR.TierService({ { name = "Skinning", sub = "Journeyman", category = "available" } }, "Journeyman").category, "available",
        "or by its rank text")
    t:eq(TR.TierService({ { name = "Journeyman Skinner", category = "used" } }, "Journeyman"), nil, "one you've learned already: not it")
    t:eq(TR.TierService(services, nil), nil, "no next tier: nothing")
    t:eq(TR.TierAsks("Skinning", 50, 50), "level 50 and Skinning 50", "what it asks for, in words")
    t:eq(TR.TierAsks("Skinning", 0, 0), nil, "nothing Flow could read: nothing to say")
    -- The reminder card goes by it too.
    local function skill() return 58, 75 end
    t:eq(#P.NextSteps({ { name = "Skinning" } }, skill, 12), 1, "the classic rule: train the next tier")
    t:eq(#P.NextSteps({ { name = "Skinning" } }, skill, 12, function() return seen end), 0, "the trainer said level 50: no reminder")
    t:ok(pcall(TR.ReadTier), "reading a trainer that isn't open does nothing")
end)

ns:Register("test", "pathing: a way into a lift-only place is learned from a ride, not from walking its rim", function(t)
    local G = ns.gates
    t:eq(G.LiftOnly(1456), true, "Thunder Bluff: lifts only")
    t:eq(G.LiftOnly(1454), false, "Orgrimmar: you walk in through its gates")
    t:eq(G.LiftOnly(1412), false, "a zone: no")
    t:eq(G.Learnable(1412, 1456, false, true, true, false), false, "into a lift-only place on foot: not a way in")
    t:eq(G.Learnable(1412, 1456, false, true, true, true), true, "by lift: learned")
    t:eq(G.Learnable(1411, 1454, false, true, false, false), true, "into a walled city through its gate: learned on foot")
    t:eq(G.Rode(10, 8, 0, -math.huge), true, "still for 2 s as the map changes: riding")
    t:eq(G.Rode(10, 9.5, 0, -math.huge), false, "still for half a second: not yet")
    t:eq(G.Rode(10, nil, 5, 8), true, "a 5 s standstill that ended 2 s ago: you stepped off the lift")
    t:eq(G.Rode(10, nil, 5, 5), false, "it ended 5 s ago: you've been walking since")
    t:eq(G.Rode(10, nil, 1, 9.5), false, "a short pause, then walking: not a ride")
end)

ns:Register("test", "route: a class quest in your log comes first, and a travel spell makes it near", function(t)
    -- "Flow Improvements shows I need Bear Form, but the Flow Tracker isn't
    -- having me go there": "Moonglade" was in the log, its step thousands of
    -- yards north, so the route left it for last.
    local Q, TS = ns.quests, ns.travelSpells
    local goals = {
        { key = "5922:done", weight = 0.8, details = { "Hand it in to Dendrite Starblaze." } },
        { key = "758:1", details = {} },
    }
    Q.MarkClassQuests(goals, { { spell = "Bear Form", state = "inlog", quest = { id = 5922 } } })
    t:ok(goals[1].milestone and goals[1].classQuest == "Bear Form" and goals[1].weight == 0.6, "the class quest's step is a milestone, weighted to come early")
    t:ok(goals[1].details[1]:find("leads to Bear Form", 1, true) ~= nil, "and says what it leads to")
    t:ok(not goals[2].milestone, "other quests are left as they are")
    local plain = { { key = "5922:done", weight = 0.8, details = {} } }
    Q.MarkClassQuests(plain, { { spell = "Bear Form", state = "accept", quest = { id = 5922 } } })
    t:ok(not plain[1].milestone, "a class quest not yet in your log: nothing to mark")

    -- A druid's Teleport: Moonglade.
    if not TS then t:ok(false, "TravelSpells.lua not loaded") return end
    local spells = { { name = "Teleport: Moonglade", map = 1450, class = "DRUID" } }
    local function zoneOf(m) return m end
    local mulgore, moonglade = { map = 1412 }, { map = 1450 }
    local s = TS.Fits(mulgore, moonglade, spells, zoneOf, "DRUID")
    t:eq(s and s.name, "Teleport: Moonglade", "a step in Moonglade from Mulgore: one cast away")
    t:eq(TS.Fits(moonglade, moonglade, spells, zoneOf, "DRUID"), nil, "already in Moonglade: walk")
    t:eq(TS.Fits(mulgore, { map = 1413 }, spells, zoneOf, "DRUID"), nil, "a step elsewhere: the spell doesn't go there")
    t:eq(TS.Fits(mulgore, moonglade, spells, zoneOf, "PALADIN"), nil, "another class: not theirs")
    t:eq(TS.Fits(mulgore, {}, spells, zoneOf, "DRUID"), nil, "a spot with no map: nothing")
    -- The planner measures such a step as near.
    local a = { cont = 1, wx = 0, wy = 0, map = 1412 }
    local b = { cont = 1, wx = 9000, wy = 0, map = 1450 }
    local port = function(x, y) return TS.Fits(x, y, spells, zoneOf, "DRUID") and TS.YARDS or nil end
    t:near(ns.planner._Far(a, b, { port = port }), TS.YARDS, 1e-6, "9000 yd on foot, one cast with the spell: counted as the cast")
    t:near(ns.planner._Far(a, b, {}), 9000, 1e-6, "without it: the walk")
    t:near(ns.planner._Far(b, a, { port = port }), 9000, 1e-6, "the way back is on foot (the spell goes one way)")
    t:ok(pcall(TS.PlanPort), "your own travel spells read without error")
    t:ok(pcall(TS.Hint, a, b), "and the panel's line")
end)

ns:Register("test", "professions: the next tier waits until you can pay for it", function(t)
    -- "journeyman skinning ... I don't have it, but it is taking me there":
    -- Skinning was 58 (enough), the price 5 silver, the purse 2s 30c. The
    -- step had no price, so the route went to the trainer anyway.
    local SP = ns.skillPlan
    t:eq(SP.TierCost("Skinning", 75, nil), 500, "Journeyman: 5 silver (read at a WoW: Forever trainer)")
    t:eq(SP.TierCost("Skinning", 75, { Herbalism = { cap = 75, cost = 450 } }), 450, "what another profession's trainer charged for the same tier")
    t:eq(SP.TierCost("Skinning", 75, { Skinning = { cap = 75, cost = 475 }, Herbalism = { cap = 75, cost = 450 } }), 475,
        "its own trainer's price first")
    t:eq(SP.TierCost("Skinning", 150, { Herbalism = { cap = 75, cost = 450 } }), nil, "a tier nobody has priced yet: nothing to wait for")
    t:eq(SP.TierCost("Skinning", 150, { Mining = { cap = 150, cost = 50000 } }), 50000, "Expert, once a trainer has shown its price")
    -- The trainer's own line on WoW: Forever (2026-11-13): skill 50, no level, 5 silver.
    local seen = { cap = 75, category = "unavailable", level = 0, skill = 50, cost = 500, atLevel = 12, atRank = 23 }
    t:ok(not SP.Tier("Herbalism", 23, 75, 12, seen).ready, "Herbalism 23: not yet")
    t:ok(SP.Tier("Herbalism", 50, 75, 12, seen).ready, "at 50 it is, at level 12 (no level asked, as in classic)")
end)

ns:Register("test", "bags: leaner rules (no auction price: vendor; ammo you can't shoot; other classes' reagents)", function(t)
    -- "I want to keep my bags as empty as possible ... before we get there on
    -- items just vendor them"
    local D = ns.disposition
    local money = function(c) return c .. "c" end
    -- The auction house only on a price that's worth it.
    t:eq(D.WorthAuction(nil, 100), false, "no price seen: not worth it")
    t:eq(D.WorthAuction(220, 100), false, "2.2x the vendor before the cut and the fee: not enough")
    t:eq(D.WorthAuction(400, 100), true, "4x the vendor: worth listing")
    t:eq(D.WorthAuction(30, 5), false, "a few copper more: not worth a trip")
    local v = D.AuctionOrVendor(nil, 100, "a gem", true, money)
    t:ok(v.action == "sell" and v.reason:find("no auction price known", 1, true) ~= nil and v.ahCandidate, "no price known: to a vendor (and still looked up at an auction house)")
    v = D.AuctionOrVendor(nil, 100, "a gem", false, money)
    t:eq(v.action, "ah", "the setting off: held for the auction house, as before")
    v = D.AuctionOrVendor(400, 100, "a gem", true, money)
    t:ok(v.action == "ah" and v.reason:find("400c", 1, true) ~= nil, "a good price seen: the auction house, with the price")
    v = D.AuctionOrVendor(150, 100, "a gem", true, money)
    t:ok(v.action == "sell" and v.reason:find("wouldn't pay enough", 1, true) ~= nil, "a poor price seen: the vendor")
    with(ns.db.sell, "vendorUnpriced", nil, function() t:eq(D.VendorUnpriced(), true, "to a vendor unless you turn it off") end)
    with(ns.db.sell, "vendorUnpriced", false, function() t:eq(D.VendorUnpriced(), false, "turned off: held") end)
    -- Rare gear is never vendored unseen.
    local rule = function(k, item) return ns:Get("disposition", k).check(item) end
    with(ns.api, "Skill", function() return nil end, function()
        v = rule("unneededGear", { quality = 3, bound = false, sellPrice = 500 })
        t:eq(v and v.action, "ah", "a tradeable blue with no price known: checked at the auction house first")
        with(ns.db.sell, "vendorUnpriced", nil, function()
            v = rule("unneededGear", { quality = 2, bound = false, sellPrice = 309 })
            t:eq(v and v.action, "sell", "a tradeable green with no price known: to a vendor")
        end)
        v = rule("unneededGear", { quality = 2, bound = true, sellPrice = 309 })
        t:eq(v and v.action, "sell", "a soulbound green: to a vendor, as ever")
    end)
    -- Ammunition.
    t:eq(D.AmmoIsUseless(6, "DRUID"), true, "bullets in a druid's bags: no use")
    t:eq(D.AmmoIsUseless(6, "HUNTER"), false, "a hunter's: kept")
    t:eq(D.AmmoIsUseless(7, "DRUID"), false, "not ammunition: another rule's business")
    -- Spell reagents.
    local classesOf = function(n) return ns:Get("classReagent", n) end
    t:eq(D.ReagentOfOthers("Light Feather", "DRUID", classesOf), true, "Light Feather (a mage's and a priest's) on a druid: goes")
    t:eq(D.ReagentOfOthers("Light Feather", "MAGE", classesOf), false, "on a mage: stays")
    t:eq(D.ReagentOfOthers("Maple Seed", "DRUID", classesOf), false, "a druid's own reagent: stays")
    t:eq(D.ReagentOfOthers("Linen Cloth", "DRUID", classesOf), nil, "not a spell reagent: not this rule's business")
    t:ok(ns:Get("disposition", "ammoNotYours") and ns:Get("disposition", "otherClassReagent"), "both rules are registered")
end)

-------------------------------------------------------------------------------
-- 0.35.177: folded menu sections, the drink step without a mana reading,
-- short lock reasons.
-------------------------------------------------------------------------------

ns:Register("test", "menu: sections after the first fold into one row each", function(t)
    local M = ns.menu
    local items = {
        { title = true, text = "This step" },
        { text = "Open it" }, { text = "Hide this step" },
        { sep = true },
        { title = true, text = "Order" },
        { text = "Most XP", radio = true, checked = false },
        { text = "Shortest path", radio = true, checked = true },
        { sep = true },
        { title = true, text = "Route includes" },
        { text = "Quests", checked = true }, { text = "Professions", checked = false }, { text = "Gear", checked = true },
        { sep = true },
        { text = "Flow Settings" },
        { title = true, text = "Nothing in it" },
    }
    local shown = M.Fold(items)
    t:eq(#shown, 7, "the step's own entries, a line, and one row per later section")
    t:ok(shown[1].title and shown[2].text == "Open it" and shown[3].text == "Hide this step", "the first section stays open")
    t:ok(shown[4].sep, "a line under it")
    t:ok(shown[5].section and shown[5].text == "Order" and #shown[5].sub == 2, "Order: one row, two entries inside")
    t:ok(shown[6].section and shown[6].text == "Route includes" and #shown[6].sub == 3, "Route includes: one row")
    t:ok(shown[7].section and shown[7].text == "More" and shown[7].sub[1].text == "Flow Settings", "entries with no title: under More")
    t:eq(M.SectionState(shown[5].sub), "Shortest path", "a choice: what it's set to")
    t:eq(M.SectionState(shown[6].sub), "2 of 3", "ticks: how many are on")
    t:eq(M.SectionState(shown[7].sub), nil, "plain entries: nothing to say")
    t:ok(shown[5].sub[2] == items[7], "the entries are the menu's own (a tick set in the pop-out is the menu's)")
    local plain = M.Fold({ { text = "A" }, { text = "B" } })
    t:ok(#plain == 2 and not plain[1].section and not plain[2].section, "a menu with no sections: as it is")
    local two = M.Fold({ { title = true, text = "One" }, { text = "a" }, { title = true, text = "Two" }, { text = "b" } })
    t:ok(#two == 4 and two[3].sep and two[4].section and two[4].text == "Two", "a second title with no line before it folds too")
    -- The real menus: every one of them folds without losing an entry.
    local ok, route = pcall(M.RouteItems, M)
    if ok and type(route) == "table" then
        local n = 0
        for _, it in ipairs(M.Fold(route)) do
            if it.section then n = n + #it.sub elseif not (it.sep or it.title) then n = n + 1 end
        end
        local want = 0
        for _, it in ipairs(route) do if not (it.sep or it.title) then want = want + 1 end end
        t:eq(n, want, "the route menu: every entry is still there, open or in a pop-out")
    end
end)

ns:Register("test", "click: a folded menu section pops out when pointed at or clicked", function(t)
    local M = ns.menu
    local ran, ticked = 0, false
    local tick = { text = "A tick", checked = false, stay = true }
    tick.func = function() ticked = not ticked end
    tick.refresh = function(it) it.checked = ticked end
    local items = {
        { title = true, text = "Test menu" },
        { text = "Plain entry", func = function() ran = ran + 1 end },
        { sep = true },
        { title = true, text = "Folded" },
        tick,
        { text = "Closes the menu", func = function() ran = ran + 10 end },
    }
    closeMenu()
    local ok, err = pcall(M.Open, M, items)
    t:ok(ok, "the menu opens" .. (ok and "" or (": " .. tostring(err))))
    t:ok(menuShown(), "on screen")
    t:ok(M.items == items or #M.items >= #items, "every entry is still in the menu's list")
    local rows, flyRows = M._Rows()
    local function find(list, want)
        for _, r in ipairs(list) do
            if r:IsShown() and r.item and want(r.item) then return r end
        end
    end
    local sectionRow = find(rows, function(it) return it.section and it.text == "Folded" end)
    local plainRow = find(rows, function(it) return it.text == "Plain entry" end)
    t:ok(sectionRow ~= nil and plainRow ~= nil, "the later section is one row, under the open one")
    t:eq(find(rows, function(it) return it == tick end), nil, "its entries aren't in the menu itself")
    local fly = _G.FlowMenuSection
    t:ok(fly and not fly:IsShown(), "they're put away until you point at it")
    if not (sectionRow and plainRow and fly) then closeMenu() return end

    local okE, errE = pcall(sectionRow:GetScript("OnEnter"), sectionRow)
    t:ok(okE, "pointing at it runs" .. (okE and "" or (": " .. tostring(errE))))
    t:ok(fly:IsShown(), "pointing at it pops its entries out")
    -- The click that follows the pointing must not shut it again.
    local okC, errC = pcall(sectionRow:GetScript("OnClick"), sectionRow, "LeftButton")
    t:ok(okC, "clicking it runs" .. (okC and "" or (": " .. tostring(errC))))
    t:ok(fly:IsShown() and menuShown(), "a click on it leaves the pop-out open")

    local tickRow = find(flyRows, function(it) return it == tick end)
    t:ok(tickRow ~= nil, "the tick is in the pop-out")
    if tickRow then
        pcall(tickRow:GetScript("OnClick"), tickRow, "LeftButton")
        t:ok(ticked and tick.checked, "a tick in the pop-out is set")
        t:ok(menuShown() and fly:IsShown(), "and the menu and the pop-out stay up for the next one")
    end

    -- Pointing at a row of the menu itself puts the pop-out away; a click on
    -- the section opens it again.
    pcall(plainRow:GetScript("OnEnter"), plainRow)
    t:ok(not fly:IsShown(), "pointing at another row puts it away")
    pcall(sectionRow:GetScript("OnClick"), sectionRow, "LeftButton")
    t:ok(fly:IsShown(), "a click on the section opens it")

    local closeRow = find(flyRows, function(it) return it.text == "Closes the menu" end)
    t:ok(closeRow ~= nil, "the other entry is in the pop-out")
    if closeRow then
        pcall(closeRow:GetScript("OnClick"), closeRow, "LeftButton")
        t:eq(ran, 10, "an entry in the pop-out runs")
        t:ok(not menuShown() and not fly:IsShown(), "and closes the menu with its pop-out")
    end
    closeMenu()
end)

ns:Register("test", "drink: low on mana where the game hides it; water by any wording", function(t)
    local E, BI = ns.rotation, ns.buffItems
    t:ok(E.ManaLow(0.2, false), "20% shown: low")
    t:ok(not E.ManaLow(0.9, true), "90% shown: not low, whatever else")
    t:ok(E.ManaLow(nil, true), "hidden, a heal out of reach: low")
    t:ok(not E.ManaLow(nil, false), "hidden, heals affordable: not low")
    t:ok(not E.ManaLow(nil, nil), "hidden, nothing known: not low")
    t:eq(BI.HealKind("Refreshing Spring Water", 0, 5, { "Use: Restores 151.2 mana over 18 sec. Must remain seated while drinking." }),
        "drink", "a fraction in the number")
    t:eq(BI.HealKind("Odd Water", 0, 5, { "Use: Restores 4% of your mana per second for 20 sec." }), "drink", "a share of your mana")
    t:eq(BI.HealKind("Unworded Water", 0, 5, { "Use: Refreshes you." }, "Drink"), "drink", "its use is the Drink spell")
    t:eq(BI.HealKind("Tough Jerky", 0, 5, { "Use: Restores 61 health over 18 sec." }, "Food"), "food", "food stays food")
    t:eq(BI.HealKind("Linen Cloth", 7, 5, { "Restores nothing." }, "Drink"), nil, "not a consumable: nothing")
    local ok, line = pcall(E.DrinkWhy, E, { hostile = false })
    t:ok(ok and type(line) == "string" and line:find("^Drink: ") ~= nil, "/flow rot why says where drinking stands: " .. tostring(line))
end)

ns:Register("test", "blocked steps: a few words in the row, the whole reason in the tooltip", function(t)
    local N = ns.nav
    local long = "Flow doesn't know where: Questie has no spot for Fish Chunks. Your quest log says how."
    t:eq(N.ShortBlocked({ blockedBy = long, blockedShort = N.NO_SPOT }), "no known spot", "a step's own short form")
    t:eq(N.ShortBlocked({ blockedBy = long }), "no known spot", "without one: from how the reason starts")
    t:eq(N.ShortBlocked({ blockedBy = "Flow doesn't know who sells Fishing Pole" }), "no known seller", "nobody known to sell it")
    t:eq(N.ShortBlocked({ blockedBy = "Flow doesn't know where Wool Cloth comes from (Auction House?)" }), "no known source", "no known source")
    t:eq(N.ShortBlocked({ blockedBy = "needs 16c (you have 6c)" }), "needs 16c", "an aside in brackets is left for the tooltip")
    t:eq(N.ShortBlocked({ blockedBy = "needs a Fishing Pole first (sold by Seller A or Seller B)" }), "needs a Fishing Pole first", "the same")
    t:eq(N.ShortBlocked({ blockedBy = "no known Fishing spot on this map" }), "no known Fishing spot...", "a long one is cut at a word")
    t:eq(N.ShortBlocked({ blockedBy = "Needs this. And then that." }), "Needs this", "the first sentence")
    local coded = "needs |cffffd200a very long thing with a colour code in it|r first"
    t:eq(N.ShortBlocked({ blockedBy = coded }), coded, "never cut through a colour code (the row's width does that)")
    t:eq(N.ShortBlocked({}), "blocked", "no reason given")
    for _, s in ipairs({ long, "no known Fishing spot on this map", "needs a Fishing Pole first (sold by Seller A or Seller B)" }) do
        t:ok(#N.ShortBlocked({ blockedBy = s }) <= N.BLOCKED_MAX, "never longer than a row has room for: " .. s)
    end
    local text, why = N:FormatBlocked({ text = "Stalk With The Earthmother: 0/1 Fish Chunks", blockedBy = long, blockedShort = N.NO_SPOT })
    t:ok(text:find("Fish Chunks", 1, true) ~= nil, "the row: what the step is")
    t:ok(why:find("no known spot", 1, true) ~= nil and not why:find("Questie", 1, true), "and a few words of why")
    -- The tooltip keeps the whole sentence.
    local tt = _G.FlowTestTooltip or CreateFrame("GameTooltip", "FlowTestTooltip", UIParent, "GameTooltipTemplate")
    tt:SetOwner(UIParent, "ANCHOR_NONE")
    local goal = { key = "t:short", text = "Fish Chunks", points = {}, blockedBy = long, blockedShort = N.NO_SPOT }
    local ok = pcall(N.FillTooltip, N, tt, goal, goal)
    local whole = false
    for i = 1, tt:NumLines() do
        local fs = _G["FlowTestTooltipTextLeft" .. i]
        local s = fs and fs:GetText()
        if s and s:find("Your quest log says how", 1, true) then whole = true end
    end
    tt:Hide()
    t:ok(ok and whole, "its tooltip says all of it")
end)

ns:Register("test", "router: a locked step's reason stays inside the Flow Router", function(t)
    local M = ns.mapOverlay
    t:eq(M.ReasonWidth(40), 42, "a short reason: as wide as its words")
    t:eq(M.ReasonWidth(900), M.REASON_W, "a long one: never wider than its column")
    t:eq(M.ReasonWidth(nil), 2, "no words: no room taken")
    t:ok(M.REASON_W <= 150, "the column leaves at least half of the Router's 300 to the step's name")
    local rows = M._ListRows()
    local r = rows and rows[1]
    if not (r and r.leg) then t:ok(true, "(the Flow Router isn't built yet)") return end
    local wraps = r.leg.CanWordWrap or r.leg.GetWordWrap
    if wraps then t:ok(not wraps(r.leg), "the reason is one line: a long one is cut with \"...\", not spilled") end
end)

-------------------------------------------------------------------------------
-- 0.35.178: the way back from a far trip (rides), and which inn is home.
-------------------------------------------------------------------------------

ns:Register("test", "rides: the way out of Moonglade is the druids' flight master", function(t)
    local R = ns.rides
    local zoneOf = function(m) return ({ [9999] = 1450 })[m] or m end
    local rides = { { name = "Bunthen Plainswind", from = 1450, class = "DRUID", faction = "Horde" },
                    { name = "Silva Fil'naveth", from = 1450, class = "DRUID", faction = "Alliance" } }
    local a, b = { map = 1450 }, { map = 1456 }
    local fit = R.Fits(a, b, rides, zoneOf, "DRUID", "Horde")
    t:eq(fit and fit.name, "Bunthen Plainswind", "a Horde druid in Moonglade, the step in Thunder Bluff")
    fit = R.Fits(a, b, rides, zoneOf, "DRUID", "Alliance")
    t:eq(fit and fit.name, "Silva Fil'naveth", "an Alliance druid: Silva Fil'naveth")
    t:eq(R.Fits(a, b, rides, zoneOf, "WARRIOR", "Horde"), nil, "not a druid: no ride")
    t:eq(R.Fits(a, { map = 9999 }, rides, zoneOf, "DRUID", "Horde"), nil, "the step is in Moonglade too: no ride")
    t:eq(R.Fits({ map = 1412 }, b, rides, zoneOf, "DRUID", "Horde"), nil, "you aren't in Moonglade: no ride")
    t:near(R.Cost(100, 9000, 50, 4.5, 40), 100 + 40 + 2000 + 50, 0.01, "its cost: to them, the talk, the flight, and on from the landing")

    -- Measured, with stand-ins for where he stands and where you land.
    local npc = { map = 1450, cont = 1, wx = 100, wy = 0 }
    local land = { map = 1456, cont = 1, wx = 9000, wy = 0 }
    local spotOf, landOf = function() return npc end, function() return land end
    local you = { map = 1450, cont = 1, wx = 0, wy = 0 }
    local far = { map = 1456, cont = 1, wx = 9100, wy = 0 }
    local way = R.Way(you, far, "DRUID", "Horde", spotOf, landOf)
    t:ok(way and way.name == "Bunthen Plainswind", "a step in Thunder Bluff from Moonglade: by his flight")
    t:near(way and way.toNpc or 0, 100, 0.01, "100 yd to him")
    t:ok(way and way.yards > 100 and way.yards < 9100, "the whole way costs less than the straight line: " .. tostring(way and way.yards))
    t:ok(way and way.point == npc, "the arrow's point is where he stands")
    t:eq(R.Text(way), "100 yd to Bunthen Plainswind: he flies druids to Thunder Bluff, free", "the arrow's line")
    -- A step next door (Felwood): walking beats a flight to Thunder Bluff and back.
    local near = { map = 1448, cont = 1, wx = 600, wy = 0 }
    t:eq((R.Way(you, near, "DRUID", "Horde", spotOf, landOf)), nil, "a step next door: on foot, not the flight")
    -- Nobody knows where he stands: not measured, but still named.
    local none, named = R.Way(you, far, "DRUID", "Horde", function() return nil end, landOf)
    t:ok(none == nil and named and named.name == "Bunthen Plainswind", "his spot unknown: named, not measured")
    t:eq((R.Way(you, far, "MAGE", "Horde", spotOf, landOf)), nil, "a mage: nothing")
    t:eq((R.Way(you, { map = 1456, cont = 2, wx = 9100, wy = 0 }, "DRUID", "Horde", spotOf, landOf)), nil, "a step on another continent: not measured")

    t:ok(ns:Get("ride", "Bunthen Plainswind") and ns:Get("ride", "Silva Fil'naveth"), "both are registered")
    local ok, lines = pcall(R.Lines)
    t:ok(ok and type(lines) == "table" and #lines >= 2, "/flow rides lists them")
    local okP, plan = pcall(R.PlanRide)
    t:ok(okP and (plan == nil or type(plan) == "function"), "the planner's question builds")
    local okH = pcall(R.Hint, you, far)
    t:ok(okH, "the panel's line builds")
    local hint = R.HintOf(way)
    t:ok(hint and hint:find("talk to Bunthen Plainswind", 1, true) ~= nil, "and says who to talk to: " .. tostring(hint))
    t:eq(R.HintOf(nil), nil, "no ride: no line")
end)

ns:Register("test", "planner and arrow: a leg out of Moonglade costs the ride", function(t)
    local P, N = ns.planner, ns.nav
    local A = { map = 1450, cont = 1, wx = 0, wy = 0 }
    local B = { map = 1456, cont = 1, wx = 9000, wy = 0 }
    t:eq(P._Far(A, B, { ride = function() return 2300 end }), 2300, "a ride that's cheaper than the straight line counts")
    t:eq(P._Far(A, B, { ride = function() return 99999 end }), 9000, "one that costs more: not taken")
    t:eq(P._Far(A, B, { ride = function() return nil end }), 9000, "no ride for this leg: the straight line")
    t:eq(P._Far(A, { map = 1450, cont = 1, wx = 300, wy = 0 }, { ride = function() return 1 end }), 300, "inside one map: never asked")
    t:eq(P._Far(A, B, { ride = function() error("boom") end }), 9000, "a ride that errors: the straight line")
    local how = N.HowText("ride", nil, { name = "Bunthen Plainswind", how = "he flies druids to Thunder Bluff, free" })
    t:ok(how:find("Bunthen Plainswind", 1, true) ~= nil and how:find("Thunder Bluff", 1, true) ~= nil, "the panel says who and where to: " .. how)
    t:ok(N.HowText("path", nil, nil):find("trail", 1, true) ~= nil, "no ride: as before")
    -- The step after the ride comes before one that's truly far.
    local function goal(key, map, x)
        return { key = key, text = key, points = { { map = map, cont = 1, wx = x, wy = 0 } } }
    end
    local you = { map = 1450, cont = 1, wx = 0, wy = 0 }
    local ride = function(a, b)
        if a.map == 1450 and b.map == 1456 then return 400 end
    end
    local plan = P:Plan(you, { goal("tb", 1456, 9000), goal("felwood", 1448, 1500) }, { ride = ride })
    t:eq(plan and plan[1] and plan[1].goal.key, "tb", "Thunder Bluff by the flight (400) before Felwood on foot (1500)")
    plan = P:Plan(you, { goal("tb", 1456, 9000), goal("felwood", 1448, 1500) }, {})
    t:eq(plan and plan[1] and plan[1].goal.key, "felwood", "without the ride: the nearer one, as before")
end)

ns:Register("test", "hearthstone: a city beats a village; home first, then a far trip", function(t)
    local H = ns.hearth
    local tb, bh = ns:Get("innkeeper", "thunderbluff"), ns:Get("innkeeper", "bloodhoof")
    local xr, tj = ns:Get("innkeeper", "crossroads"), ns:Get("innkeeper", "taurajo")
    t:ok(tb and tb.city and bh and not bh.city and xr and tj, "Horde inns are listed: Thunder Bluff (a city), Bloodhoof Village, the Barrens")
    if not (tb and bh and xr and tj) then return end
    t:ok(H.Offer(tb, bh, 700), "in Thunder Bluff with your home in Bloodhoof Village: set it here")
    t:ok(not H.Offer(bh, tb, 700), "back in Mulgore with your home in Thunder Bluff, close by: keep the city")
    t:ok(H.Offer(xr, tb, 3200), "at the Crossroads, the city far away: offered")
    t:ok(not H.Offer(tj, xr, 900), "another inn of the zone you're bound in: no")
    t:ok(H.Offer(bh, nil, nil), "your home isn't an inn Flow knows: offered, as before")
    t:ok(not H.Offer(tb, tb, 0), "bound here: no")
    t:ok(not H.Offer(bh, tb, nil), "a city home, the distance unknown: keep it")
    t:ok(not H.Offer(nil, bh, 1), "no inn here: nothing")

    -- What the game calls your home.
    with(ns.db.hearth, "binds", nil, function()
        t:ok(H:BoundTo(bh, "Bloodhoof Village") and not H:BoundTo(tb, "Bloodhoof Village"), "\"Bloodhoof Village\" is Innkeeper Kauth's")
        t:ok(H:BoundTo(ns:Get("innkeeper", "orgrimmar"), "Valley of Strength"), "a city's district counts")
        t:eq((H:Home("Bloodhoof Village")), "bloodhoof", "your home, as an inn Flow knows")
        t:eq((H:Home("Somewhere Unheard Of")), nil, "a home Flow doesn't know")
        t:ok(H.Learn("Lower Rise", "Innkeeper Pala"), "set at an innkeeper Flow knows: the game's wording is kept")
        t:ok(H:BoundTo(tb, "Lower Rise") and not H:BoundTo(bh, "Lower Rise"), "and counts from then on")
        t:ok(not H.Learn("Lower Rise", "Some Vendor"), "not an innkeeper: nothing learned")
    end)

    -- A step a travel spell away waits for "Set hearthstone".
    local goals = {
        { key = "hearth:thunderbluff", points = { { map = 1456 } } },
        { key = "q:moonglade", points = { { map = 1450 } }, deps = { "q:other" } },
        { key = "q:here", points = { { map = 1456 } } },
        { key = "q:nowhere", points = {} },
    }
    local had = goals[2].deps
    local isTrip = function(pt) return pt.map == 1450 end
    t:eq(H.BeforeTrips(goals, isTrip), 1, "one step is a cast away")
    t:ok(goals[2].deps[1] == "q:other" and goals[2].deps[2] == "hearth:thunderbluff", "it waits for Set hearthstone, and for what it waited for before")
    t:eq(#had, 1, "the list it had isn't changed (it may be shared)")
    t:eq(goals[3].deps, nil, "a step here doesn't wait")
    H.BeforeTrips(goals, isTrip)
    t:eq(#goals[2].deps, 2, "asked twice: not added twice")
    t:eq(H.BeforeTrips({ goals[2], goals[3] }, function() return true end), 0, "no Set hearthstone step on the route: nothing waits")
    -- And the planner keeps that order, even with the far step "one cast away".
    local function goal(key, map, x, deps)
        return { key = key, text = key, deps = deps, points = { { map = map, cont = 1, wx = x, wy = 0 } } }
    end
    local list = { goal("hearth:thunderbluff", 1456, 300), goal("q:moonglade", 1450, 9000) }
    H.BeforeTrips(list, isTrip)
    local port = function(a, b) if b.map == 1450 and a.map ~= 1450 then return 120 end end
    local plan = ns.planner:Plan({ map = 1456, cont = 1, wx = 0, wy = 0 }, list, { port = port })
    t:eq(plan and plan[1] and plan[1].goal.key, "hearth:thunderbluff", "Set hearthstone first (300 yd), though Moonglade is one cast away (120)")
    t:eq(plan and plan[2] and plan[2].goal.key, "q:moonglade", "then the trip")

    local okL, line = pcall(H.Line)
    t:ok(okL and type(line) == "string" and line:find("^hearthstone: set to ") ~= nil, "/flow nav why says where your home is: " .. tostring(line))
    local provider = ns:Get("navGoal", "hearth")
    local okC, res = pcall(provider.collect)
    t:ok(okC and (res == nil or type(res) == "table"), "the step's source runs" .. (okC and "" or (": " .. tostring(res))))
end)

-------------------------------------------------------------------------------
-- 0.35.179: the beam's seam, the key's bind above the icon, the "Waypoint"
-- hint, "Go to the nearest...", Shortest path first.
-------------------------------------------------------------------------------

ns:Register("test", "modern arrow: the beam and its mirror meet with no crack", function(t)
    local N = ns.nav
    local l, r, top, bottom = N.BeamCoords(false)
    t:ok(l == 0 and r == 1 and top == 0, "the upright beam: the whole picture across, from its top")
    t:ok(bottom < 1 and bottom > 0.97, "stopping short of the see-through row at its bottom edge: " .. tostring(bottom))
    t:near(bottom, 1 - 1.5 / 128, 0.0001, "at the middle of the brightest row (one and a half rows in)")
    local l2, r2, top2, bottom2 = N.BeamCoords(true)
    t:ok(l2 == 0 and r2 == 1 and bottom2 == 0, "the mirrored beam: the same picture upside down")
    t:eq(top2, bottom, "starting at the same bright row: bright meets bright")
    -- On a real arrow: both carry those coordinates, and both hang on the ring's middle.
    local a = N:MakeArrowModern(UIParent)
    local function vEdge(tex, upper)   -- the picture's v at the texture's top or bottom edge
        local _, uly, _, lly = tex:GetTexCoord()
        return upper and uly or lly
    end
    t:near(vEdge(a.beam, false), bottom, 0.0001, "the beam's lower edge is the bright row")
    t:near(vEdge(a.beamDown, true), bottom, 0.0001, "and so is the mirrored beam's upper edge")
    local p1, rel1, rp1, x1, y1 = a.beam:GetPoint(1)
    local p2, rel2, rp2, x2, y2 = a.beamDown:GetPoint(1)
    t:ok(p1 == "BOTTOM" and p2 == "TOP" and rel1 == rel2 and rp1 == rp2, "one's bottom and the other's top are on the same spot")
    t:ok(math.abs((x1 or 0) - (x2 or 0)) < 0.01 and math.abs((y1 or 0) - (y2 or 0)) < 0.01, "with no offset between them")
    a:Hide()
end)

ns:Register("test", "target button: its key bind is written to the right of the icon", function(t)
    local C, E = ns.cast, ns.rotation
    local key = C._KeyText()
    if not (key and E.icon) then t:ok(true, "(the Flow key isn't built yet)") return end
    local point, rel, relPoint, x, y = key:GetPoint(1)
    -- (On its own: above the icon. With the self button docked under it: at
    -- the middle of the icon's right side, 0.35.239.)
    if C.labelsDocked then
        t:eq(point, "LEFT", "docked: its left edge...")
        t:ok(rel == E.icon and relPoint == "RIGHT", "...on the middle of the icon's right side")
        t:ok((x or 0) > 0 and (y or 0) == 0, "a little to the right, level with the middle")
    else
        t:eq(point, "BOTTOM", "its bottom edge...")
        t:ok(rel == E.icon and relPoint == "TOP", "...on the icon's top edge, like CTRL / SHIFT / ALT above the queue")
        t:ok((x or 0) == 0 and (y or 0) > 0, "centred, a little above")
    end
    t:eq(key:GetNumPoints(), 1, "and nowhere else (not in the icon's corner)")
    local _, size = key:GetFont()
    t:near(size or 0, C.KEY_FONT, 0.6, "in the queue labels' kind of lettering")
end)

ns:Register("test", "waypoint: Ctrl over the map says \"Waypoint\" the first two times", function(t)
    local W = ns.waypoint
    local db = {}
    t:eq(W.CtrlTip("LSHIFT", 1, true, db), nil, "not Ctrl: nothing")
    t:eq(W.CtrlTip("LCTRL", 1, false, db), "hide", "Ctrl, but not over the map: no tooltip")
    t:eq(db.wayTips, nil, "and it doesn't count")
    t:eq(W.CtrlTip("LCTRL", 1, true, db), "show", "the first time over the map: shown")
    t:eq(W.CtrlTip("LCTRL", 0, true, db), "hide", "Ctrl let go: put away")
    t:eq(W.CtrlTip("RCTRL", 1, true, db), "show", "the second time (either Ctrl): shown")
    t:eq(db.wayTips, 2, "counted twice")
    t:eq(W.CtrlTip("LCTRL", 1, true, db), "hide", "the third time: not again")
    t:eq(db.wayTips, 2, "and the count stays")
    t:eq(W.TIP_TIMES, 2, "two times")
    -- The event itself, as the game sends it: runs, and shows or hides nothing it shouldn't.
    with(ns.db.nav, "wayTips", W.TIP_TIMES, function()
        local ok, act = pcall(W.OnModifier, "LCTRL", 1)
        t:ok(ok, "Ctrl pressed: runs" .. (ok and "" or (": " .. tostring(act))))
        t:ok(act == nil or act == "hide", "already shown twice: no tooltip")
        t:ok(pcall(W.OnModifier, "LCTRL", 0), "Ctrl let go: runs")
        t:ok(pcall(W.OnModifier, "LALT", 1), "another key: runs")
    end)
end)

ns:Register("test", "route menu: Go to the nearest..., and Shortest path above Most XP first", function(t)
    local ok, items = pcall(ns.menu.RouteItems, ns.menu)
    t:ok(ok and type(items) == "table", "the route menu builds")
    if not (ok and type(items) == "table") then return end
    local nearest, old, shortest, xp
    for i, it in ipairs(items) do
        local text = it.text or ""
        if it.title and text == "Go to the nearest..." then nearest = i end
        if it.title and text:find("your waypoint", 1, true) then old = i end
        if text:find("Shortest path", 1, true) then shortest = shortest or i end
        if text:find("Most XP first", 1, true) then xp = xp or i end
    end
    t:ok(nearest ~= nil, "its section is called \"Go to the nearest...\"")
    t:eq(old, nil, "with no \"(your waypoint)\" after it")
    t:ok(shortest and xp and shortest < xp, "Shortest path (the default) comes above Most XP first")
    -- Folded, the section's row reads the same.
    local row
    for _, it in ipairs(ns.menu.Fold(items)) do
        if it.section and it.text == "Go to the nearest..." then row = it end
    end
    t:ok(row and #row.sub >= 5, "folded: one row, the places inside")
    -- The Flow Router's row of route states: the default first too.
    local f = _G.FlowMapRoute and _G.FlowMapRoute.sorts
    if f and f[1] and f[2] then
        t:eq(f[1].mode, "distance", "Flow Router: Shortest first")
        t:eq(f[2].mode, "xp", "then Most XP")
    end
end)

-------------------------------------------------------------------------------
-- 0.35.180: the arrow's words on a flight; Flow Improvements stays one line
-- an entry, up to twice as wide.
-------------------------------------------------------------------------------

ns:Register("test", "flights: the arrow says where you're flying and when you land", function(t)
    local N, R = ns.nav, ns.rides
    local title, sub = N.FlightWords("Thunder Bluff", 130, "Train 1 spell(s) at your class trainer")
    t:eq(title, "Flying to Thunder Bluff", "where to")
    t:eq(sub, "landing in ~2m 10s, then: Train 1 spell(s) at your class trainer", "when you land, and what comes after")
    sub = select(2, N.FlightWords("Thunder Bluff", nil, "Next"))
    t:eq(sub, "landing time not known yet, then: Next", "a flight not timed yet says so")
    title, sub = N.FlightWords(nil, nil, nil)
    t:ok(title == "On a flight" and sub == "landing time not known yet", "a flight Flow knows nothing of: still says it's one")

    -- The ride that leaves from where you are, whatever the step.
    local rides = { { name = "Bunthen Plainswind", from = 1450, toName = "Thunder Bluff", class = "DRUID", faction = "Horde" } }
    local same = function(m) return m end
    local r = R.From(1450, rides, same, "DRUID", "Horde")
    t:eq(r and r.name, "Bunthen Plainswind", "in Moonglade, a Horde druid: Bunthen's flight")
    t:eq(R.From(1412, rides, same, "DRUID", "Horde"), nil, "somewhere else: none")
    t:eq(R.From(1450, rides, same, "MAGE", "Horde"), nil, "not a druid: none")
    t:eq(R.From(nil, rides, same, "DRUID", "Horde"), nil, "no map: none")

    -- Noticing a flight that started with a word, not a flight map.
    local keep, saved = N.taxiTrip, {}
    local bunthen = function() return rides[1] end
    N._TaxiReset(false)
    t:eq(N.NoteTaxi(false, 100, bunthen, saved), nil, "on the ground: no trip")
    local trip = N.NoteTaxi(true, 110, bunthen, saved)
    t:ok(trip and trip.to == "Thunder Bluff" and trip.from == "Bunthen Plainswind" and trip.start == 110, "taking off beside Bunthen: a trip to Thunder Bluff")
    t:ok(trip and not trip.partial, "seen from the ground up: its time counts")
    t:ok(saved.taxiTrip == trip, "kept for a /reload in the air")
    t:ok(N.NoteTaxi(true, 150, function() return nil end, saved) == trip, "still flying: the same trip")
    -- A /reload in the air: the trip comes back with its start.
    N._TaxiReset(false)
    local back = N.NoteTaxi(true, 200, function() return nil end, saved)
    t:ok(back == trip and back.start == 110, "after a /reload: the same trip, the same take-off time")
    -- First seen in the air with nothing saved (a login): a flight, but not one to time.
    N._TaxiReset(false)
    local blind = N.NoteTaxi(true, 300, function() return nil end, {})
    t:ok(blind and blind.to == nil and blind.partial, "first seen in the air: a flight of unknown end, not timed")
    -- A saved trip too old to be this flight is dropped.
    N._TaxiReset(false)
    local stale = { taxiTrip = { from = "A", to = "B", start = 10 } }
    local fresh = N.NoteTaxi(true, 10 + N.TAXI_MAX + 1, function() return nil end, stale)
    t:ok(fresh ~= nil and fresh.to == nil, "an old saved trip isn't this flight")
    -- Landing learns the time of a whole flight only.
    local times = ns.db.flightTimes
    ns.db.flightTimes = {}
    N.Landed({ from = "Bunthen Plainswind", to = "Thunder Bluff", start = 0 }, 412)
    t:eq(ns.db.flightTimes["Bunthen Plainswind>Thunder Bluff"], 412, "landed: the ride's time is remembered")
    t:eq(N.FlightSeconds("Bunthen Plainswind", "Thunder Bluff"), 412, "and known next time")
    N.Landed({ from = "?", start = 0, partial = true }, 300)
    N.Landed({ from = "X", to = "Y", start = 0, partial = true }, 300)
    t:eq(ns.db.flightTimes["X>Y"], nil, "a flight seen only in part: not learned")
    ns.db.flightTimes = times
    N._TaxiReset(true)
    N.taxiTrip = keep
    t:ok(pcall(N.FlightNow, "Next"), "the arrow's question runs")
    t:ok(pcall(N.TaxiLeft), "and the time left")
end)

ns:Register("test", "improvements: each numbered entry stays one line, up to twice as wide", function(t)
    local Adv = ns.advisor
    local measure = function(s) return #s * 6 end   -- (six a letter)
    t:eq(Adv.FitLine("short", 100, measure), "short", "a line that fits: as it is")
    local long = string.rep("word ", 40)
    local cut = Adv.FitLine(long, 300, measure)
    t:ok(cut:sub(-3) == "..." and measure(cut) <= 300, "one that doesn't: cut to fit, ending in ...")
    t:ok(not cut:find("\n", 1, true), "still one line")
    local coloured = "|cff888888" .. long .. "|r"
    cut = Adv.FitLine(coloured, 300, measure)
    t:ok(not cut:find("|", 1, true) and measure(cut) <= 300, "a coloured line is cut without breaking a colour code")
    t:eq(Adv.FitLine("|cff888888fits|r", 100, measure), "|cff888888fits|r", "a coloured line that fits keeps its colour")

    local shown = {
        { text = "Train Revive at your class trainer", improves = { "Stronger rank" } },
        { text = string.rep("a very long way to improve ", 8) },
    }
    local lines = Adv.TipLines(shown, { {} }, measure)
    t:eq(#lines, 5, "title, two entries, the hidden count, the foot")
    t:eq(lines[1].text, "Flow Improvements", "its title")
    t:ok(lines[2].text:find("^1%. Train Revive") ~= nil, "numbered")
    t:ok(lines[2].text:find("improves Stronger rank", 1, true) ~= nil, "a short one whole, with what it improves")
    local max = measure(Adv.TIP_FOOT) * Adv.TIP_WIDER
    t:ok(lines[3].text:find("^2%. ") ~= nil and measure(lines[3].text) <= max, "a long one: one line, no wider than twice the tooltip's usual width")
    t:ok(lines[3].text:sub(-3) == "...", "cut with ...")
    t:eq(lines[4].text, "(1 hidden)", "the hidden count")
    t:eq(lines[5].text, Adv.TIP_FOOT, "the foot")
    t:eq(Adv.TIP_WIDER, 2, "twice")
    local many = {}
    for i = 1, 15 do many[i] = { text = "Entry " .. i } end
    t:eq(#Adv.TipLines(many, {}, measure), 1 + Adv.TIP_MAX + 1, "ten entries at most")
    local okM, ruler = pcall(Adv.TipMeasure)
    t:ok(okM and type(ruler) == "function" and (ruler("abc") or 0) >= 0, "the tooltip's own ruler works")

    -- The list (the panel): as wide as its longest row, between its usual width and twice that.
    t:eq(Adv.PanelWidth(0), Adv.PANEL_W, "short rows: its usual width")
    t:eq(Adv.PanelWidth(500), 500 + Adv.PANEL_ROOM, "a longer row: room for it")
    t:eq(Adv.PanelWidth(5000), Adv.PANEL_W * 2, "never more than twice as wide")
    t:eq(Adv.PanelWidth(nil), Adv.PANEL_W, "nothing to measure: its usual width")
end)

ns:Register("test", "click: pointing at the Flow Improvements button lists one line an entry", function(t)
    local Adv = ns.advisor
    local b = _G.FlowAdviceButton
    if not (b and b:GetScript("OnEnter")) then t:ok(true, "(the Flow Improvements button isn't built yet)") return end
    local shown = { { text = string.rep("a very long way to improve ", 8) }, { text = "A short one" } }
    with(Adv, "Shown", function() return shown, {} end, function()
        local ok, err = pcall(b:GetScript("OnEnter"), b)
        t:ok(ok, "pointing at it runs" .. (ok and "" or (": " .. tostring(err))))
        t:ok(GameTooltip:IsShown(), "the tooltip is up")
        t:eq(GameTooltip:NumLines(), 4, "title, two entries, the foot")
        local l2, l3 = _G.GameTooltipTextLeft2, _G.GameTooltipTextLeft3
        local long, short = l2 and l2:GetText() or "", l3 and l3:GetText() or ""
        t:ok(long:find("^1%. ") ~= nil and long:sub(-3) == "...", "the long entry: numbered, cut with ... to stay on one line")
        t:eq(short, "2. A short one", "the short one whole")
        local measure = Adv.TipMeasure()
        local foot = measure(Adv.TIP_FOOT)
        if foot > 0 then
            t:ok(measure(long) <= foot * Adv.TIP_WIDER + 0.5, "no wider than twice the tooltip's usual width")
        end
        if l2 and l2.GetNumLines then t:eq(l2:GetNumLines(), 1, "and it really is one line") end
        pcall(b:GetScript("OnLeave"), b)
        t:ok(not GameTooltip:IsShown(), "put away again")
    end)
end)

