    with(ns.db.actions, "questItem", nil, function()
        local ok, step = pcall(action.get, { goal = { key = "6002:1", text = "Body and Heart" }, at = false })
        t:ok(ok and step == nil, "away from the step: nothing" .. (ok and "" or (": " .. tostring(step))))
        ok, step = pcall(action.get, { goal = { key = "train:class" }, at = true })
        t:ok(ok and step == nil, "a step that isn't a quest's: nothing")
        ok, step = pcall(action.get, { goal = nil, at = true })
        t:ok(ok and step == nil, "no step: nothing")
        ok, step = pcall(action.get, { goal = { key = "6002:1", text = "Body and Heart" }, at = true })
        t:ok(ok, "at the step: runs" .. (ok and "" or (": " .. tostring(step))))
        -- (Whether it offers the item now depends on your bags and your target: both are yours, not the test's.)
        if ok and step then
            t:eq(step.type, "item", "a step that uses an item")
            t:eq(step.item, "item:15710", "the quest's")
            t:ok(type(step.label) == "string" and step.label:find("^Use ") ~= nil, "it says what it uses")
        end
    end) end)
end)

-------------------------------------------------------------------------------
-- 0.35.188: the target button's modifier icons run out to its left; auto
-- attack sits on its right.
-------------------------------------------------------------------------------

ns:Register("test", "target button: modifier icons to its left, auto attack on its right", function(t)
    local icon = ns.rotation.icon
    if not (icon and icon.deck and icon.deck[1] and icon.swing and icon.shiftTag) then
        t:ok(true, "(the target button isn't built yet)")
        return
    end
    -- (To the left for a button in the left half of the screen; mirrored in the right half, 0.35.324.)
    local right = icon.side == "right"
    local own, other, sign = right and "BOTTOMLEFT" or "BOTTOMRIGHT", right and "BOTTOMRIGHT" or "BOTTOMLEFT", right and 1 or -1
    local p, rel, rp, x = icon.deck[1]:GetPoint(1)
    t:ok(p == own and rel == icon and rp == other and (x or 0) * sign > 0, "the first (SHIFT) hangs off the icon's edge on its side")
    for i = 2, #icon.deck do
        local p2, rel2, rp2, x2 = icon.deck[i]:GetPoint(1)
        t:ok(p2 == own and rel2 == icon.deck[i - 1] and rp2 == other and (x2 or 0) * sign > 0,
            "the next one further out (" .. i .. ")")
    end
    t:eq(icon.deck[1]:GetNumPoints(), 1, "one anchor each (not still tied to the right side)")
    local sp, srel, srp, sx = icon.swing:GetPoint(1)
    -- (Docked: small, at the bottom right corner, 0.35.239.)
    local _, wantP, wantRp = ns.SwingPlace(icon.joined, icon.side)
    t:ok(sp == wantP and srel == icon and srp == wantRp and (sx or 0) * sign < 0, "the crossed swords are on the other side")
    t:eq(icon.swing:GetNumPoints(), 1, "and only there")
    -- (0.35.199: on the key bind's line, just left of it; its own test below.)
    local tp, _, _, tx = icon.shiftTag:GetPoint(1)
    t:ok(tp ~= nil and (ns.cast.labelsDocked or (tx or 0) ~= 0), "the SHIFT+ tag sits beside the key bind (left of it; above it when docked)")
end)

