ns:Register("test", "target button: a friendly player targeted gets your buffs, then a heal", function(t)
    local E = ns.rotation
    -- Mana sense.
    t:ok(E.CanSpare(0.8, false, 0.5), "80% mana, half to keep: yes")
    t:ok(not E.CanSpare(0.3, false, 0.5), "30%: no")
    t:ok(E.CanSpare(nil, false, 0.5), "mana hidden, every heal affordable: yes")
    t:ok(not E.CanSpare(nil, true, 0.5), "mana hidden, a heal out of reach: no")
    local buffs = { { spell = "Mark of the Wild", covered = false }, { spell = "Thorns", covered = false } }
    local heal = { hot = "Rejuvenation", direct = "Regrowth" }
    local s = E.FriendStep({ hurt = false, inCombat = false }, buffs, heal, true, true)
    t:ok(s and s.spell == "Mark of the Wild" and s.kind == "buff", "a healthy friend: your first buff they lack")
    buffs[1].covered = true
    s = E.FriendStep({ hurt = false, inCombat = false }, buffs, heal, true, true)
    t:eq(s and s.spell, "Thorns", "then the next")
    buffs[2].covered = true
    t:eq(E.FriendStep({ hurt = false, inCombat = false }, buffs, heal, true, true), nil, "all on, and they're healthy: nothing more")
    s = E.FriendStep({ hurt = true, inCombat = false }, buffs, heal, true, true)
    t:ok(s and s.spell == "Rejuvenation" and s.kind == "heal", "all on, and they're hurt: the key becomes a heal")
    s = E.FriendStep({ hurt = true, inCombat = false }, buffs, { direct = "Regrowth" }, true, true)
    t:eq(s and s.spell, "Regrowth", "the heal over time is on them: your quick heal")
    buffs[1].covered, buffs[2].covered = false, false
    s = E.FriendStep({ hurt = true, inCombat = true }, buffs, heal, true, true)
    t:ok(s and s.kind == "heal" and s.why == "hurt in a fight", "hurt and in a fight: the heal before any buff")
    s = E.FriendStep({ hurt = true, inCombat = false }, buffs, heal, true, true)
    t:eq(s and s.kind, "buff", "hurt but not in a fight: the buffs first")
    -- The game hides their health.
    buffs[1].covered, buffs[2].covered = true, true
    s = E.FriendStep({ hurt = nil, inCombat = true }, buffs, heal, true, true)
    t:ok(s and s.kind == "heal" and s.why == "in a fight", "health hidden, in a fight: heal them")
    s = E.FriendStep({ hurt = nil, inCombat = false }, buffs, heal, true, true)
    t:ok(s and s.spell == "Rejuvenation" and s.why == "top up", "health hidden, no fight: one heal over time")
    t:eq(E.FriendStep({ hurt = nil, inCombat = false }, buffs, { direct = "Regrowth" }, true, true), nil, "and once it's on them, nothing more")
    -- Mana.
    buffs[1].covered = false
    t:eq(E.FriendStep({ hurt = false, inCombat = false }, buffs, heal, false, true), nil, "no mana to spare for buffs: none")
    s = E.FriendStep({ hurt = true, inCombat = true }, buffs, heal, false, true)
    t:eq(s and s.kind, "heal", "but a heal still, with a quarter left")
    t:eq(E.FriendStep({ hurt = true, inCombat = true }, buffs, heal, false, false), nil, "nothing to spare at all: nothing")
    t:eq(E.FriendStep(nil, buffs, heal, true, true), nil, "no friend: nothing")
    t:ok(E.FriendReason({ spell = "Thorns", kind = "buff" }, "Bob"):find("Thorns for Bob", 1, true) ~= nil, "it says who and what")
    t:ok(E.FriendReason({ spell = "Regrowth", kind = "heal", why = "in a fight" }, "Bob"):find("hides their health", 1, true) ~= nil,
        "and that it can't see their health")
    -- The engine's step: never in a fight of your own, never with an enemy targeted.
    local def = E:Definition()
    if def then
        local ok, step = pcall(E.FriendTarget, E, { inCombat = true, hostile = false }, def)
        t:ok(ok and step == nil, "in your own fight: nothing" .. (ok and "" or (": " .. tostring(step))))
        ok, step = pcall(E.FriendTarget, E, { inCombat = false, hostile = true }, def)
        t:ok(ok and step == nil, "an enemy targeted: nothing")
        ok = pcall(E.FriendTarget, E, { inCombat = false, hostile = false }, def)
        t:ok(ok, "out of a fight: runs, whatever you have targeted")
        with(ns.db.rotation, "friendTarget", false, function()
            local okO, stepO = pcall(E.FriendTarget, E, { inCombat = false, hostile = false }, def)
            t:ok(okO and stepO == nil, "switched off in Flow Settings: nothing")
        end)
    end
    E.ClearFriendCache()
end)

ns:Register("test", "druid: Nature's Grasp when a melee mob is hitting you", function(t)
    local T = ns.tracker
    T._NoteHit("Test Plainstrider", "test-guid-ng", 100)
    t:ok(T:HitBy("test-guid-ng", nil, 3, 101), "it hit you a second ago: on you, in melee")
    t:ok(T:HitBy(nil, "Test Plainstrider", 3, 102.5), "known by name too")
    t:ok(not T:HitBy("test-guid-ng", nil, 3, 110), "ten seconds ago: not any more")
    t:ok(not T:HitBy("someone-else", "Someone Else", 3, 101), "something that never hit you: no")
    local rot = ns:Get("rotation", "DRUID")
    t:ok(rot ~= nil, "the druid's rotation")
    if not rot then return end
    local grasp, roots
    for i, rule in ipairs(rot.priority) do
        if rule.spell == "Nature's Grasp" then grasp = i end
        if rule.spell == "Entangling Roots" then roots = roots or i end
    end
    t:ok(grasp ~= nil, "Nature's Grasp is one of its rules")
    t:ok(grasp and roots and grasp < roots, "ahead of Entangling Roots: instant, where Roots is pushed back under blows")
    if grasp then
        local okW, w = pcall(rot.priority[grasp].when, { inCombat = false, hostile = false, engine = ns.rotation })
        t:ok(okW and not w, "not out of a fight")
    end
    local keys = rot.fightKeys(ns.rotation)
    local has = false
    for _, spell in ipairs(keys.alt or {}) do if spell == "Nature's Grasp" then has = true end end
    -- (Only the caster's keys carry it: in a form the lists are the form's.)
    if keys.ctrl and keys.ctrl[1] == "Entangling Roots" then
        t:ok(has, "caster form: Alt + key holds Nature's Grasp when no potion does")
    end
end)

-------------------------------------------------------------------------------
-- 0.35.194: the suggested spell on a modifier of its own (Ctrl + Shift); the
-- move note below the button, faint.
-------------------------------------------------------------------------------

ns:Register("test", "queue: a fifth press, Ctrl + Shift, for another spell of the fight", function(t)
    local Q, C = ns.queue, ns.cast
    t:eq(#Q.ORDER, 4, "four modifier presses beside the key's own")
    t:eq(Q.ORDER[4], "more", "the last is Ctrl + Shift")
    t:eq(Q.LABEL.more, "C+S", "written C+S above its icon")
    t:eq(Q.NAME.more, "CTRL + SHIFT", "and in full in a sentence")
    -- Which spell goes on it: the first of the fight's others that no other press casts.
    local wrath = { spell = "Wrath", kind = "damage" }
    local slots = Q.Slots(wrath, { heal = "Regrowth", emergency = "item:118", ctrlSpell = "Entangling Roots",
        keySpell = "Wrath", more = { "Nature's Grasp", "Moonfire", "War Stomp", "Entangling Roots" } })
    t:eq(slots.ctrl and slots.ctrl.spell, "Entangling Roots", "Ctrl as before")
    t:eq(slots.alt and slots.alt.item, "item:118", "Alt holds the potion")
    t:eq(slots.more and slots.more.spell, "Nature's Grasp", "so Ctrl + Shift gets Nature's Grasp")
    slots = Q.Slots(wrath, { heal = "Regrowth", ctrlSpell = "Entangling Roots", altSpell = "Nature's Grasp",
        keySpell = "Wrath", more = { "Nature's Grasp", "Moonfire", "War Stomp" } })
    t:eq(slots.alt and slots.alt.spell, "Nature's Grasp", "no potion: Alt takes Nature's Grasp")
    t:eq(slots.more and slots.more.spell, "Moonfire", "and Ctrl + Shift the next one, Moonfire")
    slots = Q.Slots(wrath, { keySpell = "Wrath", more = { "Wrath" } })
    t:eq(slots.more, nil, "nothing the key doesn't cast already: empty")
    t:eq(Q.Slots(wrath, {}).more, nil, "a class with no other spells: empty")
    -- The list for it: the ones you know, the class's order, nothing twice.
    local def = { fightKeys = function() return { ctrl = { "Entangling Roots", "Moonfire" }, alt = { "Nature's Grasp", "Moonfire", "War Stomp" } } end }
    local list = Q.MoreList(def, function(s) return s ~= "War Stomp" end, nil)
    t:eq(table.concat(list, ", "), "Nature's Grasp, Moonfire, Entangling Roots", "Alt's list, then Ctrl's; only what you know; nothing twice")
    def = { fightKeys = function() return { ctrl = { "A" }, alt = { "B" }, more = { "Z" } } end }
    t:eq(Q.MoreList(def, function() return true end, nil)[1], "Z", "a class may name its own")
    -- Flow advises it: that slot is the one to press.
    local live = { key = wrath, ctrl = { spell = "Entangling Roots" }, shift = { spell = "Regrowth", kind = "heal" },
                   alt = { item = "item:118" }, more = { spell = "Nature's Grasp" } }
    t:eq(Q.AdviceSlot({ spell = "Nature's Grasp", kind = "buff" }, live), "more", "Nature's Grasp advised: Ctrl + Shift lights up")
    t:eq(Q.AdviceSlot({ spell = "Moonfire" }, live), nil, "something on no press: still your bar (the corner icon)")
    -- Holding Ctrl + Shift: the big icon shows it.
    local view, swapped = Q.ModView(wrath, live, "more", true)
    t:ok(swapped == "more" and view.spell == "Nature's Grasp", "held: the big icon becomes it")
    t:ok(view.label:find("CTRL + SHIFT + key", 1, true) ~= nil, "and says which keys: " .. tostring(view.label))
    -- The key itself.
    t:eq(C.SlotKey("Q", "more"), "CTRL-SHIFT-Q", "Q: Ctrl + Shift + Q")
    t:eq(C.SlotKey("BUTTON5", "ctrl"), "CTRL-BUTTON5", "Ctrl as before")
    t:eq(C.SlotKey("BUTTON5", "alt"), "ALT-BUTTON5", "Alt as before")
    t:eq(C.SlotKey("SHIFT-E", "more"), nil, "a key that already uses Shift: no such press")
    t:eq(C.SlotKey("Q", "nope"), nil, "not a slot: nothing")
    t:eq(#C.SLOTS, 4, "the button has the four")
    -- On the screen: a fourth, smallest icon in the row.
    local icon = ns.rotation.icon
    if icon and icon.deck then
        t:eq(#icon.deck, 4, "four icons run out to the left")
        t:ok(icon.deck[4]:GetWidth() < icon.deck[3]:GetWidth(), "each smaller than the last")
        t:eq(icon.deck[4].mod:GetText(), "C+S", "its name above it")
    end
end)

ns:Register("test", "move handle: its note sits below the button, faint", function(t)
    t:ok(ns.MOVE_NOTE_DROP >= 16, "far enough down to clear the button's own line of text")
    t:ok(ns.MOVE_NOTE_ALPHA < 1, "faint")
    local h = ns.cast and ns.cast.handle
    if not (h and h.text) then t:ok(true, "(the Flow key isn't built yet)") return end
    local p, rel, rp, _, y = h.text:GetPoint(1)
    -- (Docked, the one note hangs under the self button, so it's below both: 0.35.247.)
    t:ok(p == "TOP" and (rel == h or rel == h.noteUnder) and rp == "BOTTOM", "its top hangs from the button's bottom edge (the self button's when docked)")
    t:ok((y or 0) < 0, "below it")
    t:eq(h.text:GetNumPoints(), 1, "and nowhere above it any more")
    if not h:IsMouseOver() then
        h:Paint(false)
        t:near(h.text:GetAlpha(), ns.MOVE_NOTE_ALPHA, 0.01, "faint until the mouse is on the handle")
    end
end)

-------------------------------------------------------------------------------
-- 0.35.195: the arrow follows a trail only while it heads toward the step.
-------------------------------------------------------------------------------

ns:Register("test", "arrow: a trail is followed only while it heads toward the step", function(t)
    local N = ns.nav
    -- You at 0, 0; the step due east at 400, 0.
    t:ok(N.TrailHeadingOk(0, 0, 30, 5, 400, 0), "a trail that sets off toward the step: followed")
    t:ok(N.TrailHeadingOk(0, 0, 20, 25, 400, 0), "bending 50 degrees off: still followed")
    t:ok(not N.TrailHeadingOk(0, 0, 5, 30, 400, 0), "80 degrees off to one side: not followed")
    t:ok(not N.TrailHeadingOk(0, 0, -30, 0, 400, 0), "leading backwards: not followed (the arrow pointed the wrong way)")
    t:ok(N.TrailHeadingOk(0, 0, -3, 0, 400, 0), "a trail point right at your feet says nothing about a heading")
    t:ok(N.TrailHeadingOk(0, 0, 0, 30, 400, 0, 100), "a wider allowance when asked for")
    t:ok(N.TrailHeadingOk(0, 0, 30, 0, 0, 0), "standing on the step: nothing to compare")
    t:eq(N.TRAIL_HEADING, 60, "60 degrees at most")
end)

-------------------------------------------------------------------------------
-- 0.35.196: the export (your quests, skills and Flow's route as lines a
-- script reads) for tools\route-check.ps1.
-------------------------------------------------------------------------------

ns:Register("test", "export: your quests, skills and the route as lines a script can read", function(t)
    local X = ns.export
    t:eq(X.Clean(12), "12", "a whole number")
    t:eq(X.Clean(12.345), "12.3", "a fraction: one decimal")
    t:eq(X.Clean(true), "1", "yes")
    t:eq(X.Clean(false), "0", "no")
    t:eq(X.Clean(nil), "", "nothing")
    t:eq(X.Clean("a|cffff0000b|r^c\nd"), "ab c d", "colour codes, the separator and line breaks are taken out of text")
    local line = X.Line("goal", { { "key", "759:1" }, { "level", 10 }, { "gone", nil }, { "text", "Wildmane Totem: 5 -> 8" } })
    t:eq(line, "E^goal^key=759:1^level=10^text=Wildmane Totem: 5 -> 8", "one record: its kind, then key=value fields; missing ones left out")
    local r = X.Parse(line)
    t:ok(r and r.kind == "goal" and r.key == "759:1" and r.level == "10" and r.text == "Wildmane Totem: 5 -> 8", "and it reads back")
    t:eq(X.Parse("not a record"), nil, "another line: not a record")
    -- The real thing, as it is now.
    local ok, lines = pcall(X.Lines)
    t:ok(ok and type(lines) == "table" and #lines >= 3, "the export builds" .. (ok and "" or (": " .. tostring(lines))))
    if not (ok and type(lines) == "table") then return end
    local first, last = X.Parse(lines[1]), X.Parse(lines[#lines])
    t:ok(first and first.kind == "export" and first.v == tostring(X.VERSION), "it starts by saying its version")
    t:ok(last and last.kind == "end" and tonumber(last.lines) == #lines, "and ends by saying how many lines there were")
    local you, bad, kinds = nil, nil, {}
    for _, l in ipairs(lines) do
        local rec = X.Parse(l)
        if not rec then bad = bad or l
        else
            kinds[rec.kind] = (kinds[rec.kind] or 0) + 1
            if rec.kind == "you" then you = rec end
        end
        if l:find("|", 1, true) or l:find("\n", 1, true) then bad = bad or l end
    end
    t:eq(bad, nil, "every line is a record, with nothing the game's chat would read as a code")
    t:ok(you and tonumber(you.level) == UnitLevel("player"), "it says who you are")
    t:ok(kinds.opt == 1, "and how the route is set")
    -- (A step's own kind is the field "step": "kind" is the record's.)
    t:ok((kinds.goal or 0) + (kinds.plan or 0) >= 0, "steps and the route are records of their own")
    local plan = ns.nav and ns.nav.plan or {}
    t:eq(kinds.plan or 0, #plan, "one plan record for every step on the route")
    -- Flight masters on your continent, for "you pass one you haven't learned".
    local S = ns.services
    local okS, list = pcall(S.All, S, "flight", 5)
    t:ok(okS and type(list) == "table" and #list <= 5, "the flight masters Flow can find, nearest first" .. (okS and "" or (": " .. tostring(list))))
    t:ok(type(ns.commands.export) == "function", "/flow export")
end)

-------------------------------------------------------------------------------
-- 0.35.197: after a fight: eat and drink together, or bandage when it
-- covers it.
-------------------------------------------------------------------------------

ns:Register("test", "recovery: eat and drink in one sit, or bandage when it covers it", function(t)
    if deadSkip(t) then return end
    local E, BI = ns.rotation, ns.buffItems
    -- The count of mana casts: up with each cast, back with time.
    t:near(E.StepSpent(4, 12, false, false), 3, 0.001, "out of a fight: one cast comes back every 12 seconds")
    t:near(E.StepSpent(4, 12, true, false), 4, 0.001, "in a fight: none")
    t:near(E.StepSpent(4, 6, false, true), 2, 0.001, "drinking: one every 3 seconds")
    t:near(E.StepSpent(0.2, 60, false, false), 0, 0.001, "never below none")
    t:ok(E.DrinkWithFood(3), "three casts: worth a drink with your food")
    t:ok(not E.DrinkWithFood(2), "two: not yet")
    t:ok(not E.DrinkWithFood(nil), "nothing counted: no")
    -- The order for now.
    local mine = { "bandage", "food", "heal" }
    t:eq(table.concat(E.SmartRecover(mine, true, false), ","), "food,bandage,heal", "you'll sit to drink: food first (one sit does both)")
    t:eq(table.concat(E.SmartRecover(mine, true, true), ","), "food,bandage,heal", "and so even when a bandage would cover it")
    t:eq(table.concat(E.SmartRecover({ "food", "bandage", "heal" }, false, true), ","), "bandage,food,heal", "no drink needed, a bandage covers it: the bandage first")
    t:eq(table.concat(E.SmartRecover(mine, false, false), ","), "bandage,food,heal", "neither: your own order")
    t:eq(table.concat(E.SmartRecover({ "heal", "food", "bandage" }, false, false), ","), "heal,food,bandage", "whatever your order is")
    t:eq(table.concat(E.SmartRecover({ "heal", "bandage", "food" }, true, false), ","), "heal,food,bandage", "a heal spell you put first stays first")
    t:eq(#mine, 3, "your saved order isn't changed")
    -- Does a bandage cover it?
    t:ok(E.BandageCovers(100, 114, 0, 15), "114 healed for 100 missing: yes")
    t:ok(not E.BandageCovers(300, 114, 0, 15), "114 for 300 missing: no")
    t:ok(E.BandageCovers(nil, 114, 10, 15), "health hidden: by Flow's estimate, a little hurt: yes")
    t:ok(not E.BandageCovers(nil, 114, 30, 15), "health hidden, badly hurt: no")
    t:ok(not E.BandageCovers(nil, 114, 0, 15), "not hurt: nothing to cover")
    t:ok(not E.BandageCovers(100, nil, 0, 15), "no bandage: no")

    -- The key: with the food and bandage stood in for.
    local r = ns.db.rotation
    local keep = { busy = E.RecoverBusy, mounted = E.Mounted, hd = E.HealDecision, lh = E.LowHealthHeal, eh = E.EarlyHeal,
                   band = BI.BandageStep, food = BI.FoodStep, hurt = E.hurt, can = E.CannibalizeStep, now = E.RecoverNow,
                   order = r.recoverOrder, smart = r.recoverSmart, b = r.recoverBandage, f = r.recoverFood, h = r.recoverHeal,
                   eat = E.EatingNow, drinking = E.Drinking, share = E.ManaShare, cant = E.CantAfford, spent = E.spent,
                   drink = BI.DrinkStep, rd = r.recoverDrink }
    local ok, err = pcall(function()
        E.RecoverBusy = function() return false end
        E.Mounted = function() return false end
        E.HealDecision, E.LowHealthHeal, E.EarlyHeal = function() end, function() end, function() end
        E.CannibalizeStep = function() end
        BI.BandageStep = function() return { label = "Bandage" } end
        BI.FoodStep = function() return { label = "Food" } end
        r.recoverOrder, r.recoverBandage, r.recoverFood, r.recoverHeal, r.recoverSmart = "bandage,food,heal", nil, nil, nil, nil
        E.hurt = 8   -- (hurt a little: enough for a bandage, not for food on its own)
        local ctx = { inCombat = false, hostile = false, maxHp = 0, hpPct = 0 }
        local def = { heals = {} }
        local function pick() local s = E:Recover(ctx, def, "all"); return s and s.label end
        E.RecoverNow = function() return false, false end
        t:eq(pick(), "Bandage", "nothing special: your order, the bandage")
        E.RecoverNow = function() return true, false end
        t:eq(pick(), "Food", "you'll sit to drink: food first, though you're only a little hurt")
        E.RecoverNow = function() return false, true end
        r.recoverOrder = "food,bandage,heal"
        E.hurt = 20
        t:eq(pick(), "Bandage", "food first in your order, but a bandage covers it and no drink is needed: the bandage")
        r.recoverSmart = false
        t:eq(pick(), "Food", "switched off: your own order again")
        r.recoverSmart = nil
        -- The drink, the moment you're eating.
        BI.DrinkStep = function() return { label = "Drink: Water" } end
        E.Drinking = function() return false end
        E.ManaShare = function() return nil end
        E.CantAfford = function() return false end
        r.recoverDrink = nil
        E.EatingNow = function() return true end
        E.spent = 4
        local s = E:DrinkStep(ctx)
        t:eq(s and s.label, "Drink: Water", "eating, four casts spent: drink with it")
        t:ok(s and s.reason and s.reason:find("eating", 1, true) ~= nil, "and it says why")
        E.spent = 1
        t:eq(E:DrinkStep(ctx), nil, "eating, hardly any mana spent: no drink")
        E.spent = 4
        E.EatingNow = function() return false end
        t:eq(E:DrinkStep(ctx), nil, "not eating, mana not low: no drink on its own")
        r.recoverSmart = false
        E.EatingNow = function() return true end
        t:eq(E:DrinkStep(ctx), nil, "switched off: only when low on mana")
    end)
    E.RecoverBusy, E.Mounted, E.HealDecision, E.LowHealthHeal, E.EarlyHeal = keep.busy, keep.mounted, keep.hd, keep.lh, keep.eh
    BI.BandageStep, BI.FoodStep, E.hurt, E.CannibalizeStep, E.RecoverNow = keep.band, keep.food, keep.hurt, keep.can, keep.now
    r.recoverOrder, r.recoverSmart, r.recoverBandage, r.recoverFood, r.recoverHeal = keep.order, keep.smart, keep.b, keep.f, keep.h
    E.EatingNow, E.Drinking, E.ManaShare, E.CantAfford, E.spent = keep.eat, keep.drinking, keep.share, keep.cant, keep.spent
    BI.DrinkStep, r.recoverDrink = keep.drink, keep.rd
    t:ok(ok, "the key's recovery runs" .. (ok and "" or (": " .. tostring(err))))
    local okN, sitting, covers = pcall(E.RecoverNow, E, { hostile = false }, E:Definition() or { heals = {} })
    t:ok(okN and type(sitting) == "boolean" and type(covers) == "boolean", "what it is right now reads from the game" .. (okN and "" or (": " .. tostring(sitting))))
    t:ok(type(E.CostsMana("Wrath")) == "boolean", "whether a spell costs mana can be asked")
end)

-------------------------------------------------------------------------------
-- 0.35.198 (found by tools\route-check.ps1): an errand you can run on foot
-- isn't sent through a travel spell; flight paths to learn as you pass.
-------------------------------------------------------------------------------

ns:Register("test", "planner: an errand you can run on foot isn't sent through a travel spell", function(t)
    local P = ns.planner
    local near = { map = 1412, cont = 1, wx = 400, wy = 0 }
    local moon = { map = 1450, cont = 1, wx = 10000, wy = 0 }
    local moon2 = { map = 1450, cont = 1, wx = 10050, wy = 0 }
    local ported = function(pt) return pt.map == 1450 end
    local kept = P.OnFoot({ near, moon }, ported)
    t:ok(#kept == 1 and kept[1] == near, "a spot on foot and one a teleport away: only the one on foot")
    t:eq(#P.OnFoot({ moon, moon2 }, ported), 2, "a step that's only there keeps its spots")
    t:eq(#P.OnFoot({ near }, ported), 1, "a step with no teleport spot: as it is")
    -- The whole planner: full bags, a merchant 400 yd away and one in Moonglade "one cast away".
    local you = { map = 1412, cont = 1, wx = 0, wy = 0 }
    local port = function(a, b) if b.map == 1450 and a.map ~= 1450 then return 120 end end
    local merchant = { key = "merchant", text = "Sell", points = { near, moon } }
    local plan = P:Plan(you, { merchant }, { port = port })
    t:ok(plan and plan[1] and plan[1].point == near, "the merchant you can walk to, not the one 10,000 yards off by teleport")
    t:near(plan and plan[1] and plan[1].leg or 0, 400, 1, "400 yards")
    -- A step that is only in Moonglade (the class quest) is still a cast away.
    local quest = { key = "5926:1", text = "class quest", points = { moon } }
    plan = P:Plan(you, { quest }, { port = port })
    t:ok(plan and plan[1] and plan[1].point == moon, "a step that's only there: still planned there")
    -- Without the spell: nothing changes.
    plan = P:Plan(you, { merchant }, {})
    t:ok(plan and plan[1] and plan[1].point == near, "no travel spell: the nearest, as always")
end)

ns:Register("test", "flight paths: a step for each one you don't have, when you pass it", function(t)
    local FP = ns.flightPaths
    local kelsuwa = { name = "Kelsuwa", map = 1413, x = 0.44, y = 0.59, cont = 1, wx = -2300, wy = -1950 }
    local sikwa = { name = "Sikwa", map = 1413, x = 0.51, y = 0.30, cont = 1, wx = -430, wy = -2600 }
    t:ok(not FP.Learned(kelsuwa, {}, {}), "never talked to, no flight point there: not learned")
    t:ok(FP.Learned(kelsuwa, { Kelsuwa = true }, {}), "you opened their flight map: learned")
    t:ok(FP.Learned(kelsuwa, {}, { ["Camp Taurajo"] = { cont = 1, wx = -2350, wy = -1900 } }), "a flight point you know is where they stand: learned")
    t:ok(not FP.Learned(kelsuwa, {}, { ["Crossroads"] = { cont = 1, wx = -430, wy = -2600 } }), "a flight point somewhere else: not theirs")
    t:ok(not FP.Learned(kelsuwa, {}, { ["Elsewhere"] = { cont = 0, wx = -2300, wy = -1950 } }), "the same spot on another continent: not theirs")
    local goals = FP.Goals({ kelsuwa, sikwa, kelsuwa }, { Sikwa = true }, {})
    t:eq(#goals, 1, "one step for the one you don't have (a name once)")
    local g = goals[1]
    t:eq(g and g.key, "flightpath:Kelsuwa", "its key")
    t:eq(g and g.text, "Learn the flight path: Kelsuwa", "what it says")
    t:ok(g and g.optional == true, "optional: only when it's close to the way you're going")
    t:ok(g and g.kind == "flight" and ns.theme.kinds.flight ~= nil, "its own kind of step, with an icon")
    t:ok(g and g.points[1].map == 1413, "where they stand")
    t:eq(#FP.Goals({}, {}, {}), 0, "no flight masters known: no steps")
    -- On the route: its own kind, on by default; and the step's source runs.
    local kind = ns:Get("routeKind", "flightpaths")
    t:ok(kind and kind.default == true and kind.match({ provider = "flightpath" }) and not kind.match({ provider = "questie" }), "a kind of its own to untick")
    FP._Forget()
    local ok, res = pcall(ns:Get("navGoal", "flightpath").collect)
    t:ok(ok and (res == nil or type(res) == "table"), "the steps' source runs" .. (ok and "" or (": " .. tostring(res))))
    -- Talking to one: remembered (per character), and its step goes.
    with(ns.db, "flightTalked", {}, function()
        with(ns.nav, "Collect", function() end, function()
            t:ok(FP.Talked("Kelsuwa"), "you opened Kelsuwa's flight map")
            t:ok(ns.db.flightTalked.Kelsuwa, "remembered")
            t:ok(not FP.Talked(""), "no name: nothing")
        end)
    end)
    FP._Forget()
    -- The planner takes an optional step only when it's nearly on the way.
    local P = ns.planner
    local you = { map = 1413, cont = 1, wx = 0, wy = 0 }
    local quest = { key = "1:1", text = "quest", points = { { map = 1413, cont = 1, wx = 1000, wy = 0 } } }
    local onWay = { key = "flightpath:On", text = "fp", optional = true, weight = 1, points = { { map = 1413, cont = 1, wx = 500, wy = 40 } } }
    local offWay = { key = "flightpath:Off", text = "fp", optional = true, weight = 1, points = { { map = 1413, cont = 1, wx = 500, wy = 3000 } } }
    local plan = P:Plan(you, { quest, onWay, offWay }, {})
    local keys = {}
    for _, s in ipairs(plan or {}) do keys[s.goal.key] = true end
    t:ok(keys["flightpath:On"], "a flight master 40 yd off your way: on the route")
    t:ok(not keys["flightpath:Off"], "one 3,000 yd off it: left out")
end)

ns:Register("test", "arrow: says when your hearthstone is clearly the quicker way", function(t)
    local H, N = ns.hearth, ns.nav
    t:eq(H.Cue(nil, "Thunder Bluff"), nil, "not quicker: nothing")
    local cue = H.Cue(221, "Thunder Bluff")
    t:ok(cue and cue:find("Hearthstone (Thunder Bluff)", 1, true) ~= nil and cue:find("quicker", 1, true) ~= nil, "quicker: it says where to and by how much: " .. tostring(cue))
    t:ok(H.Cue(60, nil):find("your inn", 1, true) ~= nil, "a home with no name: your inn")
    -- 2,100 yd on foot against 413 yd from your inn, the stone ready: clearly quicker.
    local c = H.Compare(2100, 413, 0, 7)
    t:ok(c and c.better, "the walk back to Thunder Bluff the route check found: the stone wins")
    t:ok(not H.Compare(600, 413, 0, 7).better, "a short walk: not worth it")
    t:ok(not H.Compare(2100, 413, 1500, 7).better, "25 minutes left on its cooldown: not quicker")
    -- The arrow's piece of text: runs, and is words or nothing.
    local ok, text = pcall(N.HearthCue, "test:hearth-cue", { map = 1412, x = 0.5, y = 0.5 }, 2100, GetTime())
    t:ok(ok and type(text) == "string", "the arrow's cue runs" .. (ok and "" or (": " .. tostring(text))))
    local ok2, saving = pcall(H.Saves, H, 1412, 0.5, 0.5, 2100)
    t:ok(ok2 and (saving == nil or type(saving) == "number"), "and the estimate behind it")
end)

