ns:Register("test", "easy key: it follows your form in a fight", function(t)
    local C = ns.cast
    local forms = { { name = "Bear Form", index = 1 }, { name = "Cat Form", index = 3 } }
    local keys = {
        none = { key = "Wrath", ctrl = { "Moonfire", "Entangling Roots" } },
        ["Bear Form"] = { key = "Maul", ctrl = { "Swipe", "Demoralizing Roar" } },
        ["Cat Form"] = { key = "Claw", ctrl = { "Ferocious Bite", "Rake" } },
    }
    local known = { Wrath = true, Moonfire = true, Maul = true, ["Demoralizing Roar"] = true }
    local cond, plan = C.FormPlan(forms, keys, function(s) return known[s] == true end)
    t:eq(cond, "[form:1] 1; [form:3] 3; 0", "the game is asked about each form you have")
    t:ok(plan[0].key == "Wrath" and plan[0].ctrl == "Moonfire", "no form: Wrath, Moonfire on Ctrl")
    t:ok(plan[1].key == "Maul" and plan[1].ctrl == "Demoralizing Roar", "Bear Form: Maul, and the first Ctrl spell you know")
    t:eq(plan[3], nil, "Cat Form with none of its spells known: left alone")
    cond, plan = C.FormPlan({}, keys)
    t:ok(cond == "0" and plan[0].key == "Wrath", "no forms yet: only the caster's")
    local same = select(2, C.FormPlan({}, { none = { key = "Wrath", ctrl = "Wrath" } }))
    t:eq(same[0].ctrl, nil, "Ctrl never repeats the key's own spell")
    local druid = ns:Get("rotation", "DRUID")
    local ok, k = pcall(druid.formKeys, ns.rotation)
    t:ok(ok and k.none and k["Bear Form"] and k["Cat Form"], "the druid says what each form casts")
    local fk = druid.fightKeys(ns.rotation)
    if ns.api.Form() == nil then
        t:eq(fk.ctrl[1], "Moonfire", "caster: Moonfire has Ctrl")
        t:eq(fk.more and fk.more[1], "Entangling Roots", "and Entangling Roots has Ctrl + Shift")
    end
    t:ok(type(C.FormLines()) == "table" and #C.FormLines() >= 1, "/flow key test says what each form is given")
    if not InCombatLockdown() then
        local ok2, err = pcall(C.SetFormKeys)
        t:ok(ok2, "the handler is set up without error" .. (ok2 and "" or (": " .. tostring(err))))
        local _, class = UnitClass("player")
        if class == "DRUID" and not C.formFailed and C.FormKeyOn() then
            local h = C._FormHeader()
            t:ok(h ~= nil, "a druid has the handler")
            t:eq(h and h:GetAttribute("key-0"), "Wrath", "it holds the caster's key spell")
            t:ok(issecurevariable("RegisterStateDriver"), "the game's own function stays untainted")
        end
    end
end)

-------------------------------------------------------------------------------
-- 0.35.206: the second key (the self button's) has heals and potions on its
-- modifiers.
-------------------------------------------------------------------------------

ns:Register("test", "second key: heals and potions on the buff key's modifiers", function(t)
    local K = ns.careKeys
    t:ok(K ~= nil, "the second key's file loaded")
    if not K then return end
    local function modKey(key, mod) return mod .. "-" .. key end
    t:eq(K.KeyFor("E", "shift", modKey), "SHIFT-E", "Shift + the key")
    t:eq(K.KeyFor("E", "more", modKey), "SHIFT-CTRL-E", "Ctrl + Shift: both modifiers are added")
    t:eq(K.KeyFor("E", "more"), "CTRL-SHIFT-E", "in the game's own order")
    t:eq(K.KeyFor("SHIFT-E", "shift"), nil, "a key that already uses the modifier: no such press")
    local plan = K.Plan({ quick = "Regrowth", heals = { "Regrowth", "Healing Touch", "Rejuvenation" }, hots = { "Rejuvenation" },
        emergency = "item:858", bandage = "item:1251", cures = { "Cure Poison" } })
    t:eq(plan.key.spell, "Regrowth", "the key in a fight: your quickest heal")
    t:eq(plan.shift.spell, "Healing Touch", "Shift: your other heal")
    t:eq(plan.ctrl.spell, "Rejuvenation", "Ctrl: your heal over time")
    t:eq(plan.alt.item, "item:858", "Alt: your potion")
    t:eq(plan.more.item, "item:1251", "Ctrl + Shift: your bandage")
    t:eq(plan.key.unit, "player", "on you")
    plan = K.Plan({ quick = "Holy Light", heals = { "Holy Light" }, cures = { "Purify" } })
    t:ok(plan.shift == nil and plan.ctrl == nil and plan.alt == nil, "one heal and nothing carried: only the key")
    t:eq(plan.more.spell, "Purify", "no bandage: your cure")
    plan = K.Plan({})
    t:ok(plan.key == nil and plan.more == nil, "nothing known: nothing set")
    local kind, what, unit = K.Attributes({ spell = "Rejuvenation", unit = "player" })
    t:ok(kind == "spell" and what == "Rejuvenation" and unit == "player", "a spell, as the button's attributes")
    kind, what = K.Attributes({ item = "item:858" })
    t:ok(kind == "item" and what == "item:858", "an item, as the button's attributes")
    t:eq(K.Attributes(nil), nil, "nothing: none")
    local ok, now = pcall(K.Now)
    t:ok(ok and type(now) == "table", "what you'd get right now builds" .. (ok and "" or (": " .. tostring(now))))
    local lines = K.Lines()
    t:ok(type(lines) == "table" and #lines >= 1, "/flow carekeys has something to say")
    -- Off (the self button off, or no key): the key keeps the self button's own way in a fight.
    local c = ns.db.buffButton or {}
    with(c, "enabled", false, function()
        t:eq(K.FightKey(), nil, "self button off: no heal on its key")
        t:ok(not K.Active(), "and nothing bound")
    end)
    if not InCombatLockdown() then
        local okA, err = pcall(K.Apply)
        t:ok(okA, "setting the presses runs without error" .. (okA and "" or (": " .. tostring(err))))
    end
end)

-------------------------------------------------------------------------------
-- 0.35.207: the heal and potion move to the second key; every press follows
-- your form; key conflicts can be cleared; the buff key in Flow Settings.
-------------------------------------------------------------------------------

ns:Register("test", "easy key: with heals on the second key, Shift and Alt are attacks", function(t)
    local Q = ns.queue
    local def = { fightKeys = function() return { ctrl = { "Moonfire", "Entangling Roots" }, shift = { "Entangling Roots", "Nature's Grasp" },
        alt = { "Nature's Grasp", "War Stomp" } } end }
    local all = function() return true end
    local ctrl, alt, shift = Q.FightSpells(def, all, "Wrath")
    t:ok(ctrl == "Moonfire" and alt == "Nature's Grasp" and shift == "Entangling Roots", "Ctrl, Alt and Shift each get their own spell")
    local wrath = { spell = "Wrath", kind = "damage" }
    local slots = Q.Slots(wrath, { ctrlSpell = ctrl, altSpell = alt, shiftSpell = shift, keySpell = "Wrath", more = { "War Stomp" } })
    t:eq(slots.shift and slots.shift.spell, "Moonfire", "no heal on Shift: your second attack takes it (the nearest icon)")
    t:eq(slots.ctrl and slots.ctrl.spell, "Entangling Roots", "and Ctrl gets the third")
    t:eq(slots.alt and slots.alt.spell, "Nature's Grasp", "no potion on Alt: the attack takes it")
    t:eq(slots.more and slots.more.spell, "War Stomp", "Ctrl + Shift: one more")
    slots = Q.Slots(wrath, { heal = "Regrowth", ctrlSpell = ctrl, altSpell = alt, shiftSpell = shift, emergency = "item:858" })
    t:eq(slots.shift.spell, "Regrowth", "a heal on Shift (no second key): it stays")
    t:eq(slots.alt.item, "item:858", "and the potion stays on Alt")
    -- A heal advised: Shift only when Shift heals.
    t:eq(Q.AdviceSlot({ spell = "Healing Touch", kind = "heal" }, { key = wrath, shift = { spell = "Regrowth", kind = "heal" } }), "shift", "Shift heals: a heal advised is Shift")
    t:eq(Q.AdviceSlot({ spell = "Healing Touch", kind = "heal" }, { key = wrath, shift = { spell = "Entangling Roots", kind = "damage" } }), nil,
        "Shift is an attack: a heal advised isn't Shift's")
    local K = ns.careKeys
    t:eq(K.PressText("key", "E"), "E", "the second key itself")
    t:eq(K.PressText("alt", "E"), "A-E", "Alt + the second key, short")
    t:eq(K.PressText("more", "E", true), "Ctrl + Shift + E", "and in words")
    local c = ns.db.buffButton or {}
    with(c, "enabled", false, function()
        t:ok(not K.Moved(), "self button off: nothing moved, Flow's key keeps its heal")
        t:eq(ns.rotation.HealPress(), "Shift + key", "and the words say Shift + key")
        t:eq(K.PressFor({ spell = "Regrowth", kind = "heal" }), nil, "no second key to press")
    end)
    t:eq(ns.cast.AdviceLabel({ spell = "Regrowth" }, "Regrowth", nil), "Shift+", "advice label: Shift heals")
    t:eq(ns.cast.AdviceLabel({ spell = "Regrowth" }, nil, "E:"), "E:", "advice label: the second key")
    t:eq(ns.cast.AdviceLabel({ spell = "Moonfire" }, nil, nil), "bar:", "advice label: on your bar")
end)

ns:Register("test", "easy key: every press follows your form", function(t)
    local C = ns.cast
    local druid = ns:Get("rotation", "DRUID")
    local keys = druid.formKeys(ns.rotation)
    local forms = { { name = "Bear Form", index = 1 } }
    local known = { Wrath = true, Moonfire = true, ["Entangling Roots"] = true, ["Nature's Grasp"] = true, ["War Stomp"] = true,
                    Maul = true, ["Demoralizing Roar"] = true, Growl = true, Enrage = true }
    local knows = function(s) return known[s] == true end
    local _, plan = C.FormPlan(forms, keys, knows, C.FORM_SLOTS)
    local c, b = plan[0], plan[1]
    t:ok(c.key == "Wrath" and c.shift == "Moonfire" and c.ctrl == "Entangling Roots" and c.alt == "Nature's Grasp" and c.more == "War Stomp",
        "caster: Wrath, Moonfire (Shift), Roots (Ctrl), Nature's Grasp, War Stomp: five presses, none twice")
    t:ok(b.key == "Maul" and b.shift == "Demoralizing Roar" and b.ctrl == "Growl" and b.alt == "Enrage",
        "bear at this level: Maul, Demoralizing Roar (Shift), Growl (Ctrl), Enrage")
    t:eq(b.more, nil, "nothing left for Ctrl + Shift in bear: left as it was")
    _, plan = C.FormPlan(forms, keys, knows)
    t:ok(plan[1].shift == nil and plan[1].alt == nil, "heal and potion on Flow's key: Shift and Alt aren't swapped")
    local snippet = C._FormSnippet()
    for _, name in ipairs({ "ctrl", "heal", "emerg", "more" }) do
        t:ok(snippet:find('"*spell-' .. name .. '"', 1, true) ~= nil, "the game's handler sets the '" .. name .. "' press")
    end
    t:ok(snippet:find("PlayerInCombat", 1, true) ~= nil, "only in a fight")
end)

ns:Register("test", "settings: one key for one Flow button; a conflict can be cleared", function(t)
    local S = ns.settings
    t:eq(S.FlowSlotOf("Q", { "BUTTON5", "Q", nil }), 2, "Q is Flow's second key")
    t:eq(S.FlowSlotOf("E", { "BUTTON5", "Q", "E" }), 3, "E is the self button's")
    t:eq(S.FlowSlotOf("F", { "BUTTON5", "Q", "E" }), nil, "F is free of Flow")
    t:eq(S.FlowSlotOf(nil, { "A" }), nil, "no key: none")
    local text = S.ConflictText("E", "Interact With Target", false)
    t:ok(text:find("never both", 1, true) ~= nil, "it says the key won't do both")
    t:ok(text:find("Use it and unbind", 1, true) ~= nil, "and offers to take the other binding off")
    t:ok(S.ConflictText("W", "Move Forward", true):find("movement key", 1, true) ~= nil, "a movement key is flagged")
    t:ok(type(S.Unbind) == "function", "the unbind step is there (it runs only on your click)")
    local f = S._Build and S._Build()
    if f then
        t:ok(f.key3Value ~= nil and f.clear3 ~= nil and f.set3 ~= nil, "Flow Settings has a row for the self button's key")
        t:ok(f.unbind ~= nil and not f.unbind:IsShown(), "the unbind button is hidden until a key in use is picked")
    end
    local BB = ns.buffButton
    t:ok(type(BB.SetKey) == "function" and type(BB.Key) == "function", "the self button's key can be set from the settings")
end)

ns:Register("test", "click: the Flow menu's Buttons section toggles the self button", function(t)
    local ok, items = pcall(ns.menu.RouteItemsRaw, ns.menu)
    t:ok(ok and type(items) == "table", "the menu builds")
    local found, keys
    for _, it in ipairs(ok and items or {}) do
        if type(it.text) == "string" and it.text:find("^Self button: a second button and key") then found = it end
        if type(it.text) == "string" and it.text:find("Dock it under", 1, true) then keys = it end
    end
    t:ok(found ~= nil, "the Buttons section has the self button's tick")
    t:ok(keys ~= nil and type(keys.func) == "function", "and one to dock it")
    if not found or InCombatLockdown() then return end
    local BB = ns.buffButton
    local was = BB.On()
    local okC, err = pcall(found.func)
    t:ok(okC, "a click runs" .. (okC and "" or (": " .. tostring(err))))
    t:eq(BB.On(), not was, "it flips the self button")
    BB.Set(was)
end)

-------------------------------------------------------------------------------
-- 0.35.208: key messages in a box of their own; the self button only when
-- something is due.
-------------------------------------------------------------------------------

ns:Register("test", "settings: a key message stands in its own box, and a conflict flashes", function(t)
    local S = ns.settings
    local r, _, _, extra, flash = S.NoticeLook("conflict")
    t:ok(r ~= nil and flash == true, "a key something else uses: a box that flashes")
    local _, _, _, extraInfo, flashInfo = S.NoticeLook("info")
    t:ok(extra > extraInfo, "with room for its buttons inside")
    t:ok(flashInfo == false, "a plain message: a box, no flash")
    t:ok(select(5, S.NoticeLook("done")) == true, "a key that was set: flashes too")
    t:eq(S.NoticeLook(nil), nil, "no message: no box")
    local f = S._Build and S._Build()
    if not f then return end
    t:ok(f.noticeBg ~= nil and f.noticeAnim ~= nil, "Flow Settings has the box")
    local was = f.status:GetText()
    f.noticeKind = "conflict"
    f.status:SetText("E already does: Interact With Target.")
    t:ok(f.noticeBg:IsShown() and f.noticeKindShown == "conflict", "a conflict message shows it")
    f.status:SetText("Second key cleared.")
    t:eq(f.noticeKindShown, "info", "the next message is a plain one")
    f.status:SetText("")
    t:ok(not f.noticeBg:IsShown(), "an empty message hides it")
    f.status:SetText(was or "")
end)

ns:Register("test", "self button: only when something is due", function(t)
