-- 0.35.214: Flow Auctions: the price asked, giving up on what doesn't sell.
-------------------------------------------------------------------------------

ns:Register("test", "auctions: the price asked is whole silver, a silver under the cheapest seen", function(t)
    local P = ns.posting
    t:eq(P.Price(1234), 1100, "seen 12s 34c: ask 11s (a silver under, no copper)")
    t:eq(P.Price(500), 400, "seen 5s: ask 4s")
    t:eq(P.Price(150), 100, "seen 1s 50c: ask 1s, never under a silver")
    t:eq(P.Price(100), 100, "seen 1s: ask 1s")
    t:eq(P.Price(45), nil, "worth under a silver each: not for the auction house (the game takes no copper prices)")
    t:eq(P.Price(nil), nil, "no price seen: nothing to ask")
    t:eq(P.Price(100000) % 100, 0, "always whole silver")
end)

ns:Register("test", "auctions: unsold until the deposits eat the gain, then it's a vendor item", function(t)
    local P = ns.posting
    -- 10 of something at 5s each, vendor 1s each: the house would earn 37s 50c over the vendor.
    local what, left = P.Verdict(500, 100, 10, 0, 300)
    t:ok(what == "post" and left == 3450, "nothing lost yet, a 3s deposit: post (34s 50c still to gain)")
    t:eq((P.Verdict(500, 100, 10, 3600, 300)), "vendor", "36s of deposits lost already: the vendor pays more now")
    t:eq((P.Verdict(100, 100, 10, 0, 50)), "vendor", "no better than the vendor to begin with: vendor")
    -- The record over time.
    local rec = P.Note(nil, "posted", 1000, 2500)
    t:ok(rec.posted == 1 and rec.lastDeposit == 1000, "a post is counted, with its deposit")
    rec = P.Note(rec, "expired")
    t:ok(rec.expired == 1 and rec.lost == 1000 and not rec.gaveUp, "ran out once: the deposit is lost, still worth trying")
    rec = P.Note(P.Note(rec, "posted", 1000, 2500), "expired")
    rec = P.Note(P.Note(rec, "posted", 1000, 2500), "expired")
    t:ok(rec.expired == 3 and rec.lost == 3000 and rec.gaveUp == true, "three times: 30s lost on a 25s gain, given up")
    rec = P.Note(rec, "sold")
    t:ok(rec.lost == 0 and rec.gaveUp == nil, "a sale wipes the count")
    -- The game's own lines.
    local sold, expired = "A buyer has been found for your auction of %s.", "Your auction of %s has expired."
    local w, name = P.Parse("A buyer has been found for your auction of Light Leather.", sold, expired)
    t:ok(w == "sold" and name == "Light Leather", "the sold line names the item")
    w, name = P.Parse("Your auction of Pattern: Deviate Scale Belt has expired.", sold, expired)
    t:ok(w == "expired" and name == "Pattern: Deviate Scale Belt", "the expired line too")
    t:eq(P.Parse("You have learned a new spell.", sold, expired), nil, "another line: nothing")
    t:eq(P.Parse(nil, sold, expired), nil, "no line: nothing")
    -- Given up: the reason Flow's seller shows.
    with(ns.db.ah, "posts", { [999981] = { name = "Flow Test Hide", expired = 3, lost = 3000, gaveUp = true } }, function()
        local gave, why = P.GaveUp(999981)
        t:ok(gave and why:find("didn't sell at auction 3 time", 1, true) ~= nil, "it says how often it didn't sell: " .. tostring(why))
        t:ok(not P.GaveUp(999982), "an item with no record: not given up")
    end)
end)

ns:Register("test", "click: Flow Auctions opens, lists, and posts nothing away from an auction house", function(t)
    local P = ns.posting
    local ok, list = pcall(P.List)
    t:ok(ok and type(list) == "table", "the list builds" .. (ok and "" or (": " .. tostring(list))))
    t:ok(type(P.Lines()) == "table" and #P.Lines() >= 1, "/flow auctions has something to say")
    local def = ns:Get("gameButton", "auctionhouse")
    t:ok(def and def.label == "Flow Auctions", "a Flow Auctions button is registered for the auction window")
    if P.AtHouse() or InCombatLockdown() then return end   -- (never press Post at a real auction house)
    local was = P._Frame() and P._Frame():IsShown()
    local okO, err = pcall(P.Open, P)
    t:ok(okO and P._Frame() and P._Frame():IsShown(), "the window opens" .. (okO and "" or (": " .. tostring(err))))
    local posted, why = P:Post({ id = 2318, name = "Light Leather", count = 1, each = 100, vendor = 15 })
    t:ok(posted == false and why == "open the auction house first", "away from an auction house nothing is posted")
    local f = P._Frame()
    local okN = pcall(function() f.next:GetScript("OnClick")(f.next) end)
    t:ok(okN, "\"Post next\" runs without error there")
    local okD = pcall(function() f.durations[3]:GetScript("OnClick")(f.durations[3]) end)
    t:ok(okD and P.Duration() == 3, "48 h on a click")
    ns.db.ah.duration = nil
    if not was then f:Hide() end
end)

-------------------------------------------------------------------------------
-- 0.35.215: Flow Banker draws your bank as a grid of slots, read only.
-------------------------------------------------------------------------------

ns:Register("test", "banker: your bank as a grid of slots, in the bank's own order", function(t)
    local B = ns.banker
    local cells, own = B.Cells({ { 2318, 12 }, false, { 2589, 40 }, false, false }, { [2318] = 12, [2589] = 40 })
    t:ok(own and #cells == 5, "slot by slot, the empty ones too")
    t:ok(cells[1].id == 2318 and cells[1].count == 12 and cells[2] == false and cells[3].id == 2589, "each slot where it is in the bank")
    cells, own = B.Cells(nil, { [2589] = 40, [2318] = 12 }, function(id) return id == 2318 and "Light Leather" or "Linen Cloth" end)
    t:ok(not own and #cells == 2 and cells[1].id == 2318, "a bank seen before slots were kept: its things by name")
    cells = B.Cells({}, {})
    t:eq(#cells, 0, "an empty record: no cells")
    -- 8 columns, 6 rows showing.
    local first, off, below = B.GridWindow(48, 0, 8, 6)
    t:ok(first == 1 and off == 0 and below == 0, "48 slots fit: no scrolling")
    first, off, below = B.GridWindow(80, 0, 8, 6)
    t:ok(first == 1 and off == 0 and below == 4, "80 slots: four more rows below")
    first, off, below = B.GridWindow(80, 99, 8, 6)
    t:ok(first == 33 and off == 4 and below == 0, "scrolled past the end: the last six rows")
    t:ok(B.COLS * B.CELL < 330, "the grid fits the window")
end)

ns:Register("test", "click: Flow Banker's bank view shows the grid, the other views their lists", function(t)
    local B = ns.banker
    if InCombatLockdown() then return end
    local was = B._Frame() and B._Frame():IsShown()
    local view, offset = B.view, B.offset
    local bank = ns.db.bank
    ns.db.bank = { items = { [2318] = 12, [2589] = 40 }, layout = { { 2318, 12 }, false, { 2589, 40 } }, seenAt = time() - 600 }
    local ok, err = pcall(B.Show, B, "bank")
    t:ok(ok, "the bank view opens" .. (ok and "" or (": " .. tostring(err))))
    local f = B._Frame()
    if ok and f and f.cells then
        t:ok(f.cells[1]:IsShown() and f.cells[1].id == 2318, "the first slot holds what the bank's first slot held")
        t:ok(f.cells[2]:IsShown() and f.cells[2].id == nil, "an empty slot is an empty square")
        t:ok(f.cells[3]:IsShown() and not f.cells[4]:IsShown(), "as many squares as the bank has slots")
        t:eq(f.rows[1]:GetText() or "", "", "no list lines under the grid")
        t:ok(f.note:GetText():find("10 min ago", 1, true) ~= nil, "it says when Flow saw it: " .. tostring(f.note:GetText()))
        t:ok(pcall(function() f.cells[1]:GetScript("OnEnter")(f.cells[1]); f.cells[1]:GetScript("OnLeave")(f.cells[1]) end), "hovering a slot shows its item")
        t:ok(pcall(function() f:GetScript("OnMouseWheel")(f, -1) end), "the wheel scrolls it")
        pcall(B.Show, B, "prices")
        t:ok(not f.cells[1]:IsShown(), "another view: the grid goes")
    end
    ns.db.bank = bank
    B.view, B.offset = view, offset
    if f then B:Fill(); if not was then f:Hide() end end
end)

-------------------------------------------------------------------------------
-- 0.35.216: NPC roles by the quest data's own flags; banking choices of
-- your own, in a grid.
-------------------------------------------------------------------------------

ns:Register("test", "places: a flight master is a flight master, not a stable master", function(t)
    local S = ns.services
    local f = S.FlagsFrom({ VENDOR = 4, FLIGHT_MASTER = 8, INNKEEPER = 128, BANKER = 256, AUCTIONEER = 4096, STABLEMASTER = 8192, REPAIR = 16384 })
    t:eq(f.flight, 8, "the data's own number for a flight master (8 on WoW: Forever)")
    t:ok(f.flight ~= 8192, "not the stable master's (8192): Xon'cha and Seikwa were taken for flight masters")
    t:ok(f.vendor == 4 and f.repair == 16384 and f.inn == 128 and f.bank == 256 and f.auction == 4096, "and each other role by its own number")
    f = S.FlagsFrom({ VENDOR = 128, FLIGHT_MASTER = 8192, INNKEEPER = 65536, BANKER = 131072, AUCTIONEER = 2097152, REPAIR = 4096 })
    t:ok(f.flight == 8192 and f.vendor == 128, "a later game's data: its numbers")
    f = S.FlagsFrom(nil)
    t:ok(f.flight == 8 and f.vendor == 4, "no list in the data: the first game's numbers")
    local db = ns.quests.QuestieDB and ns.quests.QuestieDB()
    if db and db.npcFlags then
        t:eq(S.FlagsFrom(db.npcFlags).flight, db.npcFlags.FLIGHT_MASTER, "this client's quest data is read for it")
    end
end)

ns:Register("test", "banker: your own choice beats Flow's, and a click sets it", function(t)
    local B = ns.banker
    local function row(name, id, rule, kind)
        return { name = name, id = id, rule = rule, kind = kind, action = "keep", stacks = 1, count = 5 }
    end
    local leather = row("Light Leather", 2318, "professionMaterial", "Trade Goods: Leather")
    local water = row("Refreshing Spring Water", 159, "professionMaterial", "Consumable: Food & Drink")
    t:ok(B.Banks(leather, {}, {}), "Flow's choice: leather goes to the bank")
    local ok, why = B.Banks(leather, {}, { [2318] = "carry" })
    t:ok(not ok and why == "you chose to carry it", "you said carry it: it stays")
    ok, why = B.Banks(water, {}, { [159] = "bank" })
    t:ok(ok and why == "you chose to bank it", "you said bank it: it goes, whatever Flow thinks")
    ok = B.Banks(leather, { [2318] = true }, { [2318] = "bank" })
    t:ok(ok, "your choice also beats 'a step on your route uses it'")
    -- A click flips it; a right-click hands it back to Flow.
    t:eq(B.NextRule(true, nil, false), "carry", "it was going to the bank: a click keeps it with you")
    t:eq(B.NextRule(false, nil, false), "bank", "it was staying: a click banks it")
    t:eq(B.NextRule(false, "carry", false), "bank", "your own choice flips")
    t:eq(B.NextRule(true, "bank", true), nil, "a right-click: Flow's own choice again")
    -- The window's cells: to the bank first, then what stays.
    local cells = B.PutCells({ water, leather, { name = "Junk", id = 1, action = "sell" } }, {}, {})
    t:ok(#cells == 2 and cells[1].id == 2318 and cells[1].bank and not cells[2].bank, "what goes to the bank first; things Flow doesn't keep aren't shown")
    cells = B.PutCells({ water, leather }, {}, { [2318] = "carry" })
    t:ok(not cells[1].bank and not cells[2].bank and (cells[1].mine or cells[2].mine) == "carry", "your choice shows on its cell")
end)

ns:Register("test", "click: Flow Banker's 'to put away' grid changes a choice and puts it back", function(t)
    local B = ns.banker
    if InCombatLockdown() then return end
    local was = B._Frame() and B._Frame():IsShown()
    local view, offset = B.view, B.offset
    local ok, err = pcall(B.Show, B, "put")
    t:ok(ok, "the view opens" .. (ok and "" or (": " .. tostring(err))))
    local f = B._Frame()
    local c = f and f.cells and f.cells[1]
    if c and c:IsShown() and c.cell then
        local id, before = c.cell.id, B.Rules()[c.cell.id]
        local banked = c.cell.bank
        t:ok(pcall(function() c:GetScript("OnMouseUp")(c, "LeftButton") end), "a click on an item runs")
        t:eq(B.Rules()[id], B.NextRule(banked, before, false), "and sets your choice for it")
        local again
        for _, cell in ipairs(f.cells) do if cell:IsShown() and cell.cell and cell.cell.id == id then again = cell end end
        if again then pcall(function() again:GetScript("OnMouseUp")(again, "RightButton") end) end
        B.Rules()[id] = before
    else
        t:ok(f ~= nil, "(nothing Flow keeps in your bags right now: no cell to click)")
    end
    t:eq(f and f.rows[1]:GetText() or "", "", "no list lines under the grid")
    B.view, B.offset = view, offset
    if f then B:Fill(); if not was then f:Hide() end end
end)

