-------------------------------------------------------------------------------
-- 0.35.219: a spell your trainer doesn't list isn't advised.
-------------------------------------------------------------------------------

ns:Register("test", "improvements: a spell your trainer, read at your level, doesn't list isn't advised", function(t)
    local T = ns.trainerAdvice
    local services = { { name = "Bash" }, { name = "Thorns" } }
    t:ok(T.TrainerLacks("Cure Poison", services, 14, 14), "the trainer was read at 14 and has no Cure Poison: don't send you there for it")
    t:ok(not T.TrainerLacks("Bash", services, 14, 14), "a spell it does list: advised as usual")
    t:ok(not T.TrainerLacks("Cure Poison", services, 12, 14), "the trainer was last read two levels ago: it may list it now")
    t:ok(not T.TrainerLacks("Cure Poison", {}, 14, 14), "nothing read at a trainer: Flow's own list stands")
    t:ok(not T.TrainerLacks("Cure Poison", nil, nil, 14), "never been to a trainer: Flow's own list stands")
    -- The advice itself, with a trainer read at this level that lacks the spell.
    local _, class = UnitClass("player")
    local spells = ns:Get("classSpells", class) or {}
    local level = UnitLevel("player")
    local known = ns.rotation:KnownSpells()
    local pick
    for _, s in ipairs(spells) do
        if s.level <= level and not known[s.spell] and not s.quest and not s.note and not s.needs then pick = s.spell break end
    end
    if not pick then return end   -- (you know everything your level has: nothing to check)
    with(ns.db, "trainer", { services = { { name = "Flow Test Spell", category = "used", level = 1, sub = "" } }, seenAt = level, npc = "A Trainer" }, function()
    with(ns, "Log", function() end, function()
        local ok, items = pcall(ns:Get("advisor", "trainer").check)
        t:ok(ok, "the advice builds" .. (ok and "" or (": " .. tostring(items))))
        local said = false
        for _, it in ipairs(ok and items or {}) do
            if it.text:find("Get " .. pick, 1, true) then said = true end
        end
        t:ok(not said, pick .. " isn't on that trainer's list: no 'Get " .. pick .. "'")
    end) end)
end)

-------------------------------------------------------------------------------
-- 0.35.220: what the game told Flow is kept, used and can be shared.
-------------------------------------------------------------------------------

ns:Register("test", "facts: what trainers teach, and don't, is kept", function(t)
    local F = ns.facts
    local spells = {}
    t:ok(F.NoteSpell(spells, "DRUID", "Wrath", "Rank 3", 14, 900), "a trainer's line is kept")
    t:ok(not F.NoteSpell(spells, "DRUID", "Wrath", "Rank 3", 14, 900), "the same line again: nothing new")
    t:ok(spells.DRUID["Wrath (Rank 3)"].level == 14 and spells.DRUID["Wrath (Rank 3)"].cost == 900, "with its rank, level and price")
    F.NoteSpell(spells, "DRUID", "Wrath", "Rank 3", 14, 810)
    t:eq(spells.DRUID["Wrath (Rank 3)"].cost, 810, "a lower price seen later (reputation): kept")
    t:ok(F.NoteSpell(spells, "DRUID", "Bash", "", 14, 1000) and spells.DRUID.Bash ~= nil, "a spell with no rank text: by its name")
    t:ok(not F.NoteSpell(spells, "DRUID", "", "", 1, 1) and not F.NoteSpell(spells, nil, "X", "", 1, 1), "no name or no class: nothing")
    local lacks = {}
    t:ok(F.NoteLack(lacks, "DRUID", "Cure Poison", 14), "a spell no trainer had at 14")
    t:ok(not F.NoteLack(lacks, "DRUID", "Cure Poison", 13), "an older, lower reading adds nothing")
    t:ok(F.NoteLack(lacks, "DRUID", "Cure Poison", 16) and lacks.DRUID["Cure Poison"] == 16, "still missing at 16: kept at 16")
    -- Which of the class list's spells a trainer lacks.
    local list = { { spell = "Bash", level = 14 }, { spell = "Cure Poison", level = 14 }, { spell = "Bear Form", level = 10, quest = true },
                   { spell = "Rip", level = 20 }, { spell = "Moonfire", level = 4 }, { spell = "Teleport", level = 10, note = "from a quest" } }
    local lacking = F.Lacking(list, { Bash = true }, { Moonfire = true }, 14)
    t:ok(#lacking == 1 and lacking[1] == "Cure Poison",
        "only what's due, not known, not a quest's, and not on the trainer's list")
    -- Using it.
    local own = { spells = spells, lacks = lacks }
    local none = { spells = {}, lacks = {}, spots = {} }
    t:ok(F.NotTaught("DRUID", "Cure Poison", 14, own, none), "Cure Poison: not taught up to your level")
    t:ok(not F.NotTaught("DRUID", "Cure Poison", 18, own, none), "past the level it was last seen missing: unknown again")
    t:ok(not F.NotTaught("DRUID", "Bash", 14, own, none), "a spell a trainer lists: taught")
    t:ok(F.NotTaught("DRUID", "Cure Poison", 14, { spells = {}, lacks = {} }, { spells = {}, lacks = { DRUID = { ["Cure Poison"] = 14 } }, spots = {} }),
        "another player's shared reading counts too")
    lacks.DRUID.Bash = 14
    t:ok(not F.NotTaught("DRUID", "Bash", 14, own, none), "seen at a trainer since: that beats an older 'lacks'")
end)

ns:Register("test", "facts: what trainers teach puts the class list's levels right", function(t)
    -- "rake is lvl 24" (Flow's list, from Classic, said 20; the trainer had said 24 all along).
    local F = ns.facts
    local first = {}
    t:eq(F.NoteFirst(first, "DRUID", "Rake", 24), true, "a spell you don't know, read at a trainer: its first level")
    t:eq(F.NoteFirst(first, "DRUID", "Rake", 30), false, "a higher one later: the lowest stands")
    t:eq(F.NoteFirst(first, "DRUID", "Rake", 0), false, "no level: nothing")
    -- Older trainer lines: only spells you still don't know (a known one's lowest line is a later rank).
    local spells = { DRUID = { Rake = { name = "Rake", level = 24 }, Moonfire = { name = "Moonfire", level = 16 },
                               ["Wrath (Rank 3)"] = { name = "Wrath", rank = "Rank 3", level = 14 } } }
    local f2 = {}
    t:eq(F.FirstFromSeen(spells, f2, "DRUID", { Moonfire = true }), 1, "from the old lines: Rake only")
    t:ok(f2.DRUID.Rake == 24 and f2.DRUID.Moonfire == nil and f2.DRUID.Wrath == nil, "not Moonfire (known: 16 is a later rank), not a named later rank")
    t:eq(F.FirstLevel("DRUID", "Rake", { first = { DRUID = { Rake = 24 } } }, { first = { DRUID = { Rake = 22 } } }), 22, "yours and shared: the lowest")
    t:eq(F.FirstLevel("DRUID", "Claw", { first = {} }, { first = {} }), nil, "no trainer seen with it: nothing")
    -- The list put right, in place.
    local list = { { spell = "Rake", level = 20, needs = "Cat Form" }, { spell = "Shred", level = 22 },
                   { spell = "Bear Form", level = 10, quest = { 6001 } }, { spell = "Wrath", level = 1 } }
    local lv = { Rake = 24, Shred = 20, ["Bear Form"] = 30 }
    local changed = F.FixLevels(list, function(n) return lv[n] end)
    t:eq(#changed, 2, "two spells moved")
    t:ok(list[1].level == 24 and list[1].listLevel == 20, "Rake: 24, and the list's 20 kept")
    t:eq(list[2].level, 20, "Shred: earlier than the list said")
    t:eq(list[3].level, 10, "a class quest's spell isn't a trainer's: left as it was")
    t:eq(list[4].level, 1, "a spell no trainer was seen with: left as it was")
    t:eq(#F.FixLevels(list, function(n) return lv[n] end), 0, "again: nothing more to change")
    -- Shared, too.
    local has = {}
    for _, l in ipairs(F.ShareLines({ first = { DRUID = { Rake = 24 } } }, nil)) do has[l] = true end
    t:ok(has["F|DRUID|Rake|24"], "a first level is shared as F|class|spell|level")
    t:ok(type(F.Shared().first) == "table", "and what came with Flow has a place for them")
end)

