-- 0.35.222: "Regrowth on Bob" casts on Bob.
-------------------------------------------------------------------------------

ns:Register("test", "easy key: a heal that says 'on <someone>' is cast on them", function(t)
    local C = ns.cast
    t:eq(C.UnitFor({ spell = "Regrowth", kind = "heal", unit = "target", target = "Bob" }), "target",
        "a heal for the friend you've targeted: on them, not on you")
    t:eq(C.UnitFor({ spell = "Rejuvenation", kind = "heal", unit = "party2", target = "Ann" }), "party2", "a heal for a party member: on them")
    t:eq(C.UnitFor({ spell = "Regrowth", kind = "heal" }), "player", "a heal with nobody named: on you")
    t:eq(C.UnitFor({ spell = "Healing potion", kind = "emergency" }), "player", "an emergency with nobody named: on you")
    t:eq(C.UnitFor({ spell = "Regrowth", kind = "heal", unit = "player" }), "player", "a heal that names you: on you")
    t:eq(C.UnitFor({ spell = "Mark of the Wild", kind = "buff", unit = "target", target = "Bob" }), "target", "a buff for your friendly target: on them")
    t:eq(C.UnitFor({ spell = "Thorns", kind = "buff" }), "player", "your own buff: on you")
    t:eq(C.UnitFor({ spell = "Wrath", kind = "damage" }), nil, "an attack: your target, as the game does it")
    local kind, what, unit = C.SlotAttributes({ spell = "Regrowth", kind = "heal", unit = "target" })
    t:ok(kind == "spell" and what == "Regrowth" and unit == "target", "and the same on a modifier press")
end)

-------------------------------------------------------------------------------
-- 0.35.223: a travel spell or the hearthstone in the arrow's place.
-------------------------------------------------------------------------------

ns:Register("test", "arrow: a step a cast or a hearthstone away shows that instead of the arrow", function(t)
    local N = ns.nav
    local a = N.TravelAction("Teleport: Moonglade", nil, nil, false)
    t:ok(a and a.kind == "spell" and a.text == "Cast Teleport: Moonglade", "a step a cast away: the spell")
    a = N.TravelAction(nil, 240, "The Crossroads", false)
    t:ok(a and a.kind == "hearth" and a.text == "Use your hearthstone (The Crossroads)", "clearly quicker by hearthstone: the stone, and where it's set")
    a = N.TravelAction("Teleport: Moonglade", 240, "The Crossroads", false)
    t:eq(a.kind, "spell", "both: the spell that lands you there")
    t:eq(N.TravelAction(nil, nil, nil, false), nil, "neither: the arrow as usual")
    t:eq(N.TravelAction("Teleport: Moonglade", 240, "X", true), nil, "you chose to walk to this step: the arrow as usual")
    t:ok(N.TRAVEL_ARROW_SCALE < 1, "the arrow stays, smaller")
end)

ns:Register("test", "click: 'Walk there instead' in the Flow menu drops the travel icon for that step", function(t)
    local N = ns.nav
    local act, key, skip = N.travelAct, N.travelKey, N.travelSkip
    N.travelSkip = {}
    N.travelAct, N.travelKey = { kind = "spell", spell = "Teleport: Moonglade", text = "Cast Teleport: Moonglade" }, "flowtest:1"
    local items = N.TravelMenuItems()
    t:ok(#items == 1 and items[1].text:find("Walk there instead", 1, true) ~= nil, "the menu offers walking: " .. tostring(items[1] and items[1].text))
    local ok, err = pcall(items[1].func)
    t:ok(ok and N.travelSkip["flowtest:1"] == true, "a click remembers it for that step" .. (ok and "" or (": " .. tostring(err))))
    items = N.TravelMenuItems()
    t:ok(#items == 1 and items[1].text:find("again", 1, true) ~= nil, "then the menu offers it back")
    pcall(items[1].func)
    t:eq(N.travelSkip["flowtest:1"], nil, "and that brings it back")
    N.travelAct, N.travelKey = nil, nil
    t:eq(#N.TravelMenuItems(), 0, "no step like that: no entry")
    -- On the real arrow, with a step that's a cast away: the icon shows and goes again.
    local frame = N.arrowFrame
    if frame and frame.arrow and not InCombatLockdown() then
        local port = N.port
        N.port = "Teleport: Moonglade"
        local okS, shown = pcall(N.ShowTravel, frame, "flowtest:2", nil, 100)
        t:ok(okS and shown and frame.travel and frame.travel:IsShown(), "the icon stands where the arrow was" .. (okS and "" or (": " .. tostring(shown))))
        t:near(frame.arrow:GetScale(), N.TRAVEL_ARROW_SCALE, 0.01, "the arrow is small beside it")
        N.port = nil
        N.travelSkip["flowtest:2"] = true
        pcall(N.ShowTravel, frame, "flowtest:2", nil, 100)
        t:ok(not frame.travel:IsShown(), "no cast needed any more: the icon goes")
        t:near(frame.arrow:GetScale(), 1, 0.01, "and the arrow is its own size again")
        N.port = port
    end
    N.travelAct, N.travelKey, N.travelSkip = act, key, skip
end)

-------------------------------------------------------------------------------
-- 0.35.224: the teleport or hearthstone on your Flow key and the tracker.
-------------------------------------------------------------------------------

ns:Register("test", "easy key: it casts the teleport or hearthstone to your next step, when nothing else is on", function(t)
    local N = ns.nav
    local port = { kind = "spell", spell = "Teleport: Moonglade", text = "Cast Teleport: Moonglade" }
    local stone = { kind = "hearth", text = "Use your hearthstone (The Crossroads)" }
    t:ok(N.TravelOnKey(port, "5723:1", "5723:1", false, false, true, 1), "the step the arrow leads to is a cast away: the key takes it")
    t:ok(not N.TravelOnKey(port, "5723:1", "5723:1", true, false, true, 1), "an enemy targeted: the fight comes first")
    t:ok(not N.TravelOnKey(port, "5723:1", "5723:1", false, true, true, 1), "in a fight: no")
    t:ok(not N.TravelOnKey(port, "5723:1", "5723:1", false, false, false, 1), "switched off: no")
    t:ok(not N.TravelOnKey(port, "844:done", "5723:1", false, false, true, 1), "the travel step is for another step: no")
    t:ok(not N.TravelOnKey(nil, "5723:1", "5723:1", false, false, true, 1), "nothing to cast: no")
    t:ok(N.TravelOnKey(stone, "a", "a", false, false, true, 1), "the hearthstone, with one in your bags: yes")
    t:ok(not N.TravelOnKey(stone, "a", "a", false, false, true, 0), "no hearthstone in your bags: no")
    local action = ns:Get("action", "travel:go")
    t:ok(action and type(action.get) == "function", "it's one of the key's actions")
    local was, key = N.travelAct, N.travelKey
    N.travelAct, N.travelKey = nil, nil
    local ok, s = pcall(action.get, { goal = { key = "x" } })
    t:ok(ok and s == nil, "no travel step right now: the key does nothing of it" .. (ok and "" or (": " .. tostring(s))))
    N.travelAct, N.travelKey = was, key
end)

ns:Register("test", "tracker: the teleport or hearthstone is a button on its step's row", function(t)
    local QI = ns.questItems
    local port = { kind = "spell", spell = "Teleport: Moonglade", text = "Cast Teleport: Moonglade" }
    local rows = { { key = "844:done", shown = true }, { key = "5723:1", shown = true }, { key = "870:1", shown = false } }
    local plan = QI.WithTravel({ { row = 1, item = 5087 } }, rows, port, "5723:1")
    t:ok(#plan == 2 and plan[2].row == 2 and plan[2].travel == port, "on the row of the step it takes you to, beside the quest items")
    plan = QI.WithTravel({ { row = 2, item = 5087 } }, rows, port, "5723:1")
    t:eq(#plan, 1, "a row with a quest item keeps that: one button a row")
    t:eq(#QI.WithTravel({}, rows, port, "870:1"), 0, "its row isn't showing: no button")
    t:eq(#QI.WithTravel({}, rows, nil, "5723:1"), 0, "no travel step: nothing added")
    local kind, what, icon = QI.ButtonFor({ row = 2, travel = port }, function() return "spellicon" end, function() return "itemicon" end)
    t:ok(kind == "spell" and what == "Teleport: Moonglade" and icon == "spellicon", "a spell: cast by name")
    kind, what, icon = QI.ButtonFor({ row = 2, travel = { kind = "hearth" } }, function() return "spellicon" end, function() return "itemicon" end)
    t:ok(kind == "item" and what == "item:6948" and icon == "itemicon", "the hearthstone: used as an item")
    kind, what = QI.ButtonFor({ row = 1, item = 5087 }, function() end, function() end)
    t:ok(kind == "item" and what == "item:5087", "a quest item: as before")
    t:ok(type(ns.nav.TravelOnTracker()) == "boolean", "the tracker can ask whether there's one")
end)

-------------------------------------------------------------------------------
-- 0.35.225: next step only is the default; the area choice is last and is
-- worded in steps; what the area shows is unchanged.
-------------------------------------------------------------------------------

ns:Register("test", "steps on the map: next step only by default; the area choice still means the steps around you", function(t)
    local N = ns.nav
    with(ns.db.nav, "stopsArea", nil, function()
    with(ns.db.nav, "stopsShown", nil, function()
        t:ok(not N:AreaMode(), "nothing chosen: not the area")
        t:eq(N:StopsShown(), 1, "nothing chosen: one step")
        t:eq(N:StopsShownLabel(), "Next step only", "which the menu calls Next step only")
        t:ok(N:StopVisible(1, false) and not N:StopVisible(2, false), "the map and tracker show the first step, not the second")
        t:ok(N:StopVisible(2, true), "a step you point at always shows")
    end) end)
    -- The area rule itself (N.IsHere): the next step, and the steps near you or near it.
    local plan = {
        { point = { cont = 1, wx = 0, wy = 0 }, goal = { key = "a", points = {} } },
        { point = { cont = 1, wx = 60, wy = 0 }, goal = { key = "b", points = {} } },
        { point = { cont = 1, wx = 5000, wy = 0 }, goal = { key = "c", points = {} } },
    }
    local here = N.HereStops(plan, { cont = 1, wx = 10, wy = 0 }, 150)
    t:ok(#here == 2 and here[1] == 1 and here[2] == 2, "the next step and the one 60 yards on are 'in this area'; the one 5,000 yards off isn't")
    here = N.HereStops({ plan[1], plan[3] }, { cont = 1, wx = 10, wy = 0 }, 150)
    t:eq(#here, 1, "nothing else nearby: the area is just your next step (it then looks like Next step only)")
    t:eq(N.AREA_LABEL, "All steps in this area", "worded in steps, not objectives")
    local ok, items = pcall(ns.menu.RouteItemsRaw, ns.menu)
    local order = {}
    for _, it in ipairs(ok and items or {}) do
        if it.text == "Next step only" then order[#order + 1] = "next" end
        if it.text == N.AREA_LABEL then order[#order + 1] = "area" end
        if type(it.text) == "string" and it.text:find("^All steps %(") then order[#order + 1] = "all" end
    end
    t:eq(table.concat(order, ","), "next,all,area", "in the menu: Next step only first, the area choice last")
    local found = false
    for _, topic in ns:Each("help") do
        if topic.title == "Steps, objectives, waypoints" then found = true end
    end
    t:ok(found, "/flow help says what a step, an objective and a waypoint are")
end)

-------------------------------------------------------------------------------
-- 0.35.226: Route includes: the dungeon key's tick, and lines above Select
-- all and Unhide all steps.
-------------------------------------------------------------------------------

ns:Register("test", "click: Route includes has the dungeon key's tick and its two lines", function(t)
    local M = ns.menu
    local ok, items = pcall(M.RouteItemsRaw, M)
    t:ok(ok and type(items) == "table", "the menu builds" .. (ok and "" or (": " .. tostring(items))))
    if not ok then return end
    -- The Route includes section, as a list.
    local sec, inside = {}, false
    for _, it in ipairs(items) do
        if it.title then inside = it.text == "Route includes"
        elseif it.sep then inside = false
        elseif inside then sec[#sec + 1] = it end
    end
    local at = {}
    for i, it in ipairs(sec) do
        if it.text == "Select all" then at.select = i end
        if type(it.text) == "string" and it.text:find("^Unhide all steps") then at.unhide = i end
        if type(it.text) == "string" and it.text:find("^Dungeon key above the Flow Tracker") then at.key = i end
    end
    t:ok(at.select and sec[at.select - 1] and sec[at.select - 1].rule == true, "a line above Select all")
    t:ok(at.unhide and sec[at.unhide - 1] and sec[at.unhide - 1].rule == true, "a line above Unhide all steps")
    -- A line inside a section doesn't cut the section in two when the menu folds.
    local folded = M.Fold({ { title = true, text = "This step" }, { text = "Open it" }, { sep = true },
        { title = true, text = "Route includes" }, { text = "Quests", checked = true }, { rule = true }, { text = "Select all" } })
    local route
    for _, it in ipairs(folded) do if it.section and it.text == "Route includes" then route = it end end
    t:ok(route and #route.sub == 3 and route.sub[2].rule == true, "folded: the line stays inside its section")
    t:ok(pcall(M.Click, { rule = true }), "a click on a line does nothing")
    local D = ns.dungeons
    if D and D.Suggest then
        t:ok(at.key ~= nil, "the dungeon key has a tick in Route includes")
        if at.key then
            local was = ns.db.nav.dungeonSuggest
            local it = sec[at.key]
            t:eq(it.checked, D:Suggest(), "ticked as it is now")
            local okC, err = pcall(it.func)
            t:ok(okC and D:Suggest() == not it.checked, "a click turns the key on or off" .. (okC and "" or (": " .. tostring(err))))
            ns.db.nav.dungeonSuggest = was
        end
    end
end)

-------------------------------------------------------------------------------
-- 0.35.227: no spell on two presses; Shift nearest, Ctrl next; the side
-- icons and the auto-attack badge take clicks; an in-combat mark.
-------------------------------------------------------------------------------

ns:Register("test", "easy key: no spell on two presses; Shift is the nearest icon, Ctrl the next", function(t)
    local Q = ns.queue
    t:ok(Q.ORDER[1] == "shift" and Q.ORDER[2] == "ctrl" and Q.ORDER[3] == "alt" and Q.ORDER[4] == "more", "the icons, nearest first: Shift, Ctrl, Alt, Ctrl + Shift")
    local maul = { spell = "Maul", kind = "damage" }
    local slots = Q.NoRepeats({ key = maul, shift = { spell = "Bash" }, ctrl = { spell = "Demoralizing Roar" }, alt = { spell = "Bash" }, more = { spell = "Maul" } }, "Maul")
    t:eq(slots.shift and slots.shift.spell, "Bash", "Bash on the first press that has it")
    t:eq(slots.alt, nil, "not on a second one")
    t:eq(slots.more, nil, "nor the key's own spell on a modifier")
    t:eq(slots.ctrl and slots.ctrl.spell, "Demoralizing Roar", "the others stay")
    slots = Q.NoRepeats({ key = { spell = "Mark of the Wild", kind = "buff" }, shift = { spell = "Mark of the Wild", unit = "target" } }, nil)
    t:ok(slots.shift ~= nil, "the same spell on another unit (your friendly target) is another press")
    slots = Q.NoRepeats({ key = maul, alt = { item = "item:858" }, more = { item = "item:858" } }, nil)
    t:ok(slots.alt and slots.more, "items aren't spells: left alone")
    -- Through the whole queue: a class list that names a spell twice.
    local q = Q.Slots(maul, { ctrlSpell = "Bash", altSpell = "Bash", shiftSpell = "Bash", keySpell = "Maul", more = { "Bash", "Growl" } })
    local n = 0
    for _, name in ipairs(Q.ORDER) do if q[name] and q[name].spell == "Bash" then n = n + 1 end end
    t:eq(n, 1, "Bash named for three presses: on one")
    -- The druid's lists are one and the same for the pull and for a change of form.
    local druid = ns:Get("rotation", "DRUID")
    local forms = druid.formKeys(ns.rotation)
    local fk = druid.fightKeys(ns.rotation)
    local mine = forms[ns.api.Form() or "none"] or forms.none
    t:ok(fk.ctrl[1] == mine.ctrl[1] and fk.shift[1] == mine.shift[1] and fk.alt[1] == mine.alt[1], "the pull's presses come from the same list as the form change's")
    -- The second key's icons, in the same order.
    local K = ns.careKeys
    local plan = K.Plan({ quick = "Regrowth", heals = { "Regrowth", "Healing Touch", "Rejuvenation" }, hots = { "Rejuvenation" } })
    t:ok(plan.shift.spell == "Healing Touch" and plan.ctrl.spell == "Rejuvenation", "second key: Shift the other heal (nearest), Ctrl the heal over time")
end)

ns:Register("test", "click: the icons beside the Flow icon and the auto-attack badge take clicks", function(t)
    local S = ns.clickSlots
    t:ok(S ~= nil, "the click-to-cast file loaded")
    if not S then return end
    t:ok(S.Wanted(true, true, true), "a slot that casts something, its icon showing: a button over it")
    t:ok(not S.Wanted(true, true, false), "its icon not showing: no unseen button to click by accident")
    t:ok(not S.Wanted(true, false, true), "a slot with nothing on it: no button")
    t:ok(not S.Wanted(false, true, true), "switched off: none")
    t:eq(S.Text("spell", "Moonfire", "target"), "spell:Moonfire@target", "what a button is set to, as text")
    t:eq(S.Text(nil), "", "nothing: empty")
    t:eq(ns.SwingBadge(true, true, false, false), "on", "swinging: the badge is lit")
    t:eq(ns.SwingBadge(true, false, true, false), "off", "in a fight, not swinging: the badge is there, dim, to click")
    t:eq(ns.SwingBadge(true, false, false, true), "off", "an enemy targeted: the same")
    t:eq(ns.SwingBadge(true, false, false, false), nil, "nothing to fight: no badge")
    t:eq(ns.SwingBadge(false, true, true, true), nil, "the Flow icon hidden: no badge")
    local icon = _G.FlowRotationIcon
    if icon then
        t:ok(icon.combat ~= nil, "the Flow icon has its in-combat mark")
        t:ok(icon.swing and icon.swing:GetScript("OnEnter") ~= nil, "the auto-attack badge says what it is on hover")
        if icon.swing then
            local ok = pcall(function() icon.swing:GetScript("OnEnter")(icon.swing); icon.swing:GetScript("OnLeave")(icon.swing) end)
            t:ok(ok, "hovering it runs")
        end
    end
    if InCombatLockdown() then return end
    local ok, err = pcall(S.Sync, false)
    t:ok(ok, "the buttons are brought up to date without error" .. (ok and "" or (": " .. tostring(err))))
    if S.built then
        for _, slot in ipairs(ns.queue.ORDER) do
            local b = S.buttons[slot]
            t:ok(b ~= nil and b:GetParent() == _G.FlowCastButton, "a button for the " .. slot .. " icon, a child of Flow's own secure button")
            if b then
                -- (Never clicked here: a click would cast. Its hover runs.)
                t:ok(pcall(function() b:GetScript("OnEnter")(b); b:GetScript("OnLeave")(b) end), "hovering the " .. slot .. " icon runs")
            end
        end
        t:ok(S.swing ~= nil, "the badge has its button")
    end
    t:ok(type(S.Lines()) == "table", "it can say what each is set to")
    t:ok(issecurevariable("SecureActionButton_OnClick") ~= false, "the game's own click handler stays untainted")
end)

-------------------------------------------------------------------------------
-- 0.35.228: the self button docks under Flow's icon; it shows the held
-- modifier's spell, its cooldown and reach; the badge wears your weapon.
-------------------------------------------------------------------------------

ns:Register("test", "click: the self button docks under the Flow icon and comes off again", function(t)
    local BB = ns.buffButton
    t:ok(type(BB.SetDock) == "function" and type(BB.Docked) == "function" and type(BB.Place) == "function", "it can be docked")
    t:ok(BB.DOCK_GAP >= 12, "the gap between the rows has room for the modifier names")
    local b, main = _G.FlowBuffButton, _G.FlowCastButton
    if not (b and main) or InCombatLockdown() then return end
    ns.db.buffButton = ns.db.buffButton or {}
    local was = ns.db.buffButton.dock
    local ok, err = pcall(BB.SetDock, true)
    t:ok(ok and BB.Docked(), "docking runs" .. (ok and "" or (": " .. tostring(err))))
    local point, rel, relPoint, _, y = b:GetPoint(1)
    t:ok(point == "TOP" and rel == main and relPoint == "BOTTOM", "docked: its top hangs from the Flow button's bottom")
    t:near(y or 0, -BB.DOCK_GAP, 0.01, "with the gap between")
    -- (Its own docked size since 0.35.253, Ctrl + wheel over it: the Flow
    -- button's until you set one.)
    t:near(b:GetScale(), BB.DockScale(ns.db.buffButton.dockScale, main:GetScale()), 0.001, "at its docked size")
    ok, err = pcall(BB.SetDock, false)
    t:ok(ok and not BB.Docked(), "undocking runs" .. (ok and "" or (": " .. tostring(err))))
    point, rel = b:GetPoint(1)
    t:ok(not (point == "TOP" and rel == main), "undocked: back where it stood")
    ns.db.buffButton.dock = was
    pcall(BB.Place)
    t:ok(type(ns.DockedNow()) == "boolean", "Flow's icon can ask whether the two are one block")
    -- The menu and the settings have the switch.
    local okM, items = pcall(ns.menu.RouteItemsRaw, ns.menu)
    local found = false
    for _, it in ipairs(okM and items or {}) do
        if type(it.text) == "string" and it.text:find("Dock it under", 1, true) then found = true end
    end
    t:ok(found, "the Flow menu's Buttons section has the dock tick")
end)

ns:Register("test", "self button: a held modifier shows what that press casts", function(t)
