    t:eq(K.ColumnRight(3), K.ColumnRight(2) - K.SIZES[2] - 6, "Alt's after Ctrl's")
    t:eq(K.ColumnRight(4), K.ColumnRight(3) - K.SIZES[3] - 6, "C+S's after Alt's, whether or not Alt has anything on it")
