-- 0.35.239: docked: "CTRL +" over the key bind over a small auto-attack badge.
-------------------------------------------------------------------------------

ns:Register("test", "buttons: docked, the modifier is above the key bind and the auto-attack badge small at the bottom", function(t)
    -- The words.
    t:eq(ns.ModTag("CTRL", true), "CTRL +", "docked: the modifier on its own line, 'CTRL +'")
    t:eq(ns.ModTag("CTRL + SHIFT", true), "CTRL + SHIFT +", "two modifiers the same way")
    t:eq(ns.ModTag("CTRL", false), "CTRL+", "on its own: as before, on the bind's line")
    t:eq(ns.ModTag("CTRL + SHIFT", false), "CTRL+SHIFT+", "and two, as before")
    -- The badge.
    local size, point, rel, x, y = ns.SwingPlace(true)
    t:ok(size == ns.SWING_DOCKED and size < ns.SWING_SIZE, "docked: the badge is small, the height of the bind's letters")
    t:ok(size >= ns.cast.KEY_FONT and size <= ns.cast.KEY_FONT + 4, "about as tall as those letters")
    t:ok(point == "BOTTOMLEFT" and rel == "BOTTOMRIGHT" and x > 0 and y == 0, "at the icon's bottom right, level with its bottom")
    size, point, rel = ns.SwingPlace(false)
    t:ok(size == ns.SWING_SIZE and point == "LEFT" and rel == "RIGHT", "on its own: where and as big as it was")
    -- The real badge and the button over it agree with the mode.
    local icon = ns.rotation.icon
    if icon and icon.swing and icon.joined ~= nil then
        local p, r, rp = icon.swing:GetPoint(1)
        local wantSize, wantP, wantRp = ns.SwingPlace(icon.joined, icon.side)
        t:ok(p == wantP and r == icon and rp == wantRp, "the badge is where this mode puts it")
        t:near(icon.swing:GetWidth(), wantSize, 0.5, "and that size")
    end
    local w = ns.clickSlots and ns.clickSlots.swing
    if w and w.joined ~= nil and icon and icon.joined ~= nil and not InCombatLockdown() then
        t:near(w:GetWidth(), (ns.SwingPlace(w.joined)), 0.5, "the button over the badge is the badge's size")
    end
    -- The self button: its bind at the middle of its right side, the tag above.
    local BB = ns.buffButton
    if BB._keyText and BB._modTag and _G.FlowBuffButton then
        local tp, trel, trp = BB._modTag:GetPoint(1)
        t:ok(tp == "BOTTOMLEFT" and trel == BB._keyText and trp == "TOPLEFT", "the self button's modifier is written above its bind")
        if BB.Docked() and not InCombatLockdown() then
            local kp, krel, krp = BB._keyText:GetPoint(1)
            t:ok(kp == "LEFT" and krel == _G.FlowBuffButton and krp == "RIGHT", "docked: its bind at the middle of its right side")
        end
    end
    local held = ns.careKeys.HeldStep
    t:ok(type(held) == "function", "a held modifier's step says which modifier it is")
end)

-------------------------------------------------------------------------------
-- 0.35.240: a hand-in waits with its hidden objective; fishing is the buff
-- button's alone; the self button is docked unless taken off.
-------------------------------------------------------------------------------

ns:Register("test", "route: a hand-in whose objective you hid leaves the route with it", function(t)
    local N = ns.nav
    local collect = { key = "855:1", text = "Centaur Bracers: 10 -> 15 Centaur Bracers" }
    local turnIn = { key = "855:done", text = "Turn in: Centaur Bracers", deps = { "855:1" } }
    local after = { key = "x:after", text = "After the hand-in", deps = { "855:done" } }
    local other = { key = "850:done", text = "Turn in: Kolkar Leaders", deps = { "850:1" } }
    local free = { key = "870:1", text = "The Forgotten Pools" }
    local kept, held = N.HoldForHidden({ turnIn, after, other, free }, { collect })
    t:eq(#kept, 2, "the hand-in and what follows it are off the route")
    t:ok(kept[1] == other and kept[2] == free, "the rest stays, in order (a hand-in whose objective is done or not hidden too)")
    t:eq(#held, 2, "both are listed as waiting")
    t:ok(held[1].key == "855:done" and held[1].blockedBy:find("Centaur Bracers: 10 %-> 15", 1) ~= nil, "the reason names the hidden step")
    t:ok(held[1].blockedBy:find("you hid that step", 1, true) ~= nil, "and says you hid it")
    t:ok(held[1] ~= turnIn and turnIn.blockedBy == nil, "the step itself isn't marked (a copy is)")
    t:eq(held[2].key, "x:after", "down the chain")
    kept, held = N.HoldForHidden({ turnIn, free }, {})
    t:ok(#kept == 2 and #held == 0, "nothing hidden: nothing waits")
end)

ns:Register("test", "route: a hand-in whose objective is off the route (held, another zone) isn't a turn-in yet", function(t)
    -- "Flow is telling me to turn in quests I have that are incomplete":
    -- "Turn in: Deepmoss Spider Eggs" at 0/15, its collect step held.
    local N = ns.nav
    local eggs = { key = "1069:1", text = "Deepmoss Spider Eggs: 0/15 Deepmoss Spider Egg",
                   blockedBy = "level 20 quest: back on the route at level 20 (or in a group)" }
    local turnIn = { key = "1069:done", text = "Turn in: Deepmoss Spider Eggs", deps = { "1069:1" } }
    local after = { key = "x:after", text = "After the hand-in", deps = { "1069:done" } }
    local spores = { key = "848:1", text = "Fungal Spores: 0/4" }
    local sporesIn = { key = "848:done", text = "Turn in: Fungal Spores", deps = { "848:1" } }
    local done = { key = "870:done", text = "Turn in: The Forgotten Pools", deps = { "870:1" } }
    local known = { [eggs.key] = eggs, [turnIn.key] = turnIn, [after.key] = after,
                    [spores.key] = spores, [sporesIn.key] = sporesIn, [done.key] = done }
    local kept, held = N.HoldForDropped({ turnIn, after, spores, sporesIn, done }, known)
    t:eq(#kept, 3, "the hand-in and what follows it are off the route")
    t:ok(kept[1] == spores and kept[2] == sporesIn and kept[3] == done,
         "the rest stays: one whose objective is on the route, and one whose objective is done")
    t:eq(#held, 2, "both are listed as waiting")
    t:ok(held[1].key == "1069:done" and held[1].blockedBy:find("Deepmoss Spider Eggs: 0/15", 1, true) ~= nil,
         "the reason names the step it waits for")
    t:ok(held[1].blockedBy:find("back on the route at level 20", 1, true) ~= nil, "and why that one is off the route")
    t:ok(held[1] ~= turnIn and turnIn.blockedBy == nil, "the step itself isn't marked (a copy is)")
    t:eq(held[2].key, "x:after", "down the chain")
    -- In a zone you didn't pick: not blocked, just not on the route.
    local away = { key = "1069:1", text = "Deepmoss Spider Eggs: 0/15 Deepmoss Spider Egg" }
    kept, held = N.HoldForDropped({ turnIn }, { [away.key] = away, [turnIn.key] = turnIn })
    t:ok(#kept == 0 and held[1] and held[1].blockedBy:find("not on your route", 1, true) ~= nil,
         "its objective left out with its zone: waits, and says so")
    kept, held = N.HoldForDropped({ eggs, turnIn }, known)
    t:ok(#kept == 2 and #held == 0, "its objective on the route: the hand-in stays, after it")
    t:ok(N.HubBusiness and N.HubBusiness(turnIn, 10, { [eggs.key] = true }) == nil,
         "and the town's errands don't call it a turn-in while its objective is on the route")
end)

ns:Register("test", "route: what waits for a step off the route, in N:Collect's order: chains, needs, hidden, unknown", function(t)
    -- The same steps through Flow's own functions, in the order N:Collect runs
    -- them (ResolveNeeds, then HoldForHidden, then HoldForDropped on `present`).
    local N = ns.nav
    local function met() return false end
    local function label(tok) return (tok:gsub("^%w+:", "")) end
    local function run(list, shownKeys, hiddenKeys)
        N.ResolveNeeds(list, met, label)
        local present, shown, hidden = {}, {}, {}
        for _, g in ipairs(list) do
            present[g.key] = g
            if hiddenKeys[g.key] then hidden[#hidden + 1] = g
            elseif shownKeys[g.key] then shown[#shown + 1] = g end
        end
        local kept, waitH = N.HoldForHidden(shown, hidden)
        local kept2, waitD = N.HoldForDropped(kept, present)
        local byKey, held = {}, {}
        for _, g in ipairs(kept2) do byKey[g.key] = "kept" end
        for _, g in ipairs(waitH) do byKey[g.key] = "hidden"; held[g.key] = g end
        for _, g in ipairs(waitD) do
            t:ok(byKey[g.key] == nil, g.key .. " is listed once")
            byKey[g.key] = "held"; held[g.key] = g
        end
        return byKey, held
    end
    -- A class quest held (3+ levels above you): its item first, then its
    -- objective, then its hand-in, which teaches Bear Form. Training needs
    -- Bear Form softly, a skill step needs it hard.
    local item = { key = "9101:item:1", text = "Get the Idol", blockedBy = "level 20 quest: back on the route at level 20 (or in a group)" }
    local obj = { key = "9101:1", text = "Body and Heart: 0/1", deps = { "9101:item:1" } }
    local turnIn = { key = "9101:done", text = "Turn in: Body and Heart", deps = { "9101:1" }, provides = { "spell:Bear Form" } }
    local train = { key = "train:class", text = "Class training", needs = { { "spell:Bear Form", soft = true } } }
    local skill = { key = "x:bear", text = "Maul practice", needs = { "spell:Bear Form" } }
    -- A hand-in whose one dep Flow doesn't know (done, or never a step): stays.
    local lone = { key = "9102:done", text = "Turn in: Lone", deps = { "9102:1" } }
    local on = { [obj.key] = true, [turnIn.key] = true, [train.key] = true, [skill.key] = true, [lone.key] = true }
    local s, held = run({ item, obj, turnIn, train, skill, lone }, on, {})
    t:eq(s[obj.key], "held", "an objective waits for the item it needs first, held off the route")
    t:eq(s[turnIn.key], "held", "and its hand-in down the chain: not \"Turn in\"")
    t:ok(held[turnIn.key] and held[turnIn.key].blockedBy:find("Body and Heart: 0/1", 1, true) ~= nil, "it names the step it waits for")
    t:eq(s[train.key], "kept", "a soft need only orders: training stays on the route")
    t:ok(train.softDeps and train.softDeps[turnIn.key] and train.deps and train.deps[1] == turnIn.key,
         "(still ordered after the quest, when that's on the route)")
    t:eq(s[skill.key], "held", "a hard need waits for the quest that teaches it")
    t:eq(s[lone.key], "kept", "a dep Flow doesn't know of (done) holds nothing")
    -- Its objective hidden: held for that (named once), not twice.
    local obj2 = { key = "9103:1", text = "Wolves: 2/10" }
    local in2 = { key = "9103:done", text = "Turn in: Wolves", deps = { "9103:1" } }
    s, held = run({ obj2, in2 }, { [in2.key] = true }, { [obj2.key] = true })
    t:eq(s[in2.key], "hidden", "its objective hidden: it waits, for that reason")
    t:ok(held[in2.key] and held[in2.key].blockedBy:find("you hid that step", 1, true) ~= nil, "and says so")
    -- Both on the route: nothing waits.
    local obj3 = { key = "9104:1", text = "Boars: 1/8" }
    local in3 = { key = "9104:done", text = "Turn in: Boars", deps = { "9104:1" } }
    s = run({ obj3, in3 }, { [obj3.key] = true, [in3.key] = true }, {})
    t:ok(s[obj3.key] == "kept" and s[in3.key] == "kept", "objective and hand-in both on the route: both stay")
    -- A dep that's soft and hard (two needs, one provider): it binds.
    local both = { key = "x:both", text = "Both", needs = { { "spell:Bear Form", soft = true }, "spell:Bear Form" } }
    local q = { key = "9105:done", text = "Turn in: Teacher", provides = { "spell:Bear Form" }, blockedBy = "level 30 quest" }
    s = run({ q, both }, { [both.key] = true }, {})
    t:eq(s[both.key], "held", "soft and hard on one step: the hard one holds")
end)

ns:Register("test", "fishing: on the self button alone while it has a key; the self button is docked by default", function(t)
    local X, BB = ns.actions, ns.buffButton
    t:ok(X.OnBuffOnly({ fish = true }, true), "a fishing step, the self button fishes: not on the Flow key too")
    t:ok(not X.OnBuffOnly({ fish = true }, false), "no self button (or no key on it): the Flow key fishes, as before")
    t:ok(not X.OnBuffOnly({ type = "spell" }, true), "any other step stays on the Flow key")
    t:ok(not X.OnBuffOnly(nil, true), "no step: nothing")
    t:ok(type(BB.Fishes()) == "boolean", "the self button says whether it fishes")
    t:ok(BB.DockWanted(nil), "never chosen: docked")
    t:ok(BB.DockWanted(true), "docked by you: docked")
    t:ok(not BB.DockWanted(false), "taken off by you: stays off")
end)

-------------------------------------------------------------------------------
-- 0.35.241: the self button is yours, Flow's key is your target's.
-------------------------------------------------------------------------------

ns:Register("test", "two keys: out of a fight what's cast on you is the self button's, the rest Flow's key's", function(t)
    local BB, E = ns.buffButton, ns.rotation
    -- Who a step is for.
    t:ok(BB.IsMine({ spell = "Regrowth", kind = "heal" }), "a heal with nobody named falls on you: yours")
    t:ok(BB.IsMine({ spell = "Regrowth", kind = "heal", unit = "player" }), "a heal on you: yours")
    t:ok(not BB.IsMine({ spell = "Regrowth", kind = "heal", unit = "target", target = "Bob" }), "a heal on your target: not yours")
    t:ok(BB.IsMine({ spell = "Cure Poison", kind = "buff", unit = "player" }), "a cure for you: yours")
    t:ok(not BB.IsMine({ spell = "Cure Poison", kind = "buff", unit = "party1", target = "Bob" }), "a cure for someone in your group: not yours")
    t:ok(not BB.IsMine({ spell = "Wrath", kind = "attack" }), "an attack: not yours")
    t:ok(not BB.IsMine(nil), "no step: nothing")
    -- What Flow's key keeps.
    local heal, wrath = { spell = "Regrowth", kind = "heal" }, { spell = "Wrath" }
    t:eq(BB.ForTarget(heal, true, false), nil, "the split on, out of a fight: a heal for you leaves Flow's key")
    t:eq(BB.ForTarget(heal, true, true), heal, "in a fight nothing moves (the keys were set at the pull)")
    t:eq(BB.ForTarget(heal, false, false), heal, "the split off: as before")
    t:eq(BB.ForTarget(wrath, true, false), wrath, "an attack stays on Flow's key")
    local onBob = { spell = "Regrowth", kind = "heal", unit = "target" }
    t:eq(BB.ForTarget(onBob, true, false), onBob, "a heal on your friendly target stays on Flow's key")
    -- Order on the self button.
    local cure, food = { spell = "Cure Poison" }, { item = "item:1" }
    t:eq(BB.MineFirst(cure, food), cure, "a poison on you comes off before you eat")
    t:eq(BB.MineFirst(nil, food), food, "nothing to cure: heal up")
    t:eq(BB.MineFirst(nil, nil), nil, "neither: nothing")
    t:ok(type(BB.TakesMine()) == "boolean", "the button says whether it takes what's yours")
    -- Healing up, all of it, for the self button.
    local asked = {}
    local fake = {
        DrinkStep = function() asked[#asked + 1] = "drink" return { item = "item:2", label = "drink" } end,
        Recover = function(_, _, _, part) asked[#asked + 1] = "recover:" .. tostring(part) return nil end,
    }
    t:eq(BB.MineRecover(fake, { inCombat = true }, {}), nil, "in a fight: nothing (the fight's keys do it)")
    local s = BB.MineRecover(fake, { inCombat = false, maxHp = 100, hp = 50, hpPct = 0.5 }, {})
    t:ok(asked[1] == "recover:all", "hurt: the whole recovery order is asked, heal spell included")
    t:ok(s and s.label == "drink", "nothing to heal with: a drink")
    -- Choosing leaves the rotation as it found it.
    local hs, dp = E.HealStep, E.Dispel
    pcall(E.Choose, E)
    t:ok(E.HealStep == hs and E.Dispel == dp, "after choosing, the rotation's own heal and cure steps are back in place")
    local found
    for _, l in ipairs(ns.careKeys.Lines()) do if l:find("out of a fight", 1, true) or l:find("off", 1, true) or l:find("no key", 1, true) then found = true end end
    t:ok(found, "/flow carekeys says who each key is for")
end)

