-- 0.35.244: buffs for your group are Flow's key's, self button on or off.
-------------------------------------------------------------------------------

ns:Register("test", "group buffs: on Flow's key with the self button on; the reason when held", function(t)
    local E, BB = ns.rotation, ns.buffButton
    local ctx = { inCombat = false, hostile = false, fightType = "normal" }
    local list = {}
    t:eq(E.GroupHeld(list, true, ctx, false, true), nil, "nothing in the way: Flow looks at your group")
    t:ok(E.GroupHeld(nil, true, ctx, false, true):find("your class"), "no list for the class")
    t:ok(E.GroupHeld(list, false, ctx, false, true):find("turned off"), "the setting off")
    t:ok(E.GroupHeld(list, true, { inCombat = true }, false, true):find("fight"), "in a fight")
    t:ok(E.GroupHeld(list, true, { hostile = true }, false, true):find("enemy"), "an enemy targeted")
    t:ok(E.GroupHeld(list, true, ctx, true, true):find("city"), "in a city or an inn")
    t:ok(E.GroupHeld(list, true, ctx, false, false):find("form"), "in a form that can't cast")
    -- The self button doesn't take them: its own pick never asks for the group.
    local asked = 0
    with(E, "GroupBuff", function() asked = asked + 1 return { spell = "Mark of the Wild", unit = "party1" } end, function()
        local ok, s = pcall(BB._pickBuff, { priority = {} }, ctx)
        t:ok(ok and s == nil, "the self button offers no buff for the group")
        t:eq(asked, 0, "and doesn't look for one")
    end)
    -- And choosing leaves the engine's own group buffs in place for Flow's key.
    local before = E.GroupBuff
    pcall(E.Choose, E)
    t:ok(E.GroupBuff == before, "choosing doesn't swap group buffs out")
    local ok, lines = pcall(E.GroupWhy, E, ctx, { groupBuffs = list })
    t:ok(ok and type(lines) == "table", "the diagnostics lines build")
end)

-------------------------------------------------------------------------------
-- 0.35.245: your next step on another map: the line still leaves from you.
-------------------------------------------------------------------------------

ns:Register("test", "map: the way to a step in another zone is drawn to the map's edge, through the gate", function(t)
    local M = ns.mapOverlay
    local x, y = M.ClipToMap(0.5, 0.5, 1.5, 0.5)
    t:near(x, 1, 0.001, "east: ends on the right edge"); t:near(y, 0.5, 0.001, "level")
    x, y = M.ClipToMap(0.5, 0.5, 0.5, -1.5)
    t:near(x, 0.5, 0.001, "north: straight up"); t:near(y, 0, 0.001, "ends on the top edge")
    x, y = M.ClipToMap(0.5, 0.5, 2.5, 1.5)
    t:near(x, 1, 0.001, "a slant: the edge it meets first"); t:near(y, 0.75, 0.001, "at the right height")
    -- You (on the map), the gate (on the map), the step (in the next zone).
    local parts = M.LegParts({ { 0.2, 0.5 }, { 0.9, 0.5 }, { 1.8, 0.5 } })
    t:eq(#parts, 2, "you to the gate, the gate to the edge")
    t:ok(parts[1][1] == 0.2 and parts[1][3] == 0.9 and parts[1].from == 1, "first from you to the gate (so the dots walk that way)")
    t:near(parts[2][3], 1, 0.001, "then on to the edge, towards the step")
    -- No gate known: straight from you to the edge.
    parts = M.LegParts({ { 0.2, 0.5 }, { 1.8, 0.5 } })
    t:eq(#parts, 1, "no gate: one line"); t:near(parts[1][3], 1, 0.001, "to the edge")
    -- Looking at the step's map: in from the edge (you're beside the map), through the gate, to the step.
    parts = M.LegParts({ { -0.6, 0.5 }, { 0.1, 0.5 }, { 0.7, 0.5 } })
    t:eq(#parts, 2, "the edge to the gate, the gate to the step")
    t:near(parts[1][1], 0, 0.001, "it comes in at the edge"); t:eq(parts[2][3], 0.7, "and ends at the step")
    -- A map neither you nor the step is on, and a point missing: nothing, no error.
    t:eq(#M.LegParts({ { -1, 0.5 }, { 2, 0.5 } }), 0, "both beside the map: no line")
    t:eq(#M.LegParts({ { 0.5, 0.5 } }), 0, "one point: no line")
    t:ok(M.CrossesEdge(0.3, nil) and M.CrossesEdge(nil, 0.3), "you on the map and the step not, or the other way round")
    t:ok(not M.CrossesEdge(0.3, 0.4) and not M.CrossesEdge(nil, nil), "both on it (the usual line) or neither: not this")
    t:ok(pcall(M.Redraw, M), "the map still draws")
end)

-------------------------------------------------------------------------------
-- 0.35.246: "a more powerful spell is already active": the next buff comes up.
-------------------------------------------------------------------------------

ns:Register("test", "buffs for others: one the game refuses as weaker is skipped, the next comes up", function(t)
    local E = ns.rotation
    t:ok(E.IsBounce("A more powerful spell is already active", nil), "the game's words")
    t:ok(E.IsBounce("Ein mächtigerer Zauber ist bereits aktiv", "Ein mächtigerer Zauber ist bereits aktiv"), "or its own text in another language")
    t:ok(not E.IsBounce("Out of range.", "A more powerful spell is already active"), "another error: no")
    t:ok(not E.IsBounce(nil, nil), "nothing: no")
    local store = {}
    t:ok(not E.NoteBounce({ spell = "Mark of the Wild", unit = "player" }, 100, store), "a buff on you: not this")
    t:ok(not E.NoteBounce(nil, 100, store), "nothing offered: nothing noted")
    t:ok(E.NoteBounce({ spell = "Mark of the Wild", unit = "party1", guid = "G1", target = "Tank" }, 100, store), "a buff on someone else: noted")
    t:ok(E.NoteBounce({ spell = "Thorns", unit = "target", target = "Bob" }, 100, store), "their ID hidden: by name")
    t:ok(E.Bounced({ guid = "G1" }, "Mark of the Wild", 130, store), "that person, that spell: refused")
    t:ok(E.Bounced({ name = "Bob" }, "Thorns", 130, store), "by name too")
    t:ok(not E.Bounced({ guid = "G1" }, "Thorns", 130, store), "another spell for them: still offered")
    t:ok(not E.Bounced({ guid = "G2" }, "Mark of the Wild", 130, store), "someone else: still offered")
    t:ok(not E.Bounced({ guid = "G1" }, "Mark of the Wild", 100 + E.BOUNCE_SECONDS + 1, store), "asked again later: the stronger one runs out")
    -- And it counts as covered, so the friend step moves on to the next buff.
    with(E, "bounced", { G1 = { ["Mark of the Wild"] = 100 } }, function()
        local u = { unit = "party1", guid = "G1", name = "Tank" }
        t:ok(E.GroupCovered(u, { spell = "Mark of the Wild" }, 130, function() return false, 0 end), "covered, though it isn't among their buffs")
        t:ok(not E.GroupCovered(u, { spell = "Thorns" }, 130, function() return false, 0 end), "Thorns isn't")
        local pick = E.FriendStep({ hurt = false }, {
            { spell = "Mark of the Wild", covered = E.GroupCovered(u, { spell = "Mark of the Wild" }, 130, function() return false, 0 end) },
            { spell = "Thorns", covered = false } }, nil, true, true)
        t:eq(pick and pick.spell, "Thorns", "the next buff comes up")
    end)
end)

-------------------------------------------------------------------------------
-- 0.35.247: docked, one "drag to move" note under both buttons.
-------------------------------------------------------------------------------

ns:Register("test", "move handle: docked, the one note goes under both buttons", function(t)
    t:ok(ns.HandleWanted(true, false, true, false), "Ctrl held, no fight, on screen: the handle shows")
    t:ok(not ns.HandleWanted(true, false, true, true), "moved by something else (docked): no handle of its own")
    t:ok(not ns.HandleWanted(false, false, true, false), "no Ctrl: none")
    t:ok(not ns.HandleWanted(true, true, true, false), "in a fight: none")
    t:ok(not ns.HandleWanted(true, false, false, false), "the button hidden: none")
    local C, BB = ns.cast, ns.buffButton
    local buff = _G.FlowBuffButton
    with(BB, "Docked", function() return false end, function()
        t:eq(C.NoteUnder(), nil, "on its own: the note under Flow's button")
    end)
    if buff then
        with(BB, "Docked", function() return true end, function()
            t:eq(C.NoteUnder(), buff:IsShown() and buff or nil, "docked: under the self button when it shows")
        end)
    end
    -- The real handles: refreshing runs, and the self button's stays hidden when docked.
    local hb = BB.handle
    if hb and not InCombatLockdown() then
        with(BB, "Docked", function() return true end, function()
            t:ok(pcall(hb.Refresh, hb), "refresh runs")
            t:ok(not hb:IsShown(), "docked, no Ctrl held: no handle")
        end)
        pcall(hb.Refresh, hb)
    end
    if C.handle then t:ok(pcall(C.handle.Refresh, C.handle), "Flow's handle refreshes") end
end)

-------------------------------------------------------------------------------
-- 0.35.248: your threat on each enemy's nameplate.
-------------------------------------------------------------------------------

ns:Register("test", "threat on nameplates: the number and where you stand", function(t)
    local P = ns.plateThreat
    -- Tanking: holding it is good, someone passing you is the warning.
    t:eq(P.State(3, true), "safe", "tank, it's on you: safe")
    t:eq(P.State(2, true), "losing", "tank, on you but someone has more threat: losing it")
    t:eq(P.State(1, true), "pulling", "tank, not on you but you have more: nearly yours")
    t:eq(P.State(0, true), "lost", "tank, not on you: lost")
    -- Anyone else: it being on you is the warning.
    t:eq(P.State(3, false), "danger", "not a tank, it's on you: danger")
    t:eq(P.State(2, false), "danger", "the same while it still is")
    t:eq(P.State(1, false), "pulling", "more threat than the tank: about to take it")
    t:eq(P.State(0, false), "low", "under the tank: fine")
    t:eq(P.State(nil, true), "hidden", "the game hides it: Flow doesn't guess")
    for _, s in ipairs({ "safe", "losing", "pulling", "lost", "danger", "low", "hidden" }) do
        t:ok(type(P.COLORS[s]) == "table" and #P.COLORS[s] == 3, s .. " has a colour")
    end
    t:ok(P.COLORS.safe[2] > P.COLORS.safe[1] and P.COLORS.lost[1] > P.COLORS.lost[2], "safe is green, lost is red")
    t:eq(P.Text(84.6), "85%", "your share, whole")
    t:eq(P.Text(100, { name = "Beryl", pct = 85.2 }), "100% · Beryl 85%", "on you: who's closest behind")
    t:eq(P.Text(nil), "", "nothing to show")
    local c = P.Closest({ { name = "A", pct = 40 }, { name = "B", pct = 85 }, { name = "C" } })
    t:eq(c and c.name, "B", "the closest behind is the highest of the others (a hidden one is passed over)")
    t:eq(P.Closest({}), nil, "nobody else on its list: nobody")
    -- The switch, by a click on its settings box and by /flow threat.
    local was = ns.db.plateThreat.off
    t:ok(pcall(P.Set, false), "turning it off runs"); t:eq(P.On(), false, "off")
    t:ok(pcall(P.Set, true), "and on"); t:eq(P.On(), true, "on")
    ns.db.plateThreat.off = was
    t:ok(type(ns.commands.threat) == "function", "/flow threat")
    t:ok(pcall(P.UpdateAll), "looking at the nameplates in view runs")
    local ok, lines = pcall(P.Lines)
    t:ok(ok and #lines >= 2, "the diagnostics lines build")
    t:ok(type(P.Wanted()) == "boolean" and type(P.Tanking()) == "boolean", "wanted and tanking are yes or no")
end)

