-- 0.35.252: what grows in your zone sets the gathering skill to reach.
-------------------------------------------------------------------------------

ns:Register("test", "professions: a herb here that's beyond you sets Herbalism's target, as a step of its own", function(t)
    local SP = ns.skillPlan
    local barrens = { { name = "Peacebloom", skill = 1 }, { name = "Earthroot", skill = 15 },
                      { name = "Mageroyal", skill = 50 }, { name = "Briarthorn", skill = 70 } }
    local need = SP.ZoneNeed(35, barrens)
    t:eq(need and need.name, "Mageroyal", "Herbalism 35 in the Barrens: Mageroyal is the next one beyond you")
    t:eq(need and need.skill, 50, "so 50 is the skill to reach")
    t:eq(SP.ZoneNeed(50, barrens).name, "Briarthorn", "at 50: Briarthorn next")
    t:eq(SP.ZoneNeed(70, barrens), nil, "everything here in reach: no target from the zone")
    t:eq(SP.ZoneNeed(35, {}), nil, "nothing grows here (or no data): none")
    t:eq(SP.ZoneNeed(35, nil), nil, "no list: none")
    local ok, list = pcall(SP.NodesHere, "Herbalism")
    t:ok(ok and type(list) == "table", "asking what grows on this map runs")
    ok, list = pcall(SP.NodesHere, "Fishing")
    t:ok(ok and #list == 0, "a profession with no nodes: nothing")
    -- The target it gives is a real one: not optional, and it names the herb.
    with(SP, "NodesHere", function(prof) return prof == "Herbalism" and barrens or {} end, function()
    with(ns, "ProfessionPlan", function() return { { name = "Herbalism" } } end, function()
    with(ns.api, "Skill", function(name) if name == "Herbalism" then return 35, 75 end end, function()
        local okT, targets = pcall(SP.Targets, SP)
        local h = okT and targets.Herbalism
        if ns.nav:Includes("professions") then
            t:ok(h ~= nil, "Herbalism gets a target")
            t:eq(h and h.target, 50, "of 50")
            t:eq(h and h.zone, "Mageroyal", "because of Mageroyal")
            t:ok(h and h.optional == true, "for this zone it's optional: taken in on the way, behind your quests")
        end
    end) end) end)
end)

-------------------------------------------------------------------------------
-- 0.35.253: docked, the self button has a size of its own (Ctrl + wheel).
-------------------------------------------------------------------------------

ns:Register("test", "click: docked, the wheel over the self button resizes it alone", function(t)
    local BB = ns.buffButton
    t:eq(BB.DockScale(nil, 1.2), 1.2, "never resized: the size of Flow's icon")
    t:eq(BB.DockScale(0.8, 1.2), 0.8, "resized: its own size, whatever Flow's is")
    t:near(BB.DockScaleStep(1, 1), 1.1, 0.001, "a notch up: a tenth bigger")
    t:near(BB.DockScaleStep(1, -1), 0.9, 0.001, "a notch down: a tenth smaller")
    t:eq(BB.DockScaleStep(ns.SCALE_MAX, 1), ns.SCALE_MAX, "not past the biggest")
    t:eq(BB.DockScaleStep(ns.SCALE_MIN, -1), ns.SCALE_MIN, "nor under the smallest")
    local buff, main = _G.FlowBuffButton, _G.FlowCastButton
    if not (buff and main and BB.handle) or InCombatLockdown() then return end
    local cfg = ns.db.buffButton
    local was = cfg.dockScale
    with(BB, "Docked", function() return true end, function()
        local mainScale, before = main:GetScale(), buff:GetScale()
        local h = BB.handle
        -- The wheel, as the handle hears it (Ctrl held is what shows the handle).
        t:ok(pcall(h.ScaleBy, h, 1), "a notch over the docked button runs")
        t:near(buff:GetScale(), ns.ClampScale(before + ns.SCALE_STEP), 0.001, "the self button is a tenth bigger")
        t:near(main:GetScale(), mainScale, 0.001, "Flow's icon keeps its size")
        local p, rel = buff:GetPoint(1)
        t:ok(p == "TOP" and rel == main, "and it's still docked under Flow's icon")
        t:ok(pcall(h.ScaleBy, h, -1), "a notch back")
        t:near(buff:GetScale(), before, 0.001, "as it was")
    end)
    cfg.dockScale = was
    pcall(BB.Place)
end)

