-------------------------------------------------------------------------------
-- 0.35.261: meters: when they show, rows 2 / 5 / 10; tooltips with room.
-------------------------------------------------------------------------------

ns:Register("test", "click: the meters' menu: show in combat, in group or always; rows 2, 5, 10", function(t)
    local M = ns.meters
    t:eq(M.WhenKey({}), "group", "nothing chosen: in a group")
    t:eq(M.WhenKey({ always = true }), "always", "the older always-shown choice still counts")
    t:eq(M.WhenKey({ when = "combat" }), "combat", "in combat")
    t:ok(M.ShowNow("always", false, false, false), "always: alone and out of a fight too")
    t:ok(M.ShowNow("combat", false, true, false) and not M.ShowNow("combat", true, false, false), "combat: only in a fight, grouped or not")
    t:ok(M.ShowNow("group", true, false, false) and not M.ShowNow("group", false, true, false), "group: in a group, not alone in a fight")
    t:ok(M.ShowNow("group", false, false, true), "group: a training dummy counts too")
    local c = ns.db.meters
    local always, when, off, rows = c.always, c.when, c.off, c.rows
    local items = M.ContextItems()
    local heads, seen = {}, 0
    for _, it in ipairs(items) do
        if it.title then heads[it.text] = true end
        for _, want in ipairs({ { "Show in combat", "combat" }, { "Show in group", "group" }, { "Always show", "always" } }) do
            if it.text == want[1] then
                seen = seen + 1
                t:ok(pcall(it.func), "a click on " .. want[1] .. " runs")
                t:eq(M.WhenKey(c), want[2], "and picks it")
            end
        end
    end
    t:eq(seen, 3, "all three are there")
    t:ok(heads.Show and heads.Rows, "under Show and Rows headings")
    local labels = {}
    for _, it in ipairs(items) do
        if it.text == "2" or it.text == "5" or it.text == "10" then
            labels[#labels + 1] = it.text
            if it.text == "5" then
                t:ok(pcall(it.func) and M.PlayerRows() == 5, "a click on 5 shows five players")
            end
        end
    end
    t:eq(table.concat(labels, " "), "2 5 10", "the rows are named 2, 5 and 10")
    c.always, c.when, c.off, c.rows = always, when, off, rows
    pcall(M.Update)
end)

ns:Register("test", "tooltips: one Flow opens has room for its sentences, and gives the width back", function(t)
    t:ok(ns.TIP_WIDTH >= 280, "wide enough for a sentence")
    local set = {}
    local fake = { SetMinimumWidth = function(_, w) set[#set + 1] = w end,
                   HookScript = function(self, _, fn) self.onHide = fn end }
    t:ok(ns.WidenTip(fake), "a tooltip is widened")
    t:eq(set[1], ns.TIP_WIDTH, "to Flow's width")
    t:ok(type(fake.onHide) == "function", "and watched for closing")
    fake.onHide(fake)
    t:eq(set[2], 0, "closed: the game's own width again")
    ns.WidenTip(fake)
    t:eq(#set, 3, "opened again: widened again")
    t:eq(ns.WidenTip({}), false, "a tooltip that can't be widened: left alone")
    t:eq(ns.WidenTip(nil), false, "none: nothing")
end)

-------------------------------------------------------------------------------
-- 0.35.262: materials your skill is past; spare bags.
-------------------------------------------------------------------------------

ns:Register("test", "bags: a material your skill has moved past is no longer kept for that profession", function(t)
    local D = ns.disposition
    local guide = { steps = {
        { recipe = "Linen Bandage", mats = { [2589] = 1 } },
        { recipe = "Heavy Linen Bandage", mats = { [2589] = 2 } },
        { recipe = "Wool Bandage", mats = { [2592] = 1 } },
    } }
    -- What the First Aid window showed at 80 (W4d: no skill ranges of Flow's own).
    local seen = { ["Linen Bandage"] = { diff = "trivial" }, ["Heavy Linen Bandage"] = { diff = "trivial" },
                   ["Wool Bandage"] = { diff = "optimal" } }
    t:ok(D.StepPast(guide.steps[2], 80, seen, 80), "Heavy Linen Bandage grey in the window at 80: behind you")
    t:ok(D.StepPast(guide.steps[2], 90, seen, 80), "and at any skill above")
    t:ok(not D.StepPast(guide.steps[2], 79, seen, 80), "at 79: below where it was seen grey, not known to be past")
    t:ok(not D.StepPast(guide.steps[3], 80, seen, 80), "orange in the window: not past")
    t:ok(not D.StepPast(guide.steps[2], 300), "never seen in the window: never past")
    t:ok(not D.StepPast({}, 300, seen, 80), "nothing known about it: never past")
    t:eq(D.OutgrownBy(2589, 80, guide, seen, 80), "Heavy Linen Bandage", "Linen Cloth at First Aid 80: past it")
    local mid = { ["Linen Bandage"] = { diff = "trivial" }, ["Heavy Linen Bandage"] = { diff = "medium" } }
    t:eq(D.OutgrownBy(2589, 60, guide, mid, 60), nil, "at 60: Heavy Linen Bandage still wants it")
    t:eq(D.OutgrownBy(2592, 80, guide, seen, 80), nil, "Wool Cloth at 80: wanted now")
    t:eq(D.OutgrownBy(9999, 80, guide, seen, 80), nil, "something the profession never uses: not this rule's")
    t:eq(D.OutgrownBy(2589, 80, nil, seen, 80), nil, "no profession data: not this rule's")
    t:eq(D.OutgrownBy(2589, 80, guide), nil, "no window seen: nothing outgrown")
    t:eq(D.OutgrownText({ ["First Aid"] = "Heavy Linen Bandage" }), "your First Aid is past it (Heavy Linen Bandage)", "said in words")
    t:eq(D.OutgrownText(nil), nil, "nothing outgrown: nothing said")
    -- Spare bags.
    t:eq(D.BagSize({ { left = "Brown Leather Satchel" }, { left = "8 Slot Bag" } }), 8, "the tooltip's size")
    t:eq(D.BagSize({ { left = "Linen Cloth" } }), nil, "not a bag: no size")
    t:eq(D.SpareBag(8, { 8, 8, 10, 8 }), "spare", "every bag you wear is as big or bigger: a spare")
    t:eq(D.SpareBag(8, { 8, 6, 10, 8 }), "wear", "bigger than one you wear: put it on")
    t:eq(D.SpareBag(6, { 8, 0, 10, 8 }), "wear", "an empty bag slot: put it on")
    t:eq(D.SpareBag(nil, { 8, 8, 8, 8 }), nil, "size unknown: left alone")
    local ok, worn = pcall(D.WornBags)
    t:ok(ok and #worn == 4, "your four bag slots are read")
end)

-------------------------------------------------------------------------------
-- 0.35.263: the dungeon route keeps the errands that get you ready.
-------------------------------------------------------------------------------

ns:Register("test", "click: the dungeon route keeps your training, vendor and bank; a tick turns that off", function(t)
    local D = ns.dungeons
    t:ok(D.IsPrep({ key = "train:class", provider = "errands" }), "class training is getting ready")
    t:ok(D.IsPrep({ key = "train:Herbalism", provider = "skillplan" }), "a profession tier at its trainer too")
    t:ok(D.IsPrep({ key = "merchant", provider = "merchant" }), "selling")
    t:ok(D.IsPrep({ key = "repair", provider = "repair" }), "repairs")
    t:ok(D.IsPrep({ key = "bank", provider = "banker" }), "your bank")
    t:ok(not D.IsPrep({ key = "skill:Herbalism", provider = "skillplan" }), "gathering isn't")
    t:ok(not D.IsPrep({ key = "99:obj1", provider = "questie" }), "another quest isn't")
    t:ok(not D.IsPrep({ key = "flightpath:Tal", provider = "flightpath" }), "a flight path isn't")
    t:ok(not D.IsPrep(nil), "nothing: no")
    local ids = { [10] = true }
    t:ok(D.KeepForRun({ key = "train:class", provider = "errands" }, ids, true), "on the dungeon route: training stays")
    t:ok(not D.KeepForRun({ key = "train:class", provider = "errands" }, ids, false), "with getting ready off: only the run")
    t:ok(D.KeepForRun({ key = "10:obj1" }, ids, false), "the run's own steps stay either way")
    t:ok(not D.KeepForRun({ key = "99:obj1" }, ids, true), "other quests still go")
    -- The tick on the route's menu.
    local was, wasRun, wasOnly = ns.db.nav.dungeonPrep, ns.db.nav.dungeonRun, ns.db.nav.dungeonOnly
    with(ns.nav, "Collect", function() end, function()
        ns.db.nav.dungeonRun = { key = "no-such-run", name = "Test" }
        ns.db.nav.dungeonPrep = nil
        t:ok(D:PrepOn(), "on unless you turn it off")
        local tick
        for _, it in ipairs(D:ModeItems()) do if it.text and it.text:find("^Get ready on the way") then tick = it end end
        t:ok(tick ~= nil and tick.checked == true, "the menu has the tick, on")
        if tick then
            t:ok(pcall(tick.func), "a click runs")
            t:ok(not D:PrepOn(), "and turns it off")
            pcall(tick.func)
            t:ok(D:PrepOn(), "again: back on")
        end
    end)
    ns.db.nav.dungeonPrep, ns.db.nav.dungeonRun, ns.db.nav.dungeonOnly = was, wasRun, wasOnly
end)

-------------------------------------------------------------------------------
-- 0.35.264: the minimap marker rings the spot, the middle left clear.
-------------------------------------------------------------------------------

ns:Register("test", "minimap: in view the step's marker is a ring round the spot, clear in the middle", function(t)
    local P = ns.minimapPin
    t:eq(P.Look(false), "ring", "in view: a ring round the spot")
    t:eq(P.Look(true), "dot", "at the minimap's edge: the solid dot")
    local pts = P.RingPoints(8, 11)
    t:eq(#pts, 8, "eight dots")
    local clear = true
    for _, pt in ipairs(pts) do
        local d = math.sqrt(pt[1] * pt[1] + pt[2] * pt[2])
        if math.abs(d - 11) > 0.01 then clear = false end
    end
    t:ok(clear, "all on the ring: none over the spot itself")
    t:ok(P.RING_RADIUS - P.RING_DOT >= 7, "the clear middle is big enough for the game's icon and its arrow")
    local pin = P.Pin()
    if not (pin and pin.SetLook) then return end
    local was = pin.look
    pin:SetLook("ring", 1, 0.5, 0)
    t:ok(not pin.ring:IsShown() and not pin.dot:IsShown() and not pin.hole:IsShown() and not pin.edge:IsShown(), "ring: nothing drawn on the spot")
    t:ok(pin.around[1].dot:IsShown() and pin.around[8].dot:IsShown(), "the dots round it show")
    pin:SetLook("dot", 1, 0.5, 0)
    t:ok(pin.ring:IsShown() and pin.dot:IsShown() and not pin.around[1].dot:IsShown(), "dot: the solid marker, no ring of dots")
    if was then pin:SetLook(was) end
end)

-------------------------------------------------------------------------------
-- 0.35.265: a form's new spell goes on that form's bar.
-------------------------------------------------------------------------------

ns:Register("test", "bars: a new spell that needs a form goes to the first empty slot of that form's bar", function(t)
    local AP = ns.autopush
    local first, last = AP.FormSlots(3)
    t:ok(first == 97 and last == 108, "bear (the game's bar 3): slots 97 to 108")
    first, last = AP.FormSlots(1)
    t:ok(first == 73 and last == 84, "cat (bar 1): slots 73 to 84")
    t:eq(AP.FormSlots(0), nil, "no form bar: none")
    t:eq(AP.FormSlots(nil), nil, "unknown: none")
    local forms = { "Bear Form", "Cat Form", "Dire Bear Form", "Travel Form" }
    t:eq(AP.FormOf({ { left = "Maul" }, { left = "Requires Bear Form" } }, forms), "Bear Form", "the tooltip says the form")
    t:eq(AP.FormOf({ { left = "Requires Cat Form" } }, forms), "Cat Form", "cat")
    t:eq(AP.FormOf({ { left = "Requires Dire Bear Form" } }, forms), "Dire Bear Form", "the longer name wins over Bear Form")
    t:eq(AP.FormOf({ { left = "Requires Level 20" } }, forms), nil, "another requirement: no form")
    t:eq(AP.FormOf({ { left = "Turns you into Bear Form." } }, forms), nil, "a mention that isn't a requirement: no")
    t:eq(AP.FormOf({ { left = "Requires Bear Form" } }, {}), nil, "you have no forms: no")
    t:eq(AP.FirstEmpty(97, 108, function(s) return s < 100 end), 100, "the first empty slot")
    t:eq(AP.FirstEmpty(97, 108, function() return true end), nil, "a full bar: none")
    t:ok(AP.OnBar(100, 97, 108) and not AP.OnBar(5, 97, 108), "already on the form's bar, or not")
    t:eq(AP.KNOWN_BARS.DRUID["Bear Form"], 3, "a druid's bars are known from the start")
    -- The setting's box.
    local was = ns.db.autopush.formBars
    ns.db.autopush.formBars = false
    t:eq(AP.On(), false, "off when you turn it off")
    t:eq(AP:Move(1, 1, "Test"), "off", "and then nothing is moved")
    ns.db.autopush.formBars = was
    t:eq(AP.On(), was ~= false, "on unless turned off")
    -- A spell with no form stays where the game put it (nothing is picked up).
    local ok, what = pcall(AP.Move, AP, 0, 1, "No such spell")
    t:ok(ok and (what == "no form" or what == "off"), "a spell that needs no form is left alone")
end)

-------------------------------------------------------------------------------
-- 0.35.266: a leftover quest item reads the same in the bags and in Improvements.
-------------------------------------------------------------------------------

ns:Register("test", "bags: a leftover quest item gets one answer: keep for a quest not done, sell, or destroy", function(t)
    local L = ns.leftovers
    local what, why = L.Advice({ { name = "Blood Shards of Agamaggan", level = 15, done = true },
                                 { name = "Rage of Ages", level = 20, done = false } }, 25)
    t:eq(what, "keep", "a quest you haven't done uses it: keep")
    t:ok(why:find("Rage of Ages", 1, true) ~= nil and why:find("level 20", 1, true) ~= nil, "and it names the quest")
    what, why = L.Advice({ { name = "Old Quest", level = 12, done = true } }, 25)
    t:eq(what, "sell", "every quest that used it is done, and a vendor pays: sell")
    t:ok(why:find("quest you've done", 1, true) ~= nil, "saying it's left over from a quest you've done")
    what, why = L.Advice({ { name = "Old Quest", level = 12, done = true } }, 0)
    t:eq(what, "destroy", "done, and vendors won't take it: destroy")
    t:ok(why:find("destroy", 1, true) ~= nil, "in words")
    what = L.Advice({}, 0)
    t:eq(what, "keep", "no quest known for it: kept, Flow does not guess")
    what = L.Advice({}, 40)
    t:eq(what, "keep", "no quest known for it, a price: still kept")
    what = L.Advice({ { name = "A", level = 30, done = false }, { name = "B", level = 18, done = false } }, 0)
    t:eq(what, "keep", "two quests not done: keep")
    -- The bags' rule and Flow Improvements go by the same function.
    local rule = ns:Get("disposition", "leftover")
    t:ok(rule ~= nil and rule.order < 2, "the bags ask before 'vendors won't buy it' and 'quest item'")
    with(L, "For", function(id) if id == 5075 then return "sell", "left over from a quest you've done: sell it" end end, function()
        local v = rule.check({ classID = 12, id = 5075, name = "Blood Shard", sellPrice = 25 })
        t:ok(v and v.action == "sell" and v.reason:find("left over", 1, true) ~= nil, "the bags: sell, with the reason")
        t:eq(L.ImproveText({ id = 5075, name = "Blood Shard", sell = 25 }), "Blood Shard in your bags: left over from a quest you've done: sell it.",
            "Flow Improvements: the same words")
        t:eq(rule.check({ classID = 12, id = 1, name = "Wanted", sellPrice = 0 }), nil, "a quest item your log uses: left to the usual rules")
        t:eq(rule.check({ classID = 7, id = 5075, name = "Not a quest item", sellPrice = 5 }), nil, "not of the Quest kind: not this rule's")
    end)
    with(L, "For", function() return "destroy", "nothing uses it, and vendors won't take it: destroy it for the slot" end, function()
        local v = rule.check({ classID = 12, id = 5165, name = "Sunscale Feather", sellPrice = 0 })
        t:ok(v and v.action == "keep" and v.reason:find("destroy", 1, true) ~= nil, "to destroy: Flow keeps it (it never destroys) and says to")
    end)
    t:ok(pcall(L.Lines), "the diagnostics lines build")
    t:ok(pcall(L.Related, 5075), "asking the quest data about an item runs")
end)

-------------------------------------------------------------------------------
-- 0.35.267: how many you have, on item tooltips.
-------------------------------------------------------------------------------

ns:Register("test", "tooltips: an item's tooltip says how many you have, in bags and bank", function(t)
    local H = ns.haveCount
    t:eq(H.Text(12, 40), "You have 52: 12 in your bags, 40 in your bank", "both: the total and the split")
    t:eq(H.Text(12, 0), "You have 12 (in your bags)", "only in your bags")
    t:eq(H.Text(0, 40), "You have 40, all in your bank", "only in your bank")
    t:eq(H.Text(0, 0), nil, "none: no line")
    t:eq(H.Text(nil, nil), nil, "unknown: no line")
    t:eq(H.Text(-3, 2), "You have 2, all in your bank", "a wrong count below zero is taken as none")
    local ok, bags, bank = pcall(H.Counts, 6948)
    t:ok(ok and type(bags) == "number" and type(bank) == "number", "counting an item runs")
    -- The line goes on the tooltip, and not when the setting is off.
    local lines = {}
    local fake = { AddLine = function(_, text) lines[#lines + 1] = text end }
    with(H, "Counts", function() return 3, 7 end, function()
        H._addLine(fake, 1)
        t:eq(lines[1], "You have 10: 3 in your bags, 7 in your bank", "the line is added")
        ns.db.settings = ns.db.settings or {}
        local was = ns.db.settings.haveCount
        ns.db.settings.haveCount = false
        H._addLine(fake, 1)
        t:eq(#lines, 1, "turned off: no line")
        ns.db.settings.haveCount = was
    end)
    with(H, "Counts", function() return 0, 0 end, function()
        H._addLine(fake, 1)
        t:eq(#lines, 1, "you have none: no line")
    end)
end)

-------------------------------------------------------------------------------
-- 0.35.268: the key rows have room; the auction scan says done once and waits.
-------------------------------------------------------------------------------

ns:Register("test", "settings: the key rows keep the key clear of the buttons, with room between rows", function(t)
    local S = ns.settings
    t:ok(S.KEY_BUTTON_X - S.KEY_VALUE_X >= 140, "the key has a column of its own before the buttons")
    t:ok(S.KEY_VALUE_X >= 190, "past the longest label (Self button's second key:)")
    t:ok(S.KEY_ROW >= 30, "a little more room between the rows")
    t:ok(S.KEY_BUTTON_X + 90 + 8 + 80 <= 580, "Set key and Clear still fit in the window")
    local f = S._Build and S._Build()
    t:ok(f ~= nil, "Flow Settings builds")
    if f and f.key4Value and f.set4 then
        t:ok(f.key4Value:GetWidth() <= S.KEY_BUTTON_X - S.KEY_VALUE_X, "the self button's second key ends before its buttons")
        local p, _, _, x = f.set4:GetPoint(1)
        t:ok(p == "TOPLEFT" and math.abs((x or 0) - S.KEY_BUTTON_X) < 1, "its Set key button is in the button column (" .. tostring(p) .. ", " .. tostring(x) .. ")")
    end
end)

ns:Register("test", "auctions: opening the window again soon doesn't look everything up again", function(t)
    local AH = ns.auction
    t:ok(AH.ScanDue(nil, 1000), "never looked: look")
    t:ok(not AH.ScanDue(1000, 1060), "a minute ago: not again")
    t:ok(AH.ScanDue(1000, 1000 + AH.SCAN_EVERY), "after the wait: look again")
    t:ok(AH.SCAN_EVERY >= 120, "a few minutes between looks")
end)

-------------------------------------------------------------------------------
-- 0.35.269: Flow Banker: Deposit on the right, the choices button on the left.
-------------------------------------------------------------------------------

ns:Register("test", "banker: Deposit and All my choices sit on opposite sides, clear of each other", function(t)
    local B = ns.banker
    local ok, f = pcall(function() return B._Frame and B._Frame() or _G.FlowBanker end)
    f = ok and f or _G.FlowBanker
    if not (f and f.go and f.all) then return end
    local p, _, rp, x = f.go:GetPoint(1)
    t:ok(p == "BOTTOMRIGHT" and rp == "BOTTOMRIGHT" and x < 0, "Deposit hangs from the right edge")
    local pa, _, rpa, xa = f.all:GetPoint(1)
    t:ok(pa == "BOTTOMLEFT" and rpa == "BOTTOMLEFT" and xa > 0, "the choices button from the left edge")
    t:ok(xa + f.all:GetWidth() + 8 <= f:GetWidth() + x - f.go:GetWidth(), "with a gap between them")
end)

-------------------------------------------------------------------------------
-- 0.35.270: the bank's picture; leftovers look through every quest; class items.
-------------------------------------------------------------------------------

ns:Register("test", "banker: the bank's picture starts with the containers that hold things", function(t)
    local SP = ns.skillPlan
    local old = { false, false, false }                       -- the old main bank: nothing but empty slots
    local tab = { { 2589, 20 }, false, { 2318, 7 } }          -- a tab with your things
    local layout = SP.BankLayout({ old, tab })
    t:eq(#layout, 6, "every slot is still there")
    t:ok(layout[1] and layout[1][1] == 2589, "your things first, from the top left")
    t:ok(layout[2] == false and layout[3] and layout[3][1] == 2318, "in their own order, gaps kept")
    t:ok(layout[4] == false and layout[6] == false, "the empty container after them")
    t:eq(#SP.BankLayout({}), 0, "no containers: nothing")
    local same = SP.BankLayout({ tab, old })
    t:ok(same[1][1] == 2589 and same[6] == false, "already in that order: unchanged")
    local btn = ns:Get("gameButton", "bank")
    t:ok(btn ~= nil and btn.frames[1] == "BankFrame" and btn.label == "Flow Banker", "a Flow Banker button on the bank's window")
    t:ok(pcall(btn.isOpen), "its open check runs")
end)

ns:Register("test", "bags: a leftover with no quest known is kept, not destroyed; other classes' items go", function(t)
    local L, D = ns.leftovers, ns.disposition
    local what, why = L.Advice({}, 0)
    t:eq(what, "keep", "no quest known: Flow doesn't say destroy")
    t:ok(why:find("read its tooltip", 1, true) ~= nil, "it says to read the item first")
    local ids = L.MergeIds({ 905, 881 }, { [905] = true, [3261] = true })
    t:eq(table.concat(ids, ","), "881,905,3261", "the quest data's list and the look through every quest, once each")
    t:eq(#L.MergeIds(nil, nil), 0, "neither: none")
    t:ok(L.SCAN_CHUNK >= 50, "a few hundred quests a frame")
    -- "Classes: Mage" on something that isn't gear.
    local classes = D.ClassesOf({ { left = "Scroll: CWAL" }, { left = "Classes: Mage" }, { left = "Requires Comprehension (1)" } })
    t:ok(classes and #classes == 1 and classes[1] == "Mage", "the tooltip names the class")
    classes = D.ClassesOf({ { left = "Classes: Mage, Warlock" } })
    t:ok(classes and classes[2] == "Warlock", "several classes")
    t:eq(D.ClassesOf({ { left = "Use: Restores 100 health." } }), nil, "no class named: anyone's")
    t:ok(not D.ForYourClass({ "Mage" }, "Druid"), "a Mage's scroll is no use to a Druid")
    t:ok(D.ForYourClass({ "Mage", "Druid" }, "Druid"), "one of them is yours: it is")
    t:ok(D.ForYourClass(nil, "Druid"), "no classes named: yours to use")
    local rule = ns:Get("disposition", "otherClassItem")
    t:ok(rule ~= nil and rule.order < 30, "asked before the plain 'not gear: keep'")
    t:eq(rule.check({ gear = {}, link = "x" }), nil, "gear is left to the gear rules")
end)

-------------------------------------------------------------------------------
-- 0.35.271: your own party messages, signed with a name Flow isn't given.
-------------------------------------------------------------------------------

ns:Register("test", "party: your own message come back under your full name is you, not a party member", function(t)
    local P, H = ns.party, ns.partyHelp
    t:ok(P.IsEcho("Sooth Tao", "Sooth", 100, 101), "the same words a second later, signed with a name that starts with yours: you")
    t:ok(P.IsEcho("Sooth", "Sooth", 100, 101), "signed with the name Flow knows: you")
    t:ok(not P.IsEcho("Sooth Tao", "Sooth", nil, 101), "words Flow never sent: someone else's")
    t:ok(not P.IsEcho("Sooth Tao", "Sooth", 100, 100 + P.ECHO_SECONDS + 1), "long after Flow sent them: someone else's")
    t:ok(not P.IsEcho("Beryl Rattlewick", "Sooth", 100, 101), "another name: someone else")
    t:ok(not P.IsEcho("Sooth Tao", "", 100, 101), "your name unknown: no guess")
    -- Once learned, that name is you; the old checks are unchanged.
    local was = P.aliases["Sooth Tao"]
    P.aliases["Sooth Tao"] = true
    t:ok(P.IsMe("Sooth Tao"), "the learned name is you from then on")
    t:ok(not P.IsMe("Sooth Tao", "Sooth", "Realm"), "a plain comparison of two names is unchanged")
    P.aliases["Sooth Tao"] = was
    t:ok(P.IsMe("Bob-Realm", "Bob", "Realm") and not P.IsMe("Alice-Realm", "Bob", "Realm"), "names with realms as before")
    t:ok(pcall(H.Drop, "Nobody By This Name"), "forgetting a name's progress runs")
    t:ok(pcall(H.Drop, nil), "no name: nothing")
end)

-------------------------------------------------------------------------------
-- 0.35.272: your buffs for others on a player's tooltip, whoever cast them.
-------------------------------------------------------------------------------

ns:Register("test", "tooltips: a player's tooltip says which of your buffs they have, from anyone", function(t)
    local T = ns.groupTip
    local text, kind = T.Line("Mark of the Wild", true, 24 * 60, "Mark of the Wild", false)
    t:eq(text, "Mark of the Wild: has it (24 min)", "they have it: with the time left")
    t:eq(kind, "has", "counted as having it")
    text, kind = T.Line("Mark of the Wild", true, 51 * 60, "Gift of the Wild", false)
    t:eq(text, "Mark of the Wild: has Gift of the Wild (51 min)", "the group version from someone else: named")
    t:eq(kind, "other", "and it counts")
    text, kind = T.Line("Mark of the Wild", false, 0, nil, true)
    t:eq(text, "Mark of the Wild: has a more powerful one", "the game refused yours: a stronger one is on them")
    t:eq(kind, "stronger", "no need to buff")
    text, kind = T.Line("Thorns", false, 0, nil, false)
    t:eq(text, "Thorns: MISSING", "not on them: missing")
    t:eq(kind, "missing", "yours to give")
    text, kind = T.Line("Thorns", nil, nil, nil, false)
    t:eq(kind, "hidden", "the game hides their buffs: Flow says it can't tell")
    t:ok(text:find("can't tell", 1, true) ~= nil, "in words")
    t:eq(T.Left(40), " (40 s)", "under a minute and a half: seconds")
    t:eq(T.Left(math.huge), "", "doesn't run out: no time")
    t:eq(T.Left(nil), "", "unknown: no time")
    t:ok(T.COLORS.missing[1] > T.COLORS.missing[2] and T.COLORS.has[2] > T.COLORS.has[1], "missing is red, having it green")
    -- The lines go on the tooltip under a heading; nothing for yourself.
    local lines = {}
    local fake = { AddLine = function(_, s) lines[#lines + 1] = s end }
    with(T, "Lines", function() return { { text = "Thorns: MISSING", kind = "missing" } } end, function()
        T._addLines(fake, "party1")
        t:ok(lines[1] == "Your buffs for them:" and lines[2] == "  Thorns: MISSING", "a heading, then a line per buff")
        ns.db.settings = ns.db.settings or {}
        local was = ns.db.settings.groupTip
        ns.db.settings.groupTip = false
        T._addLines(fake, "party1")
        t:eq(#lines, 2, "turned off: nothing added")
        ns.db.settings.groupTip = was
    end)
    local ok, mine = pcall(T.Lines, "player")
    t:ok(ok and #mine == 0, "your own tooltip gets none")
    t:ok(type(ns.rotation.AuraOn) == "function", "the buff reader says which buff it found")
end)

-------------------------------------------------------------------------------
-- 0.35.273: every small icon shows its cooldown and status; nameplate threat.
-------------------------------------------------------------------------------

ns:Register("test", "small icons: cooldown and can't-cast look on Flow's and the self button's alike", function(t)
    local grey, r, g, b = ns.StatusLook("", nil)
    t:ok(not grey and r == 1 and g == 1 and b == 1, "ready: drawn as it is")
    grey = ns.StatusLook("12", nil)
    t:ok(grey, "cooling down: greyed")
    grey, r, g, b = ns.StatusLook("", { 1, 0.35, 0.35, false })
    t:ok(not grey and r == 1 and g < 0.5 and b < 0.5, "out of range: red, not grey")
    grey, r = ns.StatusLook("", { 0.55, 0.55, 0.55, true })
    t:ok(grey and r < 1, "can't be cast now: grey")
    local txt, tv = ns.StepStatus(nil, GetTime())
    t:ok(txt == "" and tv == nil, "no step: nothing to show")
    t:ok(pcall(ns.StepStatus, { item = "item:858" }, GetTime()), "an item's cooldown reads (a potion, a bandage)")
    t:ok(pcall(ns.StepStatus, { spell = "No Such Spell" }, GetTime()), "a spell you don't have: no error")
    -- Painting onto an icon.
    local seen = {}
    local tex = { SetDesaturated = function(_, v) seen.grey = v end, SetVertexColor = function(_, rr) seen.r = rr end }
    local timer = { SetText = function(_, s) seen.text = s end }
    t:ok(pcall(ns.PaintStatus, tex, timer, { spell = "No Such Spell" }, GetTime()), "painting runs")
    t:ok(seen.text ~= nil and seen.grey ~= nil and seen.r ~= nil, "it sets the timer, the grey and the colour")
    -- The self button's icons have a timer and are kept fresh.
    local K = ns.careKeys
    t:ok(K.STATUS_EVERY <= 0.5, "a few times a second")
    local ok, n = pcall(K.PaintStatus, GetTime())
    t:ok(ok and type(n) == "number", "painting the self button's icons runs")
    for _, ic in pairs(K._icons) do
        t:ok(ic.timer ~= nil, "each has a place for its cooldown")
    end
end)

ns:Register("test", "threat on nameplates: raised, and coloured by your share when you're not tanking", function(t)
    local P = ns.plateThreat
    t:ok(P.RAISE >= 8, "raised clear of the level")
    t:eq(P.Band(120), "over", "over 100%")
    t:eq(P.Band(100), "over", "at 100%")
    t:eq(P.Band(95), "high", "above 90%")
    t:eq(P.Band(70), "mid", "below that")
    t:eq(P.Band(20), "calm", "way below")
    t:eq(P.Band(nil), nil, "hidden: no band")
    local key, flash = P.Look("danger", 110, false)
    t:ok(key == "over" and flash == true, "over 100%: red and flashing")
    key, flash = P.Look("pulling", 93, false)
    t:ok(key == "high" and not flash, "above 90%: red, steady")
    key, flash = P.Look("low", 60, false)
    t:ok(key == "mid" and not flash, "below: yellow")
    key = P.Look("low", 10, false)
    t:eq(key, "calm", "way below: green")
    key, flash = P.Look("safe", 100, true)
    t:ok(key == "safe" and not flash, "tanking: 100% is where you want to be, so Flow's tanking colours, no flash")
    key = P.Look("hidden", nil, false)
    t:eq(key, "hidden", "a hidden share: white")
    t:ok(P.COLORS.over[1] > 0.9 and P.COLORS.over[2] < 0.3, "over is red")
    t:ok(P.COLORS.mid[1] > 0.9 and P.COLORS.mid[2] > 0.8, "mid is yellow")
    t:ok(P.COLORS.calm[2] > P.COLORS.calm[1], "calm is green")
end)

