-------------------------------------------------------------------------------
-- 0.35.275: the upgrade arrow on a loot roll; the seller says why it stopped.
-------------------------------------------------------------------------------

local rollTestFrame   -- (made once: a test may not make a new frame every run)
ns:Register("test", "loot rolls: an upgrade gets the green arrow and its figure on the roll window", function(t)
    local R = ns.rollHint
    local show, gain = R.ArrowFor({ roll = "need", gain = 2.14 })
    t:ok(show and gain == "+2.1", "an upgrade: the arrow, and how much better")
    show, gain = R.ArrowFor({ roll = "greed" })
    t:ok(not show and gain == "", "not an upgrade: no arrow")
    show = R.ArrowFor(nil)
    t:ok(not show, "no verdict: no arrow")
    t:ok(R.ARROW >= 16, "big enough to see at a glance")
    -- (0.35.318: the marks are on a frame laid over the item's picture, which
    -- is a frame of its own; the arrow used to be under it. A stand-in roll
    -- window with its item's frame, made once.)
    local f = rollTestFrame
    if not f then
        f = CreateFrame("Frame", nil, UIParent)
        f:SetSize(240, 50); f:Hide()
        f.IconFrame = CreateFrame("Button", nil, f)
        f.IconFrame:SetSize(36, 36)
        f.IconFrame:SetPoint("LEFT", 6, 0)
        rollTestFrame = f
    end
    local cmp = { canUse = true, diffs = { dps = 3, heal = -1, tank = 0.1 } }
    local ok, o = pcall(R.Paint, f, { roll = "need", gain = 3 }, "need", cmp)
    t:ok(ok and o ~= nil, "an upgrade: the marks are painted" .. (ok and "" or (": " .. tostring(o))))
    if not (ok and o) then return end
    t:ok(o:GetParent() == f.IconFrame and o:GetFrameLevel() > f.IconFrame:GetFrameLevel(), "on a frame over the item's own picture")
    t:ok(not o:IsMouseEnabled(), "taking no clicks")
    t:ok(o.arrow:IsShown() and o.gain:GetText() == "+3.0", "the arrow, with the figure")
    t:ok(o.specs:IsShown(), "and the spec marks along the bottom")
    t:ok(not o.coin:IsShown() and not o.ah:IsShown(), "no coin or auction mark on an upgrade")
    R.Paint(f, { roll = "greed" }, "sell", { canUse = false })
    t:ok(not o.arrow:IsShown() and o.coin:IsShown(), "a vendor item: the coin, no arrow")
    t:ok(not o.specs:IsShown(), "something you can't wear: no spec marks")
    R.Paint(f, { roll = "greed" }, "de", cmp)
    t:eq(o.letters:GetText(), "DE", "one to disenchant: DE")
    R.Paint(f, { roll = "greed" }, "ah", cmp)
    t:ok(o.ah:IsShown() or o.letters:GetText() == "AH", "one for the auction house: its mark")
    t:eq(R.IconHost(f), f.IconFrame, "the item's frame is found")
end)

ns:Register("test", "loot rolls: what becomes of an item that isn't an upgrade", function(t)
    -- "the major up arrow to tell me if it's an upgrade item or a vendor item"
    local R = ns.rollHint
    t:eq(R.Fate({ roll = "need" }, true, true), "need", "an upgrade: Need, whatever else")
    t:eq(R.Fate({ roll = "greed" }, false, true), "de", "the roll offers disenchanting: DE")
    t:eq(R.Fate({ roll = "greed" }, true, false, 50000, 100), "sell", "binds when picked up: no auction, the vendor")
    t:eq(R.Fate({ roll = "greed" }, false, false, 50000, 100, true), "ah", "a good auction price: the auction house")
    t:eq(R.Fate({ roll = "greed" }, false, false, nil, 100, true), "sell", "no price known: the vendor (the setting)")
    t:eq(R.Fate(nil), nil, "no verdict: nothing")
    t:eq(R.FATE_WORDS.sell, "then vendor it", "the line says it")
end)

ns:Register("test", "seller: after selling 12 it says why the rest are still there", function(t)
    local V = ns.vendor
    local note = V.HeldNote(12, 7, 12)
    t:ok(note ~= nil, "12 sold, 7 left: a note")
    t:ok(note:find("sold 12", 1, true) ~= nil and note:find("The 7 below", 1, true) ~= nil, "it counts both")
    t:ok(note:find("buy back", 1, true) ~= nil, "and says it's about buying back")
    t:ok(note:find("can no longer be bought back", 1, true) ~= nil, "and what selling the rest costs you")
    t:eq(V.HeldNote(12, 0, 12), nil, "nothing left: no note")
    t:eq(V.HeldNote(5, 7, 12), nil, "fewer than 12 sold: nothing was held back")
    t:eq(V.HeldNote(nil, nil, 12), nil, "nothing known: no note")
end)

-------------------------------------------------------------------------------
-- 0.35.276: the gathering step names what to pick.
-------------------------------------------------------------------------------

ns:Register("test", "professions: the gathering step names the herbs you can pick here", function(t)
    local SP = ns.skillPlan
    local barrens = { { name = "Peacebloom", skill = 1 }, { name = "Silverleaf", skill = 1 }, { name = "Earthroot", skill = 15 },
                      { name = "Mageroyal", skill = 50 }, { name = "Briarthorn", skill = 70 } }
    local function raises(skill, rank) return rank < skill + 100 end
    local picks = SP.PickNames(barrens, 35, raises)
    t:eq(table.concat(picks, ","), "Earthroot,Peacebloom,Silverleaf", "at 35: what you can pick, the best for skill first")
    t:eq(#SP.PickNames(barrens, 0, raises), 0, "no skill: nothing")
    picks = SP.PickNames(barrens, 120, raises)
    t:ok(picks[1] == "Briarthorn" and picks[2] == "Mageroyal", "at 120: the higher herbs first")
    for _, n in ipairs(picks) do t:ok(n ~= "Peacebloom" and n ~= "Silverleaf", n .. ": one that still raises your skill") end
    t:eq(SP.NameList({ "Earthroot", "Peacebloom", "Silverleaf" }), "Earthroot, Peacebloom or Silverleaf", "three, in words")
    t:eq(SP.NameList({ "Earthroot", "Peacebloom" }), "Earthroot or Peacebloom", "two")
    t:eq(SP.NameList({ "Earthroot" }), "Earthroot", "one")
    t:eq(SP.NameList({}), nil, "none: nothing to name")
    t:eq(SP.NameList({ "A", "B", "C", "D", "E" }, 3), "A, B or C", "no more than three named")
end)

-------------------------------------------------------------------------------
-- 0.35.277: the arrow's look, key bindings and extras live in Flow Settings.
-------------------------------------------------------------------------------

ns:Register("test", "click: what left the Flow menu is in Flow Settings, as ticks and buttons that work", function(t)
    local S, M = ns.settings, ns.menu
    t:eq(S.MenuRowKind({ text = "x", checked = true, func = function() end }), "check", "an entry with a tick stays a tick")
    t:eq(S.MenuRowKind({ text = "x", radio = true, func = function() end }), "check", "one of a set too")
    t:eq(S.MenuRowKind({ text = "x", func = function() end }), "action", "an entry that does something becomes a button")
    t:eq(S.MenuRowKind({ title = true, text = "x" }), nil, "a title isn't a row")
    t:eq(S.MenuRowKind({ sep = true }), nil, "nor a line")
    t:eq(S.MenuRowKind({ text = "only words" }), nil, "nor words with nothing to click")
    t:eq(S.MenuRowText({ text = "   Dock it" }), "Dock it", "the menu's indent is dropped")
    local list = { { text = "A" }, { text = "   B", checked = true } }
    t:ok(S.FindMenuItem(list, "B") == list[2], "an entry is found again by its words")
    t:eq(S.FindMenuItem(list, "C"), nil, "one that's gone: none")
    local groups = {}
    for _, sec in ipairs(M.SettingsSections()) do
        groups[sec.title] = sec.group
        local ok, items = pcall(sec.build)
        t:ok(ok and type(items) == "table", sec.title .. ": its entries build")
    end
    t:eq(groups["The arrow"], "route", "the arrow's look: under Finding your way")
    t:eq(groups["Key bindings"], nil, "key bindings aren't a second section: they're with the keys already")
    -- The page builds with them, and each button there runs.
    local f = S._Build and S._Build()
    t:ok(f ~= nil, "Flow Settings builds")
    if f and f.showKeys then
        local okC
        with(ns, "Print", function() end, function() okC = pcall(f.showKeys:GetScript("OnClick"), f.showKeys) end)
        t:ok(okC, "a click on Show keys bound to spells runs")
    end
    -- The menu's Buttons section: the self button, and docking it.
    local items = M.ButtonItems()
    t:eq(#items, 2, "two ticks: the self button, and docked")
    t:ok(items[1].checked ~= nil and items[2].checked ~= nil, "both show their state")
    -- Flow Meters in the Flow menu: one tick.
    local mi = ns.meters.MenuItems()
    t:eq(#mi, 1, "Flow Meters: shown or not, the rest on its own right-click")
end)

