-- 0.35.291: why a click on the self button might not cast.
-------------------------------------------------------------------------------

ns:Register("test", "self button: Flow can say what lies over it and whether presses came by mouse", function(t)
    local BB = ns.buffButton
    t:ok(BB.Overlaps({ 0, 0, 10, 10 }, { 5, 5, 10, 10 }), "two rectangles that share a corner overlap")
    t:ok(not BB.Overlaps({ 0, 0, 10, 10 }, { 10, 0, 10, 10 }), "side by side: they don't")
    t:ok(not BB.Overlaps({ 0, 0, 10, 10 }, { 0, 20, 10, 10 }), "one above the other with a gap: they don't")
    t:ok(not BB.Overlaps(nil, { 0, 0, 1, 1 }), "nothing to compare: no")
    t:ok(BB.Above("DIALOG", 1, "MEDIUM", 50), "a higher strata is on top, whatever the level")
    t:ok(BB.Above("MEDIUM", 60, "MEDIUM", 50), "the same strata: the higher level is on top")
    t:ok(not BB.Above("MEDIUM", 50, "MEDIUM", 50), "the same place: not on top")
    t:ok(not BB.Above("LOW", 99, "MEDIUM", 1), "a lower strata is underneath")
    -- (The look over every frame in the game runs only when you ask, /flow
    -- selfbutton why: measuring other frames made their own layout code run
    -- as Flow's, logged as taint, 0.35.315. The tests don't run it.)
    local okW, lines = pcall(BB.WhyLines, false)
    t:ok(okW and #lines >= 1, "the report builds")
    t:ok(type(ns.commands.selfbutton) == "function", "/flow selfbutton why")
end)

-------------------------------------------------------------------------------
-- 0.35.293: your quest steps by zone, and leaving a zone out.
-------------------------------------------------------------------------------

ns:Register("test", "click: quest steps are counted by zone, and a zone can be left out of the route", function(t)
    local N = ns.nav
    local goals = {
        { key = "a", provider = "questie", level = 14, z = 1 },
        { key = "b", provider = "questie", level = 18, z = 1 },
        { key = "c", provider = "pickups", kind = "accept", level = 20, z = 2 },
        { key = "d", provider = "questie", level = 22, z = 2 },
        { key = "e", provider = "errands", z = 2 },            -- a trainer: not a zone's quest
        { key = "f", provider = "questie", level = 16 },       -- no place known
    }
    local names = { [1] = "The Barrens", [2] = "Stonetalon Mountains" }
    local function zoneOf(g) return g.z end
    local function nameOf(z) return names[z] end
    local sum, kept, left = N.ZoneFilter(goals, {}, zoneOf, nameOf)
    t:eq(#sum, 2, "two zones have quest steps")
    t:eq(left, 0, "nothing left out")
    t:eq(#kept, 6, "everything stays")
    local byName = {}
    for _, z in ipairs(sum) do byName[z.name] = z end
    t:ok(byName["The Barrens"].steps == 2 and byName["The Barrens"].min == 14 and byName["The Barrens"].max == 18, "the Barrens: 2 steps, levels 14-18")
    t:ok(byName["Stonetalon Mountains"].steps == 2 and byName["Stonetalon Mountains"].accept == 1, "Stonetalon: 2 steps, one to accept (the trainer isn't counted)")
    t:eq(N.ZoneLine(byName["The Barrens"]), "The Barrens: 2 steps, levels 14-18", "said in a line")
    t:eq(N.ZoneLine(byName["Stonetalon Mountains"]), "Stonetalon Mountains: 2 steps (1 to accept), levels 20-22", "with what's still to accept")
    -- Stonetalon left out: its quest steps go, the trainer there stays.
    sum, kept, left = N.ZoneFilter(goals, { [2] = true }, zoneOf, nameOf)
    t:eq(left, 2, "its two quest steps are left out")
    local keys = {}
    for _, g in ipairs(kept) do keys[#keys + 1] = g.key end
    t:eq(table.concat(keys, ","), "a,b,e,f", "the rest stay, the trainer there too")
    for _, z in ipairs(sum) do
        if z.name == "Stonetalon Mountains" then
            t:ok(z.off, "it's still listed, marked as left out")
            t:ok(N.ZoneLine(z):find("LEFT OUT", 1, true) ~= nil, "and says so")
        end
    end
    t:eq(N.ZoneByName(sum, "stonetalon").name, "Stonetalon Mountains", "a zone is found by a part of its name")
    t:eq(N.ZoneByName(sum, "ashenvale"), nil, "one with no quest steps: none")
    t:eq(N.ZoneByName(sum, ""), nil, "nothing typed: none")
    -- The switch, by the menu's tick and by /flow zones. (Picked one by one
    -- since 0.35.316: ns.db.nav.zonesOn holds your zones. The zones for your
    -- level, WhereNext.lua, are stood in for: none here.)
    local was = ns.db.nav.zonesOn
    local W = ns.whereNext
    with(ns, "Print", function() end, function()
    with(N, "RequestCollect", function() end, function()
    with(W, "ByZone", function() return {} end, function()
    with(N, "zoneSummary", sum, function()
        ns.db.nav.zonesOn = { [1] = true, [2] = true }
        local items = N.ZoneMenuItems()
        local ticks = 0
        for _, it in ipairs(items) do if it.checked ~= nil then ticks = ticks + 1 end end
        t:eq(ticks, 2, "the Flow menu has a tick a zone")
        local tick
        for _, it in ipairs(items) do if it.text and it.text:find("^Stonetalon") then tick = it end end   -- (the line under them has no words)
        t:ok(tick ~= nil and type(tick.tipLines) == "table", "each zone has a tooltip of what it holds")
        t:ok(tick ~= nil and pcall(tick.func), "a click on Stonetalon's tick runs")
        t:ok(not ns.db.nav.zonesOn[2], "and leaves it out")
        t:ok(pcall(ns.commands.zones, "on stonetalon"), "/flow zones on runs")
        t:eq(ns.db.nav.zonesOn[2], true, "and picks it again")
        t:ok(pcall(ns.commands.zones, "off barrens") and not ns.db.nav.zonesOn[1], "/flow zones off leaves a zone out")
        t:ok(pcall(ns.commands.zones, "all") and ns.db.nav.zonesOn[1] and ns.db.nav.zonesOn[2], "/flow zones all picks every zone listed")
        t:ok(pcall(ns.commands.zones, ""), "/flow zones lists them")
        -- 0.35.311: Select all / Select none / Current zone only, under a line.
        local buttons = {}
        for _, it in ipairs(N.ZoneMenuItems()) do
            if it.text then buttons[(it.text:match("^(Select %a+ zones)") or it.text:match("^(Current zone only)") or "")] = it end
        end
        t:ok(buttons["Select no zones"] and pcall(buttons["Select no zones"].func), "click: Select no zones runs")
        t:ok(not ns.db.nav.zonesOn[1] and not ns.db.nav.zonesOn[2], "and unticks every zone")
        t:ok(buttons["Select all zones"] and pcall(buttons["Select all zones"].func) and ns.db.nav.zonesOn[1] and ns.db.nav.zonesOn[2],
            "click: Select all zones ticks them all")
        t:ok(buttons["Current zone only"] and pcall(buttons["Current zone only"].func), "click: Current zone only runs")
        t:ok(pcall(ns.commands.zones, "none") and next(ns.db.nav.zonesOn) == nil, "/flow zones none")
        t:ok(pcall(ns.commands.zones, "all"), "/flow zones all")
    end) end) end) end)
    ns.db.nav.zonesOn = was
    N.planDirty = true
end)

local taxiTestButton   -- (made once: a test may not make a new frame every run)
ns:Register("test", "flight map: your next step's flight master gets a ring", function(t)
    -- "it would be really nice if the target destination flight path that is
    -- recommended for my next flow item was somehow illuminated, circled"
    local TM = ns.taxiMark
    if not TM then t:ok(false, "TaxiMark.lua not loaded") return end
    local nodes = {
        { name = "Crossroads", cont = 1, wx = 0, wy = 0 },
        { name = "Camp Taurajo", cont = 1, wx = 2000, wy = 0 },
        { name = "Ratchet", cont = 1, wx = 0, wy = 1500 },
        { name = "Undercity", cont = 0, wx = 2100, wy = 0 },
    }
    local step = { cont = 1, wx = 2100, wy = 50 }
    local name, yd = TM.Pick(nodes, "Crossroads", step, function() return 60 end, 7, 0.8)
    t:eq(name, "Camp Taurajo", "the one that lands you nearest the step")
    t:ok(yd and yd > 100 and yd < 120, "and how far from it")
    t:eq(TM.Pick(nodes, "Camp Taurajo", step, function() return 60 end, 7, 0.8), nil, "standing at the nearest one: nothing to ring")
    t:eq(TM.Pick(nodes, "Crossroads", { cont = 1, wx = 300, wy = 0 }, function() return 120 end, 7, 0.8), nil,
        "a step a short walk from here: no flight")
    t:eq(TM.Pick(nodes, "Crossroads", { cont = 5, wx = 0, wy = 0 }), nil, "a step on another continent: none on this map")
    t:eq(TM.Pick(nodes, "Crossroads", nil), nil, "no step: nothing")
    t:eq(TM.Pick(nodes, "Crossroads", step, nil, 7), "Camp Taurajo", "flight time not known yet: the nearest still")
    t:eq(TM.Label("Turn in: The Ashenvale Hunt"), "Flow: Turn in: The Ashenvale Hunt", "the words under the ring")
    t:ok(#TM.Label(string.rep("word ", 20)) <= #"Flow: " + TM.LABEL_MAX, "a long step's name is cut")
    t:ok(pcall(TM.Button, "Crossroads"), "looking for the game's button runs with no flight map open")
    -- The ring itself, around a button of the tests' own.
    if not taxiTestButton then
        taxiTestButton = CreateFrame("Button", nil, UIParent)
        taxiTestButton:SetSize(16, 16)
        taxiTestButton:SetPoint("CENTER", UIParent, "CENTER", 0, -2000)   -- (off the screen)
    end
    taxiTestButton:Show()
    t:ok(pcall(TM.ShowAt, taxiTestButton, "Flow: test"), "ringing a button runs")
    local ring = TM._Ring()
    t:ok(ring and ring:IsShown() and not ring:IsMouseEnabled(), "the ring shows, and takes no clicks")
    t:ok(ring and ring.radius > 8, "around the button, not on it")
    TM.Hide()
    t:ok(ring and not ring:IsShown(), "and goes when the map closes")
    taxiTestButton:Hide()
end)

ns:Register("test", "zones: finish the selected zones first", function(t)
    -- "the option to finish the area you're in first should be finish the selected zones first"
    local N = ns.nav
    local sum = { { zone = 1, name = "The Barrens" }, { zone = 2, name = "Stonetalon Mountains" }, { zone = 3, name = "Ashenvale" } }
    -- (Picked one by one since 0.35.316: N.ZonesOnFor gives the zones a quick choice picks.)
    local on = N.ZonesOnFor("all", sum, 1)
    t:ok(on[1] and on[2] and on[3], "select all: every zone listed")
    t:eq(next(N.ZonesOnFor("none", sum, 1)), nil, "select none: none")
    on = N.ZonesOnFor("here", sum, 2)
    t:ok(on[2] and not on[1] and not on[3], "current zone only: the zone you're in")
    local keep = ns.db.nav.zonesOn
    ns.db.nav.zonesOn = { [1] = true, [2] = true }
    local picked = N.SelectedZones()
    ns.db.nav.zonesOn = keep
    t:ok(picked[1] and picked[2] and not picked[3], "the selection: the ticked zones")
    local names = { "The Barrens", "Stonetalon Mountains", "Ashenvale" }
    local nameOf = function(z) return names[z] end
    t:eq(N.PickedNote(picked, nameOf), "Finishing Stonetalon Mountains and The Barrens first", "the Flow Tracker's line, two zones")
    t:eq(N.PickedNote({ [1] = true, [2] = true, [3] = true }, nameOf), "Finishing your 3 zones first", "more: how many")
    t:eq(N.PickedNote({}, nameOf), nil, "none ticked: nothing")
    -- The split by a set of zones: steps in a ticked zone hold you; the rest wait.
    local zoneOf = function(map) return map end
    local function g(key, map) return { key = key, points = { { map = map } } } end
    local here, away = N.AreaSplit({ g("10:1", 1), g("11:1", 2), g("12:1", 3) }, { [1] = true, [2] = true }, nil, zoneOf)
    t:ok(here and here["10:1"] and here["11:1"] and away["12:1"], "ticked zones first, the rest after")
    t:eq(N.ZoneLine({ name = "Ashenvale", steps = 3, accept = 0, later = true }), "Ashenvale: 3 steps - after your zones", "an unticked zone says it comes after")
    -- The switch, from the Flow menu's Order and from Flow Settings.
    local was = ns.db.nav.zonesFirst
    with(N, "RequestCollect", function() end, function()
        N.SetZonesFirst(true)
        t:eq(N.ZonesFirstOn(), true, "on")
        N.SetZonesFirst(false)
        t:eq(N.ZonesFirstOn(), false, "off")
    end)
    ns.db.nav.zonesFirst = was
    N.planDirty = true
end)

-------------------------------------------------------------------------------
-- 0.35.294: the professions card doesn't pop up for a tier to train.
-------------------------------------------------------------------------------

ns:Register("test", "professions: the card pops for a main profession to learn or a changed suggestion, never for a tier to train", function(t)
    local P = ns.professions
    local train = { { name = "Skinning", kind = "train" }, { name = "Herbalism", kind = "train" } }
    local learn = { { name = "Skinning", kind = "train" }, { name = "Herbalism", kind = "learn" } }
    local cook = { { name = "Cooking", kind = "learn" } }
    local s = { level = 18, revealed = true, primaries = 2 }
    t:ok(not P.ShouldRemind("level", train, s), "two main professions, a tier to train: no pop-up")
    t:ok(not P.ShouldRemind("login", train, s), "nor at login")
    t:ok(not P.ShouldRemind("town", train, s), "nor at the trainer's town")
    t:ok(not P.ShouldRemind("change", learn, s), "you have two already: not for learning a third")
    t:ok(P.ShouldRemind("level", learn, { level = 18, revealed = true, primaries = 1 }), "one main profession, another to learn: it pops")
    t:ok(not P.ShouldRemind("level", cook, { level = 18, revealed = true, primaries = 0 }), "a secondary to learn: no pop-up (it's on the route)")
    t:ok(P.ShouldRemind("suggest", train, s), "Flow's suggestion changed: it pops")
    t:ok(not P.ShouldRemind("suggest", train, { level = 18, revealed = true, primaries = 2, remind = false }), "reminders off: never")
    t:eq(P.PopStep(learn, 1).name, "Herbalism", "the step that's worth the card")
    t:eq(P.PopStep(learn, 2), nil, "two main professions: none")
    t:eq(P.PopStep(train, 0), nil, "only tiers to train: none")
    t:eq(P.SuggestKey({ { name = "Skinning" }, { name = "Herbalism" }, { name = "Cooking" } }), "Herbalism+Skinning", "the suggestion as one word: the main ones, in order")
    t:ok(P.SuggestChanged("Herbalism+Skinning", "Alchemy+Herbalism"), "a different pair: changed")
    t:ok(not P.SuggestChanged("Herbalism+Skinning", "Herbalism+Skinning"), "the same pair: not changed")
    t:ok(not P.SuggestChanged(nil, "Herbalism+Skinning"), "never noted before: not a change")
end)

