-- 0.35.319: profession mobs get the profession's icon and a tooltip line;
-- Flow learns which spells take you out of a form.
-------------------------------------------------------------------------------

ns:Register("test", "marks: mobs a profession wants (Kodo Meat for Cooking) get its icon, a count and a tooltip line", function(t)
    -- "Can we put a different kind of icon above them that shows the profession that I need to kill them for?"
    local QM = ns.questMarks
    local COOK = "Interface\\Icons\\INV_Misc_Food_15"
    local goals = {
        { key = "farm:5467", prof = "Cooking", loot = "Kodo Meat", have = 0, need = 8, npcs = { "Barrens Kodo", "Kodo Calf" } },
        { key = "farm:5469", prof = "Cooking", loot = "Strider Meat", have = 1, need = 25, npcs = { "Greater Plainstrider" } },
        { key = "821:1", kind = "kill", npcs = { "Savannah Huntress" } },   -- a quest's: its own marks
        { key = "farm:1", npcs = { "No Profession" } },                     -- (no profession: nothing)
    }
    local mobs = QM.ProfMobs(goals, function(p) return p == "Cooking" and COOK or nil end)
    t:ok(mobs["barrens kodo"] and mobs["kodo calf"] and mobs["greater plainstrider"], "every mob that drops it, by name")
    t:eq(mobs["barrens kodo"].icon, COOK, "with the profession's icon")
    t:ok(not mobs["savannah huntress"] and not mobs["no profession"], "a quest's mobs and steps with no profession: not these")
    t:eq(mobs["greater plainstrider"].loot, "Strider Meat", "and what it drops")
    t:eq(QM.ProfMobs(goals, function() return nil end)["kodo calf"].icon, QM.PROF_FALLBACK, "a profession with no icon: the trainer's")
    t:eq(QM.TipLine(mobs["barrens kodo"]), "Flow: loot Kodo Meat for Cooking, 0 -> 8", "the tooltip's line")
    local tex, trim = QM.MarkTexture({ kind = "prof", icon = COOK })
    t:ok(tex == COOK and trim, "the nameplate shows the profession's icon, its edge trimmed")
    tex, trim = QM.MarkTexture({ kind = "kill" })
    t:ok(tex:find("RaidTargetingIcon_8", 1, true) ~= nil and not trim, "a quest kill keeps its skull")
    t:ok(QM.MarkTexture({ kind = "drop" }):find("AvailableQuestIcon", 1, true) ~= nil, "a quest-starting drop keeps its !")
    t:ok(select(1, QM.MarkTexture({ kind = "something new" })) ~= nil, "a kind with no picture still gets one")
    t:ok(pcall(QM.Lines), "/flow quest lists them")
end)

ns:Register("test", "forms: Flow learns which spells keep your form and which take you out of it", function(t)
    -- "Is there a clear way for me to know which ones will and will not change form back to human?"
    local FS = ns.formSpells
    if not FS then t:ok(false, "FormSpells.lua not loaded") return end
    local store = {}
    t:ok(FS.Note(store, "Regrowth", "Bear Form", false), "a heal that dropped Bear Form: noted")
    t:ok(not FS.Note(store, "Regrowth", "Bear Form", false), "the second time: nothing new")
    FS.Note(store, "Faerie Fire", "Bear Form", true)
    FS.Note(store, "Faerie Fire", "Cat Form", true)
    t:eq(FS.Words(store["Regrowth"]), "Flow: takes you out of Bear Form", "the tooltip: takes you out")
    t:eq(FS.Words(store["Faerie Fire"]), "Flow: keeps you in Bear Form and Cat Form", "keeps you in both")
    t:eq(FS.Words(nil, "Bear Form"), "Flow: a Bear Form ability (keeps you in it)", "a form's own ability")
    t:ok(FS.Words(nil):find("not seen", 1, true) ~= nil, "not seen yet: says so")
    FS.Note(store, "Regrowth", "Bear Form", true)
    t:eq(FS.Words(store["Regrowth"]), "Flow: keeps you in Bear Form", "seen the other way later: the latest wins")
    t:ok(FS.Shifts("DRUID") and not FS.Shifts("PALADIN"), "the druid shifts; the paladin's auras aren't forms to leave")
    t:eq(FS.FormAbilities("DRUID")["Maul"], "Bear Form", "Maul is a Bear Form ability (the class list)")
    -- The watching, with forms and times of the test's own (Flow's own store stood in for).
    local seen = {}
    with(ns, "Log", function() end, function()
    with(FS, "Store", function() return seen end, function()
        local keepP, keepD = FS.pending, FS.dropped
        FS.pending, FS.dropped = nil, nil
        FS.Sent("Healing Touch", "Bear Form", 100)
        FS.FormChanged("Bear Form", nil, 100.3)
        t:ok(seen["Healing Touch"] and seen["Healing Touch"].out["Bear Form"], "sent in Bear Form, the form drops: takes you out")
        FS.Sent("Demoralizing Roar", "Bear Form", 200)
        FS.Cast("Demoralizing Roar", "Bear Form", 200.1)
        t:ok(seen["Demoralizing Roar"] and seen["Demoralizing Roar"].keep["Bear Form"], "cast and still in Bear Form: keeps it")
        FS.FormChanged("Cat Form", nil, 300)
        FS.Sent("Rejuvenation", nil, 300.2)
        t:ok(seen["Rejuvenation"] and seen["Rejuvenation"].out["Cat Form"], "the form dropped just before the cast went out: takes you out")
        FS.FormChanged("Bear Form", nil, 400)
        FS.Sent("Wrath", nil, 405)
        t:eq(seen["Wrath"], nil, "you left the form long before: nothing learned")
        FS.Sent("Cancel Form", "Cat Form", 500)
        t:eq(FS.pending, nil, "shifting form itself isn't a spell that takes you out")
        FS.pending, FS.dropped = keepP, keepD
    end) end)
    t:ok(pcall(FS.Lines), "/flow forms lists them")
    t:ok(pcall(FS._addLine, GameTooltip, "Regrowth"), "the tooltip line adds")
end)

-------------------------------------------------------------------------------
-- 0.35.322: click flight masters on the map: where you can fly, the flight's time.
-------------------------------------------------------------------------------

ns:Register("test", "click: flight masters on the map: pick one for where you can fly, another for the flight", function(t)
    -- "if I click on one of the flight masters it should show me the route ... green ... red ... flight details as far as time"
    local MF = ns.mapFlights
    local sel = MF.Click({}, "Crossroads, The Barrens")
    t:eq(sel.from, "Crossroads, The Barrens", "the first click picks where you'd fly from")
    -- (0.35.328: one pick; the next click on any flight master clears it.)
    t:eq(MF.Click(sel, "Camp Taurajo, The Barrens").from, nil, "a click on another: nothing picked")
    t:eq(MF.Click(sel, "Crossroads, The Barrens").from, nil, "the same one clicked again: nothing picked")
    local have1 = { name = "Crossroads, The Barrens", kind = "have", cont = 1 }
    local have2 = { name = "Camp Taurajo, The Barrens", kind = "have", cont = 1 }
    local new = { name = "Bragok", npc = "Bragok", kind = "new", cont = 1 }
    local away = { name = "Undercity, Tirisfal", kind = "have", cont = 0 }
    t:ok(MF.CanFly(have1, have2), "both paths yours: you can fly it (green)")
    t:ok(not MF.CanFly(have1, new), "one not learned: you can't yet (red)")
    t:ok(not MF.CanFly(have1, away), "across the sea: no flight")
    local fmt = function(s) return s .. " s" end
    local text, can = MF.FlightText(have1, have2, 78, nil, fmt)
    t:ok(can and text == "Crossroads to Camp Taurajo: 78 s (your last flight)", "flown before: its time: " .. text)
    text = MF.FlightText(have1, have2, nil, 80, fmt)
    t:eq(text, "Crossroads to Camp Taurajo: about 80 s", "never flown: Flow's guess")
    t:eq(MF.FlightText(have1, have2, nil, nil, fmt), "Crossroads to Camp Taurajo: flight time not known yet", "no guess: says so")
    text, can = MF.FlightText(have1, new, nil, nil, fmt)
    t:ok(not can and text:find("learn the flight path at Bragok", 1, true) ~= nil, "can't yet: says where to learn it")
    t:eq(MF.Short("Crossroads, The Barrens"), "Crossroads", "short names")
    t:ok(ns.theme.flightCant and ns.theme.flightHave, "green and red come from the theme")
    -- Picking with the map closed runs (nothing drawn); clearing puts it back.
    local was = MF.sel
    with(ns, "Log", function() end, function()
        local ok, err = pcall(MF.Pick, "Crossroads, The Barrens")
        t:ok(ok and MF.sel.from == "Crossroads, The Barrens", "a pick runs" .. (ok and "" or (": " .. tostring(err))))
        t:ok(pcall(MF.ClearPick) and MF.sel.from == nil, "and clears")
    end)
    MF.sel = was
end)

-------------------------------------------------------------------------------
-- 0.35.323: the arrow's lines are stacked by length, away from the arrow.
-------------------------------------------------------------------------------

ns:Register("test", "arrow: its lines stack by length, the shortest next to the arrow, on the side with room", function(t)
    local N = ns.nav
    local long = "2166 yd ~10s (to the flight master: fly Thunder Bluff, Mulgore to Crossroads, The Barrens, 70 yd). Hearthstone (The Crossroads) is about 3 min quicker"
    t:ok(N.LongLine(long), "a long line is wrapped")
    t:ok(not N.LongLine("184 yd ~40s NE"), "a short one isn't")
    t:ok(not N.LongLine("|cffffd100" .. string.rep("x", N.SUB_LONG - 2) .. "|r"), "colour codes aren't letters")
    t:ok(not N.LongLine(nil) and not N.LongLine(""), "nothing: not long")
    local order = N.StackOrder({ { key = "title", w = 150, h = 12 }, { key = "sub", w = 60, h = 10 }, { key = "dungeon", w = 300, h = 16 } })
    t:ok(order[1].key == "sub" and order[2].key == "title" and order[3].key == "dungeon", "shortest first: it sits next to the arrow")
    local same = N.StackOrder({ { key = "b", w = 50, h = 10 }, { key = "a", w = 50, h = 10 } })
    t:eq(same[1].key, "a", "two as long as each other: always the same way round")
    t:eq(N.StackSide(900, 1000, 930, 60), "above", "top half, with room: above the arrow")
    t:eq(N.StackSide(970, 1000, 995, 60), "below", "top half, no room above: below, not off the screen")
    t:eq(N.StackSide(300, 1000, 330, 60), "below", "bottom half: below the arrow")
    local off, total = N.StackOffsets(order, 4, 2)
    t:ok(off.sub == 4 and off.title == 16 and off.dungeon == 30, "each line past the one before, a gap between")
    t:eq(total, 48, "and the stack's height")
    local f = N.arrowFrame
    if not (f and f.sub and f.text and f:IsVisible()) then t:ok(true, "(no arrow on screen)") return end
    local wasTitle, wasSub = f.text:GetText(), f.sub:GetText()
    f.text:SetText("Enter Wailing Caverns")
    f.sub:SetText("184 yd")
    f.stackSig = nil
    t:ok(pcall(N.LayoutLines, f), "the lines lay out")
    local side = f.stackSide
    t:ok(side == "above" or side == "below", "on one side: " .. tostring(side))
    local p1, r1 = f.sub:GetPoint(1)
    local p2, r2, _, _, y2 = f.text:GetPoint(1)
    local want = side == "above" and "BOTTOM" or "TOP"
    t:ok(p1 == want and p2 == want and r1 == f and r2 == f, "both lines hang from the arrow, on that side")
    local _, _, _, _, y1 = f.sub:GetPoint(1)
    t:ok(math.abs(y1) < math.abs(y2), "the short line is nearer the arrow than the step's name")
    f.sub:SetText(long)
    f.stackSig = nil
    N.LayoutLines(f)
    t:near(f.sub:GetWidth(), N.SUB_WIDTH, 0.5, "a long line is wrapped, not across the screen")
    _, _, _, _, y1 = f.sub:GetPoint(1)
    _, _, _, _, y2 = f.text:GetPoint(1)
    t:ok(math.abs(y1) > math.abs(y2), "and, being the longest, it's furthest from the arrow")
    if f.textHit then
        local hp = f.textHit:GetPoint(1)
        t:eq(hp, want, "the lines click like the arrow, on their side")
    end
    t:eq(N.LayoutLines(f), false, "nothing changed: nothing moved again")
    f.text:SetText(wasTitle or "")
    f.sub:SetText(wasSub or "")
    f.stackSig = nil
    N.LayoutLines(f)
end)

-------------------------------------------------------------------------------
-- 0.35.324: a button's small icons run toward the side of the screen it's on.
-------------------------------------------------------------------------------

ns:Register("test", "buttons: the small icons run left in the left half of the screen, right in the right half", function(t)
    t:eq(ns.SideFor(400, 1920), "left", "left half: out to the left")
    t:eq(ns.SideFor(1500, 1920), "right", "right half: out to the right")
    t:eq(ns.SideFor(960, 1920), "left", "dead centre: left, as it always was")
    t:eq(ns.SideFor(nil, 1920), "left", "not on screen yet: left")
    t:eq(ns.ButtonSide(nil), "left", "no button: left")
    -- What sat on the right swaps over, so nothing lies under the icons.
    local _, p, rp, x = ns.SwingPlace(false, "right")
    t:ok(p == "RIGHT" and rp == "LEFT" and x < 0, "icons to the right: the auto-attack badge on the left")
    _, p, rp, x = ns.SwingPlace(true, "right")
    t:ok(p == "BOTTOMRIGHT" and rp == "BOTTOMLEFT" and x < 0, "docked too")
    _, p, rp, x = ns.SwingPlace(false, "left")
    t:ok(p == "LEFT" and rp == "RIGHT" and x > 0, "icons to the left: the badge on the right, as before")
    local C, K = ns.cast, ns.careKeys
    local ap, arp, ax = C.AdvicePlace(true, "right")
    t:ok(ap == "RIGHT" and arp == "LEFT" and ax < 0, "the bar's advice mark swaps over with the key's name")
    ap, arp, ax = C.AdvicePlace(true, "left")
    t:ok(ap == "LEFT" and arp == "RIGHT" and ax > 0, "and is where it was on the left")
    t:eq(K.ColumnEdge(2, "left"), K.ColumnRight(2), "the self button's columns: as before to the left")
    t:eq(K.ColumnEdge(2, "right"), -K.ColumnRight(2), "the same steps the other way to the right")
    t:eq(K.ColumnCentre(3, "right"), -K.ColumnMiddle(3), "and the names over them")
    local icon = ns.rotation.icon
    if not (icon and icon.deck and icon.deck[1]) or InCombatLockdown() then t:ok(true, "(the target button isn't built, or a fight is on)") return end
    local was = icon.side or "left"
    ns.PlaceDeck(icon, "right")
    local dp, drel, drp, dx = icon.deck[1]:GetPoint(1)
    t:ok(dp == "BOTTOMLEFT" and drel == icon and drp == "BOTTOMRIGHT" and dx > 0, "to the right: the first icon off the right edge, bottoms level")
    local d2p, d2rel, d2rp = icon.deck[2]:GetPoint(1)
    t:ok(d2p == "BOTTOMLEFT" and d2rel == icon.deck[1] and d2rp == "BOTTOMRIGHT", "the next, smaller one further right")
    t:eq(icon.deck[1]:GetNumPoints(), 1, "one anchor each")
    ns.PlaceDeck(icon, "left")
    dp, drel, drp, dx = icon.deck[1]:GetPoint(1)
    t:ok(dp == "BOTTOMRIGHT" and drel == icon and drp == "BOTTOMLEFT" and dx < 0, "to the left: off the left edge")
    ns.PlaceDeck(icon, was)
    t:ok(type(ns.SelfSide()) == "string", "the self button knows its side: " .. tostring(ns.SelfSide()))
    t:ok(pcall(K.Apply), "the self button's icons place on that side without an error")
end)

