-- 0.35.325: from group to group in a quest's area.
-------------------------------------------------------------------------------

ns:Register("test", "route: in a quest's area the arrow leads from group to group, the nearest first, across steps", function(t)
    local H = ns.areaHop
    local steps = {
        { key = "1486:1", title = "Deviate Hides", points = {
            { wx = 0, wy = 0, cont = 1 }, { wx = 20, wy = 10, cont = 1 }, { wx = 30, wy = 0, cont = 1 },   -- one group
            { wx = 400, wy = 0, cont = 1 }, { wx = 420, wy = 15, cont = 1 },                                -- another
            { wx = 50, wy = 50, cont = 0 } } },                                                             -- another continent: left out
        { key = "962:1", title = "Serpentbloom", points = { { wx = 150, wy = 0, cont = 1 }, { wx = 160, wy = 20, cont = 1 } } },
    }
    local groups = H.Groups(steps, 1)
    t:eq(#groups, 3, "spots close together are one group; the other continent's are left out")
    t:eq(#groups[1].spots, 3, "the first group has its three spots")
    t:near(groups[1].x, 50 / 3, 0.01, "a group's middle is the middle of its spots")
    t:ok(groups[1].id ~= groups[2].id and groups[3].key == "962:1", "each group knows its step")
    t:eq(H.Inside(groups, 10, 5), groups[1], "standing among its spots: in that group")
    t:eq(H.Inside(groups, 250, 0), nil, "between groups: in none")
    t:near(H.YardsTo(groups[2], 400, 30), 25, 0.5, "how far a group is: to its nearest spot")
    -- From the first group: the nearest other one, whichever step it's for.
    local nextG, d = H.Next(groups, 10, 5, {}, 100, groups[1])
    t:ok(nextG == groups[3] and d < 200, "the next group is the nearest: another quest's, on the way")
    -- That one worked: on to the one after; the first rests too.
    local worked = { [groups[1].id] = 90, [groups[3].id] = 95 }
    nextG = H.Next(groups, 155, 10, worked, 100, groups[3])
    t:eq(nextG, groups[2], "a worked group is passed over")
    t:ok(H.Resting(worked, groups[1].id, 100) and not H.Resting(worked, groups[1].id, 90 + H.REST + 1), "it rests a few minutes, then counts again")
    t:eq((H.Next(groups, 10, 5, { [groups[2].id] = 99, [groups[3].id] = 99 }, 100, groups[1])), nil, "everything near worked: nothing to point at")
    t:eq((H.Next(groups, 5000, 5000, {}, 100, nil)), nil, "nothing within range: nothing offered")
    t:eq(H.Text("go", "Serpentbloom", 139.6), "Next group: 140 yd (Serpentbloom)", "the arrow's line names another step's group")
    t:eq(H.Text("go", nil, 80), "Next group: 80 yd", "the same step's next group: just how far")
    t:eq(H.Text("in", nil, nil, 140), "You're in the area. Next group: 140 yd", "in a group: where the next one is")
    t:eq(H.Text("in", "Serpentbloom", nil, nil), "In the area: Serpentbloom", "in another step's group: whose it is")
    t:eq(H.Text("in", nil, nil, nil), "You're in the area", "the only group: as it always read")
    -- The arrow only takes it for the step it was worked out for.
    local was = H.cur
    H.cur = { state = "go", key = "1486:1", wx = 1, wy = 2, d = 3, text = "x" }
    t:eq(ns.nav.Hop(nil, { goal = { key = "1486:1" } }), H.cur, "the arrow gets it for that step")
    t:eq(ns.nav.Hop(nil, { goal = { key = "other" } }), nil, "and not for another")
    H.cur = nil
    t:eq(ns.nav.Hop(nil, { goal = { key = "1486:1" } }), nil, "nothing worked out: the usual arrow")
    H.cur = was
    t:ok(pcall(H.Tick), "a look at where you are runs")
    t:ok(pcall(H.Lines), "/flow hop builds")
    local wasOn = ns.db.nav.areaHop
    ns.db.nav.areaHop = false
    t:ok(not H.On(), "it can be turned off")
    pcall(H.Tick)
    t:eq(H.cur, nil, "off: the ring and nothing more")
    ns.db.nav.areaHop = wasOn
end)

-------------------------------------------------------------------------------
-- 0.35.326: prowling, the key holds the opener; out of stealth, the form's own.
-------------------------------------------------------------------------------

ns:Register("test", "easy key: prowling in Cat Form it holds your opener, and the game moves it on when stealth breaks", function(t)
    local C = ns.cast
    t:eq(C.STEALTH_STATE, C.FORM_STATES + 1, "stealthed is one more state, past the forms")
    local forms = { { name = "Bear Form", index = 1 }, { name = "Cat Form", index = 3 } }
    local keys = {
        none = { key = "Wrath" },
        ["Bear Form"] = { key = "Maul" },
        ["Cat Form"] = { key = "Claw", ctrl = { "Ferocious Bite", "Rake" } },
        stealth = { form = "Cat Form", key = { "Ravage", "Pounce", "Shred", "Rake", "Claw" }, ctrl = { "Ferocious Bite", "Rake" } },
    }
    local known = { Wrath = true, Maul = true, Claw = true, Rake = true, Shred = true }
    local cond, plan = C.FormPlan(forms, keys, function(s) return known[s] == true end)
    t:eq(cond, "[form:1] 1; [form:3,stealth] " .. C.STEALTH_STATE .. "; [form:3] 3; 0", "stealthed in the form is asked before the form itself")
    t:eq(plan[C.STEALTH_STATE].key, "Shred", "the best opener you know")
    t:eq(plan[3].key, "Claw", "out of stealth: the form's own attack")
    t:eq(plan.stealthForm, 3, "and which form it belongs to")
    known.Ravage = true
    t:eq(select(2, C.FormPlan(forms, keys, function(s) return known[s] == true end))[C.STEALTH_STATE].key, "Ravage", "Ravage once you have it")
    -- At 20: no opener of its own yet, so the bleed first.
    local young = { Wrath = true, Claw = true, Rake = true }
    local _, p20 = C.FormPlan(forms, keys, function(s) return young[s] == true end)
    t:eq(p20[C.STEALTH_STATE].key, "Rake", "before Shred: Rake opens")
    t:eq(p20[C.STEALTH_STATE].ctrl, nil, "and isn't on a second press as well")
    -- A class that doesn't say so, or a form you don't have: nothing new.
    local plainKeys = { none = keys.none, ["Bear Form"] = keys["Bear Form"], ["Cat Form"] = keys["Cat Form"] }
    local plainCond, plainPlan = C.FormPlan(forms, plainKeys, function(s) return known[s] == true end)
    t:ok(plainCond == "[form:1] 1; [form:3] 3; 0" and plainPlan[C.STEALTH_STATE] == nil, "no stealth spells named: as before")
    local noCat, noCatPlan = C.FormPlan({ { name = "Bear Form", index = 1 } }, keys, function(s) return known[s] == true end)
    t:ok(noCat == "[form:1] 1; 0" and noCatPlan[C.STEALTH_STATE] == nil, "no Cat Form yet: nothing about stealth")
    -- The handler is told about that state like any form's.
    t:ok(C._FormSnippet():find("key-", 1, true) ~= nil, "the handler reads the state's key")
    t:ok(type(C.StealthReady()) == "boolean", "a class can ask whether the hand-over is set up")
    local druid = ns:Get("rotation", "DRUID")
    local ok, k = pcall(druid.formKeys, ns.rotation)
    t:ok(ok and k.stealth and k.stealth.form == "Cat Form" and k.stealth.key[1] == "Ravage", "the druid names its openers, best first")
    t:ok(pcall(C.FormLines), "/flow key test lists it")
    -- The pull's spell is asked without an error whatever form you're in.
    t:ok(pcall(druid.pullLock, nil, ns.rotation), "the druid's spell for the pull is worked out")
end)

-------------------------------------------------------------------------------
-- 0.35.327: alignment lines while moving Flow's buttons; the auto-attack
-- badge's picture and glow; no "Attack" while prowling.
-------------------------------------------------------------------------------

ns:Register("test", "move: a button dragged near a line-up shows the line and settles on it", function(t)
    local G = ns.guides
    local xs, ys = G.Marks({ l = 100, r = 140, b = 200, t = 240 })
    t:ok(xs[1] == 100 and xs[2] == 120 and xs[3] == 140 and ys[1] == 200 and ys[2] == 220 and ys[3] == 240, "left, middle, right; bottom, middle, top")
    local d, at = G.Nearest({ 100, 120, 140 }, { 500, 125 }, 8)
    t:ok(d == 5 and at == 125, "the middle is 5 from a line: that far to move, onto it")
    t:eq((G.Nearest({ 100, 120, 140 }, { 500 }, 8)), nil, "nothing near: nothing")
    d = G.Nearest({ 100, 120, 140 }, { 104, 119 }, 8)
    t:eq(d, -1, "two near: the nearer wins")
    local screen = { w = 1000, h = 800 }
    -- Middle of the screen, both ways.
    local s = G.Snap({ l = 477, r = 517, b = 383, t = 423 }, screen, {})
    t:ok(s.dx == 3 and s.x == 500 and s.dy == -3 and s.y == 400, "near the middle of the screen: onto it, both ways")
    -- On top of another button: its bottom on the other's top, middles level.
    local other = { l = 300, r = 340, b = 100, t = 140 }
    s = G.Snap({ l = 298, r = 338, b = 144, t = 184 }, screen, { other })
    t:ok(s.dx == 2 and s.dy == -4 and s.y == 140, "set on top of the other: it settles on its top edge, edges level")
    -- Beside it: left edge to the other's right edge, tops level.
    s = G.Snap({ l = 345, r = 385, b = 103, t = 143 }, screen, { other })
    t:ok(s.dx == -5 and s.x == 340 and s.dy == -3, "beside it: edge to edge, level")
    -- Far from everything: left where it's dropped.
    s = G.Snap({ l = 50, r = 90, b = 600, t = 640 }, screen, { other })
    t:ok(s.dx == 0 and s.dy == 0 and s.x == nil and s.y == nil, "near nothing: no line, no move")
    t:eq(G.RectOf(nil), nil, "no frame: no rectangle")
    -- A drag on a frame of our own: the lines come up, the release settles it.
    local wasOn = ns.db.settings and ns.db.settings.moveGuides
    ns.db.settings = ns.db.settings or {}
    ns.db.settings.moveGuides = true
    local f = CreateFrame("Frame", nil, UIParent)
    f:SetSize(40, 40)
    local cx, cy = UIParent:GetWidth() / 2, UIParent:GetHeight() / 2
    f:SetPoint("CENTER", UIParent, "BOTTOMLEFT", cx + 4, cy + 300)
    f:Show()
    t:ok(G.Start(f), "a drag begins: the lines watch it")
    local host = G._Host()
    t:ok(host and host:IsShown(), "their frame is up")
    local now = G.Now(f)
    t:ok(now and now.x ~= nil and now.dx ~= 0 and math.abs(now.dx) <= G.SNAP, "4 off the screen's middle: a line-up is within reach (" .. tostring(now and now.dx) .. ")")
    pcall(G.Draw, now)
    t:ok(host.v:IsShown(), "the upright line shows")
    local dx = G.Drop(f)
    t:ok(now and math.abs(dx - now.dx) < 0.6 and not host:IsShown(), "let go: it settles by that much, and the lines are put away")
    t:near((f:GetCenter()), cx + 4 + (now and now.dx or 0), 0.6, "its middle on the line")
    ns.db.settings.moveGuides = false
    t:ok(not G.Start(f), "switched off: no lines")
    ns.db.settings.moveGuides = wasOn
    f:Hide()
end)

ns:Register("test", "target button: the auto-attack badge wears your form's attack or your weapon, and glows softly when on", function(t)
    t:eq(ns.SwingPicture("paw", "staff"), "paw", "the game's own picture for Attack in your shape")
    t:eq(ns.SwingPicture(nil, "staff"), "staff", "the game has none: your weapon")
    t:eq(ns.SwingPicture(nil, nil), nil, "neither known: left as it is")
    local r, g, b, a = ns.QualityColor(2, { [2] = { r = 0.1, g = 1, b = 0 } })
    t:ok(r == 0.1 and g == 1 and b == 0 and a == 1, "the edge: the colour of your weapon's quality")
    t:eq(select(4, ns.QualityColor(nil, {})), 0, "no weapon: no edge")
    t:ok(ns.SwingPulses("on") and not ns.SwingPulses("off") and not ns.SwingPulses(nil), "its ring pulses only while auto attack is on")
    t:ok(ns.SWING_RING > 2, "and stands out past the weapon-coloured edge")
    t:eq(ns.AttackPicture("bar", "spell"), "bar", "Attack on a bar: exactly the picture the action bar shows")
    t:eq(ns.AttackPicture(nil, "spell"), "spell", "not on a bar: the spell's own")
    t:eq(ns.AttackPicture(nil, nil), nil, "neither: none")
    t:ok(pcall(ns.AttackTexture, GetTime()), "the game is asked for Attack's picture without an error")
    t:eq(ns:Get("rotation", "DRUID").swingSpell, nil, "the druid no longer lends Claw's or Maul's picture (it was the target button's own)")
    local icon = ns.rotation.icon
    if not (icon and icon.swing) then t:ok(true, "(the target button isn't built yet)") return end
    t:ok(icon.swing.glow and icon.swing.edge, "the badge has its ring and its edge")
    t:ok(icon.swing.glow:IsShown() == (icon.swingState == "on"), "the ring is there only while auto attack is on")
    t:ok(ns.pulse.Has(icon.swing.glow) == (icon.swingState == "on"), "and pulses on Flow's one beat, with the other marks")
    t:near(icon.swing.tex:GetAlpha(), 1, 0.01, "the picture itself doesn't blink")
end)

ns:Register("test", "druid: prowling with an enemy targeted, the key doesn't say Attack", function(t)
    -- (Read from the file's own list: the two "start attacking" entries ask about stealth.)
    local druid = ns:Get("rotation", "DRUID")
    t:ok(druid ~= nil, "the druid's rotation is there")
    local stealthedNow = false
    if IsStealthed then
        local ok, v = pcall(IsStealthed)
        stealthedNow = ok and ns.api.Safe(v) == true
    end
    local cur = ns.rotation.current
    if stealthedNow and cur then
        t:ok(cur.spell ~= "Attack" and cur.spell ~= "Auto Attack", "prowling now: the icon isn't Attack (" .. tostring(cur.spell) .. ")")
    else
        t:ok(true, "(not prowling now: checked when you are)")
    end
end)

-------------------------------------------------------------------------------
-- 0.35.328: flight masters on the map: one pick, point at a line for its
-- flight's time; right-click again takes the waypoint off.
-------------------------------------------------------------------------------

ns:Register("test", "click: flight masters on the map: one pick, the next click clears; a line near the mouse says its flight", function(t)
    local MF = ns.mapFlights
    local sel = MF.Click({}, "Crossroads, The Barrens")
    t:eq(sel.from, "Crossroads, The Barrens", "a click picks one")
    sel = MF.Click(sel, "Ratchet, The Barrens")
    t:ok(sel.from == nil and sel.to == nil, "the next click, on any of them, clears: never two picked")
    t:eq(MF.Click({}, nil).from, nil, "a click on nothing: nothing")
    -- Which line the mouse is near.
    t:near(MF.SegDist(5, 3, 0, 0, 10, 0), 3, 0.001, "beside a line: straight across to it")
    t:near(MF.SegDist(-4, 3, 0, 0, 10, 0), 5, 0.001, "past its end: to the end")
    t:near(MF.SegDist(2, 2, 7, 7, 7, 7), 7.071, 0.01, "a line with no length: to its point")
    local lines = { { name = "Ratchet", ax = 0, ay = 0, bx = 100, by = 0 }, { name = "Camp Taurajo", ax = 0, ay = 0, bx = 0, by = 100 } }
    t:eq(MF.LineAt(lines, 60, 6, 14), "Ratchet", "near the line to Ratchet: that one")
    t:eq(MF.LineAt(lines, 5, 60, 14), "Camp Taurajo", "near the other: the other")
    t:eq(MF.LineAt(lines, 60, 60, 14), nil, "between them, near neither: none")
    t:eq(MF.LineAt(lines, 3, 2, 14), "Ratchet", "by the picked one, where they all meet: the nearest")
    t:ok(MF.LINE_BOLD > MF.LINE_THIN and MF.LINE_THIN >= 2, "the lines are bold enough to see, the one you point at bolder")
    t:ok(pcall(MF.HoverTick), "looking for the line under the mouse runs with nothing drawn")
    -- Right-click: a waypoint on it; right-click again: off.
    local pin = { name = "Crossroads, The Barrens", npc = "Devrak", kind = "have", map = 1413, x = 0.515, y = 0.303 }
    t:ok(MF.WaypointOn({ map = 1413, x = 0.2, y = 0.2, note = "Devrak (flight master)" }, pin), "your waypoint is the one set on this flight master (by its note)")
    t:ok(MF.WaypointOn({ map = 1413, x = 0.515, y = 0.303 }, pin, { map = 1413, x = 0.515, y = 0.303 }), "or by its place")
    t:ok(not MF.WaypointOn({ map = 1413, x = 0.7, y = 0.7, note = "My spot" }, pin, { map = 1413, x = 0.515, y = 0.303 }), "a waypoint somewhere else isn't")
    t:ok(not MF.WaypointOn(nil, pin), "no waypoint: no")
    local keepW, set, cleared, wp = ns.waypoint, 0, 0, nil
    ns.waypoint = {
        Get = function() return wp end,
        Set = function(_, map, x, y, note) set = set + 1; wp = { map = map, x = x, y = y, note = note } end,
        Clear = function() cleared = cleared + 1; wp = nil end,
    }
    local ok1, r1, ok2, r2
    with(ns, "Print", function() end, function()
        ok1, r1 = pcall(MF.RightClick, pin)
        ok2, r2 = pcall(MF.RightClick, pin)
    end)
    ns.waypoint = keepW
    t:ok(ok1 and r1 == "set" and set == 1, "a right click points Flow's arrow there")
    t:ok(ok2 and r2 == "cleared" and cleared == 1 and set == 1, "a right click on it again takes the waypoint off")
end)

-------------------------------------------------------------------------------
-- 0.35.329: the planner visits a kill or collect step group by group.
-------------------------------------------------------------------------------

ns:Register("test", "route: a kill step with several groups of spots is planned as a visit to each, other steps in between", function(t)
    local P = ns.planner
    local function pt(x, y) return { wx = x, wy = y, cont = 1, map = 1 } end
    -- Spots into groups, nearest first.
    local groups = P.Groups({ pt(0, 0), pt(10, 0), pt(500, 0), pt(30, 10), pt(510, 0) })
    t:eq(#groups, 2, "spots close together are one group")
    t:ok(#groups[1].points == 3 and #groups[2].points == 2, "each with its spots")
    t:near(groups[2].x, 505, 0.01, "a group's middle")
    -- How many visits a step gets.
    t:eq(P.VisitsFor(10, 5), 3, "ten to get: three groups (never more)")
    t:eq(P.VisitsFor(6, 5), 2, "six to get: two")
    t:eq(P.VisitsFor(3, 5), 1, "three to get: one group will do")
    t:eq(P.VisitsFor(nil, 4), 2, "not known how many: two")
    t:eq(P.VisitsFor(10, 1), 1, "all its spots in one group: one visit")
    t:eq(P.VisitsFor(10, 2), 2, "never more visits than groups")
    -- What depends on a step waits for its last visit; your first pick goes by its first.
    local a1 = { key = "1:1", goal = { key = "1:1" } }
    local a2 = { key = "1:1", goal = a1.goal }
    local b = { key = "2:1", goal = { key = "2:1" } }
    local turnIn = { key = "1:done", goal = { key = "1:done", deps = { "1:1" } } }
    t:ok(P._valid({ a1, b, a2, turnIn }, {}), "the turn-in after the last visit: fine")
    t:ok(not P._valid({ a1, turnIn, b, a2 }, {}), "the turn-in before the last visit: not allowed")
    t:ok(P._valid({ a1, b, a2 }, { first = "1:1" }), "your first pick is first by its first visit")
    t:ok(not P._valid({ b, a1, a2 }, { first = "1:1" }), "and not when something comes before it")
    -- A whole plan: two groups of boars 500 yards apart, another quest's spot between them.
    local wasOn = ns.db.nav.groupVisits
    ns.db.nav.groupVisits = true
    local boars = { key = "1:1", area = true, left = 8, title = "Boars", points = { pt(0, 0), pt(10, 0), pt(500, 0), pt(510, 0) } }
    local herbs = { key = "2:1", title = "A crate", points = { pt(250, 0) } }
    local hand = { key = "1:done", title = "Turn in", points = { pt(520, 0) }, deps = { "1:1" } }
    local me = pt(-50, 0)
    local ok, plan = pcall(P.Plan, P, me, { boars, herbs, hand }, {})
    t:ok(ok and plan ~= nil, "the plan is made" .. (ok and "" or (": " .. tostring(plan))))
    if ok and plan then
        t:eq(#plan, 3, "still one line a step")
        t:ok(plan[1].goal == boars and plan[2].goal == herbs and plan[3].goal == hand, "the boars (first group), the crate on the way, then the turn-in")
        t:ok(plan[1].visits and #plan[1].visits == 2 and plan[1].visits[2].wx >= 500, "the boars' second group is a visit of its own, after the crate")
        t:eq(#plan.hops, 2, "the groups, in the order planned, for the arrow")
        t:ok(plan.hops[1].wx < 100 and plan.hops[2].wx > 400, "near group first, far group second")
        t:near(plan[3].cum, 570, 5, "the turn-in's distance counts every visit before it")
        t:near(plan[2].cum, 300, 5, "the crate comes between the two groups")
    end
    -- Three to get: one visit, as it always was.
    boars.left = 3
    local ok1, one = pcall(P.Plan, P, me, { boars, herbs, hand }, {})
    t:ok(ok1 and one and #one.hops == 0 and one[1].visits == nil, "few left: one visit, nothing split")
    -- Switched off (or asked not to): one spot a step.
    boars.left = 8
    local ok2, plain = pcall(P.Plan, P, me, { boars, herbs, hand }, { groups = false })
    t:ok(ok2 and plain and #plain == 3 and #plain.hops == 0, "a plan asked for without visits has none")
    ns.db.nav.groupVisits = false
    local ok3, off = pcall(P.Plan, P, me, { boars, herbs, hand }, {})
    t:ok(ok3 and off and #off.hops == 0 and not P.GroupsOn(), "switched off: none")
    ns.db.nav.groupVisits = wasOn
    -- The arrow takes the plan's order of groups.
    local H = ns.areaHop
    local list = H.Groups({ { key = "1:1", title = "Boars", points = { pt(0, 0), pt(10, 0), pt(500, 0), pt(510, 0) } },
                            { key = "3:1", title = "Wolves", points = { pt(40, 80) } } }, 1)
    local hops = { { key = "1:1", wx = 5, wy = 0 }, { key = "1:1", wx = 505, wy = 0 } }
    local nextG = H.Planned(list, hops, 5, 0, {}, 100, list[1])
    t:ok(nextG == list[2], "in the first group: the plan's next group, though another quest's is nearer")
    t:eq((H.Planned(list, hops, 5, 0, { [list[2].id] = 99 }, 100, list[1])), nil, "the plan's groups all worked: none (the nearest is used instead)")
    t:eq((H.Planned(list, nil, 5, 0, {}, 100, list[1])), nil, "no plan: none")
end)

-------------------------------------------------------------------------------
-- 0.35.330: the alignment lines only use what's on screen and stays put, and
-- show what they line up with.
-------------------------------------------------------------------------------

ns:Register("test", "move: a docked partner is never lined up with; a line to another thing runs from the button to it", function(t)
    local G = ns.guides
    t:eq(G.Partner("FlowCastButton", false), "FlowBuffButton", "on their own: the target button may line up with the self button")
    t:eq(G.Partner("FlowBuffButton", false), "FlowCastButton", "and the other way round")
    t:eq(G.Partner("FlowCastButton", true), nil, "docked: the self button moves with it, so it's no guide (it always 'lined up')")
    t:eq(G.Partner("FlowBuffButton", true), nil, "docked, the other way: the same")
    t:eq(G.Partner("FlowZoneNote", false), nil, "something else dragged: neither")
    local screen = { w = 1000, h = 800 }
    -- The docked case that went wrong: with no partner, the pair lines up with the screen's middle again.
    local s = G.Snap({ l = 477, r = 517, b = 100, t = 140 }, screen, {})
    t:ok(s.dx == 3 and s.x == 500 and s.xSrc == nil, "near the middle of the screen: onto it (a line right across)")
    -- With the partner wrongly counted (its middle on the dragged one's), the screen's middle lost.
    local partner = { l = 477, r = 517, b = 40, t = 80 }
    local wrong = G.Snap({ l = 477, r = 517, b = 100, t = 140 }, screen, { partner })
    t:ok(wrong.dx == 0 and wrong.xSrc == partner, "(what happened before: its own partner was the nearest line-up, at no distance)")
    -- What a line belongs to.
    local other = { l = 300, r = 340, b = 100, t = 140, name = "FlowBuffButton" }
    s = G.Snap({ l = 298, r = 338, b = 144, t = 184 }, screen, { other })
    t:ok(s.xSrc == other and s.ySrc == other and s.rect ~= nil, "a line to the other button knows it's that button's")
    local lo, hi = G.Span(144, 184, 100, 140, 14)
    t:ok(lo == 86 and hi == 198, "the line runs from the one to the other and a little past, not across the screen")
    -- The arrow offers its middle only (its frame is a box you can't see).
    local arrow = { l = 480, r = 536, b = 700, t = 756, middle = true, name = "FlowNavArrow" }
    s = G.Snap({ l = 479, r = 519, b = 300, t = 340 }, { w = 2000, h = 800 }, { arrow })
    t:ok(s.x == nil and s.dx == 0, "level with the arrow frame's left edge: nothing (only its middle counts)")
    s = G.Snap({ l = 485, r = 525, b = 300, t = 340 }, { w = 2000, h = 800 }, { arrow })
    t:ok(s.x == 508 and s.dx == 3 and s.xSrc == arrow, "its middle near the arrow's middle: onto it")
    -- Only what's really on screen.
    local hidden = CreateFrame("Frame", nil, UIParent)
    hidden:SetSize(20, 20); hidden:SetPoint("CENTER"); hidden:Hide()
    t:eq(G.RectOf(hidden), nil, "a hidden frame is no guide")
    hidden:Show()
    t:ok(G.RectOf(hidden) ~= nil, "a shown one is")
    hidden:Hide()
    t:ok(pcall(G.Others, _G.FlowCastButton), "what the target button may line up with is worked out")
    -- Drawing a line-up of each kind.
    local wasOn = ns.db.settings and ns.db.settings.moveGuides
    ns.db.settings = ns.db.settings or {}
    ns.db.settings.moveGuides = true
    local f = CreateFrame("Frame", nil, UIParent)
    f:SetSize(40, 40); f:SetPoint("CENTER", UIParent, "BOTTOMLEFT", 300, 300); f:Show()
    G.Start(f)
    local host = G._Host()
    local okD = pcall(G.Draw, { dx = 2, dy = -4, x = 300, y = 140, xSrc = other, ySrc = other, rect = { l = 298, r = 338, b = 144, t = 184 } })
    t:ok(okD and host.v:IsShown() and host.h:IsShown(), "both lines draw")
    t:ok(host.box[1][1]:IsShown() and not host.box[2][1]:IsShown(), "and what they line up with is outlined, once")
    okD = pcall(G.Draw, { dx = 3, dy = 0, x = 500, rect = { l = 477, r = 517, b = 100, t = 140 } })
    t:ok(okD and host.v:IsShown() and not host.h:IsShown() and not host.box[1][1]:IsShown(), "the screen's middle: one line, nothing outlined")
    pcall(G.Draw, nil)
    t:ok(not host.v:IsShown() and not host.h:IsShown(), "near nothing: no lines")
    G.Drop(f)
    ns.db.settings.moveGuides = wasOn
    f:Hide()
end)

-------------------------------------------------------------------------------
-- 0.35.331: "Show on map" for a step in another zone: a second click goes to
-- the map's own bar of parent maps.
-------------------------------------------------------------------------------

ns:Register("test", "click: Show on map, a step in another zone: the second click zooms the game's map out to where it shows", function(t)
    local O = ns.mapOpen
    -- Kalimdor (1414) holds The Barrens (1413) and Stonetalon (1442); Azeroth (947) holds Kalimdor.
    local parents = { [1413] = 1414, [1442] = 1414, [1414] = 947, [1420] = 1415, [1415] = 947, [947] = 946 }
    local function info(id) return parents[id] and { parentMapID = parents[id] } or { parentMapID = 0 } end
    local lineage = O.Ancestors(1442, info)
    t:ok(lineage[1] == 1442 and lineage[2] == 1414 and lineage[3] == 947, "a map and its parents, nearest first")
    t:eq(#O.Ancestors(nil, info), 0, "no map: none")
    t:ok(#O.Ancestors(5, function() return { parentMapID = 5 } end) == 1, "a map that names itself as its parent doesn't loop")
    -- The bar while the map shows The Barrens: World, Kalimdor, The Barrens.
    local home, kalimdor, barrens = { id = 947 }, { data = { id = 1414 } }, { id = 1413 }
    local bar = { home, kalimdor, barrens }
    local b, id = O.NavPick(1442, 1413, bar, info)
    t:ok(b == kalimdor and id == 1414, "a step in Stonetalon, the map on The Barrens: the bar's Kalimdor")
    t:eq((O.NavPick(1413, 1413, bar, info)), nil, "a step on the map shown: nothing to turn")
    t:eq((O.NavPick(1442, 1414, { home, kalimdor }, info)), nil, "the map already on the continent the step is on: nothing to turn")
    b, id = O.NavPick(1420, 1413, bar, info)
    t:ok(b == home and id == 947, "a step across the sea: all the way out, to the world")
    b = O.NavPick(9999, 1413, bar, info)
    t:eq(b, home, "a map the bar knows nothing of: all the way out")
    t:eq((O.NavPick(1442, 1413, {}, info)), nil, "no bar: nothing")
    t:eq((O.NavPick(nil, 1413, bar, info)), nil, "a step with no map: nothing")
    t:eq(O.FollowText("map", "Kalimdor"), "Click again: zoom the map out to Kalimdor", "the words while the second click is ready")
    t:eq(O.FollowText("log"), "Click again: open this quest in the log", "and for the quest log's link")
    t:eq(O.NavText("Kalimdor", "The Barrens", "Kalimdor"), "a click passed to the map's bar (Kalimdor): the map turned from The Barrens to Kalimdor", "what the click did is kept for the diagnostics")
    t:ok(O.NavText("Kalimdor", "The Barrens", "The Barrens"):find("stayed on The Barrens", 1, true) ~= nil, "also when it did nothing")
    t:ok(pcall(O.NavTarget, 1442), "asking the game's bar doesn't error")
    t:ok(pcall(O.Lines), "/flow buttons lists it")
    -- The step card hands the link the step's map.
    local N = ns.nav
    t:eq(N.GoalMap({ key = "x", points = { { map = 1442 } } }), 1442, "a step's map: its first spot's, when the route has no place for it")
    t:eq(N.GoalMap(nil), nil, "no step: none")
end)

