-------------------------------------------------------------------------------
-- 0.35.341: Flow Banker's "To sell": what the seller takes, what to take out
-- of the bank to sell; why Flow keeps a thing; undoing "bought back".
-------------------------------------------------------------------------------

ns:Register("test", "banker: To sell lists what leaves your bags, and what's in the bank that Flow would sell", function(t)
    local B = ns.banker
    local bags = B.SellRows({
        { id = 1, name = "Broken Fang", action = "sell", reason = "junk", count = 3, stacks = 1 },
        { id = 2, name = "Small Lustrous Pearl", action = "ah", reason = "worth more at auction", count = 1 },
        { id = 3, name = "Light Leather", action = "keep", reason = "for Leatherworking", count = 20 },
        { id = 4, name = "Worn Axe", action = "equip", reason = "better", count = 1 },
    })
    t:eq(#bags, 2, "what's sold or auctioned, not what's kept or worn")
    t:eq(bags[1].name, "Broken Fang", "in the order given")

    local verdicts = {
        [2589] = { action = "sell", reason = "your First Aid is past it", item = { classID = 7, name = "Linen Cloth" } },
        [2318] = { action = "keep", reason = "for Leatherworking", item = { classID = 7, name = "Light Leather" } },
        [5498] = { action = "ah", reason = "worth more at auction", item = { classID = 7, name = "Small Lustrous Pearl" } },
        [100]  = { action = "sell", reason = "not for you", item = { classID = 4, name = "Old Helm" } },
        [200]  = { action = "sell", reason = "no quest uses it", item = { classID = 12, name = "Odd Relic" } },
        [300]  = { action = "sell", reason = "past it", item = { classID = 7, name = "Coarse Thread" } },
    }
    local items = { [2589] = 40, [2318] = 12, [5498] = 1, [100] = 1, [200] = 1, [300] = 5, [999] = 2 }
    local out = B.TakeOutRows(items, function(id) return verdicts[id] end, { [300] = "bank" })
    t:eq(#out, 2, "only what Flow would sell or auction: not kept things, gear, quest items, your own 'bank it', or things not loaded")
    t:eq(out[1].name, "Linen Cloth", "by name")
    t:eq(out[1].count, 40, "with how many the bank holds")
    t:eq(out[2].action, "ah", "the auction house counts too")
    t:eq(#B.TakeOutRows(nil, function() return nil end, nil), 0, "a bank Flow hasn't seen: nothing")

    local note, lines = B.SellLines(bags, out, false)
    t:eq(#lines, 4, "a line each: bags first, then the bank")
    t:ok(lines[1]:find("3 x Broken Fang", 1, true) and lines[1]:find("(vendor: junk)", 1, true), "what, how many, where it goes and why")
    t:ok(lines[3]:find("In your bank:", 1, true) and lines[3]:find("40 x Linen Cloth", 1, true), "the bank's are marked")
    t:ok(note:find("2 thing(s) in your bags", 1, true) and note:find("2 more in your bank", 1, true) and note:find("at a bank, Take out", 1, true),
        "the line above counts both and says where Take out works")
    t:ok((B.SellLines(bags, out, true)):find("Take out brings them", 1, true), "at the bank it just says Take out")
    t:ok((B.SellLines({}, {}, false)):find("Nothing to sell", 1, true), "nothing either way: said so")
    t:ok(not (B.SellLines(bags, {}, false)):find("in your bank", 1, true), "nothing in the bank to sell: the bank isn't mentioned")

    t:eq(B.TakeCount(5, 3), 3, "only as many stacks as your bags have room for")
    t:eq(B.TakeCount(5, 0), 0, "full bags: none")
    t:eq(B.TakeCount(5, nil), 5, "room unknown: all (the game refuses what doesn't fit)")

    t:eq(B.StepText(4, 0), "Bank: put 4 stack(s) away", "the route's step, as before")
    t:eq(B.StepText(4, 2), "Bank: put 4 stack(s) away, take 2 thing(s) out to sell", "with things to take out")
    t:eq(B.StepText(0, 2), "Bank: take 2 thing(s) out to sell", "only things to take out")

    t:ok(pcall(B.TakeOut, true), "reading your own bank doesn't error")
    t:eq(type(B.TakeOut()), "table", "and gives a list")
    t:eq(#ns.skillPlan.BankSlotsWith({}), 0, "nothing wanted: no bank slots")
    local okL, l = pcall(B.Lines)
    t:ok(okL and type(l) == "table", "/flow banker lists it" .. (okL and "" or (": " .. tostring(l))))
end)

ns:Register("test", "banker: a thing's tooltip says why Flow keeps it; a bought-back one can be let go", function(t)
    local B, D = ns.banker, ns.disposition
    local cells = B.PutCells({ { id = 2934, name = "Ruined Leather Scraps", action = "keep", rule = "neverSell",
        reason = "you bought it back before", kind = "Trade Goods", count = 7 } }, {}, {})
    t:eq(cells[1].reason, "you bought it back before", "the cell carries Flow's reason")
    t:eq(cells[1].rule, "neverSell", "and the rule")
    local why = B.WhyLines(cells[1])
    t:eq(why[1], "Flow keeps it: you bought it back before.", "the tooltip says why it's kept")
    t:ok(why[2] and why[2]:find("Alt-click", 1, true), "and how to undo a buy-back")
    t:eq(#B.WhyLines({ reason = "for First Aid: Wool Bandage", rule = "professionMaterial" }), 1, "another reason: just the reason")
    t:eq(#B.WhyLines({}), 0, "no reason known: no line")

    local never = ns.db.sell.never
    local id = 987654321
    local had = never[id]
    never[id] = true
    t:ok(D.Forget(id), "forgetting one that's on the list")
    t:eq(never[id], nil, "takes it off")
    t:ok(not D.Forget(id), "one that isn't on it: nothing to do")
    never[id] = had
    t:eq(D:DecideId(-5), nil, "an item the game doesn't know: no verdict, no error")
    local v = D:DecideId(6948)   -- (the hearthstone: the game always has it loaded)
    t:ok(v == nil or (type(v.action) == "string" and v.item and v.item.away), "something not in your bags gets a verdict by its ID")
end)

ns:Register("test", "click: Flow Banker's To sell view opens, and Alt-click lets a bought-back thing go", function(t)
    local B = ns.banker
    if InCombatLockdown() then return end
    local was = B._Frame() and B._Frame():IsShown()
    local view, offset = B.view, B.offset
    local ok, err = pcall(B.Show, B, "sell")
    t:ok(ok and B.view == "sell", "the view opens" .. (ok and "" or (": " .. tostring(err))))
    local f = B._Frame()
    t:ok(f and f.tabs.sell and f.tabs.sell:IsShown(), "it has its word under the title")
    t:ok(f and f.tabs.prices:GetRight() == nil or f.tabs.prices:GetRight() <= f:GetRight() + 1, "the four words fit the window")
    t:ok(f and f.all:IsShown() and not f.search:IsShown(), "the choices button, no search box")
    t:eq(f and f.go:IsShown(), (B.takeCount or 0) > 0, "Take out shows only with something in the bank to sell")
    if f and f.go:IsShown() then
        t:eq(f.go:GetText(), B.AtBank() and "Take out" or "At a bank", "and says where it works")
        t:eq(f.go:IsEnabled(), B.AtBank(), "enabled at a bank")
    end
    if not B.AtBank() then
        t:ok(pcall(B.GoClick, B), "the button's click runs away from a bank")
        t:eq(B:Withdraw(), 0, "and moves nothing there")
    end
    -- Alt-click: only for a thing kept because you bought it back.
    local never = ns.db.sell.never
    local id = 987654322
    local had = never[id]
    never[id] = true
    local cell = { quiet = true, cell = { id = id, name = "Test Scraps", rule = "neverSell" } }
    local okC, done = pcall(B.CellClick, B, cell, "LeftButton", true)
    t:ok(okC and done, "Alt-click on a bought-back thing runs" .. (okC and "" or (": " .. tostring(done))))
    t:eq(never[id], nil, "and Flow may sell it again")
    t:eq(B.Rules()[id], nil, "without changing your banking choice")
    never[id] = had
    local other = { cell = { id = id, name = "Test Leather", rule = "professionMaterial" } }
    t:ok(not B:CellClick(other, "LeftButton", true), "Alt-click on anything else does nothing")
    t:eq(B.Rules()[id], nil, "nor sets a choice")
    B.view, B.offset = view, offset
    if f then B:Fill(); if not was then f:Hide() end end
end)

-------------------------------------------------------------------------------
-- 0.35.342: "Keep set for": a tick for each spec on your bags; an unticked
-- spec's gear isn't kept; Build sets makes the game's equipment sets.
-------------------------------------------------------------------------------

ns:Register("test", "gear: a spec's gear is kept only while its set is ticked", function(t)
    local K = ns.keepSets
    t:ok(K.Kept("dps", { dps = false }, false, "dps"), "the spec you level as is always kept")
    t:ok(K.Kept("tank", nil, true, "dps"), "no tick yet: the old switch for other specs decides (on)")
    t:ok(not K.Kept("tank", nil, false, "dps"), "(off)")
    t:ok(not K.Kept("tank", { tank = false }, true, "dps"), "unticked: not kept, whatever the old switch says")
    t:ok(K.Kept("heal", { heal = true }, false, "dps"), "ticked: kept")
    local kept = K.KeptOf({ "dps", "heal", "tank" }, function(r) return r ~= "heal" end)
    t:eq(table.concat(kept, ","), "dps,tank", "of a list of specs, the kept ones")
    t:eq(K.SetName("Feral (Bear)"), "Feral (Bear)", "the game's set is named after the spec")
    t:eq(#K.SetName("A Very Long Spec Name Indeed"), 16, "cut to what the game allows")

    -- The rule that keeps gear for another spec goes by the ticks.
    local rule = ns:Get("disposition", "laterOrOtherRole")
    local main = ns:LevelingRole()
    local other
    for _, r in ipairs(ns.gear.ROLES) do if r ~= main then other = r break end end
    local diffs = { dps = -5, heal = -5, tank = -5 }
    diffs[other] = 12
    local item = { minLevel = 1, gear = { canUse = true, diffs = diffs } }
    local g = ns.db.gear
    local was = g.keepSet
    g.keepSet = { [other] = true }
    local v = rule.check(item)
    t:ok(v and v.action == "keep" and v.reason == "better for " .. ns:RoleName(other), "ticked: better for that spec is a reason to keep it, by the spec's name")
    g.keepSet = { [other] = false }
    t:eq(rule.check(item), nil, "unticked: it isn't, so the item goes by the rules after it (sold)")
    g.keepSet = was
    ns.disposition:Invalidate()
end)

ns:Register("test", "gear: building a set picks the best piece a slot from your bags", function(t)
    local K = ns.keepSets
    local picks = K.Best({
        { link = "helm A", loc = "INVTYPE_HEAD", diff = 4 },
        { link = "helm B", loc = "INVTYPE_HEAD", diff = 9 },
        { link = "belt", loc = "INVTYPE_WAIST", diff = 0.2 },
        { link = "ring", loc = "INVTYPE_FINGER", diff = 2 },
        { link = "cloak", loc = "INVTYPE_CLOAK", diff = -3 },
    })
    t:eq(#picks, 2, "one a kind of slot, and only what's better")
    t:eq(picks[1].link, "helm B", "the better of two helms, the biggest gain first")
    t:eq(picks[2].link, "ring", "then the ring")
    t:eq(#K.Best({}), 0, "nothing in your bags: nothing to put on")
    t:ok(pcall(K.Wants, "tank"), "looking through your real bags doesn't error")
    local role = K.WornRole()
    t:ok(role == "dps" or role == "heal" or role == "tank", "the spec you're wearing is one of the three")
    local okL, lines = pcall(K.Lines)
    t:ok(okL and #lines >= 4, "/flow keepsets lists each spec" .. (okL and "" or (": " .. tostring(lines))))
    t:eq(type(ns.gear.sets.GameSet), "function", "the game's set for a spec can be asked for")
    if InCombatLockdown() then
        local said
        K:Build("tank", function(ok, text) said = { ok, text } end)
        t:ok(said and said[1] == false, "in a fight nothing is built")
    end
end)

ns:Register("test", "click: a Keep set tick on your bags changes what's kept, and puts it back", function(t)
    local K = ns.keepSets
    t:ok(pcall(K.Attach, K), "the row attaches to the bag windows that exist")
    local main = ns:LevelingRole()
    local other
    for _, r in ipairs(ns.gear.ROLES) do if r ~= main then other = r break end end
    local g = ns.db.gear
    local was, auto = g.keepSet, K.autoBuild
    g.keepSet = {}
    for k, v in pairs(was or {}) do g.keepSet[k] = v end
    K.autoBuild = false   -- (a click here must not swap your gear)
    local bar
    for _, b in pairs(K._Bars()) do bar = bar or b end
    if bar then
        local cb = bar.ticks[other]
        local before = K.Keeps(other)
        cb:SetChecked(not before)
        local ok, err = pcall(function() cb:GetScript("OnClick")(cb) end)
        t:ok(ok, "a click on another spec's tick runs" .. (ok and "" or (": " .. tostring(err))))
        t:eq(K.Keeps(other), not before, "and flips whether its gear is kept")
        local mine = bar.ticks[main]
        mine:SetChecked(false)
        t:ok(pcall(function() mine:GetScript("OnClick")(mine) end), "a click on your own spec's tick runs")
        t:ok(K.Keeps(main) and mine:GetChecked(), "and it stays ticked")
        t:ok(bar:GetWidth() > 150, "the row is as wide as its ticks and button")
        t:ok(type(bar.build:GetScript("OnClick")) == "function", "Build sets has its click")
    else
        K:Tick(other, false, true)
        t:ok(not K.Keeps(other), "(no bag window yet) the tick itself works")
    end
    K.autoBuild = auto
    g.keepSet = was
    ns.disposition:Invalidate()
    K:Refresh()
    t:eq(ns.db.gear.keepSet, was, "(your own ticks restored)")
end)

-------------------------------------------------------------------------------
-- 0.35.343: your own "sell it" or "keep it" for an item, set and undone in
-- Flow Banker.
-------------------------------------------------------------------------------

ns:Register("test", "items: your own sell or keep choice comes before Flow's rules, and can be undone", function(t)
    local D = ns.disposition
    local v = D.ChoiceVerdict("sell", 25, 1)
    t:ok(v and v.action == "sell" and v.reason == "you chose to sell it", "sell: sold, and the reason says it's your choice")
    v = D.ChoiceVerdict("keep", 25, 1)
    t:ok(v and v.action == "keep" and v.reason == "you chose to keep it", "keep: kept")
    t:eq(D.ChoiceVerdict("sell", 0, 1), nil, "sell on a thing vendors won't buy: Flow's rules decide")
    t:ok(D.ChoiceVerdict("sell", 0, 0), "(a grey thing always sells)")
    t:eq(D.ChoiceVerdict(nil, 25, 1), nil, "no choice: Flow's rules decide")

    local id = 987654323
    local was = ns.db.sell.mine[id]
    ns.db.sell.mine[id] = nil
    t:ok(D.SetChoice(id, "sell"), "a choice is set")
    t:eq(D.Choice(id), "sell", "and read back")
    t:ok(not D.SetChoice(id, "sell"), "the same again changes nothing")
    t:ok(not D.SetChoice(id, "burn"), "only sell or keep")
    local rule = ns:Get("disposition", "yourChoice")
    local got = rule.check({ id = id, sellPrice = 10, quality = 1 })
    t:ok(got and got.action == "sell", "the rule gives your choice")
    t:ok((rule.order or 99) < (ns:Get("disposition", "neverSell").order or 0), "and is asked first of all")
    t:ok(D.SetChoice(id, "keep") and D.Forget(id), "a keep of your own is undone like a buy-back")
    t:eq(D.Choice(id), nil, "and it's Flow's choice again")
    t:eq(rule.check({ id = id, sellPrice = 10, quality = 1 }), nil, "so the rule has nothing to say")
    ns.db.sell.mine[id] = was
    D:Invalidate()
end)

ns:Register("test", "click: Flow Banker's To sell lines and To bank cells set your own choice", function(t)
    local B, D = ns.banker, ns.disposition
    t:eq(B.NextSellChoice(nil, false), "keep", "a click on a thing Flow sells: keep it")
    t:eq(B.NextSellChoice(true, false), "sell", "on one you keep: sell it after all")
    t:eq(B.NextSellChoice(nil, true), nil, "a right-click: Flow's choice")
    t:ok(B.RowTip("sell", { mine = true })[1]:find("Sold: your choice", 1, true), "your own line says so")
    t:ok(B.RowTip("sell", {})[2]:find("keep it", 1, true), "Flow's line offers to keep it")
    t:ok(B.RowTip("prices", nil)[1]:find("Flow Prices", 1, true), "a price line still opens the chart")
    local rows = B.SellRows({ { id = 1, name = "Linen Cloth", action = "sell", reason = "you chose to sell it", rule = "yourChoice", count = 4 } })
    t:ok(rows[1].mine, "a row sold by your choice is marked")
    local _, lines = B.SellLines(rows, {}, false)
    t:ok(lines[1]:find("Your choice:", 1, true), "and its line says so")
    local why = B.WhyLines({ id = 5, rule = "yourChoice", reason = "you chose to keep it", sell = 12 })
    t:ok(table.concat(why, " "):find("Alt-click: Flow's own choice again", 1, true), "a kept thing's tooltip says how to undo")
    t:ok(table.concat(why, " "):find("Shift-click: sell it", 1, true), "and a thing vendors buy offers to sell it")
    t:ok(not table.concat(B.WhyLines({ id = 5, reason = "x", sell = 0, quality = 1 }), " "):find("Shift-click", 1, true), "one they won't buy doesn't")

    if InCombatLockdown() then return end
    local id = 987654324
    local wasMine = ns.db.sell.mine[id]
    ns.db.sell.mine[id] = nil
    local frame = B._Frame()
    local shown = frame and frame:IsShown()
    local view, offset = B.view, B.offset
    -- Shift-click a cell: sell it. Alt-click a kept one: Flow's choice.
    local cell = { quiet = true, cell = { id = id, name = "Test Cloth", rule = "professionMaterial", sell = 13, quality = 1 } }
    local ok, done = pcall(B.CellClick, B, cell, "LeftButton", false, true)
    t:ok(ok and done, "Shift-click on a kept thing runs" .. (ok and "" or (": " .. tostring(done))))
    t:eq(D.Choice(id), "sell", "and it's yours to sell")
    t:eq(B.Rules()[id], nil, "without touching your banking choice")
    t:ok(not B:CellClick({ quiet = true, cell = { id = id, name = "Soulbound", sell = 0, quality = 1 } }, "LeftButton", false, true),
        "Shift-click on a thing vendors won't buy does nothing")
    -- A click on its To sell line: undone.
    B.view = "sell"
    local okR = pcall(B.RowClick, B, { id = id, row = { mine = true } }, "RightButton")
    t:ok(okR, "a right-click on your own To sell line runs")
    t:eq(D.Choice(id), nil, "and it's Flow's choice again")
    pcall(B.RowClick, B, { id = id, row = {} }, "LeftButton")
    t:eq(D.Choice(id), "keep", "a click on a line Flow sells: kept")
    pcall(B.RowClick, B, { id = id, row = {} }, "RightButton")
    t:eq(D.Choice(id), nil, "a right-click: Flow's choice")
    -- The real row buttons take both mouse buttons.
    frame = B._Frame()
    if frame and frame.rowButtons and frame.rowButtons[1] then
        t:eq(type(frame.rowButtons[1]:GetScript("OnClick")), "function", "each line has its click")
    end
    ns.db.sell.mine[id] = wasMine
    D:Invalidate()
    B.view, B.offset = view, offset
    if frame then B:Fill(); if not shown then frame:Hide() end end
end)

-------------------------------------------------------------------------------
-- 0.35.344: quest items in your bags: what clears each one.
-------------------------------------------------------------------------------

ns:Register("test", "quest bags: every quest thing in your bags gets what clears it", function(t)
    local QG = ns.questBags
    local quests = {
        { id = 821, title = "Chen's Empty Keg", complete = true, items = { [4893] = true, [4894] = true, [4895] = true } },
        { id = 866, title = "Root Samples", complete = true, items = { [5056] = true } },
        { id = 5725, title = "The Power to Destroy...", complete = true, items = { [14395] = true, [14396] = true } },
        { id = 875, title = "Harpy Lieutenants", complete = false, items = { [5065] = true } },
        { id = 76240, title = "Stalk With The Earthmother", complete = false, items = { [206344] = true } },
        { id = 6128, title = "Gathering the Cure", complete = true, items = { [2449] = true, [15852] = true } },
    }
    local function row(id, name, count, kind, action, reason, stacks)
        return { id = id, name = name, count = count, stacks = stacks or 1, kind = kind or "Quest", action = action or "keep", reason = reason }
    end
    local rows = {
        row(4893, "Savannah Lion Tusk", 5), row(4894, "Plainstrider Kidney", 5), row(4895, "Thunder Lizard Horn", 1),
        row(5056, "Root Sample", 8), row(14395, "Spells of Shadow", 1), row(14396, "Incantations from the Nether", 1),
        row(5065, "Harpy Lieutenant Ring", 2), row(206344, "Knife Set", 1),
        row(2449, "Earthroot", 14, "Trade Goods: Herb"), row(15852, "Kodo Horn", 5),
        row(5134, "Small Furry Paw", 2, "Quest", "sell", "its quest is 39 levels away"),
        row(5165, "Sunscale Feather", 9, "Quest", "keep", "no quest in your log uses it"),
        row(2318, "Light Leather", 30, "Trade Goods: Leather", "keep", "for Leatherworking", 2),
    }
    local where = { [5725] = { "away", "Carendin Halgar" }, [76240] = { "stuck" }, [821] = { nil, "Brewmaster Drohn" } }
    local plan = QG.Plan(rows, quests, function(id) local w = where[id] or {}; return w[1], w[2] end)
    t:eq(plan.slots, 12, "the quest things' slots, leather not among them")
    t:eq(#plan.turnin, 3, "three finished quests to hand in")
    t:eq(plan.turnin[1].title, "Chen's Empty Keg", "the one that frees the most first")
    t:eq(plan.turnin[1].slots, 3, "with its slots")
    t:eq(plan.turnin[1].who, "Brewmaster Drohn", "and who takes it")
    t:eq(plan.turnin[2].title, "Gathering the Cure", "a plain herb a quest asks for counts with it")
    t:eq(plan.turnin[2].slots, 2, "(Earthroot and Kodo Horn)")
    t:eq(#plan.bank, 2, "to the bank: a finished quest that's handed in on another continent, and a leftover that waits")
    t:eq(plan.bank[1].title, "The Power to Destroy...", "the quest, by its slots")
    t:eq(plan.bank[1].why, "its next step is on another continent", "and why")
    t:eq(plan.bank[2].title, "Sunscale Feather", "the leftover")
    t:eq(#plan.sell, 1, "one leftover to sell")
    t:eq(#plan.finish, 1, "one quest in progress here")
    t:eq(plan.finish[1].title, "Harpy Lieutenants", "by name")
    t:eq(#plan.stuck, 1, "one Flow can't place")
    t:eq(QG.Slots(plan.turnin), 6, "slots the hand-ins free")

    local lines = QG.Lines(plan, 0, 54)
    t:eq(lines[1], "Quest items hold 12 of your 54 bag slots (0 free).", "the report's first line")
    t:ok(table.concat(lines, "\n"):find("3: Chen's Empty Keg, to Brewmaster Drohn (5 x Savannah Lion Tusk, 5 x Plainstrider Kidney, 1 x Thunder Lizard Horn)", 1, true),
        "a line a quest: slots, who, what")
    t:ok(table.concat(lines, "\n"):find("Hand in (finished): 6 slot(s)", 1, true), "each kind with its slots")

    local adv = QG.Advice(plan, 0)
    t:eq(#adv, 3, "nearly full bags: hand in, bank, sell")
    t:ok(adv[1].text:find("hand in 3 finished quest(s) to free 6 slot(s): Chen's Empty Keg (3), Gathering the Cure (2), Root Samples (1)", 1, true),
        "the hand-ins named, most slots first")
    t:ok(adv[1].importance > adv[2].importance and adv[2].importance > adv[3].importance, "in that order")
    t:eq(#QG.Advice(plan, 12), 0, "room to spare: nothing said")
    t:eq(#QG.Advice(QG.Plan({}, quests), 0), 0, "no quest things: nothing said")
    t:eq(QG.Names({ { title = "A", slots = 2 }, { title = "B", slots = 1 }, { title = "C", slots = 1 } }, 2), "A (2), B (1) and 1 more", "a long list is cut")
end)

ns:Register("test", "quest bags: a quest whose next step is on another continent waits; its later steps don't count", function(t)
    local QG = ns.questBags
    local seaLion = {
        { key = "30:item:15882", conts = { [0] = true } },
        { key = "30:1", deps = { "30:item:15882" }, conts = { [1] = true } },
        { key = "30:done", deps = { "30:1", "30:item:15882" }, conts = { [1] = true } },
    }
    t:ok(QG.Away(seaLion, 1), "the first thing to do is across the sea: it waits, though later steps are here")
    t:ok(not QG.Away(seaLion, 0), "over there it doesn't")
    t:ok(not QG.Away({ { key = "875:1", conts = { [1] = true } }, { key = "875:done", deps = { "875:1" }, conts = { [1] = true } } }, 1), "a quest here doesn't wait")
    t:ok(QG.Away({ { key = "264:done", conts = { [0] = true } } }, 1), "a finished quest handed in over there waits")
    t:ok(not QG.Away({ { key = "1:1", conts = {} } }, 1), "a step with no place known isn't 'another continent'")
    t:ok(not QG.Away({}, 1), "no steps: not known")
    local q = QG.QuestOf(5, { { id = 1, complete = false, items = { [5] = true } }, { id = 2, complete = true, items = { [5] = true } } })
    t:eq(q and q.id, 2, "an item two quests ask for: the finished one (its hand-in frees the slot)")
    t:eq(QG.QuestOf(9, {}), nil, "no quest: nil")
end)

ns:Register("test", "route: a finished quest's hand-in that frees bag slots stays on the route with nearly full bags", function(t)
    local QG = ns.questBags
    local g = { key = "821:done", weight = 0.8, text = "Turn in: Chen's Empty Keg", details = {} }
    t:ok(QG.MarkStep(g, 3, 0), "three slots, full bags: marked")
    t:ok(g.keep, "it always makes the route's cut")
    t:eq(g.weight, 0.5, "and comes early")
    t:eq(g.text, "Turn in: Chen's Empty Keg (frees 3 bag slots)", "its words say what it frees")
    t:eq(g.frees, 3, "the slots are on the step")
    local roomy = { key = "866:done", weight = 0.8, text = "Turn in: Root Samples" }
    QG.MarkStep(roomy, 1, 20)
    t:ok(not roomy.keep and roomy.weight == 0.8 and roomy.text == "Turn in: Root Samples", "with room in your bags the route is as it was")
    t:ok(roomy.details and roomy.details[1]:find("frees 1 bag slot", 1, true), "its details still say what it frees")
    t:ok(not QG.MarkStep({ key = "1:done" }, 0, 0), "a quest with nothing in your bags: not marked")

    -- The planner: 40 nearer steps, and the far hand-in is still planned.
    local goals = {}
    for i = 1, 40 do goals[i] = { key = "pickup:" .. i, text = "near " .. i, points = { { cont = 1, wx = i * 10, wy = 0 } } } end
    local far = { key = "821:done", text = "far hand-in", points = { { cont = 1, wx = 9000, wy = 0 } } }
    goals[#goals + 1] = far
    local function planned(plan)
        for _, s in ipairs(plan or {}) do if s.goal and s.goal.key == "821:done" then return true end end
        return false
    end
    local p = { cont = 1, wx = 0, wy = 0 }
    local ok, plan = pcall(ns.planner.Plan, ns.planner, p, goals, {})
    t:ok(ok and not planned(plan), "unmarked, the far hand-in is cut (the 30 nearest steps)" .. (ok and "" or (": " .. tostring(plan))))
    far.keep = true
    ok, plan = pcall(ns.planner.Plan, ns.planner, p, goals, {})
    t:ok(ok and planned(plan), "marked, it's on the route" .. (ok and "" or (": " .. tostring(plan))))
end)

ns:Register("test", "banker: quest things go to the bank only when there's nothing to do with them here, and come back", function(t)
    local B, L = ns.banker, ns.leftovers
    local function row(name, id, rule, kind, reason)
        return { name = name, id = id, action = "keep", rule = rule, kind = kind, reason = reason, count = 1, stacks = 1 }
    end
    local pendant = row("Clarice's Pendant", 6145, "unsellable", "Quest", "vendors won't buy it; quest item")
    t:ok(not B.Banks(pendant, {}, {}, {}), "a quest item: stays")
    local bank, why = B.Banks(pendant, {}, {}, { [6145] = "Until Death Do Us Part" })
    t:ok(bank and why:find("Until Death Do Us Part", 1, true) and why:find("another continent", 1, true), "its quest goes on across the sea: to the bank, saying so")
    t:ok(not B.Banks(pendant, {}, { [6145] = "carry" }, { [6145] = "x" }), "your own 'carry it' still wins")
    t:ok(B.Banks(row("Sunscale Feather", 5165, "leftover", "Quest", "no quest in your log uses it"), {}, {}, {}), "a leftover that waits for a quest: to the bank")
    t:ok(not B.Banks(row("Earthroot", 2449, "questNeeds", "Trade Goods: Herb", "for your quest: Gathering the Cure"), {}, {}, {}),
        "a herb your quest asks for stays with you (it was headed for the bank)")
    t:ok(B.Banks(row("Briarthorn", 2450, "professionMaterial", "Trade Goods: Herb", "for Alchemy"), {}, {}, {}), "a plain material still goes")
    t:eq(#B.Pick({ pendant }, {}, {}, { [6145] = "Q" }), 1, "the list to put away carries it")
    local cells = B.PutCells({ pendant }, {}, {}, { [6145] = "Q" })
    t:ok(cells[1].bank, "and so does the grid")

    -- Back out of the bank when a quest here can use it.
    local out = B.TakeOutRows({ [5165] = 9, [6145] = 1, [2318] = 20 },
        function(id) return { action = "keep", reason = "x", item = { classID = 12, name = id == 5165 and "Sunscale Feather" or "Other" } } end,
        {}, function(id) return id == 5165 and "The Angry Scytheclaws" or nil end)
    t:eq(#out, 1, "only what a quest here needs (kept things stay in the bank)")
    t:ok(out[1].action == "quest" and out[1].reason == "The Angry Scytheclaws" and out[1].count == 9, "for which quest, and how many")
    local _, lines = B.SellLines({}, out, true)
    t:ok(lines[1]:find("In your bank:", 1, true) and lines[1]:find("(your quest: The Angry Scytheclaws)", 1, true), "its line says it's for your quest")
    t:eq(#B.SellRows({ { id = 1, name = "x", action = "quest" } }), 0, "(nothing in your bags is ever listed that way)")
    t:eq(#B.TakeOutRows({ [5165] = 9 }, function() return nil end, { [5165] = "bank" }, function() return "Q" end), 0, "what you chose to bank stays there")

    -- A leftover whose quest is far above you: sold.
    local what, text = L.Advice({ { name = "Small Furry Paws", level = 60, done = false } }, 92, 21)
    t:ok(what == "sell" and text:find("39 levels away", 1, true), "a quest 39 levels away isn't a reason to carry its item")
    what = L.Advice({ { name = "Small Furry Paws", level = 60, done = false } }, 0, 21)
    t:eq(what, "keep", "unless no vendor buys it")
    what = L.Advice({ { name = "The Angry Scytheclaws", level = 17, done = false } }, 5, 21)
    t:eq(what, "keep", "a quest near your level: kept, as before")
end)

ns:Register("test", "quest bags: your own bags and log can be read, and /flow questbags lists them", function(t)
    local QG = ns.questBags
    local ok, now = pcall(QG.Now, true)
    t:ok(ok and type(now) == "table" and type(now.plan) == "table", "the plan for your own bags builds" .. (ok and "" or (": " .. tostring(now))))
    if not ok then return end
    t:eq(type(now.plan.slots), "number", "with its count of slots")
    t:ok(pcall(QG.Lines, now.plan, now.free, now.total), "and its report")
    t:eq(type(QG.SlotsByQuest()), "table", "slots a quest are counted")
    t:eq(type(QG.Waits()), "table", "what waits for another continent is listed")
    t:eq(QG.NeededHere(-1), nil, "an item no quest asks for isn't needed here")
    local def = ns:Get("advisor", "questBags")
    local okA, list = pcall(def.check)
    t:ok(okA and type(list) == "table", "Flow Improvements can ask" .. (okA and "" or (": " .. tostring(list))))
