    end
    t:ok(n >= 0, "(" .. n .. " bag window(s) have the row)")
end)

-------------------------------------------------------------------------------
-- 0.35.350: trips from step to step are timed, and the route is planned by them.
-------------------------------------------------------------------------------

ns:Register("test", "legs: a trip is timed from one step to your arrival at the next: travelling only", function(t)
    local L = ns.legs
    local st = {}
    local A, B = { cont = 1, wx = 0, wy = 0 }, { cont = 1, wx = 300, wy = 0 }
    local function look(x, y, extra)
        local s = { cont = 1, wx = x, wy = y, dt = 1, target = B }
        for k, v in pairs(extra or {}) do s[k] = v end
        return L.Look(st, s)
    end
    -- Arriving somewhere starts the next trip from there.
    t:eq(L.Look(st, { cont = 1, wx = 5, wy = 0, dt = 1, target = A }), nil, "arriving at a step with no trip before it: nothing learned yet")
    t:ok(st.anchor and st.anchor.wx == 0, "but the next trip starts from that step's spot")
    for x = 12, 96, 7 do look(x, 0) end                       -- 13 s running
    for _ = 1, 20 do look(96, 0, { combat = true }) end        -- a fight on the way: not travel
    for _ = 1, 30 do look(96, 0) end                           -- standing still: not travel
    local leg
    for x = 103, 271, 7 do leg = leg or look(x, 0) end         -- 25 s more, arriving within 30 yd
    t:ok(leg ~= nil, "arriving at the next step ends the trip")
    if not leg then return end
    t:near(leg.d, 300, 0.1, "its length: the straight line between the two steps' spots")
    t:ok(leg.sec >= 36 and leg.sec <= 40, "its time: the seconds you were moving, not the fight or the wait (" .. tostring(leg.sec) .. ")")
    t:eq(leg.mode, "foot", "on foot")
    t:ok(st.anchor.wx == 300 and st.sec == 0, "and the next trip starts here")

    -- A hearthstone in the middle: no trip.
    st = { anchor = { cont = 1, wx = 0, wy = 0 }, last = { cont = 1, wx = 10, wy = 0 }, sec = 5, ground = 10 }
    t:eq(look(280, 0), nil, "a jump of hundreds of yards in a second isn't travel")
    t:eq(st.anchor, nil, "and the trip it was part of is dropped")
    -- A flight is: fast, and counted whole.
    st = { anchor = { cont = 1, wx = 0, wy = 0 }, last = { cont = 1, wx = 0, wy = 0 }, sec = 0, ground = 0 }
    look(150, 0, { taxi = true })
    leg = look(290, 0, { taxi = true })
    t:ok(leg and leg.mode == "taxi" and leg.sec == 2, "a flight is a trip, marked as one")
    -- Wandering: three times the straight line on the ground.
    st = { anchor = { cont = 1, wx = 0, wy = 0 }, last = { cont = 1, wx = 0, wy = 0 }, sec = 0, ground = 0 }
    for i = 1, 60 do look((i % 2) * 8, 0) end
    for x = 8, 280, 8 do leg = look(x, 0) end
    t:eq(leg, nil, "a trip with a long wander in it teaches nothing")
    -- Death, another continent.
    st = { anchor = { cont = 1, wx = 0, wy = 0 }, last = { cont = 1, wx = 0, wy = 0 } }
    look(5, 0, { dead = true })
    t:eq(st.anchor, nil, "dying ends the trip unlearned")
    st = { anchor = { cont = 1, wx = 0, wy = 0 }, last = { cont = 1, wx = 0, wy = 0 } }
    L.Look(st, { cont = 0, wx = 5, wy = 0, dt = 1 })
    t:eq(st.anchor, nil, "so does another continent")
end)

ns:Register("test", "legs: your quickest time for a trip is kept, and the planner measures by it", function(t)
    local L = ns.legs
    local store, coarse = {}, {}
    local leg = { cont = 1, ax = 10, ay = 10, bx = 610, by = 10, sec = 200, d = 600, mode = "foot" }
    local e, best = L.Keep(store, leg, 100)
    t:ok(e and best and e.s == 200 and e.n == 1, "a first trip is the best so far")
    leg.sec = 260
    e, best = L.Keep(store, leg, 200)
    t:ok(not best and e.s == 200 and e.n == 2, "a slower one is counted, the quickest stays")
    leg.sec, leg.mode = 150, "mount"
    e, best = L.Keep(store, leg, 300)
    t:ok(best and e.s == 150 and e.m == "mount" and e.n == 3, "a quicker one replaces it, with how you travelled")
    t:eq(L.Count(store), 1, "one trip between those two places")
    t:eq((L.Keep(store, { ax = 1, ay = 1, bx = 5, by = 5, sec = 3, d = 6, mode = "foot" }, 1)), nil, "both ends in one square: not a trip")

    -- 150 s at a run is 1050 yards for a 600-yard line: the road goes round something.
    local a, b = { wx = 20, wy = 20 }, { wx = 600, wy = 30 }
    local yards, how = L.Lookup(store, coarse, a, b, 580)
    t:eq(how, "exact", "the same two squares: a trip you've made")
    t:near(yards, 150 * L.RUN * (580 / 600), 1, "what it took, at a run, for this length")
    _, how = L.Lookup(store, coarse, b, a, 580)
    t:eq(how, "exact", "and the way back counts the same")
    t:eq(L.Lookup(store, coarse, { wx = 2000, wy = 2000 }, { wx = 2600, wy = 2000 }, 600), nil, "somewhere you've never been: nothing known")
    t:eq(L.Lookup(store, coarse, a, b, 20), nil, "a few steps: not asked")

    -- The neighbourhoods: another trip between the same two, not the same squares.
    local ratio = L.Ratio(coarse, e, leg.ax, leg.ay, leg.bx, leg.by)
    t:near(ratio, 150 * L.RUN / 600, 0.01, "how much longer than the straight line it took")
    yards, how = L.Lookup(store, coarse, { wx = 100, wy = 100 }, { wx = 700, wy = 120 }, 600)
    t:eq(how, "area", "a trip between the same two neighbourhoods")
    t:near(yards, 600 * ratio, 1, "is stretched the same way")
    t:eq(L.Ratio({}, { s = 10, d = 600, m = "taxi" }, 0, 0, 600, 0), nil, "a flight says nothing about the ground between")

    -- Bounds: a time can't make a trip free or endless.
    t:near(L.YardsOf({ s = 1, d = 1000 }, 1000), 1000 * L.FASTEST, 0.01, "never less than a small share of the line")
    t:near(L.YardsOf({ s = 9000, d = 100 }, 100), 100 * L.SLOWEST, 0.01, "never more than a few times it")

    -- The planner takes an exact trip as the answer and only stretches by an area's.
    local P = ns.planner
    local p1, p2 = { wx = 0, wy = 0, map = 1 }, { wx = 600, wy = 0, map = 1 }
    t:near(P._Far(p1, p2, {}), 600, 0.01, "nothing learned: the straight line")
    t:near(P._Far(p1, p2, { legs = function() return 1050, "exact" end }), 1050, 0.01, "a trip you made: what it took")
    t:near(P._Far(p1, p2, { legs = function() return 300, "exact" end }), 300, 0.01, "(also when it was quicker than a run: a flight)")
    t:near(P._Far(p1, p2, { legs = function() return 900, "area" end }), 900, 0.01, "its neighbourhood: stretched")
    t:near(P._Far(p1, p2, { legs = function() return 400, "area" end }), 600, 0.01, "but an area never shortens the line")
    t:near(P._Far(p1, p2, { legs = function() error("x") end }), 600, 0.01, "an error in the lookup: the straight line")

    -- Old trips go first when the store is full.
    local big = {}
    for i = 1, 10 do L.Keep(big, { ax = i * 100, ay = 0, bx = i * 100, by = 500, sec = 60, d = 500, mode = "foot" }, i) end
    t:eq(L.Prune(big, 6), 4, "over the limit: the ones used longest ago go")
    t:eq(L.Count(big), 6, "the rest stay")
    t:ok(big[L.Cell(1000, 0)] ~= nil and big[L.Cell(100, 0)] == nil, "the newest kept, the oldest gone")
end)

ns:Register("test", "legs: your own trips are read, the planner is given them, and /flow legs lists them", function(t)
    local L = ns.legs
    t:eq(type(ns.db.nav.legs), "table", "the store is there")
    local ok, lines = pcall(L.Lines)
    t:ok(ok and #lines >= 3, "/flow legs builds" .. (ok and "" or (": " .. tostring(lines))))
    t:ok(pcall(L.Tick), "a look at where you are doesn't error")
    local was = ns.db.nav.learnLegs
    ns.db.nav.learnLegs = false
    t:eq(L.PlanLegs(), nil, "off: the planner isn't given them")
    ns.db.nav.learnLegs = nil
    t:eq(L.PlanLegs(), L.Yards, "on (as it comes): it is")
    ns.db.nav.learnLegs = was
    t:eq(L.Yards({ cont = 1, wx = 0, wy = 0 }, { cont = 0, wx = 500, wy = 0 }, 500), nil, "two continents: not a trip Flow times")
    local okO, opts = pcall(ns.nav.Options, ns.nav)
    t:ok(okO and type(opts) == "table" and (opts.legs == nil or type(opts.legs) == "function"), "the route's options carry it" .. (okO and "" or (": " .. tostring(opts))))
end)

-------------------------------------------------------------------------------
-- 0.35.351: a thing parked in the bank for a quest across the sea stays
-- parked; Flow never moves a thing one way and then back.
-------------------------------------------------------------------------------

ns:Register("test", "banker: banking a quest's thing doesn't make Flow ask for it back", function(t)
    local QG = ns.questBags
    -- In the bank, the game calls the quest unfinished: a "collect it" step is back, here.
    local steps = {
        { key = "5725:1", item = 14395, conts = { [1] = true }, placed = true },
        { key = "5725:2", item = 14396, conts = { [1] = true }, placed = true },
        { key = "5725:done", deps = { "5725:1", "5725:2" }, conts = { [0] = true }, placed = true },
    }
    t:ok(not QG.Away(steps, 1), "as the route has it, the quest now looks like one to do here (that was the bug)")
    local banked = { [14395] = true, [14396] = true }
    local real = QG.Unheld(steps, function(id) return banked[id] end)
    t:eq(#real, 1, "a step that fetches a thing lying in your bank isn't a step")
    local away, to = QG.Away(real, 1)
    t:ok(away and to == 0, "what's left is the hand-in across the sea: it waits, and Flow knows on which continent")
    t:eq(#QG.Unheld(steps, function() return false end), 3, "with nothing in the bank every step counts")
    t:eq(#QG.Unheld(nil, nil), 0, "no steps: none")

    -- Parked: it stays so until you're over there or the quest is gone.
    local quests = { { id = 5725, title = "The Power to Destroy...", items = { [14395] = true, [14396] = true } },
                     { id = 881, title = "Echeyakee", items = { [10327] = true } } }
    local parked = QG.Park({}, quests, { [5725] = "away", [881] = "here" }, { [5725] = 0 }, 1)
    t:ok(parked[14395] and parked[14395].cont == 0 and parked[14395].title == "The Power to Destroy...", "a quest across the sea parks its things, with where it goes on")
    t:eq(parked[10327], nil, "a quest here parks nothing")
    QG.Park(parked, quests, { [5725] = "here", [881] = "here" }, {}, 1)
    t:ok(parked[14395] ~= nil, "the quest log changing its mind (the thing is in the bank now) doesn't unpark it")
    QG.Park(parked, quests, { [5725] = "stuck" }, {}, nil)
    t:ok(parked[14395] ~= nil, "nor does not knowing where you are")
    QG.Park(parked, quests, { [5725] = "here" }, {}, 0)
    t:eq(parked[14395], nil, "being on its continent does: now it can come out")
    parked = QG.Park({}, quests, { [5725] = "away" }, { [5725] = 0 }, 1)
    QG.Park(parked, { quests[2] }, {}, {}, 1)
    t:eq(parked[14395], nil, "and so does the quest leaving your log")
end)

ns:Register("test", "banker: what Flow just moved one way isn't offered the other way", function(t)
    local B = ns.banker
    local moved = { [14395] = { dir = "in", cont = 1 }, [2589] = { dir = "out", cont = 1 } }
    t:ok(not B.Settled(moved, 14395, "out", 1), "just deposited: not offered back out here")
    t:ok(B.Settled(moved, 14395, "in", 1), "(more of it may still go in)")
    t:ok(B.Settled(moved, 14395, "out", 0), "on another continent it may: that's what changes a quest thing's use")
    t:ok(not B.Settled(moved, 2589, "in", 1), "just taken out: not offered back in")
    t:ok(B.Settled(moved, 999, "out", 1) and B.Settled(nil, 1, "in", 1), "a thing Flow hasn't moved is free either way")
    local rows = { { id = 14395, name = "Spells of Shadow" }, { id = 5, name = "Other" }, { id = 2589, name = "Linen Cloth", mine = true } }
    local out = B.Unmoved(rows, moved, "out", 1, nil)
    t:eq(#out, 2, "the take-out list loses what was just deposited")
    t:eq(out[1].id, 5, "the rest stay")
    local put = B.Unmoved({ { id = 2589, name = "Linen Cloth" }, { id = 5 } }, moved, "in", 1, {})
    t:eq(#put, 1, "the put-away list loses what was just taken out")
    put = B.Unmoved({ { id = 2589, name = "Linen Cloth" } }, moved, "in", 1, { [2589] = "bank" })
    t:eq(#put, 1, "unless you chose to bank it yourself: your own choice is never held back")

    -- Your own things, right now: both lists build, and share nothing.
    local okT, take = pcall(B.TakeOut, true)
    local okP, list = pcall(B.List)
    t:ok(okT and okP, "both lists build" .. ((okT and okP) and "" or (": " .. tostring(okT and list or take))))
    if okT and okP then t:eq(#B.Thrash(take, list), 0, "nothing of yours is in both") end
    local okL, lines = pcall(B.Lines)
    t:ok(okL and table.concat(lines, "\n"):find("parked for a quest across the sea", 1, true), "/flow banker says what's parked" .. (okL and "" or (": " .. tostring(lines))))
end)

ns:Register("test", "route: a quest thing that lies in your bank isn't collected again", function(t)
    local QG = ns.questBags
    t:ok(QG.Banked(1, nil, nil), "one in the bank, no count asked: you have it")
    t:ok(QG.Banked(3, 5, 2), "three in the bank and two on you make the five")
    t:ok(not QG.Banked(2, 5, 2), "two and two don't")
    t:ok(not QG.Banked(0, 1, 0) and not QG.Banked(nil), "none in the bank: still to get")
    t:eq(QG.InBank(-1), false, "an item the bank doesn't hold")
end)

-------------------------------------------------------------------------------
-- 0.35.352: Flow Trader: deals from the auction house's listings, a button each.
-------------------------------------------------------------------------------

ns:Register("test", "trader: a listing under the vendor's price, or at half its usual price, is a deal", function(t)
    local T = ns.trader
    local usual, n = T.Usual({ 100, 80, 200, 120, 300, 100, 400, 110, 500, 5000 })
    t:eq(usual, 110, "an item's usual price is the middle of its history: one wild look doesn't move it")
    t:eq(n, 5, "from five visits")
    t:eq((T.Usual({ 1, 80, 2, 90 })), nil, "two visits aren't enough to call a price usual")
    t:eq((T.Usual({ 1, 80, 2, 90, 3, 100, 4, 110 })), 95, "an even number: between the two middle ones")

    local a = T.Listing(nil, 10, 300, 25, 100)       -- 30 each: over the vendor's 25, at 30% of the usual 100
    t:ok(a and a.vq == 0 and a.dq == 10 and a.dc == 300, "half the usual price or less: a resell deal")
    a = T.Listing(a, 5, 100, 25, 100)                -- 20 each: under the vendor's price too
    t:ok(a.vq == 5 and a.vc == 100 and a.dq == 15 and a.dc == 400, "under the vendor's price: a vendor deal as well")
    a = T.Listing(a, 20, 2000, 25, 100)              -- 100 each: no deal
    t:ok(a.dq == 15 and a.vq == 5, "a listing at the usual price adds nothing")
    t:eq(T.Listing(nil, 20, 2000, 25, 100), nil, "and makes no deal of its own")
    t:eq(T.Listing(nil, 5, 100, nil, nil), nil, "no vendor price and no history: nothing to compare with")
    t:eq(T.Listing(nil, 0, 100, 25, 100), nil, "a listing of nothing: skipped")
    t:eq(T.Listing(nil, 5, 0, 25, 100), nil, "one with no buyout: skipped")

    local deals = T.Deals({
        [1] = { vq = 5, vc = 100, dq = 15, dc = 400, vendor = 25, usual = 100 },   -- vendor: 125 - 100 = +25
        [2] = { vq = 0, vc = 0, dq = 4, dc = 400, vendor = 10, usual = 400 },      -- resell: 400*0.95*4 - 400 = +1120
        [3] = { vq = 2, vc = 10, dq = 0, dc = 0, vendor = 5000, usual = nil },     -- vendor: 10000 - 10 = +9990
        [4] = { vq = 1, vc = 99, dq = 0, dc = 0, vendor = 100 },                   -- +1: too little
        [5] = { vq = 9, vc = 9, dq = 0, dc = 0, vendor = 900 },                    -- kept by Flow: not offered
    }, function(id) return "Item " .. id end, function(id) return id ~= 5 end, 20)
    t:eq(#deals, 3, "worth listing, and not something Flow keeps for you")
    t:eq(deals[1].id, 3, "the most gain first")
    t:ok(deals[1].kind == "vendor" and deals[1].gain == 9990 and deals[1].limit == 5000, "a vendor deal: the gain is what the vendor pays less what it costs")
    t:ok(deals[2].id == 2 and deals[2].kind == "resell" and math.abs(deals[2].gain - 1120) < 0.01, "a resell deal: the usual price less the auction house's 5%, less what it costs")
    t:eq(deals[2].limit, 200, "bought at half the usual price at most")
    t:ok(deals[3].id == 1 and deals[3].kind == "vendor" and deals[3].qty == 5, "an item that is both is listed as the certain one, for the listings under the vendor's price")
    t:ok(T.Line(deals[1], function(c) return c .. "c" end):find("2 x Item 3 for 10c: a vendor pays 10000c", 1, true), "a vendor deal's line")
    t:ok(T.Line(deals[2], function(c) return c .. "c" end):find("usually 400c each", 1, true), "a resell deal's line names the usual price")
end)

ns:Register("test", "trader: Flow buys only what's still within the limit and your budget", function(t)
    local T = ns.trader
    -- Stackable: any number of the cheapest.
    local stack = { { unit = 10, qty = 5 }, { unit = 12, qty = 10 }, { unit = 30, qty = 100 } }
    local pick = T.Pick(stack, 15, 1000)
    t:ok(pick.qty == 15 and pick.cost == 170, "everything at or under the limit, nothing over it")
    pick = T.Pick(stack, 15, 100)
    t:ok(pick.qty == 9 and pick.cost == 98, "as many as the budget buys, part of a listing too")
    t:eq(T.Pick(stack, 5, 1000).qty, 0, "the price moved over the limit: nothing")
    t:eq(T.Pick({}, 15, 1000).qty, 0, "not listed any more: nothing")
    -- Single auctions: all of one or none of it.
    local single = { { unit = 100, qty = 1, auction = 11, buyout = 100 }, { unit = 120, qty = 2, auction = 12, buyout = 240 }, { unit = 500, qty = 1, auction = 13, buyout = 500 } }
    pick = T.Pick(single, 150, 300)
    t:ok(#pick.auctions == 1 and pick.auctions[1].id == 11 and pick.cost == 100, "an auction the budget can't cover whole is left")
    pick = T.Pick(single, 150, 1000)
    t:ok(#pick.auctions == 2 and pick.qty == 3 and pick.cost == 340, "with the gold for it, each auction within the limit")
    t:eq(T.Budget(10000, 0.25), 2500, "a quarter of your gold on one trade")
    t:eq(T.Budget(nil), 0, "no gold: no budget")

    -- The button says where a purchase stands.
    local has = { search = true, commodity = true, item = true }
    local label, can = T.Button(nil, 7, has)
    t:ok(label == "Buy" and can, "a deal: Buy")
    label, can = T.Button({ id = 7, stage = "search" }, 7, has)
    t:ok(label == "..." and not can, "looking it up: wait")
    label, can = T.Button({ id = 7, stage = "ready", commodity = true }, 7, has)
    t:ok(label == "Confirm" and can, "found, stackable: Confirm (asks the game for the price)")
    label = T.Button({ id = 7, stage = "quoted", total = 170 }, 7, has)
    t:ok(label:find("^Pay "), "the game quoted: Pay, with the sum")
    label = T.Button({ id = 7, stage = "ready", auctions = { {}, {} }, done = 1 }, 7, has)
    t:eq(label, "Buy 2 of 2", "single auctions: one a click")
    label, can = T.Button({ id = 8, stage = "ready", commodity = true }, 7, has)
    t:ok(label == "Buy" and can, "another deal's button is still Buy")
    _, can = T.Button(nil, 7, { search = false })
    t:ok(not can, "a client without the search: the button is greyed")
    t:ok(#T.Tip({ kind = "vendor", limit = 25, name = "x", id = 1 }, nil) >= 2, "a vendor deal's tooltip explains it")
    t:ok(table.concat(T.Tip({ kind = "resell", limit = 50, usual = 100, name = "x", id = 1 }, nil), " "):find("may not sell", 1, true), "a resell deal's says it's a guess")
end)

ns:Register("test", "click: Flow Trader opens from the auction house's tab; a button away from the auction house buys nothing", function(t)
    local T = ns.trader
    local def = ns:Get("gameButton", "auctiontrader")
    t:ok(def and def.label == "Flow Trader", "a Flow Trader tab is registered for the auction house")
    t:ok(def.x and def.x < ns.gameButtons.X, "to the left of the Flow Auctions tab, not on it")
    if InCombatLockdown() then return end
    local was = T._Frame() and T._Frame():IsShown()
    local deals, job = T.deals, T.job
    T.deals = { { id = 2589, name = "Linen Cloth", kind = "vendor", qty = 20, cost = 200, gain = 60, limit = 13 } }
    if was then T._Frame():Hide() end
    local ok, err = pcall(def.click)
    t:ok(ok, "a click on the tab runs" .. (ok and "" or (": " .. tostring(err))))
    local f = T._Frame()
    t:ok(f and f:IsShown(), "the window is up")
    if f then
        local r = f.rows[1]
        for _, row in ipairs(f.rows) do if row.deal == T.deals[1] then r = row end end   -- (your route's own purchases come first)
        t:ok(r:IsShown() and r.text:GetText():find("20 x Linen Cloth", 1, true), "with the deal on its first line")
        t:eq(r.btn:GetText(), "Buy", "and its button")
        -- (Not while you stand at an auction house: there a click really looks the item up.)
        local atAH = _G.AuctionHouseFrame and _G.AuctionHouseFrame:IsShown()
        if not atAH then
            local okC, did = pcall(function() return T:Click(r.deal) end)
            t:ok(okC and not did, "away from an auction house the click buys nothing" .. (okC and "" or (": " .. tostring(did))))
            t:eq(T.job, job, "and starts nothing")
            t:ok(pcall(function() r.btn:GetScript("OnClick")(r.btn) end), "the real button's click runs")
        end
        t:eq(type(r.btn:GetScript("OnClick")), "function", "each line's button has its click")
        t:ok(not f.rows[#T.Rows() + 1] or not f.rows[#T.Rows() + 1]:IsShown(), "no line past the last one")
        pcall(def.click)
        t:ok(not f:IsShown(), "a second click on the tab closes it")
    end
    T.deals, T.job = deals, job
    if f then T:Fill(); if was then f:Show() end end
    local okL, lines = pcall(T.Lines)
    t:ok(okL and lines[2]:find("this client: search", 1, true), "/flow trader says which auction calls this client has" .. (okL and "" or (": " .. tostring(lines))))
    t:eq(type(ns.auction.Busy()), "boolean", "the auction reader says whether it's busy")
    -- A read with nothing in it finds nothing, and says nothing.
    local readAt = T.readAt
    T.ReadStart()
    T.ReadListing(987654330, 0, 0)
    local quiet = ns.db.trader.quiet
    ns.db.trader.quiet = true
    local d2 = T.deals
    t:ok(pcall(T.ReadDone), "the end of a read runs")
    t:eq(#T.deals, 0, "nothing listed, nothing found")
    T.deals, T.readAt, ns.db.trader.quiet = d2, readAt, quiet
end)

-------------------------------------------------------------------------------
-- 0.35.353: the route's own steps at the auction house and the bank get a
-- button; a probe for "above or below".
-------------------------------------------------------------------------------

ns:Register("test", "trader: what your route has you buy heads Flow Trader's list, with the same Buy button", function(t)
    local T = ns.trader
    local needs = T.RouteNeeds({
        { key = "need:5051", kind = "buy", cost = 960, text = "Buy 8 Dig Rat at the auction house (about 9.6s)" },
        { key = "qbuy:6128:1", kind = "buy", item = 2449, cost = 600, text = "Buy 5 Earthroot at the auction house (about 6s): Gathering the Cure" },
        { key = "need:5051", kind = "buy", cost = 960, text = "Buy 8 Dig Rat at the auction house (about 9.6s)" },
        { key = "need:77", kind = "buy", text = "Buy 3 Odd Thing at the auction house (about ?)" },
        { key = "buy:159", kind = "merchant", text = "Buy 5 Refreshing Spring Water" },
        { key = "875:1", kind = "collect", text = "Harpy Lieutenants" },
    })
    t:eq(#needs, 3, "the auction steps, each item once; not a vendor's or a quest's")
    t:ok(needs[1].id == 5051 and needs[1].qty == 8 and needs[1].name == "Dig Rat" and needs[1].kind == "route", "which item, how many, by name")
    t:eq(needs[1].limit, 120 * T.ROUTE_OVER, "bought at up to a few times the price Flow last saw")
    t:eq(needs[1].max, 8, "and no more than the step asks for")
    t:eq(needs[2].id, 2449, "a quest's material comes by its item")
    t:eq(needs[3].limit, math.huge, "no price known: no limit (the sum is shown before you pay)")
    t:ok(T.Line(needs[1], function(c) return c .. "c" end):find("8 x Dig Rat", 1, true) and T.Line(needs[1], function(c) return c .. "c" end):find("for your route", 1, true),
        "its line says it's for your route")
    t:ok(T.Tip(needs[1], nil)[1]:find("A step on your route", 1, true), "and its tooltip names the step")

    -- Eight wanted: eight bought, the cheapest, though more are listed.
    local pick = T.Pick({ { unit = 100, qty = 5 }, { unit = 110, qty = 20 } }, 360, 100000, 8)
    t:ok(pick.qty == 8 and pick.cost == 830, "the cheapest eight")
    pick = T.Pick({ { unit = 100, qty = 3, auction = 1, buyout = 300 }, { unit = 100, qty = 3, auction = 2, buyout = 300 }, { unit = 100, qty = 3, auction = 3, buyout = 300 },
                    { unit = 100, qty = 3, auction = 4, buyout = 300 } }, 360, 100000, 8)
    t:eq(#pick.auctions, 3, "single auctions: until the step's count is reached")
    t:eq(T.Pick({ { unit = 400, qty = 5 } }, 360, 100000, 8).qty, 0, "far dearer than Flow last saw: not bought blind")

    local okR, rows = pcall(T.Rows)
    t:ok(okR and type(rows) == "table", "the window's lines build from your own route" .. (okR and "" or (": " .. tostring(rows))))
    local label, can = T.Button(nil, 5051, { search = true })
    t:ok(label == "Buy" and can, "a route line's button is Buy")
end)

ns:Register("test", "banker: a step that has you take things out of the bank puts them in the Take out list", function(t)
    local B = ns.banker
    local fetch = B.FetchBy({
        { key = "bank:Cooking", text = "Get from your bank: 5 Mild Spices", fetch = { [2678] = 5 } },
        { key = "bankget:6328", text = "Bank: take out Recipe: Longjaw Mud Snapper", fetch = { [6328] = 1 } },
        { key = "875:1", text = "Harpy Lieutenants" },
    })
    t:eq(fetch[2678], "Get from your bank: 5 Mild Spices", "the step's things, with its words")
    t:ok(fetch[6328] ~= nil and fetch[5] == nil, "a recipe to fetch too; nothing else")
    local rows = B.TakeOutRows({ [2678] = 20, [2318] = 40 },
        function(id) return { action = "keep", reason = "for Cooking", item = { classID = 7, name = id == 2678 and "Mild Spices" or "Light Leather" } } end,
        {}, nil, function(id) return fetch[id] end)
    t:eq(#rows, 1, "what the step asks for comes out; what Flow just keeps stays in")
    t:ok(rows[1].action == "route" and rows[1].name == "Mild Spices" and rows[1].reason == "Get from your bank: 5 Mild Spices", "for which step")
    local _, lines = B.SellLines({}, rows, true)
    t:ok(lines[1]:find("In your bank:", 1, true) and lines[1]:find("(your route: Get from your bank: 5 Mild Spices)", 1, true), "its line says it's for your route")
    t:ok(B.TakeUrgent(rows), "a step's things are needed now: the window opens on them")
    t:ok(not B.TakeUrgent({ { action = "sell" }, { action = "ah" } }), "things only to sell aren't")
    t:ok(B.NeededBy({ { fetch = { [2678] = 5 } } })[2678], "and what a step takes out isn't offered back in")
    t:eq(#B.TakeOutRows({ [2678] = 20 }, function() return nil end, { [2678] = "bank" }, nil, function() return "x" end), 0, "your own 'bank it' still wins")
    t:eq(type(B.RouteFetch()), "table", "your own route's steps are read")
end)

ns:Register("test", "nav: the above/below probe reads the game's marker without changing anything", function(t)
    local HP = ns.heightProbe
    t:eq(HP.Text(false), "no C_Navigation", "a client without the marker says so")
    t:ok(HP.Text(true, false, nil, nil, false, false, 0, 0):find("^no frame"), "no frame to measure")
    t:ok(HP.Text(true, true, 600, 1000, true, false, 2, 130):find("frame at 60%% of the screen's height") ~= nil, "a frame: where it sits")
    t:ok(HP.Text(true, true, nil, 1000, true, false, 2, 130):find("can't measure", 1, true), "a frame Flow may not measure")
    t:eq(HP.Side(800, 1000), "above", "over the middle of the screen: above you")
    t:eq(HP.Side(200, 1000), "below", "under it: below")
    t:eq(HP.Side(520, 1000), "level", "about the middle: level")
    t:eq(HP.Side(nil, 1000), nil, "nothing to measure: can't say")
    local looks = HP.seen.looks
    t:ok(pcall(HP.Look), "a look runs")
    t:eq(HP.seen.looks, looks + 1, "and is counted")
