-------------------------------------------------------------------------------
-- 0.35.366: the row whose section is popped out stays lit.
-------------------------------------------------------------------------------

ns:Register("test", "click: a Flow menu's row stays lit while its section is popped out", function(t)
    local M = ns.menu
    local a, b = {}, {}
    t:ok(M.IsOpenRow(a, a, true), "the open section's row: lit")
    t:ok(not M.IsOpenRow(b, a, true), "another row: not")
    t:ok(not M.IsOpenRow(a, a, false), "the pop-out put away: not")
    t:ok(not M.IsOpenRow(nil, nil, true), "nothing open: nothing lit")
    if InCombatLockdown() then return end
    local items = {
        { title = true, text = "This step" }, { text = "Open it", func = function() end },
        { sep = true },
        { title = true, text = "Order" }, { text = "Shortest path", radio = true, checked = true, stay = true, func = function() end },
        { text = "Most XP first", radio = true, stay = true, func = function() end },
        { sep = true },
        { title = true, text = "Steps" }, { text = "Three", stay = true, func = function() end },
    }
    local ok, err = pcall(M.Open, M, items)
    t:ok(ok, "a menu opens" .. (ok and "" or (": " .. tostring(err))))
    if not ok then return end
    local rows, flyRows = M._Rows()
    local order, steps, plain
    for _, r in ipairs(rows) do
        if r:IsShown() and r.item then
            if r.item.section and r.item.text == "Order" then order = r end
            if r.item.section and r.item.text == "Steps" then steps = r end
            if r.item.text == "Open it" then plain = r end
        end
    end
    t:ok(order and steps and plain, "its rows: an entry and two folded sections")
    if order and steps and plain then
        t:ok(not order.openHl:IsShown(), "nothing popped out: no row lit")
        order:GetScript("OnEnter")(order)
        t:ok(order.openHl:IsShown() and not steps.openHl:IsShown(), "pointing at Order pops it out and lights its row")
        order:GetScript("OnLeave")(order)
        -- The mouse is in the pop-out now: its rows' handlers don't touch the main menu.
        local first = flyRows[1]
        if first and first:IsShown() then
            first:GetScript("OnEnter")(first)
            t:ok(order.openHl:IsShown(), "moving into the pop-out leaves Order lit")
            pcall(function() first:GetScript("OnClick")(first) end)   -- (a tick that keeps the menu open: it's drawn again)
            t:ok(order.openHl:IsShown(), "and so does setting a tick in it")
        end
        steps:GetScript("OnEnter")(steps)
        t:ok(steps.openHl:IsShown() and not order.openHl:IsShown(), "pointing at another section moves the light to it")
        plain:GetScript("OnEnter")(plain)
        t:ok(not steps.openHl:IsShown() and not order.openHl:IsShown(), "pointing at a plain entry puts the pop-out away and the light out")
    end
    M:Close()
    GameTooltip:Hide()
end)

-------------------------------------------------------------------------------
-- 0.35.367: a custom route that can't be walked doesn't take the arrow away.
-------------------------------------------------------------------------------

ns:Register("test", "custom route: lines with nothing to do from here wait, and the usual route shows", function(t)
    local F, N = ns.focus, ns.nav
    t:ok(F.Routable({ points = { { map = 1 } } }), "a step with a place and nothing holding it can be routed")
    t:ok(not F.Routable({ points = {} }), "one with no place can't (a book sold across the sea)")
    t:ok(not F.Routable({ points = { { map = 1 } }, blockedBy = "needs 5s" }), "nor one that's held")
    t:ok(not F.Routable(nil), "nothing: no")
    t:ok(F.AnyRoutable({ { points = {} }, { points = { {} } } }) and not F.AnyRoutable({ { points = {} } }) and not F.AnyRoutable({}), "any step the arrow could point at")
    local n, stuck = F.EmptyLooks(0, true, false, 0)
    t:ok(n == 1 and not stuck, "one look with no plan: wait")
    n, stuck = F.EmptyLooks(2, true, false, 0)
    t:ok(n == 3 and stuck, "three in a row: the lines wait")
    n, stuck = F.EmptyLooks(2, true, false, 5)
    t:ok(n == 0 and not stuck, "a plan with steps starts the count again")
    n = F.EmptyLooks(2, false, false, 0)
    t:eq(n, 0, "no custom route: nothing to watch")

    if InCombatLockdown() then return end
    local saved, sorter, sel, idle, stuckWas = ns.db.nav.focus, ns.db.nav.sorter, N.selection, F.idle, F.stuck
    ns.db.nav.focus = { { key = "test:nowhere", title = "First Aid 141 of 150" } }
    ns.db.nav.sorter = "custom"
    F.idle, F.stuck = nil, nil
    local list = { { key = "test:nowhere", points = {} }, { key = "1:1", points = { { map = 1 } } }, { key = "bank", points = { { map = 1 } } } }
    local out = F.Filter(list, true)
    t:eq(#out, 3, "a line whose only step has no place: the whole usual route stays (the arrow isn't lost)")
    t:ok(F.idle, "and the lines are marked as waiting")
    t:eq(F.all, list, "every step is still there for Flow Improvements to link to")
    list[1].points = { { map = 1 } }
    out = F.Filter(list, true)
    t:ok(#out == 1 and not F.idle, "once that step has a place, the route is the line again")
    F.stuck = true
    t:eq(#F.Filter(list, true), 3, "a route that came out empty anyway: the usual one shows")
    ns.db.nav.focus, ns.db.nav.sorter, N.selection, F.idle, F.stuck = saved, sorter, sel, idle, stuckWas
    F.all = nil
    N.RequestCollect("test done")
    pcall(F.UpdateBar)
    -- Flow Improvements finds a step that's off the route while you're on a custom one.
    F.all = { { key = "test:offroute", text = "Turn in: Something" } }
    local Adv = ns.advisor
    t:ok(Adv.FindGoal("test:offroute", F.all) ~= nil, "a step set aside by the custom route can still be linked")
    F.all = nil
end)

