    tip = Adv.LinkTip("goal", "x", "Learn Expert First Aid", "open")
    t:ok(tip[1] == "Open the step" and tip[3]:find("isn't added", 1, true), "one that can't be walked to: just opens, and says why it isn't added")
    t:eq(Adv.LinkTip("spell", "Moonfire (put it on a bar or bind a key)")[1], "Open Moonfire (put it on a bar or bind a key)", "a spell's link reads as before")
    t:eq(Adv.LinkTip("open", nil)[1], "Open it", "a link with nothing named")
    t:eq(Adv.LinkState(nil), "open", "no step: nothing to add")
    t:eq(Adv.LinkState({ key = "test:nowhere", points = {} }), "open", "a step with no place can't be added")
    local state = Adv.LinkState({ key = "test:somewhere", points = { { map = 1 } } })
    t:ok(state == "add" or state == "on", "a step with a place can")
    local _, label = Adv.LinkOf({ text = "x", goalKey = "k" }, function() return { key = "k", text = "Turn in: X" } end)
    t:eq(label, "the step on your route: Turn in: X", "the row's own words name the step")
end)

-------------------------------------------------------------------------------
-- 0.35.372: "Go here next" on a step across the sea leads to its crossing;
-- the crossing comes first when you're beside it with a hearthstone ready.
-------------------------------------------------------------------------------

ns:Register("test", "crossings: beside the tower with a hearthstone ready, the crossing comes first", function(t)
    local C = ns.crossings
    t:eq(C.Weight(300, true), C.W_NOW, "close to the boarding place, hearthstone ready: first")
    t:eq(C.Weight(300, false), C.W_NEAR, "close, no hearthstone for the way back: with the rest, by its distance")
    t:eq(C.Weight(5000, true), C.WEIGHT, "far from it: after what's left here, as before")
    t:eq(C.Weight(nil, true), C.WEIGHT, "distance unknown: after what's left here")
    t:ok(C.W_NOW < 1 and C.W_NEAR >= 1 and C.WEIGHT > C.W_NEAR, "first means worth a detour; later means not")
    t:ok(C.WhenText(C.W_NOW):find("comes first", 1, true) and C.WhenText(C.WEIGHT):find("far from it", 1, true), "the step says why it comes when it does")
    t:eq(type(C.HearthReady()), "boolean", "whether your hearthstone is ready is read")

    local steps = { { key = "cross:0", toCont = 0, text = "Zeppelin to Undercity" }, { key = "cross:530", toCont = 530 } }
    t:eq(C.StepFor(0, steps).key, "cross:0", "the crossing for a continent is found among the route's")
    t:eq(C.StepFor(1, steps), nil, "none for a continent nothing waits on")
    t:eq(C.StepFor(0, nil), nil, "no crossings: none")
    t:eq(C.AwayOf(nil), nil, "no step: not across the sea")
    t:ok(not C.CanLead({ key = "test:here", points = {} }), "a step with no place isn't one a crossing leads to")
    t:eq(C.Lead({ key = "test:here", points = {} }), false, "and picking it does nothing")
end)

ns:Register("test", "click: Go here next on a locked step is offered only when a crossing leads to it", function(t)
    local C = ns.crossings
    if InCombatLockdown() then return end
    -- The tracker's and the router's menus ask the same question: a locked
    -- step is greyed unless its crossing can be the next step.
    local locked = { key = "test:locked", text = "Trial of the Sea Lion", blockedBy = "It's in Silverpine Forest", points = {} }
    local disabled = locked.blockedBy ~= nil and not C.CanLead(locked)
    t:ok(disabled, "locked for another reason: Go here next stays greyed")
    -- A custom route doesn't take a crossing as a line of its own.
    local F, N = ns.focus, ns.nav
    local saved, sorter, sel, key = ns.db.nav.focus, ns.db.nav.sorter, N.selection, ns.db.nav.selectedKey
    ns.db.nav.focus = {}
    local ok, err = pcall(N.Select, N, "cross:0")
    t:ok(ok, "picking a crossing runs" .. (ok and "" or (": " .. tostring(err))))
    t:eq(#ns.db.nav.focus, 0, "and adds no line of its own to the custom route")
    ns.db.nav.focus, ns.db.nav.sorter, N.selection, ns.db.nav.selectedKey = saved, sorter, sel, key
    if ns.theme and ns.theme.UpdateRoute then ns.theme:UpdateRoute() end
    N.planDirty = true
    N.RequestCollect("test done")
    pcall(F.UpdateBar)
end)

-------------------------------------------------------------------------------
-- 0.35.373: the self-tests are off the login path; lite mode covers raid
-- groups and battlegrounds and holds the route's gathering back.
-------------------------------------------------------------------------------

ns:Register("test", "tests: they don't run by themselves after login, and never on a release", function(t)
    local A = ns.tests.Auto
    t:ok(not A("login", false, true, false), "a release: never after login")
    t:ok(not A("logout", false, false, false), "a release: not at logout either (it made every reload 3 s longer)")
    t:ok(A("logout", true, false, false), "a developer install: at reload and logout, with the diagnostics")
    t:ok(not A("login", true, false, false), "a developer install: not after login unless asked")
    t:ok(A("login", true, true, false), "asked for (/flow test login on): after login")
    t:ok(not A("login", true, true, true), "but never in a raid, a dungeon or a battleground")
    t:eq(type(ns.tests.AtLogin()), "boolean", "the choice is read")
    t:eq(type(ns.diag:IsDev()), "boolean", "whether this is a developer install is known")
end)

ns:Register("test", "perf: lite mode is on in a raid group, an instance, a battleground and a boss fight", function(t)
    local W = ns.LiteWhy
    t:eq(W(false, nil, false, false, nil), nil, "out in the world, alone or in a party: off")
    t:eq(W(false, nil, false, true, nil), "in a raid group", "a raid group, wherever you are")
    t:eq(W(true, "raid", false, true, nil), "in a raid", "inside a raid")
    t:eq(W(true, "party", false, false, nil), "in a dungeon", "inside a dungeon")
    t:eq(W(true, "pvp", false, false, nil), "in a battleground", "a battleground")
    t:eq(W(false, nil, true, false, nil), "a boss fight", "a boss fight anywhere")
    t:eq(W(true, "raid", true, true, false), nil, "switched off in Flow Settings: never")
    t:eq(type(ns.Lite()), "boolean", "the game is asked")

    local N = ns.nav
    t:eq(N.LiteGather(false, 0), "now", "not in lite mode: the route is gathered when something changes")
    t:eq(N.LiteGather(true, 5), "later", "in lite mode, 5 s after the last gathering: it waits")
    t:eq(N.LiteGather(true, N.LITE_GATHER), "now", "after the gap: once")
    t:eq(N.LiteGather(true, nil), "now", "the first one in lite mode goes ahead")
    t:ok(N.LITE_GATHER >= 15, "the gap is long enough to matter: " .. tostring(N.LITE_GATHER) .. " s")
    local found = false
    for _, name in ipairs(ns.menu.SECTIONS) do found = found or name == "Custom route" end
    t:ok(found, "(the Flow menu's sections list knows Custom route)")
end)

-------------------------------------------------------------------------------
-- 0.35.374: the zone note waits until you've settled, and No is for good.
-------------------------------------------------------------------------------

ns:Register("test", "zone note: it waits until you've been in the zone a while, and a No is never asked again", function(t)
    local Z = ns.zoneNotice
    t:ok(not Z.Settled(3), "three seconds in a zone (a zeppelin leaving, a flicker between zones): not asked")
    t:ok(not Z.Settled(Z.SETTLE - 1), "just under the wait: not yet")
    t:ok(Z.Settled(Z.SETTLE), "after the wait: asked")
    t:ok(not Z.Settled(nil), "how long isn't known: not asked")
    t:ok(Z.SETTLE >= 20, "the wait is long enough to cover a loading flicker: " .. tostring(Z.SETTLE) .. " s")
    local zone = 987654341
    local was = Z.Declined(zone)
    t:ok(not Z.Declined(nil), "no zone: nothing declined")
    Z.Decline(zone, true)
    t:ok(Z.Declined(zone), "a zone you said No to is remembered")
    local choice = { name = "Durotar", where = { quests = 4, min = 1, max = 10 } }
    t:ok(not Z.Wanted(zone, false, choice, Z.Declined(zone) and zone or nil, false), "and never asked about again, however often you come back")
    t:ok(Z.Wanted(zone + 1, false, choice, Z.Declined(zone + 1) and (zone + 1) or nil, false), "another zone is still asked about")
    Z.Decline(zone, was)
    t:eq(Z.Declined(zone), was, "(put back)")
    -- Coming into a zone starts the wait.
    local last, entered = Z.lastHere, Z.enteredAt
    Z.lastHere = -1
    t:ok(pcall(Z.Check), "a look on entering a zone runs")
    t:ok(Z.lastHere == -1 or (Z.enteredAt ~= nil and GetTime() - Z.enteredAt < 1), "and the wait starts from now")
    Z.lastHere, Z.enteredAt = last, entered
end)

-------------------------------------------------------------------------------
-- 0.35.375: bigger gear set icons with a menu; sets get a matching picture;
-- Flow can build a Fishing set.
-------------------------------------------------------------------------------

ns:Register("test", "gear sets: each gets a picture that matches it, yours first", function(t)
    local SR = ns.setRecipes
    local recipes = { { name = "Fishing", icon = "fish.tga" } }
    local roles = { { name = "Feral (Cat)", icon = "cat.tga" }, { name = "Restoration", icon = "tree.tga" } }
    t:eq((SR.Pick("Feral (Cat)", {}, recipes, roles, 134400)), "cat.tga", "a spec's set: its spec's picture")
    t:eq((SR.Pick("Fishing", {}, recipes, roles, 134400)), "fish.tga", "a set Flow built: its own")
    t:eq((SR.Pick("Feral (Cat)", { ["Feral (Cat)"] = "mine.tga" }, recipes, roles, 134400)), "mine.tga", "one you picked comes before both")
    t:eq((SR.Pick("My PvP Set", {}, recipes, roles, 134400)), 134400, "a set of your own making keeps the game's picture")
    local _, from = SR.Pick("Fishing", {}, recipes, roles, 1)
    t:eq(from, "recipe", "and it says where the picture is from")
    t:eq(table.concat(SR.ToPutOn({ "pole", "hat" }, { hat = true }), ","), "pole", "building a set puts on only what you aren't wearing")
    t:eq(#SR.ToPutOn({ "pole" }, { pole = true }), 0, "wearing it all: nothing to put on")
    t:eq(#SR.ToPutOn(nil, nil), 0, "nothing wanted: nothing")
    t:eq(SR.GameIcon(134400), 134400, "a picture's number goes to the game as it is")
    local fishing = ns:Get("gearSet", "fishing")
    t:ok(fishing and fishing.name == "Fishing" and fishing.icon:find("Fishing", 1, true), "Fishing is a set Flow can build, with a fishing picture")
    t:ok(pcall(fishing.offer) and pcall(fishing.wants), "asking whether to offer it, and what goes on, doesn't error")
    t:ok(pcall(SR.Offers), "the sets worth building are listed")
    t:ok(#SR.Choices() >= 4, "a set's menu has pictures to choose from")
    local said
    SR.Build("no-such-set", function(ok, text) said = { ok, text } end)
    t:ok(said and said[1] == false, "a set Flow doesn't know: said so, nothing done")
end)

ns:Register("test", "click: a gear set icon is bigger, and its right-click menu sets the size and the picture", function(t)
    local SI, SR = ns.setIcons, ns.setRecipes
    t:eq((SI.SizeOf(nil)), 26, "medium, as it comes: bigger than the 20 it was")
    t:eq((SI.SizeOf("small")), 20, "small")
    t:eq((SI.SizeOf("large")), 34, "large")
    t:eq(select(2, SI.SizeOf("huge")), "medium", "an unknown choice is medium")
    local set = { id = 987654350, name = "Test Set 987654350" }
    local items = SI.MenuItems(set)
    local texts = {}
    for _, it in ipairs(items) do if it.text then texts[#texts + 1] = it.text end end
    local all = table.concat(texts, "|")
    t:ok(all:find("Put it on", 1, true) and all:find("Picture", 1, true) and all:find("Icon size", 1, true), "the menu: put it on, its picture, the icons' size")
    t:ok(all:find("Equipment Manager", 1, true), "and where the game lets you pick any other picture")
    -- Size.
    local was = ns.db.gear.setIconSize
    for _, it in ipairs(items) do
        if it.text == "Large" then t:ok(pcall(it.func), "picking Large runs") end
    end
    t:eq(ns.db.gear.setIconSize, "large", "and is kept")
    t:eq(SI.Size(), 34, "the icons are that big now")
    ns.db.gear.setIconSize = was
    -- Picture: kept for this set, and put back.
    local mine = ns.db.gear.setIcon[set.name]
    local choice = SR.Choices()[1]
    t:ok(SR.SetIcon({ name = set.name }, choice.texture), "picking a picture runs")
    t:eq((SR.IconFor(set.name, 1)), choice.texture, "the set shows it")
    SR.SetIcon({ name = set.name }, nil)
    t:eq((SR.IconFor(set.name, 1)), 1, "Flow's own choice: back to what it was")
    ns.db.gear.setIcon[set.name] = mine
    -- A right-click opens the menu; a click with no set does nothing.
    if not InCombatLockdown() then
        local ok, what = pcall(SI.Click, set, "RightButton")
        t:ok(ok and what == "menu", "a right-click on an icon opens its menu" .. (ok and "" or (": " .. tostring(what))))
        ns.menu:Close()
    end
    t:eq(SI.Click(nil, "LeftButton"), nil, "no set: nothing")
    pcall(SI.Refresh)
end)

-------------------------------------------------------------------------------
-- 0.35.376: every gear set has a default picture; the icon's menu resets to
-- it and lets you set it.
-------------------------------------------------------------------------------

ns:Register("test", "gear sets: a default picture per set name, yours before Flow's", function(t)
    local SR = ns.setRecipes
    local recipes = { { name = "Fishing", icon = "fish.tga" } }
    local roles = { { name = "Feral (Cat)", icon = "cat.tga" } }
    t:eq((SR.Pick("Fishing", nil, recipes, roles, 1, {})), "fish.tga", "no default set: the recipe's")
    t:eq((SR.Pick("Fishing", nil, recipes, roles, 1, { Fishing = "mine.tga" })), "mine.tga", "the default you set comes before the recipe's")
    t:eq((SR.Pick("Feral (Cat)", nil, recipes, roles, 1, { ["Feral (Cat)"] = "paw.tga" })), "paw.tga", "and before the spec's")
    t:eq((SR.Pick("Feral (Cat)", { ["Feral (Cat)"] = "one.tga" }, recipes, roles, 1, { ["Feral (Cat)"] = "paw.tga" })), "one.tga", "a pick for this one set comes before the default")
    t:eq(select(2, SR.Pick("Fishing", nil, recipes, roles, 1, { Fishing = "mine.tga" })), "default", "and it says it's the default")
    t:eq((SR.Pick("My PvP Set", nil, recipes, roles, 1, { ["My PvP Set"] = "pvp.tga" })), "pvp.tga", "a set of your own can have a default too")
    t:eq((SR.DefaultFor("Fishing", 1)), ns.db.gear.setDefault.Fishing or ns:Get("gearSet", "fishing").icon, "Fishing has a default without being told")
end)

ns:Register("test", "click: a gear set icon's menu sets the default picture and resets to it", function(t)
    local SI, SR = ns.setIcons, ns.setRecipes
    local name = "Test Set 987654376"
    local set = { name = name, icon = 134400 }   -- no id: nothing is asked of the game
    local wasMine, wasDef = ns.db.gear.setIcon[name], ns.db.gear.setDefault[name]
    ns.db.gear.setIcon[name], ns.db.gear.setDefault[name] = nil, nil
    local function entry(start)
        for _, it in ipairs(SI.MenuItems(set)) do
            if it.text and it.text:find(start, 1, true) == 1 then return it end
        end
    end
    t:ok(entry("Reset to the default"), "the menu has: Reset to the default")
    t:ok(not entry("Forget my default"), "no default of yours: nothing to forget")
    local choice = SR.Choices()[1].texture
    SR.SetIcon(set, choice)
    local make = entry("Make this the default")
    t:ok(make, "with a picture picked: Make this the default")
    t:ok(make and pcall(make.func), "clicking it runs")
    t:eq(ns.db.gear.setDefault[name], choice, "the default for sets of that name is kept")
    t:eq(ns.db.gear.setIcon[name], nil, "and the pick for this one set is folded into it")
    t:ok(not entry("Make this the default"), "showing the default: nothing to make")
    -- Another pick, then back to the default.
    local other = SR.Choices()[2].texture
    SR.SetIcon(set, other)
    t:eq((SR.IconFor(name, 134400)), other, "another pick shows")
    local reset = entry("Reset to the default")
    t:ok(reset and pcall(reset.func), "clicking Reset runs")
    t:eq((SR.IconFor(name, 134400)), choice, "and the set shows its default again")
    -- Forgetting it.
    local forget = entry("Forget my default")
    t:ok(forget and pcall(forget.func), "Forget my default runs")
    t:eq((SR.IconFor(name, 134400)), 134400, "a set Flow doesn't know is back to the game's picture")
    t:eq((SR.Reset(nil)), nil, "no set: nothing")
    ns.db.gear.setIcon[name], ns.db.gear.setDefault[name] = wasMine, wasDef
    pcall(SI.Refresh)
end)

-------------------------------------------------------------------------------
-- 0.35.377: a custom route is your lines in place of the quest kinds, plus
-- the errands ticked under Route includes (their own ticks while it's on).
-------------------------------------------------------------------------------

ns:Register("test", "custom route: errands ride along, quest kinds are replaced by your lines", function(t)
    local F = ns.focus
    t:ok(F.ReplacesDef({ custom = "lines" }) and not F.ReplacesDef({}) and not F.ReplacesDef({ custom = false }), "a kind says whether your lines stand in for it")
    t:ok(F.KindDefault({}) and F.KindDefault(nil) and not F.KindDefault({ custom = false }), "an errand starts ticked unless its kind says otherwise")
    for _, kind in ipairs({ "quests", "newQuests", "lowQuests", "battlegrounds" }) do
        t:ok(F.Replaces(kind), kind .. ": your lines instead")
    end
    for _, kind in ipairs({ "training", "town", "banker", "flightpaths", "crossings", "professions" }) do
        t:ok(not F.Replaces(kind), kind .. ": an errand")
    end
    local was = ns.db.nav.focusKinds
    ns.db.nav.focusKinds = {}
    t:ok(F.KindOn("training") and F.KindOn("town") and F.KindOn("banker") and F.KindOn("flightpaths") and F.KindOn("crossings"),
        "on from the start: training, town errands, the bank, flight paths, crossings")
    t:ok(not F.KindOn("professions"), "professions start off")
    F.SetKind("professions", true)
    t:ok(F.KindOn("professions"), "ticking one is kept")
    ns.db.nav.focusKinds = was
    -- Which steps ride along.
    local function replaces(kind) return kind == "quests" end
    t:ok(F.Errand({ key = "train:class", routeKind = "training" }, replaces), "a trainer step rides along")
    t:ok(not F.Errand({ key = "30:1", routeKind = "quests" }, replaces), "a quest that isn't in your lines doesn't")
    t:ok(not F.Errand({ key = "cross:0", routeKind = "crossings", forQuests = { [30] = true } }, replaces), "a crossing goes by the line that needs it")
    t:ok(not F.Errand({ key = "dungeon:x" }, replaces), "a step of no kind doesn't")
    local list = {
        { key = "3:1", routeKind = "quests" }, { key = "30:1", routeKind = "quests" },
        { key = "train:class", routeKind = "training" }, { key = "fp:1", routeKind = "flightpaths" },
    }
    local out = F.FilterBy(list, { [3] = true }, {}, function(g) return F.Errand(g, replaces) end)
    local keys = {}
    for _, g in ipairs(out) do keys[#keys + 1] = g.key end
    t:eq(table.concat(keys, ","), "3:1,train:class,fp:1", "the line's step, the trainer and the flight path; not the other quest")
end)

ns:Register("test", "click: Route includes on a custom route has its own ticks, and your lines can't be unticked", function(t)
    local N, M, F = ns.nav, ns.menu, ns.focus
    local usual, mine = ns.db.nav.kinds, ns.db.nav.focusKinds
    local usualCopy = {}
    for k, v in pairs(usual or {}) do usualCopy[k] = v end
    ns.db.nav.focusKinds = {}
    with(N, "Collect", function() end, function()
        with(F, "KindsOn", function() return true end, function()
            local items = M.KindItems()
            local by, first
            by = {}
            for _, it in ipairs(items) do
                if it.custom then first = it end
                if it.kind or it.text then by[it.kind or it.text] = it end
            end
            t:ok(first and first.checked and first.disabled and first.text:find("Custom route", 1, true), "the custom route is a ticked row that can't be unticked")
            t:ok(by.quests and by.quests.disabled and not by.quests.checked, "current quests: greyed, your lines instead")
            t:ok(by.newQuests and by.newQuests.disabled and by.lowQuests.disabled, "new and low-level quests too")
            t:ok(by.training and by.training.checked and not by.training.disabled, "training is ticked and can be unticked")
            t:ok(by.banker and by.banker.checked and by.flightpaths.checked and by.crossings.checked and by.town.checked, "the bank, flight paths, crossings and town errands are ticked")
            t:ok(by.professions and not by.professions.checked, "professions aren't")
            M:Open(items)
            t:ok(pcall(M.Click, by.training), "clicking training runs")
            t:ok(not F.KindOn("training") and not N:Includes("training"), "it's off for the custom route")
            pcall(M.Click, by["Select all"])
            t:ok(F.KindOn("training") and F.KindOn("professions"), "Select all ticks every errand")
            pcall(M.Click, by["Clear all"])
            t:ok(not F.KindOn("training") and not F.KindOn("banker"), "Clear all unticks them")
            t:ok(F.Replaces("quests"), "and your lines are still what the route is")
            M:Close()
        end)
    end)
    local same = true
    for k, v in pairs(usualCopy) do if (ns.db.nav.kinds or {})[k] ~= v then same = false end end
    t:ok(same and ns.db.nav.kinds == usual, "none of it touched your usual route's ticks")
    ns.db.nav.focusKinds = mine
end)
